export const WORKFLOW_TOPICS = [{"id":"hello","name":"Hello Srinivas: the Git journey","color":"#E11D48","tagline":"Follow one file, hello.txt, through every Git idea in order: working folder, staging area, local commit, remote server (GitHub, GitLab or Bitbucket), branches, merges and recovery. After each step the four coloured boxes show where your file is and where HEAD points. All of it runs on your own computer.","icon":"git-repo","workflows":[{"id":"hello-first-commit","title":"Module 1: hello.txt from folder to first commit","level":1,"icon":"lucide-git-commit","summary":"Create hello.txt with \"Hello Srinivas\", then watch it move from your working folder to the staging area to a local commit.","qna":[{"q":"In which situation do we use this?","a":"Whenever a folder of work needs history: notes, scripts, config. Run git init once, then add and commit after each meaningful change."},{"q":"What are the three places a file can be?","a":"The working folder (what you edit), the staging area (what the next commit will contain) and the repository (saved commits)."},{"q":"What comes next?","a":"Module 2 sends these commits to a server so others can get them."}],"steps":[{"title":"Create hello.txt in a new folder","icon":"lucide-pencil","text":"Git works on ordinary folders. Make one and put a file in it. The echo command writes text into a file and > creates it. Git does not know this file yet.","cmd":"mkdir -p ~/hello-git\ncd ~/hello-git\necho \"Hello Srinivas\" > hello.txt\ncat hello.txt","out":"$ cat hello.txt\nHello Srinivas","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"","hash":"","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[],"local":[],"norepo":true,"remote":null,"remoteFile":[]}},{"title":"git init: turn the folder into a repository","icon":"lucide-settings","text":"git init creates a hidden .git folder. That folder is the repository: every commit, branch and setting lives there. HEAD is a pointer inside it that says which commit you are on, and there is none yet.","cmd":"git init\nls -a","out":"$ git init\nInitialized empty Git repository in /home/you/hello-git/.git/\n\n$ ls -a\n.\n..\n.git\nhello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"","status":["?? hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[],"local":[],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git add: copy hello.txt into the staging area","icon":"lucide-plus","text":"The staging area (also called the index) is a waiting room for the next commit. add copies the current content of hello.txt into it. Your working file is unchanged.","cmd":"git add hello.txt\ngit status","out":"$ git status\nOn branch main\n\nNo commits yet\n\nChanges to be committed:\n  (use \"git rm --cached <file>...\" to unstage)\n\tnew file:   hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"","status":["A  hello.txt"],"staged":["A\thello.txt"],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":[],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git commit: save a snapshot in the local repository","icon":"lucide-save","text":"commit turns everything in the staging area into a permanent snapshot with a message. HEAD now points at this first commit. The hash is its unique ID.","cmd":"git commit -m \"Add hello.txt\"\ngit log --oneline --decorate","out":"$ git commit -m \"Add hello.txt\"\n[main (root-commit) 069c509] Add hello.txt\n 1 file changed, 1 insertion(+)\n create mode 100644 hello.txt\n\n$ git log --oneline --decorate\n069c509 (HEAD -> main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Edit the file: folder and repository now differ","icon":"lucide-pencil","text":"Add a second line. The working folder now holds newer content than the staging area and the last commit. status shows \"modified\", and diff shows the added line with a + sign.","cmd":"echo \"Welcome to Git\" >> hello.txt\ngit status --short\ngit diff","out":"$ git status --short\n M hello.txt\n\n$ git diff\ndiff --git a/hello.txt b/hello.txt\nindex dff1d38..efb31e9 100644\n--- a/hello.txt\n+++ b/hello.txt\n@@ -1 +1,2 @@\n Hello Srinivas\n+Welcome to Git","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Stage and commit the second version","icon":"lucide-git-commit","text":"Run add then commit again. A second commit is created with the first as its parent, and HEAD moves forward to it. The branch name main moves with HEAD.","cmd":"git add hello.txt\ngit commit -m \"Add welcome line\"\ngit log --oneline --graph --decorate","out":"$ git commit -m \"Add welcome line\"\n[main 1552f3b] Add welcome line\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline --graph --decorate\n* 1552f3b (HEAD -> main) Add welcome line\n* 069c509 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"1552f3b","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 1552f3b (HEAD -> main) Add welcome line","* 069c509 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Read an old version of the file","icon":"lucide-file-text","text":"Every commit keeps a full snapshot. show prints a file as it was at any commit: HEAD~1 means \"one commit before HEAD\".","cmd":"git show HEAD~1:hello.txt\ngit show HEAD:hello.txt","out":"$ git show HEAD~1:hello.txt\nHello Srinivas\n\n$ git show HEAD:hello.txt\nHello Srinivas\nWelcome to Git","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"1552f3b","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 1552f3b (HEAD -> main) Add welcome line","* 069c509 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":1,"of":12,"prev":null,"next":{"id":"hello-remote-push","title":"Module 2: Send hello.txt to GitHub, GitLab or Bitbucket"}}},{"id":"hello-remote-push","title":"Module 2: Send hello.txt to GitHub, GitLab or Bitbucket","level":1,"icon":"lucide-upload","summary":"Add a remote, push your commits to it, change the file again, push again, and clone it onto another computer.","qna":[{"q":"In which situation do we use this?","a":"When work must be backed up or shared: a new project, a new laptop, or before asking someone to review."},{"q":"GitHub, GitLab or Bitbucket: do the commands differ?","a":"No. Git is the same everywhere; only the website around it differs. You change only the address in git remote add."},{"q":"What comes next?","a":"Module 3 shows how to inspect and undo changes before they are committed."}],"steps":[{"title":"Start: hello.txt is committed locally","icon":"lucide-folder","text":"This is where module 1 ended. One commit, only on your computer. The remote box is empty because no server is connected yet.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt\ngit add hello.txt\ngit commit -qm \"Add hello.txt\"\ngit log --oneline --decorate","out":"$ git log --oneline --decorate\n652b700 (HEAD -> main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Create an empty remote repository","icon":"lucide-cloud","text":"On GitHub, GitLab or Bitbucket you click New repository and get an address. Here a bare repository in a local folder plays that role, so you can run everything offline. A bare repository holds history but has no working files.","cmd":"git init -q --bare -b main ~/remote/hello.git\nls ~/remote/hello.git","out":"$ ls ~/remote/hello.git\nHEAD\nconfig\ndescription\nhooks\ninfo\nobjects\nrefs","outKind":"recorded","note":"A real address looks like https://github.com/you/hello-git.git or git@gitlab.com:you/hello-git.git.","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git remote add: tell Git where the server is","icon":"lucide-link","text":"A remote is a named address. By convention the main one is called origin. This only saves the address; nothing is sent yet.","cmd":"git remote add origin ~/remote/hello.git\ngit remote -v","out":"$ git remote -v\norigin\t/home/you/remote/hello.git (fetch)\norigin\t/home/you/remote/hello.git (push)","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":[],"remoteFile":[]}},{"title":"git push -u: send your commits to the server","icon":"lucide-upload","text":"push copies your commits to the remote branch. -u remembers the pairing so later you can type just git push. Look at the Remote box: it now has your commit.","cmd":"git push -u origin main\ngit branch -vv","out":"$ git push -u origin main\nTo /home/you/remote/hello.git\n * [new branch]      main -> main\nbranch 'main' set up to track 'origin/main'.\n\n$ git branch -vv\n* main 652b700 [origin/main] Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 652b700 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Change the file, commit and push again","icon":"lucide-refresh-cw","text":"The normal daily loop: edit, add, commit, push. Only the new commit travels; the server already has the old one.","cmd":"echo \"Welcome to Git\" >> hello.txt\ngit commit -qam \"Add welcome line\"\ngit push\ngit log --oneline --decorate","out":"$ git push\nTo /home/you/remote/hello.git\n   652b700..9018c43  main -> main\n\n$ git log --oneline --decorate\n9018c43 (HEAD -> main, origin/main) Add welcome line\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9018c43","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 9018c43 (HEAD -> main, origin/main) Add welcome line","* 652b700 Add hello.txt"],"norepo":false,"remote":["* 9018c43 (HEAD -> main) Add welcome line","* 652b700 Add hello.txt"],"remoteFile":["Hello Srinivas","Welcome to Git"]}},{"title":"git clone: get the project on another computer","icon":"lucide-download","text":"clone copies the whole repository with all its history and sets origin automatically. This is how a teammate, or you on a new laptop, starts. The new folder is a complete, independent copy.","cmd":"git clone -q ~/remote/hello.git ~/hello-copy\ncat ~/hello-copy/hello.txt\ngit -C ~/hello-copy log --oneline","out":"$ cat ~/hello-copy/hello.txt\nHello Srinivas\nWelcome to Git\n\n$ git -C ~/hello-copy log --oneline\n9018c43 Add welcome line\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9018c43","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 9018c43 (HEAD -> main, origin/main) Add welcome line","* 652b700 Add hello.txt"],"norepo":false,"remote":["* 9018c43 (HEAD -> main) Add welcome line","* 652b700 Add hello.txt"],"remoteFile":["Hello Srinivas","Welcome to Git"]}}],"nav":{"pos":2,"of":12,"prev":{"id":"hello-first-commit","title":"Module 1: hello.txt from folder to first commit"},"next":{"id":"hello-edit-diff-restore","title":"Module 3: Changes, diff, unstage and restore"}}},{"id":"hello-edit-diff-restore","title":"Module 3: Changes, diff, unstage and restore","level":1,"icon":"lucide-arrow-left-right","summary":"Move changes between the folder and the staging area with diff, restore --staged and restore.","qna":[{"q":"In which situation do we use this?","a":"Before every commit, to see exactly what changed, and whenever you edited the wrong thing and want it back."},{"q":"Which command moves which box?","a":"add copies working to staging, restore --staged undoes that, restore resets the working file from the staging area."},{"q":"What comes next?","a":"Module 4 undoes things that are already committed."}],"steps":[{"title":"Start with a committed hello.txt","icon":"lucide-folder","text":"One clean commit. All four boxes agree, which is what a clean status means.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt\ngit add hello.txt\ngit commit -qm \"Add hello.txt\"\ngit status","out":"$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Edit the file: only the working folder changes","icon":"lucide-pencil","text":"Only the first box changes. status marks the file as modified, not staged. diff compares the working file with the staging area.","cmd":"echo \"Hello India\" >> hello.txt\ngit status --short\ngit diff","out":"$ git status --short\n M hello.txt\n\n$ git diff\ndiff --git a/hello.txt b/hello.txt\nindex dff1d38..043c1f8 100644\n--- a/hello.txt\n+++ b/hello.txt\n@@ -1 +1,2 @@\n Hello Srinivas\n+Hello India","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Hello India"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git add: the change moves to the staging area","icon":"lucide-plus","text":"Now working folder and staging area agree, so plain diff shows nothing. diff --staged compares the staging area with the last commit, which is what the next commit would contain.","cmd":"git add hello.txt\ngit diff\ngit diff --staged","out":"$ git diff --staged\ndiff --git a/hello.txt b/hello.txt\nindex dff1d38..043c1f8 100644\n--- a/hello.txt\n+++ b/hello.txt\n@@ -1 +1,2 @@\n Hello Srinivas\n+Hello India","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":["M  hello.txt"],"staged":["M\thello.txt"],"working":[["hello.txt",["Hello Srinivas","Hello India"]]],"staging":[["hello.txt",["Hello Srinivas","Hello India"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git restore --staged: take it back out of staging","icon":"lucide-undo-2","text":"This unstages the file. The edit is not lost: it is still in the working folder. Only the staging box goes back to matching the commit.","cmd":"git restore --staged hello.txt\ngit status --short\ncat hello.txt","out":"$ git status --short\n M hello.txt\n\n$ cat hello.txt\nHello Srinivas\nHello India","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Hello India"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git restore: throw the edit away","icon":"lucide-eraser","text":"restore without options replaces the working file with the version from the staging area (here the same as the last commit). The extra line disappears for good, because it was never committed.","cmd":"git restore hello.txt\ncat hello.txt\ngit status","out":"$ cat hello.txt\nHello Srinivas\n\n$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"Uncommitted edits cannot be recovered after restore. Check git diff first.","risk":true,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Deleted by mistake? Bring it back","icon":"lucide-wrench","text":"A deleted tracked file is just another change. restore brings it back from the repository.","cmd":"rm hello.txt\ngit status --short\ngit restore hello.txt\ncat hello.txt","out":"$ git status --short\n D hello.txt\n\n$ cat hello.txt\nHello Srinivas","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":3,"of":12,"prev":{"id":"hello-remote-push","title":"Module 2: Send hello.txt to GitHub, GitLab or Bitbucket"},"next":{"id":"hello-head-reset","title":"Module 4: Watch HEAD move: reset --soft, --mixed, --hard and revert"}}},{"id":"hello-head-reset","title":"Module 4: Watch HEAD move: reset --soft, --mixed, --hard and revert","level":2,"icon":"lucide-undo-2","summary":"Make three commits, then move HEAD backwards in three different ways and see exactly which box each one changes.","qna":[{"q":"In which situation do we use this?","a":"A commit was wrong, too early or too big and you want to redo it, or you need to understand what HEAD actually does."},{"q":"Soft, mixed or hard?","a":"soft moves only HEAD, mixed also clears staging, hard also overwrites your files. Hard can destroy uncommitted work."},{"q":"What comes next?","a":"Module 5 uses branches so you rarely need to undo in the first place."}],"steps":[{"title":"Three commits, HEAD on the newest","icon":"lucide-git-commit","text":"Each line is a commit. HEAD points at the newest one through the branch name main. Remember the content: three lines.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Line one\"\necho \"Line two\" >> hello.txt && git commit -qam \"Line two\"\necho \"Line three\" >> hello.txt && git commit -qam \"Line three\"\ngit log --oneline --decorate","out":"$ git log --oneline --decorate\ne160e24 (HEAD -> main) Line three\n9f75459 Line two\n9300ecd Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"e160e24","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* e160e24 (HEAD -> main) Line three","* 9f75459 Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"reset --soft HEAD~1: move HEAD only","icon":"lucide-undo-2","text":"--soft moves HEAD back one commit and touches nothing else. The undone change is waiting in the staging area, ready to commit again. Working folder and staging keep line three.","cmd":"git reset --soft HEAD~1\ngit status --short\ngit log --oneline --decorate","out":"$ git status --short\nM  hello.txt\n\n$ git log --oneline --decorate\n9f75459 (HEAD -> main) Line two\n9300ecd Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9f75459","status":["M  hello.txt"],"staged":["M\thello.txt"],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* 9f75459 (HEAD -> main) Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Commit it again","icon":"lucide-save","text":"Because the change was still staged, a new commit recreates it. The hash differs from before: same content, new commit.","cmd":"git commit -qm \"Line three, again\"\ngit log --oneline --decorate","out":"$ git log --oneline --decorate\ne084910 (HEAD -> main) Line three, again\n9f75459 Line two\n9300ecd Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"e084910","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* e084910 (HEAD -> main) Line three, again","* 9f75459 Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"reset --mixed HEAD~1: move HEAD and clear staging","icon":"lucide-undo-2","text":"--mixed is the default. It moves HEAD and empties the staging area but keeps your file as it is. The change is still in the working folder, now unstaged.","cmd":"git reset HEAD~1\ngit status --short\ncat hello.txt","out":"$ git reset HEAD~1\nUnstaged changes after reset:\nM\thello.txt\n\n$ git status --short\n M hello.txt\n\n$ cat hello.txt\nHello Srinivas\nLine two\nLine three","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9f75459","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two"]]],"local":["* 9f75459 (HEAD -> main) Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"reset --hard HEAD~1: move HEAD and erase the change","icon":"lucide-eraser","text":"--hard moves HEAD and also overwrites the staging area and the working file. Line three is gone from the folder. Compare the four boxes: all of them now match commit two.","cmd":"git commit -qam \"Line three, final\"\ngit reset --hard HEAD~1\ncat hello.txt\ngit log --oneline --decorate","out":"$ git reset --hard HEAD~1\nHEAD is now at 9f75459 Line two\n\n$ cat hello.txt\nHello Srinivas\nLine two\n\n$ git log --oneline --decorate\n9f75459 (HEAD -> main) Line two\n9300ecd Line one","outKind":"recorded","note":"","risk":true,"viz":"","state":{"branch":"main","hash":"9f75459","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two"]]],"staging":[["hello.txt",["Hello Srinivas","Line two"]]],"local":["* 9f75459 (HEAD -> main) Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"reflog: find the lost commit and return","icon":"lucide-search","text":"Git remembers every place HEAD has been in the reflog, even after a hard reset. HEAD@{1} is where HEAD was one move ago. Resetting to it brings line three back.","cmd":"git reflog | head -n 6\ngit reset --hard HEAD@{1}\ncat hello.txt","out":"$ git reflog | head -n 6\n9f75459 HEAD@{0}: reset: moving to HEAD~1\n7ca5661 HEAD@{1}: commit: Line three, final\n9f75459 HEAD@{2}: reset: moving to HEAD~1\ne084910 HEAD@{3}: commit: Line three, again\n9f75459 HEAD@{4}: reset: moving to HEAD~1\ne160e24 HEAD@{5}: commit: Line three\n\n$ git reset --hard HEAD@{1}\nHEAD is now at 7ca5661 Line three, final\n\n$ cat hello.txt\nHello Srinivas\nLine two\nLine three","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"7ca5661","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* 7ca5661 (HEAD -> main) Line three, final","* 9f75459 Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"revert: undo a commit without rewriting history","icon":"lucide-git-merge","text":"revert adds a new commit that does the opposite of an old one. History only grows, so it is the safe way to undo something you already pushed.","cmd":"git revert --no-edit HEAD\ncat hello.txt\ngit log --oneline --decorate","out":"$ git revert --no-edit HEAD\n[main f45d452] Revert \"Line three, final\"\n Date: Mon Oct 26 13:30:20 2026 +0530\n 1 file changed, 1 deletion(-)\n\n$ cat hello.txt\nHello Srinivas\nLine two\n\n$ git log --oneline --decorate\nf45d452 (HEAD -> main) Revert \"Line three, final\"\n7ca5661 Line three, final\n9f75459 Line two\n9300ecd Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"f45d452","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two"]]],"staging":[["hello.txt",["Hello Srinivas","Line two"]]],"local":["* f45d452 (HEAD -> main) Revert \"Line three, final\"","* 7ca5661 Line three, final","* 9f75459 Line two","* 9300ecd Line one"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":4,"of":12,"prev":{"id":"hello-edit-diff-restore","title":"Module 3: Changes, diff, unstage and restore"},"next":{"id":"hello-branch-merge","title":"Module 5: Branches and merging hello.txt"}}},{"id":"hello-branch-merge","title":"Module 5: Branches and merging hello.txt","level":2,"icon":"lucide-git-branch","summary":"Create a branch, commit on it, then merge it back with a fast-forward and with a merge commit.","qna":[{"q":"In which situation do we use this?","a":"For any change you are unsure about: a feature, an experiment, a fix. main stays safe while you work."},{"q":"Fast-forward or merge commit?","a":"Fast-forward happens when the target has no new commits. A merge commit appears when both sides moved."},{"q":"What comes next?","a":"Module 6 handles the case where both sides edit the same line."}],"steps":[{"title":"Start with one commit","icon":"lucide-folder","text":"One commit on main. A branch is only a movable label on a commit, which is why creating one is instant.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\"\ngit branch","out":"$ git branch\n* main","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git switch -c: create and move to a branch","icon":"lucide-git-branch","text":"The new branch greeting points at the same commit as main. HEAD now points at greeting, so the next commit moves greeting, not main.","cmd":"git switch -c greeting\ngit branch\ngit log --oneline --decorate","out":"$ git switch -c greeting\nSwitched to a new branch 'greeting'\n\n$ git branch\n* greeting\n  main\n\n$ git log --oneline --decorate\n652b700 (HEAD -> greeting, main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"greeting","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> greeting, main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Commit on the branch; main stays behind","icon":"lucide-git-commit","text":"Add a line and commit. greeting moved forward; main did not. Switch back to main and the file loses the new line, because your working folder follows the branch you are on.","cmd":"echo \"Namaste\" >> hello.txt\ngit commit -qam \"Add Namaste\"\ngit switch main\ncat hello.txt\ngit log --oneline --graph --all --decorate","out":"$ git switch main\nSwitched to branch 'main'\n\n$ cat hello.txt\nHello Srinivas\n\n$ git log --oneline --graph --all --decorate\n* 0ee8742 (greeting) Add Namaste\n* 652b700 (HEAD -> main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 0ee8742 (greeting) Add Namaste","* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Fast-forward merge","icon":"lucide-git-merge","text":"main has no new commits of its own, so Git simply moves the main label forward to greeting. No merge commit is needed, and history stays a straight line.","cmd":"git merge greeting\ncat hello.txt\ngit log --oneline --graph --decorate","out":"$ git merge greeting\nUpdating 652b700..0ee8742\nFast-forward\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ cat hello.txt\nHello Srinivas\nNamaste\n\n$ git log --oneline --graph --decorate\n* 0ee8742 (HEAD -> main, greeting) Add Namaste\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"0ee8742","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Namaste"]]],"staging":[["hello.txt",["Hello Srinivas","Namaste"]]],"local":["* 0ee8742 (HEAD -> main, greeting) Add Namaste","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Both branches move: history diverges","icon":"lucide-git-branch","text":"Now footer adds a line to hello.txt while main adds a different file. Two lines of work started from the same commit. A fast-forward is no longer possible.","cmd":"git switch -c footer\necho \"Footer: Srinivas\" >> hello.txt && git commit -qam \"Add footer\"\ngit switch main\necho \"Header\" > header.txt && git add header.txt && git commit -qm \"Add header file\"\ngit log --oneline --graph --all --decorate","out":"$ git switch -c footer\nSwitched to a new branch 'footer'\n\n$ git switch main\nSwitched to branch 'main'\n\n$ git log --oneline --graph --all --decorate\n* f66b4bc (HEAD -> main) Add header file\n| * 1b35180 (footer) Add footer\n|/\n* 0ee8742 (greeting) Add Namaste\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"f66b4bc","status":[],"staged":[],"working":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste"]]],"staging":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste"]]],"local":["* f66b4bc (HEAD -> main) Add header file","| * 1b35180 (footer) Add footer","|/","* 0ee8742 (greeting) Add Namaste","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Merge commit: join the two lines of work","icon":"lucide-git-merge","text":"Because both sides have new commits, Git creates a merge commit with two parents. The changes touch different files, so Git combines them without asking you anything.","cmd":"git merge footer -m \"Merge footer into main\"\nls\ngit log --oneline --graph --decorate","out":"$ git merge footer -m \"Merge footer into main\"\nMerge made by the 'ort' strategy.\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ ls\nheader.txt\nhello.txt\n\n$ git log --oneline --graph --decorate\n*   96466f9 (HEAD -> main) Merge footer into main\n|\\\n| * 1b35180 (footer) Add footer\n* | f66b4bc Add header file\n|/\n* 0ee8742 (greeting) Add Namaste\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"96466f9","status":[],"staged":[],"working":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste","Footer: Srinivas"]]],"staging":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste","Footer: Srinivas"]]],"local":["*   96466f9 (HEAD -> main) Merge footer into main","|\\","| * 1b35180 (footer) Add footer","* | f66b4bc Add header file","|/","* 0ee8742 (greeting) Add Namaste","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Delete the finished branches","icon":"lucide-eraser","text":"A branch is just a label, so deleting it after the merge loses no commits. -d refuses if the branch is not merged, which protects you.","cmd":"git branch -d greeting footer\ngit branch","out":"$ git branch -d greeting footer\nDeleted branch greeting (was 0ee8742).\nDeleted branch footer (was 1b35180).\n\n$ git branch\n* main","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"96466f9","status":[],"staged":[],"working":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste","Footer: Srinivas"]]],"staging":[["header.txt",["Header"]],["hello.txt",["Hello Srinivas","Namaste","Footer: Srinivas"]]],"local":["*   96466f9 (HEAD -> main) Merge footer into main","|\\","| * 1b35180 Add footer","* | f66b4bc Add header file","|/","* 0ee8742 Add Namaste","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":5,"of":12,"prev":{"id":"hello-head-reset","title":"Module 4: Watch HEAD move: reset --soft, --mixed, --hard and revert"},"next":{"id":"hello-merge-conflict","title":"Module 6: A merge conflict on the same line"}}},{"id":"hello-merge-conflict","title":"Module 6: A merge conflict on the same line","level":2,"icon":"lucide-git-merge","summary":"Two branches change the same line of hello.txt. Git stops, you read the markers, decide, and finish the merge.","qna":[{"q":"In which situation do we use this?","a":"Two people, or two branches, changed the same lines. Git refuses to guess and asks you to decide."},{"q":"What goes wrong most often?","a":"Committing with the <<<<<<< markers still in the file. Search for them before running git add."},{"q":"What comes next?","a":"Module 7 shows how to avoid many merges by rebasing."}],"steps":[{"title":"Start with one commit","icon":"lucide-folder","text":"hello.txt has a single line. Both branches will edit exactly that line.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\"\ngit log --oneline","out":"$ git log --oneline\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Two branches edit the same line","icon":"lucide-pencil","text":"friendly says \"welcome\" and main says \"good morning\" on line one. Neither commit is wrong, but Git cannot know which to keep.","cmd":"git switch -qc friendly\necho \"Hello Srinivas, welcome\" > hello.txt && git commit -qam \"Friendly greeting\"\ngit switch -q main\necho \"Hello Srinivas, good morning\" > hello.txt && git commit -qam \"Morning greeting\"\ngit log --oneline --graph --all --decorate","out":"$ git log --oneline --graph --all --decorate\n* 8cc3f59 (HEAD -> main) Morning greeting\n| * 9cbdd0b (friendly) Friendly greeting\n|/\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"8cc3f59","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas, good morning"]]],"staging":[["hello.txt",["Hello Srinivas, good morning"]]],"local":["* 8cc3f59 (HEAD -> main) Morning greeting","| * 9cbdd0b (friendly) Friendly greeting","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git merge: Git stops with a conflict","icon":"lucide-triangle-alert","text":"The merge could not finish. The file is unmerged, and status marks it UU (both modified). HEAD has not moved yet: you are in the middle of a merge.","cmd":"git merge friendly\ngit status --short","out":"$ git merge friendly\nAuto-merging hello.txt\nCONFLICT (content): Merge conflict in hello.txt\nAutomatic merge failed; fix conflicts and then commit the result.\n\n$ git status --short\nUU hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"8cc3f59","status":["UU hello.txt"],"staged":["U\thello.txt"],"working":[["hello.txt",["<<<<<<< HEAD","Hello Srinivas, good morning","=======","Hello Srinivas, welcome",">>>>>>> friendly"]]],"staging":[["hello.txt",[]]],"local":["* 8cc3f59 (HEAD -> main) Morning greeting","| * 9cbdd0b (friendly) Friendly greeting","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Read the conflict markers","icon":"lucide-eye","text":"Git wrote both versions into the file. Above the ======= line is your side (HEAD), below it is the other branch. The markers are not valid content, so they must go before you commit.","cmd":"cat hello.txt","out":"$ cat hello.txt\n<<<<<<< HEAD\nHello Srinivas, good morning\n=======\nHello Srinivas, welcome\n>>>>>>> friendly","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"8cc3f59","status":["UU hello.txt"],"staged":["U\thello.txt"],"working":[["hello.txt",["<<<<<<< HEAD","Hello Srinivas, good morning","=======","Hello Srinivas, welcome",">>>>>>> friendly"]]],"staging":[["hello.txt",[]]],"local":["* 8cc3f59 (HEAD -> main) Morning greeting","| * 9cbdd0b (friendly) Friendly greeting","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Resolve: write the content you want","icon":"lucide-pencil","text":"Edit the file to the final text and remove every marker line. Here we combine both greetings. Then add it, which tells Git the conflict is solved.","cmd":"echo \"Hello Srinivas, welcome and good morning\" > hello.txt\ncat hello.txt\ngit add hello.txt\ngit status --short","out":"$ cat hello.txt\nHello Srinivas, welcome and good morning\n\n$ git status --short\nM  hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"8cc3f59","status":["M  hello.txt"],"staged":["M\thello.txt"],"working":[["hello.txt",["Hello Srinivas, welcome and good morning"]]],"staging":[["hello.txt",["Hello Srinivas, welcome and good morning"]]],"local":["* 8cc3f59 (HEAD -> main) Morning greeting","| * 9cbdd0b (friendly) Friendly greeting","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Finish the merge with a commit","icon":"lucide-save","text":"The merge commit has two parents and records your resolution. HEAD moves forward and the conflict is over. To give up instead, run git merge --abort before committing.","cmd":"git commit -qm \"Merge friendly: combine greetings\"\ngit log --oneline --graph --decorate","out":"$ git log --oneline --graph --decorate\n*   ef546d9 (HEAD -> main) Merge friendly: combine greetings\n|\\\n| * 9cbdd0b (friendly) Friendly greeting\n* | 8cc3f59 Morning greeting\n|/\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"ef546d9","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas, welcome and good morning"]]],"staging":[["hello.txt",["Hello Srinivas, welcome and good morning"]]],"local":["*   ef546d9 (HEAD -> main) Merge friendly: combine greetings","|\\","| * 9cbdd0b (friendly) Friendly greeting","* | 8cc3f59 Morning greeting","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":6,"of":12,"prev":{"id":"hello-branch-merge","title":"Module 5: Branches and merging hello.txt"},"next":{"id":"hello-rebase","title":"Module 7: Rebase and squash: a straight history"}}},{"id":"hello-rebase","title":"Module 7: Rebase and squash: a straight history","level":3,"icon":"lucide-git-merge","summary":"Replay your branch on top of the newest main, merge it as a straight line, and squash small commits into one.","qna":[{"q":"In which situation do we use this?","a":"Your branch is behind main and you want a straight history, or you want to squash noisy commits before review."},{"q":"When must I not rebase?","a":"Never on commits that others already pulled. Rebase gives commits new hashes and breaks their copies."},{"q":"What comes next?","a":"Module 8 puts several people on one remote."}],"steps":[{"title":"Start with one commit","icon":"lucide-folder","text":"One commit on main. We will make main and a feature branch each move on.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\"\ngit log --oneline","out":"$ git log --oneline\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Main and the feature both move","icon":"lucide-git-branch","text":"The feature branch changes hello.txt, main adds notes.txt. The branches have diverged, so merging would create a merge commit.","cmd":"git switch -qc feature\necho \"Feature line\" >> hello.txt && git commit -qam \"Feature: add line\"\ngit switch -q main\necho \"Notes\" > notes.txt && git add notes.txt && git commit -qm \"Add notes\"\ngit log --oneline --graph --all --decorate","out":"$ git log --oneline --graph --all --decorate\n* b58dff7 (HEAD -> main) Add notes\n| * d041cde (feature) Feature: add line\n|/\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"b58dff7","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]],["notes.txt",["Notes"]]],"staging":[["hello.txt",["Hello Srinivas"]],["notes.txt",["Notes"]]],"local":["* b58dff7 (HEAD -> main) Add notes","| * d041cde (feature) Feature: add line","|/","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git rebase main: replay the feature on top","icon":"lucide-git-merge","text":"Rebase lifts your feature commit off, moves the branch to the tip of main, and applies the commit again. The content is the same but it is a new commit with a new hash.","cmd":"git switch -q feature\ngit rebase main\ngit log --oneline --graph --all --decorate","out":"$ git rebase main\nRebasing (1/1)\nSuccessfully rebased and updated refs/heads/feature.\n\n$ git log --oneline --graph --all --decorate\n* 899914d (HEAD -> feature) Feature: add line\n* b58dff7 (main) Add notes\n* 652b700 Add hello.txt","outKind":"recorded","note":"Never rebase commits that other people have already pulled; the new hashes would confuse their copies.","risk":true,"viz":"","state":{"branch":"feature","hash":"899914d","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Feature line"]],["notes.txt",["Notes"]]],"staging":[["hello.txt",["Hello Srinivas","Feature line"]],["notes.txt",["Notes"]]],"local":["* 899914d (HEAD -> feature) Feature: add line","* b58dff7 (main) Add notes","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Merge it: now a fast-forward","icon":"lucide-git-merge","text":"The feature already sits directly on top of main, so merging just moves main forward. The history is one straight line, with no merge commit.","cmd":"git switch -q main\ngit merge feature\ngit log --oneline --graph --decorate","out":"$ git merge feature\nUpdating b58dff7..899914d\nFast-forward\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline --graph --decorate\n* 899914d (HEAD -> main, feature) Feature: add line\n* b58dff7 Add notes\n* 652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"899914d","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Feature line"]],["notes.txt",["Notes"]]],"staging":[["hello.txt",["Hello Srinivas","Feature line"]],["notes.txt",["Notes"]]],"local":["* 899914d (HEAD -> main, feature) Feature: add line","* b58dff7 Add notes","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Squash small commits into one","icon":"lucide-layers","text":"Make two work-in-progress commits, then fold the second into the first. fixup keeps the first commit's message and drops the second. GIT_SEQUENCE_EDITOR edits the todo list automatically here; normally you edit it in your editor.","cmd":"echo \"wip one\" >> hello.txt && git commit -qam \"wip: draft\"\necho \"wip two\" >> hello.txt && git commit -qam \"wip: fix typo\"\nGIT_SEQUENCE_EDITOR=\"sed -i.bak -e '2s/^pick/fixup/'\" git rebase -i HEAD~2\ngit log --oneline --decorate\ncat hello.txt","out":"$ GIT_SEQUENCE_EDITOR=\"sed -i.bak -e '2s/^pick/fixup/'\" git rebase -i HEAD~2\nRebasing (2/2)\nSuccessfully rebased and updated refs/heads/main.\n\n$ git log --oneline --decorate\n2203494 (HEAD -> main) wip: draft\n899914d (feature) Feature: add line\nb58dff7 Add notes\n652b700 Add hello.txt\n\n$ cat hello.txt\nHello Srinivas\nFeature line\nwip one\nwip two","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"2203494","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Feature line","wip one","wip two"]],["notes.txt",["Notes"]]],"staging":[["hello.txt",["Hello Srinivas","Feature line","wip one","wip two"]],["notes.txt",["Notes"]]],"local":["* 2203494 (HEAD -> main) wip: draft","* 899914d (feature) Feature: add line","* b58dff7 Add notes","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":7,"of":12,"prev":{"id":"hello-merge-conflict","title":"Module 6: A merge conflict on the same line"},"next":{"id":"hello-fetch-pull-team","title":"Module 8: Working with a teammate: fetch, pull and rejected pushes"}}},{"id":"hello-fetch-pull-team","title":"Module 8: Working with a teammate: fetch, pull and rejected pushes","level":2,"icon":"lucide-users","summary":"A teammate pushes to the server. See your remote box change, then use fetch, pull and pull --rebase.","qna":[{"q":"In which situation do we use this?","a":"Several people push to one repository. The daily loop is fetch or pull, commit, push."},{"q":"Why was my push rejected?","a":"Someone pushed first, so your copy is behind. Pull with --rebase, then push again."},{"q":"What comes next?","a":"Module 9 covers parking work and marking releases."}],"steps":[{"title":"Start: you and the server are in sync","icon":"lucide-cloud","text":"The server has your first commit and your local copy matches it. This is the clean starting point.","cmd":"git init -q --bare -b main ~/remote/hello.git\ngit clone -q ~/remote/hello.git ~/hello-git\ncd ~/hello-git\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\" && git push -q -u origin main\ngit log --oneline --decorate","out":"$ git clone -q ~/remote/hello.git ~/hello-git\nwarning: You appear to have cloned an empty repository.\n\n$ git log --oneline --decorate\n069c509 (HEAD -> main, origin/main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"A teammate pushes a change","icon":"lucide-users","text":"The teammate has their own clone in another folder. They add a line and push. Your folder is untouched, but look at the Remote box: the server is now one commit ahead of you.","cmd":"git clone -q ~/remote/hello.git ~/teammate\ncd ~/teammate\necho \"From the teammate\" >> hello.txt && git commit -qam \"Teammate line\" && git push -q\ncd ~/hello-git\ngit log --oneline --decorate","out":"$ git log --oneline --decorate\n069c509 (HEAD -> main, origin/main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 066d247 (HEAD -> main) Teammate line","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","From the teammate"]}},{"title":"git fetch: look without changing your files","icon":"lucide-download","text":"fetch downloads new commits into the remote-tracking branch origin/main but does not touch your branch or files. You can inspect first, then decide.","cmd":"git fetch\ngit log --oneline --graph --all --decorate\ncat hello.txt","out":"$ git fetch\nFrom /home/you/remote/hello\n   069c509..066d247  main       -> origin/main\n\n$ git log --oneline --graph --all --decorate\n* 066d247 (origin/main, origin/HEAD) Teammate line\n* 069c509 (HEAD -> main) Add hello.txt\n\n$ cat hello.txt\nHello Srinivas","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 066d247 (origin/main, origin/HEAD) Teammate line","* 069c509 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":["* 066d247 (HEAD -> main) Teammate line","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","From the teammate"]}},{"title":"git pull: fetch and bring it into your branch","icon":"lucide-download","text":"pull is fetch plus merge. Your branch had no commits of its own, so it just fast-forwards, and the teammate's line appears in your file.","cmd":"git pull\ncat hello.txt","out":"$ git pull\nUpdating 069c509..066d247\nFast-forward\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ cat hello.txt\nHello Srinivas\nFrom the teammate","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"066d247","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","From the teammate"]]],"staging":[["hello.txt",["Hello Srinivas","From the teammate"]]],"local":["* 066d247 (HEAD -> main, origin/main, origin/HEAD) Teammate","* 069c509 Add hello.txt"],"norepo":false,"remote":["* 066d247 (HEAD -> main) Teammate line","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","From the teammate"]}},{"title":"You commit while the teammate pushes: push is rejected","icon":"lucide-ban","text":"Both of you add a commit from the same starting point. The teammate pushes first, so your push is refused because the server has work you do not have.","cmd":"cd ~/teammate\necho \"Second teammate line\" >> hello.txt && git commit -qam \"Teammate again\" && git push -q\ncd ~/hello-git\necho \"Mine\" > mine.txt && git add mine.txt && git commit -qm \"Add mine.txt\"\ngit push","out":"$ git push\nTo /home/you/remote/hello.git\n ! [rejected]        main -> main (fetch first)\nerror: failed to push some refs to '/home/you/remote/hello.git'\nhint: Updates were rejected because the remote contains work that you do not\nhint: have locally. This is usually caused by another repository pushing to\nhint: the same ref. If you want to integrate the remote changes, use\nhint: 'git pull' before pushing again.\nhint: See the 'Note about fast-forwards' in 'git push --help' for details.","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"4c7d4b2","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","From the teammate"]],["mine.txt",["Mine"]]],"staging":[["hello.txt",["Hello Srinivas","From the teammate"]],["mine.txt",["Mine"]]],"local":["* 4c7d4b2 (HEAD -> main) Add mine.txt","* 066d247 (origin/main, origin/HEAD) Teammate line","* 069c509 Add hello.txt"],"norepo":false,"remote":["* ce737ce (HEAD -> main) Teammate again","* 066d247 Teammate line","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","From the teammate","Second teammate line"]}},{"title":"pull --rebase, then push","icon":"lucide-refresh-cw","text":"Rebase places your commit after the teammate's, so history stays straight, and then the push is accepted. This is the usual fix for a rejected push.","cmd":"git pull --rebase\ngit push\ngit log --oneline --graph --decorate","out":"$ git pull --rebase\nFrom /home/you/remote/hello\n   066d247..ce737ce  main       -> origin/main\nRebasing (1/1)\nSuccessfully rebased and updated refs/heads/main.\n\n$ git push\nTo /home/you/remote/hello.git\n   ce737ce..ed867f1  main -> main\n\n$ git log --oneline --graph --decorate\n* ed867f1 (HEAD -> main, origin/main, origin/HEAD) Add mine.txt\n* ce737ce Teammate again\n* 066d247 Teammate line\n* 069c509 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"ed867f1","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","From the teammate","Second teammate line"]],["mine.txt",["Mine"]]],"staging":[["hello.txt",["Hello Srinivas","From the teammate","Second teammate line"]],["mine.txt",["Mine"]]],"local":["* ed867f1 (HEAD -> main, origin/main, origin/HEAD) Add mine.","* ce737ce Teammate again","* 066d247 Teammate line","* 069c509 Add hello.txt"],"norepo":false,"remote":["* ed867f1 (HEAD -> main) Add mine.txt","* ce737ce Teammate again","* 066d247 Teammate line","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","From the teammate","Second teammate line"]}}],"nav":{"pos":8,"of":12,"prev":{"id":"hello-rebase","title":"Module 7: Rebase and squash: a straight history"},"next":{"id":"hello-stash-tags","title":"Module 9: Stash unfinished work and tag a release"}}},{"id":"hello-stash-tags","title":"Module 9: Stash unfinished work and tag a release","level":2,"icon":"lucide-bookmark","summary":"Park half-done changes safely, bring them back, and mark a version with a tag that you also push.","qna":[{"q":"In which situation do we use this?","a":"Stash when you must switch task or pull while your work is unfinished. Tag when a version is released."},{"q":"Does a normal push send tags?","a":"No. Push a tag by name or use --tags."},{"q":"What comes next?","a":"Module 10 goes back in time to old commits."}],"steps":[{"title":"Start with a committed hello.txt and a remote","icon":"lucide-cloud","text":"A clean repository connected to a server.","cmd":"git init -q --bare -b main ~/remote/hello.git\ngit clone -q ~/remote/hello.git ~/hello-git\ncd ~/hello-git\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\" && git push -q -u origin main\ngit status --short","out":"$ git clone -q ~/remote/hello.git ~/hello-git\nwarning: You appear to have cloned an empty repository.","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Half-done work appears","icon":"lucide-pencil","text":"You started a change but are not ready to commit. The working folder is dirty.","cmd":"echo \"Unfinished idea\" >> hello.txt\ngit status --short","out":"$ git status --short\n M hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"git stash: park it","icon":"lucide-save","text":"stash saves the working and staging changes on a shelf and returns the folder to the last commit. You can now switch branches or pull safely.","cmd":"git stash\ncat hello.txt\ngit stash list","out":"$ git stash\nSaved working directory and index state WIP on main: 069c509 Add hello.txt\n\n$ cat hello.txt\nHello Srinivas\n\n$ git stash list\nstash@{0}: WIP on main: 069c509 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"git stash pop: take it off the shelf","icon":"lucide-undo-2","text":"pop puts the saved change back into the working folder and removes it from the shelf. If the file changed meanwhile you may get a conflict to resolve.","cmd":"git stash pop\ncat hello.txt\ngit stash list","out":"$ git stash pop\nOn branch main\nYour branch is up to date with 'origin/main'.\n\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\tmodified:   hello.txt\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nDropped refs/stash@{0} (5cab45a4fab53dbcea463893be3685838c26a88a)\n\n$ cat hello.txt\nHello Srinivas\nUnfinished idea","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[" M hello.txt"],"staged":[],"working":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Commit it and mark release v1.0 with a tag","icon":"lucide-bookmark","text":"A tag is a permanent name for one commit. An annotated tag (-a) stores a message, author and date, which is right for releases.","cmd":"git commit -qam \"Add idea line\"\ngit tag -a v1.0 -m \"First release\"\ngit tag\ngit log --oneline --decorate","out":"$ git tag\nv1.0\n\n$ git log --oneline --decorate\ne80a057 (HEAD -> main, tag: v1.0) Add idea line\n069c509 (origin/main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"e80a057","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"staging":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"local":["* e80a057 (HEAD -> main, tag: v1.0) Add idea line","* 069c509 (origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Push the tag to the server","icon":"lucide-upload","text":"A normal push does not send tags. Push the tag by name, or all tags with --tags. Then describe tells you where HEAD is relative to the last tag.","cmd":"git push origin v1.0\ngit describe\ngit ls-remote --tags origin","out":"$ git push origin v1.0\nTo /home/you/remote/hello.git\n * [new tag]         v1.0 -> v1.0\n\n$ git describe\nv1.0\n\n$ git ls-remote --tags origin\n9ed5ac4b4cd1d2af2fde8d03e256820b33205a54\trefs/tags/v1.0\ne80a0575b2ff9492f694e05af7b77dc9490484f6\trefs/tags/v1.0^{}","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"e80a057","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"staging":[["hello.txt",["Hello Srinivas","Unfinished idea"]]],"local":["* e80a057 (HEAD -> main, tag: v1.0) Add idea line","* 069c509 (origin/main) Add hello.txt"],"norepo":false,"remote":["* e80a057 (tag: v1.0) Add idea line","* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}}],"nav":{"pos":9,"of":12,"prev":{"id":"hello-fetch-pull-team","title":"Module 8: Working with a teammate: fetch, pull and rejected pushes"},"next":{"id":"hello-detached-head","title":"Module 10: Time travel: checkout old commits and detached HEAD"}}},{"id":"hello-detached-head","title":"Module 10: Time travel: checkout old commits and detached HEAD","level":3,"icon":"lucide-clock","summary":"Move HEAD to an old commit, see the file as it was, learn why commits made there can be lost, and rescue them.","qna":[{"q":"In which situation do we use this?","a":"To see the project as it was at an old commit, or to find which commit broke something."},{"q":"What is a detached HEAD?","a":"HEAD points at a commit, not a branch. New commits there belong to no branch and can be lost, so create a branch if you want to keep them."},{"q":"What comes next?","a":"Module 11 covers moving and renaming files."}],"steps":[{"title":"Start with three commits","icon":"lucide-git-commit","text":"Three commits, each adding a line. We hide Git's long hint so the boxes stay readable; the lesson explains it.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q && git config advice.detachedHead false\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Line one\"\necho \"Line two\" >> hello.txt && git commit -qam \"Line two\"\necho \"Line three\" >> hello.txt && git commit -qam \"Line three\"\ngit log --oneline --decorate","out":"$ git log --oneline --decorate\n9c96e93 (HEAD -> main) Line three\n460e98e Line two\nac787ce Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9c96e93","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* 9c96e93 (HEAD -> main) Line three","* 460e98e Line two","* ac787ce Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Detach HEAD at an old commit","icon":"lucide-clock","text":"switch --detach points HEAD straight at a commit instead of at a branch name. Your folder now shows the file exactly as it was then: only one line. HEAD is \"detached\".","cmd":"git switch --detach HEAD~2\ncat hello.txt\ngit log --oneline --decorate","out":"$ git switch --detach HEAD~2\nHEAD is now at ac787ce Line one\n\n$ cat hello.txt\nHello Srinivas\n\n$ git log --oneline --decorate\nac787ce (HEAD) Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"(detached)","hash":"ac787ce","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 9c96e93 (main) Line three","* 460e98e Line two","* ac787ce (HEAD) Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Commit while detached","icon":"lucide-git-commit","text":"You can commit here, but no branch label follows this commit. It is reachable only from HEAD, so it can be lost once you move away.","cmd":"echo \"Side idea\" >> hello.txt && git commit -qam \"Side idea\"\ngit log --oneline --all --graph --decorate","out":"$ git log --oneline --all --graph --decorate\n* dc5a763 (HEAD) Side idea\n| * 9c96e93 (main) Line three\n| * 460e98e Line two\n|/\n* ac787ce Line one","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"(detached)","hash":"dc5a763","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Side idea"]]],"staging":[["hello.txt",["Hello Srinivas","Side idea"]]],"local":["* dc5a763 (HEAD) Side idea","| * 9c96e93 (main) Line three","| * 460e98e Line two","|/","* ac787ce Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Go back to main: the commit seems lost","icon":"lucide-triangle-alert","text":"Switching to main moves HEAD. The side commit is no longer on any branch, and it is gone from the log. It still exists for a while; the reflog knows its hash.","cmd":"git switch main\ncat hello.txt\ngit reflog | head -n 5","out":"$ git switch main\nWarning: you are leaving 1 commit behind, not connected to\nany of your branches:\n\n  dc5a763 Side idea\n\nSwitched to branch 'main'\n\n$ cat hello.txt\nHello Srinivas\nLine two\nLine three\n\n$ git reflog | head -n 5\n9c96e93 HEAD@{0}: checkout: moving from dc5a763a8e2fc28165e417f2cc7869e2aff1a280 to main\ndc5a763 HEAD@{1}: commit: Side idea\nac787ce HEAD@{2}: checkout: moving from main to HEAD~2\n9c96e93 HEAD@{3}: commit: Line three\n460e98e HEAD@{4}: commit: Line two","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"9c96e93","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* 9c96e93 (HEAD -> main) Line three","* 460e98e Line two","* ac787ce Line one"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Rescue it with a branch","icon":"lucide-undo-2","text":"Create a branch at the lost commit using the hash from the reflog. Now it has a name and is safe.","cmd":"git branch rescue HEAD@{1}\ngit log --oneline --all --graph --decorate\ngit show rescue:hello.txt","out":"$ git log --oneline --all --graph --decorate\n* dc5a763 (rescue) Side idea\n| * 9c96e93 (HEAD -> main) Line three\n| * 460e98e Line two\n|/\n* ac787ce Line one\n\n$ git show rescue:hello.txt\nHello Srinivas\nSide idea","outKind":"recorded","note":"The commit before the last switch is HEAD@{1}. Use the hash shown in your own reflog.","risk":false,"viz":"","state":{"branch":"main","hash":"9c96e93","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"staging":[["hello.txt",["Hello Srinivas","Line two","Line three"]]],"local":["* dc5a763 (rescue) Side idea","| * 9c96e93 (HEAD -> main) Line three","| * 460e98e Line two","|/","* ac787ce Line one"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":10,"of":12,"prev":{"id":"hello-stash-tags","title":"Module 9: Stash unfinished work and tag a release"},"next":{"id":"hello-move-rename-delete","title":"Module 11: Move, rename and delete files"}}},{"id":"hello-move-rename-delete","title":"Module 11: Move, rename and delete files","level":1,"icon":"lucide-folder","summary":"Rename and move hello.txt into a folder and delete files, with Git recording each change.","qna":[{"q":"In which situation do we use this?","a":"Reorganising a project: renaming files, moving them into folders, removing what is no longer needed."},{"q":"Does Git track renames?","a":"Git stores snapshots and detects renames by comparing content. Use git mv and log --follow to keep the trail clear."},{"q":"What comes next?","a":"Module 12 puts everything together in the team flow."}],"steps":[{"title":"Start with hello.txt committed","icon":"lucide-folder","text":"One tracked file at the top of the project.","cmd":"mkdir -p ~/hello-git && cd ~/hello-git\ngit init -q\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\"\nls","out":"$ ls\nhello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git mv: rename the file","icon":"lucide-repeat","text":"git mv renames in the working folder and stages the change in one go. Git sees a rename: the content is the same, only the path changed.","cmd":"git mv hello.txt greeting.txt\ngit status --short\nls","out":"$ git status --short\nR  hello.txt -> greeting.txt\n\n$ ls\ngreeting.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"652b700","status":["R  hello.txt -> greeting.txt"],"staged":["R100\thello.txt\tgreeting.txt"],"working":[["greeting.txt",["Hello Srinivas"]]],"staging":[["greeting.txt",["Hello Srinivas"]]],"local":["* 652b700 (HEAD -> main) Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Commit the rename","icon":"lucide-git-commit","text":"The rename is now part of history. Use log --follow to track a file across renames.","cmd":"git commit -qm \"Rename hello.txt to greeting.txt\"\ngit log --oneline --follow greeting.txt","out":"$ git log --oneline --follow greeting.txt\nf74b6c0 Rename hello.txt to greeting.txt\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"f74b6c0","status":[],"staged":[],"working":[["greeting.txt",["Hello Srinivas"]]],"staging":[["greeting.txt",["Hello Srinivas"]]],"local":["* f74b6c0 (HEAD -> main) Rename hello.txt to greeting.txt","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"Move it into a folder","icon":"lucide-folder","text":"Moving into a new directory is the same command. Git stores folders only through the files inside them.","cmd":"mkdir docs\ngit mv greeting.txt docs/greeting.txt\ngit commit -qm \"Move greeting into docs\"\nls -R\ngit log --oneline --follow docs/greeting.txt","out":"$ ls -R\ndocs\n\n./docs:\ngreeting.txt\n\n$ git log --oneline --follow docs/greeting.txt\n055fb82 Move greeting into docs\nf74b6c0 Rename hello.txt to greeting.txt\n652b700 Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"055fb82","status":[],"staged":[],"working":[["docs/greeting.txt",["Hello Srinivas"]]],"staging":[["docs/greeting.txt",["Hello Srinivas"]]],"local":["* 055fb82 (HEAD -> main) Move greeting into docs","* f74b6c0 Rename hello.txt to greeting.txt","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}},{"title":"git rm: delete a tracked file","icon":"lucide-eraser","text":"rm deletes the file and stages the deletion. The file still exists in older commits, so you can get it back with restore from a past commit.","cmd":"git rm docs/greeting.txt\ngit commit -qm \"Remove greeting\"\ngit ls-files\ngit restore --source=HEAD~1 docs/greeting.txt\ncat docs/greeting.txt","out":"$ git rm docs/greeting.txt\nrm 'docs/greeting.txt'\n\n$ cat docs/greeting.txt\nHello Srinivas","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"838fe0c","status":["?? docs/"],"staged":[],"working":[["docs/greeting.txt",["Hello Srinivas"]]],"staging":[],"local":["* 838fe0c (HEAD -> main) Remove greeting","* 055fb82 Move greeting into docs","* f74b6c0 Rename hello.txt to greeting.txt","* 652b700 Add hello.txt"],"norepo":false,"remote":null,"remoteFile":[]}}],"nav":{"pos":11,"of":12,"prev":{"id":"hello-detached-head","title":"Module 10: Time travel: checkout old commits and detached HEAD"},"next":{"id":"hello-pr-flow","title":"Module 12: Feature branch to pull request to merged"}}},{"id":"hello-pr-flow","title":"Module 12: Feature branch to pull request to merged","level":2,"icon":"lucide-rocket","summary":"Do the full team flow: branch, commit, push, merge as a pull request would, then clean up.","qna":[{"q":"In which situation do we use this?","a":"Any team using GitHub, GitLab or Bitbucket: branch, push, review, merge, clean up."},{"q":"Why delete the branch after merging?","a":"The commits are safe in main. Old branches clutter the list and confuse everyone."},{"q":"What comes next?","a":"Go deeper in the Git topic: bisect, worktrees, hooks, submodules and recovery."}],"steps":[{"title":"Start: main on the server","icon":"lucide-cloud","text":"The shared repository has hello.txt. Everyone works on branches and merges through pull requests.","cmd":"git init -q --bare -b main ~/remote/hello.git\ngit clone -q ~/remote/hello.git ~/hello-git\ncd ~/hello-git\necho \"Hello Srinivas\" > hello.txt && git add hello.txt && git commit -qm \"Add hello.txt\" && git push -q -u origin main\ngit branch -a","out":"$ git clone -q ~/remote/hello.git ~/hello-git\nwarning: You appear to have cloned an empty repository.\n\n$ git branch -a\n* main\n  remotes/origin/main","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"069c509","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas"]]],"staging":[["hello.txt",["Hello Srinivas"]]],"local":["* 069c509 (HEAD -> main, origin/main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Create a feature branch and commit","icon":"lucide-git-branch","text":"Never work directly on main. Make a branch named for the task and commit on it.","cmd":"git switch -c feature/welcome\necho \"Welcome to Git\" >> hello.txt && git commit -qam \"Add welcome line\"\ngit log --oneline --decorate","out":"$ git switch -c feature/welcome\nSwitched to a new branch 'feature/welcome'\n\n$ git log --oneline --decorate\n217b00d (HEAD -> feature/welcome) Add welcome line\n069c509 (origin/main, main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"feature/welcome","hash":"217b00d","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 217b00d (HEAD -> feature/welcome) Add welcome line","* 069c509 (origin/main, main) Add hello.txt"],"norepo":false,"remote":["* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"Push the branch to the server","icon":"lucide-upload","text":"The server now has your branch. On GitHub, GitLab or Bitbucket this is the moment the site offers \"Open pull request\" (or merge request).","cmd":"git push -u origin feature/welcome\ngit branch -vv","out":"$ git push -u origin feature/welcome\nTo /home/you/remote/hello.git\n * [new branch]      feature/welcome -> feature/welcome\nbranch 'feature/welcome' set up to track 'origin/feature/welcome'.\n\n$ git branch -vv\n* feature/welcome 217b00d [origin/feature/welcome] Add welcome line\n  main            069c509 [origin/main] Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"feature/welcome","hash":"217b00d","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["* 217b00d (HEAD -> feature/welcome, origin/feature/welcome)","* 069c509 (origin/main, main) Add hello.txt"],"norepo":false,"remote":["* 217b00d (feature/welcome) Add welcome line","* 069c509 (HEAD -> main) Add hello.txt"],"remoteFile":["Hello Srinivas"]}},{"title":"The pull request is merged on the server","icon":"lucide-git-merge","text":"A reviewer approves and presses Merge. We simulate that button with a merge in a second clone that pushes main. In your own clone, main is not updated yet.","cmd":"git clone -q ~/remote/hello.git ~/reviewer\ngit -C ~/reviewer merge --no-ff origin/feature/welcome -m \"Merge pull request #1 from feature/welcome\"\ngit -C ~/reviewer push -q origin main\ngit fetch\ngit log --oneline --graph --all --decorate","out":"$ git -C ~/reviewer merge --no-ff origin/feature/welcome -m \"Merge pull request #1 from feature/welcome\"\nMerge made by the 'ort' strategy.\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ git fetch\nFrom /home/you/remote/hello\n   069c509..b56e307  main       -> origin/main\n\n$ git log --oneline --graph --all --decorate\n*   b56e307 (origin/main, origin/HEAD) Merge pull request #1 from feature/welcome\n|\\\n| * 217b00d (HEAD -> feature/welcome, origin/feature/welcome) Add welcome line\n|/\n* 069c509 (main) Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"feature/welcome","hash":"217b00d","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["*   b56e307 (origin/main, origin/HEAD) Merge pull request #1","|\\","| * 217b00d (HEAD -> feature/welcome, origin/feature/welcome","|/","* 069c509 (main) Add hello.txt"],"norepo":false,"remote":["*   b56e307 (HEAD -> main) Merge pull request #1 from featur","|\\","| * 217b00d (feature/welcome) Add welcome line","|/","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","Welcome to Git"]}},{"title":"Update main and clean up","icon":"lucide-eraser","text":"Pull the merged main, then delete the finished branch locally and on the server. fetch --prune removes the stale remote-tracking name.","cmd":"git switch main\ngit pull\ngit branch -d feature/welcome\ngit push origin --delete feature/welcome\ngit fetch --prune\ngit branch -a","out":"$ git switch main\nSwitched to branch 'main'\nYour branch is behind 'origin/main' by 2 commits, and can be fast-forwarded.\n  (use \"git pull\" to update your local branch)\n\n$ git pull\nUpdating 069c509..b56e307\nFast-forward\n hello.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ git branch -d feature/welcome\nDeleted branch feature/welcome (was 217b00d).\n\n$ git push origin --delete feature/welcome\nTo /home/you/remote/hello.git\n - [deleted]         feature/welcome\n\n$ git branch -a\n* main\n  remotes/origin/HEAD -> origin/main\n  remotes/origin/main","outKind":"recorded","note":"","risk":false,"viz":"","state":{"branch":"main","hash":"b56e307","status":[],"staged":[],"working":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"staging":[["hello.txt",["Hello Srinivas","Welcome to Git"]]],"local":["*   b56e307 (HEAD -> main, origin/main, origin/HEAD) Merge p","|\\","| * 217b00d Add welcome line","|/","* 069c509 Add hello.txt"],"norepo":false,"remote":["*   b56e307 (HEAD -> main) Merge pull request #1 from featur","|\\","| * 217b00d Add welcome line","|/","* 069c509 Add hello.txt"],"remoteFile":["Hello Srinivas","Welcome to Git"]}}],"nav":{"pos":12,"of":12,"prev":{"id":"hello-move-rename-delete","title":"Module 11: Move, rename and delete files"},"next":null}}]},{"id":"git","name":"Git","color":"#F05133","tagline":"Version control from Hello World to branching, remotes, recovery and hooks. Every command here uses only local folders, so you can run all of it.","icon":"git-repo","workflows":[{"id":"git-first-repo","title":"Your first repo: from Hello World to a commit","level":1,"icon":"lucide-git-commit","summary":"Create hello.txt, understand the file, then init, add, commit, status and log, watching each area change.","qna":[{"q":"In which situation do we use this?","a":"Whenever a folder of work needs history: a script, a config set, lesson notes. Run git init once at the project root."},{"q":"When is it the wrong tool?","a":"For big binaries or secrets. Git stores every version forever, so keep passwords and large media out."},{"q":"What comes next?","a":"Learn the three areas (git-three-areas), then branching and remotes."}],"steps":[{"title":"Create a folder for the project","icon":"lucide-folder","text":"A Git repository is an ordinary folder that Git watches. Make one and move into it.","cmd":"mkdir -p ~/git-lab/hello-git\ncd ~/git-lab/hello-git\npwd","out":"$ pwd\n/home/you/git-lab/hello-git","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create hello.txt with \"Hello World\"","icon":"lucide-pencil","text":"echo prints text and the > symbol sends it into a file, creating it. Git does not know about this file yet.","cmd":"echo \"Hello World\" > hello.txt\nls\ncat hello.txt","out":"$ ls\nhello.txt\n\n$ cat hello.txt\nHello World","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Understand the file syntax","icon":"lucide-eye","text":"A .txt file is plain text: characters grouped into lines, each line ending with a newline character. cat -e shows that hidden end of line as a $ sign. wc -l counts lines and wc -c counts bytes: 11 visible characters plus the newline make 12.","cmd":"cat -e hello.txt\nwc -l hello.txt\nwc -c hello.txt","out":"$ cat -e hello.txt\nHello World$\n\n$ wc -l hello.txt\n1 hello.txt\n\n$ wc -c hello.txt\n12 hello.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git init: start tracking","icon":"lucide-settings","text":"git init creates a hidden .git folder. That folder is the repository: it holds every commit, branch and setting. Delete .git and the history is gone, but your files stay.","cmd":"git init\nls -a","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/hello-git/.git/\n\n$ ls -a\n.\n..\n.git\nhello.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git status: what does Git see?","icon":"lucide-search","text":"status compares three things: your folder, the staging area and the last commit. hello.txt is listed as untracked, meaning it exists but Git is not recording it yet.","cmd":"git status","out":"$ git status\nOn branch main\n\nNo commits yet\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\thello.txt\n\nnothing added to commit but untracked files present (use \"git add\" to track)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git add: stage the file","icon":"lucide-plus","text":"add copies the current content of hello.txt into the staging area, a waiting room for the next commit. Run status again and the file moves to \"Changes to be committed\".","cmd":"git add hello.txt\ngit status","out":"$ git status\nOn branch main\n\nNo commits yet\n\nChanges to be committed:\n  (use \"git rm --cached <file>...\" to unstage)\n\tnew file:   hello.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git commit: save a snapshot","icon":"lucide-save","text":"commit turns everything in the staging area into a permanent snapshot with a message. -m supplies the message so no editor opens. Write messages that finish the sentence \"This commit will...\".","cmd":"git commit -m \"Add hello.txt\"","out":"$ git commit -m \"Add hello.txt\"\n[main (root-commit) 8423b95] Add hello.txt\n 1 file changed, 1 insertion(+)\n create mode 100644 hello.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git log: read the history","icon":"lucide-file-text","text":"log lists commits, newest first. Each has a unique ID (a hash), an author, a date and the message. --oneline shows a short form.","cmd":"git log --oneline\ngit log","out":"$ git log --oneline\n8423b95 Add hello.txt\n\n$ git log\ncommit 8423b95f9e87659ee63db3d96d47695d437937f9\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:10:50 2026 +0530\n\n    Add hello.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Change the file and look at the difference","icon":"lucide-arrow-left-right","text":"Edit the file again. status now says \"modified\" and diff shows exactly what changed: lines starting with + were added.","cmd":"echo \"Hello Git\" >> hello.txt\ngit status --short\ngit diff","out":"$ git status --short\n M hello.txt\n\n$ git diff\ndiff --git a/hello.txt b/hello.txt\nindex 557db03..93f515c 100644\n--- a/hello.txt\n+++ b/hello.txt\n@@ -1 +1,2 @@\n Hello World\n+Hello Git","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Complete the cycle: add, commit, log","icon":"lucide-refresh-cw","text":"The everyday loop is edit, add, commit. Each pass adds one more snapshot to the history, and status ends clean.","cmd":"git add hello.txt\ngit commit -m \"Add greeting line\"\ngit log --oneline\ngit status","out":"$ git commit -m \"Add greeting line\"\n[main fffd78f] Add greeting line\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline\nfffd78f Add greeting line\n8423b95 Add hello.txt\n\n$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":31,"prev":null,"next":{"id":"git-three-areas","title":"Working directory, staging area, repository"}}},{"id":"git-three-areas","title":"Working directory, staging area, repository","level":1,"icon":"lucide-layers","summary":"The mental model behind every Git command: three places a change can live and the commands that move it between them.","qna":[{"q":"In which situation do we use this?","a":"When status output confuses you, or a commit holds the wrong files. Knowing folder, staging and commit tells you where a change is."},{"q":"What goes wrong without it?","a":"People commit half-finished edits because add copies the file as of that moment. Edit again after add and the new change is not staged."},{"q":"What comes next?","a":"git-status-diff to read changes, then git-undo-changes to move them between areas."}],"steps":[{"title":"Start with one commit","icon":"lucide-git-commit","text":"Make a repo with a single committed file so there is something to change.","cmd":"mkdir -p ~/git-lab/areas && cd ~/git-lab/areas\ngit init\necho \"v1\" > notes.txt\ngit add notes.txt\ngit commit -m \"Start notes\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/areas/.git/\n\n$ git commit -m \"Start notes\"\n[main (root-commit) 732c186] Start notes\n 1 file changed, 1 insertion(+)\n create mode 100644 notes.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Edit the file: only the working directory changes","icon":"lucide-pencil","text":"Your edit exists only in the working directory. Nothing is staged and nothing is committed. git diff compares the working directory with the staging area.","cmd":"echo \"v2\" >> notes.txt\ngit status --short\ngit diff","out":"$ git status --short\n M notes.txt\n\n$ git diff\ndiff --git a/notes.txt b/notes.txt\nindex 626799f..2139d8b 100644\n--- a/notes.txt\n+++ b/notes.txt\n@@ -1 +1,2 @@\n v1\n+v2","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git add: copy the change to the staging area","icon":"lucide-plus","text":"Now the change is staged. git diff shows nothing, because the working directory matches the staging area. git diff --staged compares the staging area with the last commit.","cmd":"git add notes.txt\ngit diff\ngit diff --staged","out":"$ git diff --staged\ndiff --git a/notes.txt b/notes.txt\nindex 626799f..2139d8b 100644\n--- a/notes.txt\n+++ b/notes.txt\n@@ -1 +1,2 @@\n v1\n+v2","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Edit again: the same file in two places","icon":"lucide-layers","text":"Editing after git add gives the file two versions. The staging area still holds v2, while the working directory has v3. The two letters in the short status show it: M in both columns.","cmd":"echo \"v3\" >> notes.txt\ngit status --short","out":"$ git status --short\nMM notes.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Commit saves only what is staged","icon":"lucide-save","text":"Commit snapshots the staging area, not your folder. That is why v3 is still waiting as an unstaged change afterwards.","cmd":"git commit -m \"Add v2\"\ngit status --short\ngit log --oneline","out":"$ git commit -m \"Add v2\"\n[main bb63cc3] Add v2\n 1 file changed, 1 insertion(+)\n\n$ git status --short\n M notes.txt\n\n$ git log --oneline\nbb63cc3 Add v2\n732c186 Start notes","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Stage and commit the rest","icon":"lucide-check","text":"git add -A stages every change in the project. Commit again and the working directory, staging area and repository all agree.","cmd":"git add -A\ngit commit -m \"Add v3\"\ngit status","out":"$ git commit -m \"Add v3\"\n[main c95dce5] Add v3\n 1 file changed, 1 insertion(+)\n\n$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":31,"prev":{"id":"git-first-repo","title":"Your first repo: from Hello World to a commit"},"next":{"id":"git-config-identity","title":"Configure Git: identity, defaults and aliases"}}},{"id":"git-config-identity","title":"Configure Git: identity, defaults and aliases","level":1,"icon":"lucide-sliders-horizontal","summary":"Tell Git who you are, set sensible defaults, add shortcuts and learn the three configuration levels.","qna":[{"q":"In which situation do we use this?","a":"On every new laptop, server or CI runner before the first commit. Commits carry your name and email permanently."},{"q":"What goes wrong if skipped?","a":"Commits get a wrong or generated identity, and later fixing it means rewriting history."},{"q":"What comes next?","a":"Set a global identity, then use includeIf or a per-repo setting for work and personal projects."}],"steps":[{"title":"Set your name and email","icon":"lucide-user","text":"Every commit records an author. Set it once with --global. Use the email you use on your Git host.","cmd":"git config --global user.name \"Alice Dev\"\ngit config --global user.email \"alice@example.com\"\ngit config --global user.name","out":"$ git config --global user.name\nAlice Dev","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Choose defaults","icon":"lucide-sliders-horizontal","text":"init.defaultBranch names the first branch of new repositories. pull.rebase false makes git pull merge, so its behaviour is explicit instead of a hint message.","cmd":"git config --global init.defaultBranch main\ngit config --global pull.rebase false\ngit config --global --list","out":"$ git config --global --list\nuser.name=Alice Dev\nuser.email=alice@example.com\ninit.defaultbranch=main\npull.rebase=false","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Add aliases","icon":"lucide-bookmark","text":"An alias is a shortcut stored in the configuration. Here st is a short status and lg is a compact history graph.","cmd":"git config --global alias.st \"status --short\"\ngit config --global alias.lg \"log --oneline --graph --decorate --all\"\nmkdir -p ~/git-lab/alias && cd ~/git-lab/alias && git init\necho hi > a.txt\ngit st","out":"$ mkdir -p ~/git-lab/alias && cd ~/git-lab/alias && git init\nInitialized empty Git repository in /home/you/git-lab/alias/.git/\n\n$ git st\n?? a.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Three levels of configuration","icon":"lucide-layers","text":"system applies to every user, global to you, and local to one repository. The most specific level wins. Use --show-scope to see where a value comes from.","cmd":"git config --local user.email \"alice@work.example\"\ngit config user.email\ngit config --show-scope user.email","out":"$ git config user.email\nalice@work.example\n\n$ git config --show-scope user.email\nlocal\talice@work.example","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Edit and unset a value","icon":"lucide-pencil","text":"Values live in plain text files: ~/.gitconfig for global and .git/config for local. Remove a value you no longer want with --unset.","cmd":"git config --local --unset user.email\ngit config user.email\ncat .git/config","out":"$ git config user.email\nalice@example.com\n\n$ cat .git/config\n[core]\n\trepositoryformatversion = 0\n\tfilemode = true\n\tbare = false\n\tlogallrefupdates = true\n\tignorecase = true\n\tprecomposeunicode = true","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":31,"prev":{"id":"git-three-areas","title":"Working directory, staging area, repository"},"next":{"id":"git-status-diff","title":"Read status and diff like a pro"}}},{"id":"git-status-diff","title":"Read status and diff like a pro","level":1,"icon":"lucide-arrow-left-right","summary":"Modified, new, deleted and untracked files in the long and short status, and the four useful forms of diff.","qna":[{"q":"In which situation do we use this?","a":"Before every add and every commit, to see exactly what will be saved. Make git status a reflex."},{"q":"Why use diff and not just status?","a":"status lists which files changed; diff shows which lines. Use diff --staged to review what the next commit contains."},{"q":"What comes next?","a":"If the diff shows a mistake, use git-undo-changes before committing."}],"steps":[{"title":"A repo with two files","icon":"lucide-folder","text":"Create two committed files so there is something to change.","cmd":"mkdir -p ~/git-lab/sd && cd ~/git-lab/sd\ngit init\necho \"alpha\" > a.txt\necho \"beta\" > b.txt\ngit add .\ngit commit -m \"Add a and b\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/sd/.git/\n\n$ git commit -m \"Add a and b\"\n[main (root-commit) 822e0b2] Add a and b\n 2 files changed, 2 insertions(+)\n create mode 100644 a.txt\n create mode 100644 b.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Modify one file, delete one, add one","icon":"lucide-pencil","text":"Three kinds of change at once: a.txt is modified, b.txt is deleted and c.txt is brand new.","cmd":"echo \"alpha two\" >> a.txt\nrm b.txt\necho \"gamma\" > c.txt\ngit status","out":"$ git status\nOn branch main\nChanges not staged for commit:\n  (use \"git add/rm <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\tmodified:   a.txt\n\tdeleted:    b.txt\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\tc.txt\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The short status","icon":"lucide-table","text":"Two columns before each name: the left is the staging area and the right is the working directory. M modified, D deleted and ?? untracked. A blank means no change in that column.","cmd":"git status --short","out":"$ git status --short\n M a.txt\n D b.txt\n?? c.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"git diff shows the content change","icon":"lucide-arrow-left-right","text":"diff lists changed lines for tracked files only. Lines starting with - were removed, + were added. The untracked c.txt does not appear.","cmd":"git diff","out":"$ git diff\ndiff --git a/a.txt b/a.txt\nindex 4a58007..d50109e 100644\n--- a/a.txt\n+++ b/a.txt\n@@ -1 +1,2 @@\n alpha\n+alpha two\ndiff --git a/b.txt b/b.txt\ndeleted file mode 100644\nindex 65b2df8..0000000\n--- a/b.txt\n+++ /dev/null\n@@ -1 +0,0 @@\n-beta","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A summary instead of the full patch","icon":"lucide-chart-line","text":"--stat shows files and the number of changed lines and --name-only lists just the names, handy for scripts.","cmd":"git diff --stat\ngit diff --name-only","out":"$ git diff --stat\n a.txt | 1 +\n b.txt | 1 -\n 2 files changed, 1 insertion(+), 1 deletion(-)\n\n$ git diff --name-only\na.txt\nb.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Stage some changes and compare again","icon":"lucide-plus","text":"After staging a.txt, plain diff no longer shows it. Use --staged for what the next commit will contain.","cmd":"git add a.txt\ngit diff --name-only\ngit diff --staged","out":"$ git diff --name-only\nb.txt\n\n$ git diff --staged\ndiff --git a/a.txt b/a.txt\nindex 4a58007..d50109e 100644\n--- a/a.txt\n+++ b/a.txt\n@@ -1 +1,2 @@\n alpha\n+alpha two","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":31,"prev":{"id":"git-config-identity","title":"Configure Git: identity, defaults and aliases"},"next":{"id":"git-undo-changes","title":"Undo mistakes safely"}}},{"id":"git-undo-changes","title":"Undo mistakes safely","level":2,"icon":"lucide-undo-2","summary":"Discard edits, unstage files, undo a commit with revert and move the branch back with reset --soft.","qna":[{"q":"In which situation do we use this?","a":"You edited the wrong file, staged too much, or want a file back as it was in the last commit."},{"q":"What is the risky part?","a":"git restore on a modified file discards your edits with no recovery, because they were never committed."},{"q":"What comes next?","a":"For committed mistakes, use git-cherry-pick-revert or git-reset-reflog."}],"steps":[{"title":"A repo with one good commit","icon":"lucide-git-commit","text":"Start from a clean state with one commit, so each undo has a known target.","cmd":"mkdir -p ~/git-lab/undo && cd ~/git-lab/undo\ngit init\necho \"good line\" > app.txt\ngit add app.txt\ngit commit -m \"Add app.txt\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/undo/.git/\n\n$ git commit -m \"Add app.txt\"\n[main (root-commit) 9ba4127] Add app.txt\n 1 file changed, 1 insertion(+)\n create mode 100644 app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Throw away an uncommitted edit","icon":"lucide-eraser","text":"git restore puts the file back to the last committed (or staged) version. The edit is gone for good because Git never saved it.","cmd":"echo \"oops\" >> app.txt\ncat app.txt\ngit restore app.txt\ncat app.txt","out":"$ cat app.txt\ngood line\noops\n\n$ cat app.txt\ngood line","outKind":"recorded","note":"","risk":true,"viz":""},{"title":"Unstage a file","icon":"lucide-minus","text":"git restore --staged removes a file from the staging area but keeps your edit in the working directory.","cmd":"echo \"not ready\" >> app.txt\ngit add app.txt\ngit status --short\ngit restore --staged app.txt\ngit status --short","out":"$ git status --short\nM  app.txt\n\n$ git status --short\n M app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clean up the leftover edit","icon":"lucide-eraser","text":"The edit is still in the working directory. Discard it to get back to a clean state.","cmd":"git restore app.txt\ngit status --short","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Undo a commit with revert","icon":"lucide-undo-2","text":"revert makes a new commit that cancels an old one. History is kept, so it is safe even after you have shared the commit.","cmd":"echo \"bad change\" >> app.txt\ngit commit -am \"Add bad change\"\ngit revert --no-edit HEAD\ngit log --oneline","out":"$ git commit -am \"Add bad change\"\n[main 4614c8f] Add bad change\n 1 file changed, 1 insertion(+)\n\n$ git revert --no-edit HEAD\n[main 84cbdd4] Revert \"Add bad change\"\n Date: Mon Oct 26 13:21:20 2026 +0530\n 1 file changed, 1 deletion(-)\n\n$ git log --oneline\n84cbdd4 Revert \"Add bad change\"\n4614c8f Add bad change\n9ba4127 Add app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Undo a commit that is not shared: reset --soft","icon":"lucide-arrow-up","text":"reset --soft moves the branch back one commit and leaves the changes staged, ready to commit again with a better message. Only do this for commits nobody else has.","cmd":"echo \"small step\" >> app.txt\ngit commit -am \"Too early commit\"\ngit reset --soft HEAD~1\ngit status --short\ngit commit -m \"Add small step properly\"\ngit log --oneline","out":"$ git commit -am \"Too early commit\"\n[main 69c74ac] Too early commit\n 1 file changed, 1 insertion(+)\n\n$ git status --short\nM  app.txt\n\n$ git commit -m \"Add small step properly\"\n[main 6fd166d] Add small step properly\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline\n6fd166d Add small step properly\n84cbdd4 Revert \"Add bad change\"\n4614c8f Add bad change\n9ba4127 Add app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The safety net: reflog","icon":"lucide-search","text":"reflog records every place HEAD has pointed, including commits you thought were lost. It is how you recover from most mistakes.","cmd":"git reflog -n 6","out":"$ git reflog -n 6\n6fd166d HEAD@{0}: commit: Add small step properly\n84cbdd4 HEAD@{1}: reset: moving to HEAD~1\n69c74ac HEAD@{2}: commit: Too early commit\n84cbdd4 HEAD@{3}: revert: Revert \"Add bad change\"\n4614c8f HEAD@{4}: commit: Add bad change\n9ba4127 HEAD@{5}: commit (initial): Add app.txt","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":31,"prev":{"id":"git-status-diff","title":"Read status and diff like a pro"},"next":{"id":"git-gitignore","title":"Keep junk out with .gitignore"}}},{"id":"git-gitignore","title":"Keep junk out with .gitignore","level":1,"icon":"lucide-ban","summary":"Ignore logs and build output, find out why a file is ignored and stop tracking a file that was committed by mistake.","qna":[{"q":"In which situation do we use this?","a":"At the start of a project: build output, node_modules, logs, .env files and editor folders should never be committed."},{"q":"Why does a file stay tracked after I ignore it?","a":".gitignore affects only untracked files. Remove an already tracked file from Git with git rm --cached."},{"q":"What comes next?","a":"Add a global ignore file for your own editor junk, and use git check-ignore to debug a rule."}],"steps":[{"title":"A project with files you do not want","icon":"lucide-folder","text":"A script plus a log file and a build folder. Git lists all three as untracked.","cmd":"mkdir -p ~/git-lab/ignore/build && cd ~/git-lab/ignore\ngit init\necho \"print('hi')\" > app.py\necho \"debug line\" > debug.log\necho \"binary\" > build/app.bin\ngit status --short","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/ignore/.git/\n\n$ git status --short\n?? app.py\n?? build/\n?? debug.log","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create .gitignore","icon":"lucide-pencil","text":"One pattern per line. *.log matches any file ending in .log and a trailing slash matches a folder. Now only the useful files remain untracked.","cmd":"echo \"*.log\" > .gitignore\necho \"build/\" >> .gitignore\ncat .gitignore\ngit status --short","out":"$ cat .gitignore\n*.log\nbuild/\n\n$ git status --short\n?? .gitignore\n?? app.py","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Ask why a file is ignored","icon":"lucide-search","text":"check-ignore -v prints the exact rule and line that matched. It is the fastest way to debug an ignore pattern.","cmd":"git check-ignore -v debug.log build/app.bin","out":"$ git check-ignore -v debug.log build/app.bin\n.gitignore:1:*.log\tdebug.log\n.gitignore:2:build/\tbuild/app.bin","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Commit the right files","icon":"lucide-save","text":"Commit the source and the .gitignore itself, so everyone shares the same rules.","cmd":"git add .gitignore app.py\ngit commit -m \"Add app and gitignore\"\ngit status --short","out":"$ git commit -m \"Add app and gitignore\"\n[main (root-commit) 16cbb09] Add app and gitignore\n 2 files changed, 3 insertions(+)\n create mode 100644 .gitignore\n create mode 100644 app.py","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fix a file that is already tracked","icon":"lucide-triangle-alert","text":"Ignore rules only affect untracked files. If you committed .env by mistake, adding it to .gitignore is not enough. git rm --cached stops tracking it but keeps your local copy.","cmd":"echo \"SECRET=1\" > .env\ngit add -f .env\ngit commit -m \"Oops: add .env\"\necho \".env\" >> .gitignore\ngit rm --cached .env\ngit commit -am \"Stop tracking .env\"\ngit status --short","out":"$ git commit -m \"Oops: add .env\"\n[main 1e41252] Oops: add .env\n 1 file changed, 1 insertion(+)\n create mode 100644 .env\n\n$ git rm --cached .env\nrm '.env'\n\n$ git commit -am \"Stop tracking .env\"\n[main bec2d85] Stop tracking .env\n 2 files changed, 1 insertion(+), 1 deletion(-)\n delete mode 100644 .env","outKind":"recorded","note":"The secret is still in the older commit. If it was ever pushed, treat it as leaked and rotate it.","risk":false,"viz":""}],"nav":{"pos":6,"of":31,"prev":{"id":"git-undo-changes","title":"Undo mistakes safely"},"next":{"id":"git-branching","title":"Branching: work on a copy without breaking main"}}},{"id":"git-branching","title":"Branching: work on a copy without breaking main","level":1,"icon":"lucide-git-branch","summary":"Create, switch, compare and delete branches, and see that each branch has its own files.","qna":[{"q":"In which situation do we use this?","a":"For any change you are not sure about: a feature, an experiment, a fix. main stays clean while you work."},{"q":"When should a branch be deleted?","a":"After it is merged. Short-lived branches keep history readable and avoid painful merges."},{"q":"What comes next?","a":"Bring the branch back with git-merge or git-rebase."}],"steps":[{"title":"Start with one commit on main","icon":"lucide-git-commit","text":"A branch is just a movable label on a commit. Create a repo with one commit.","cmd":"mkdir -p ~/git-lab/branching && cd ~/git-lab/branching\ngit init\necho \"home page\" > index.txt\ngit add index.txt\ngit commit -m \"Add home page\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/branching/.git/\n\n$ git commit -m \"Add home page\"\n[main (root-commit) 9fc45cf] Add home page\n 1 file changed, 1 insertion(+)\n create mode 100644 index.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create a branch and switch to it","icon":"lucide-git-branch","text":"switch -c creates a branch and moves to it in one step. The star marks the branch you are on.","cmd":"git switch -c feature/login\ngit branch","out":"$ git switch -c feature/login\nSwitched to a new branch 'feature/login'\n\n$ git branch\n* feature/login\n  main","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Commit on the branch","icon":"lucide-save","text":"This commit belongs to feature/login only. main has not moved.","cmd":"echo \"login page\" > login.txt\ngit add login.txt\ngit commit -m \"Add login page\"\ngit log --oneline --graph --all","out":"$ git commit -m \"Add login page\"\n[feature/login 931142a] Add login page\n 1 file changed, 1 insertion(+)\n create mode 100644 login.txt\n\n$ git log --oneline --graph --all\n* 931142a Add login page\n* 9fc45cf Add home page","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Switch back: your files change","icon":"lucide-repeat","text":"Git rewrites your working directory to match the branch. On main the login file does not exist. Switch back and it returns.","cmd":"git switch main\nls\ngit switch feature/login\nls","out":"$ git switch main\nSwitched to branch 'main'\n\n$ ls\nindex.txt\n\n$ git switch feature/login\nSwitched to branch 'feature/login'\n\n$ ls\nindex.txt\nlogin.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Compare the branches","icon":"lucide-arrow-left-right","text":"main..feature/login lists the commits on the feature branch that main does not have yet.","cmd":"git branch -v\ngit log main..feature/login --oneline","out":"$ git branch -v\n* feature/login 931142a Add login page\n  main          9fc45cf Add home page\n\n$ git log main..feature/login --oneline\n931142a Add login page","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Rename, merge and delete","icon":"lucide-eraser","text":"-d deletes a branch only when its work is merged, and refuses otherwise. That refusal is a safety feature. Merge first, then delete.","cmd":"git branch -m feature/login feature/sign-in\ngit switch main\ngit branch -d feature/sign-in\ngit merge feature/sign-in\ngit branch -d feature/sign-in","out":"$ git switch main\nSwitched to branch 'main'\n\n$ git branch -d feature/sign-in\nerror: the branch 'feature/sign-in' is not fully merged\nhint: If you are sure you want to delete it, run 'git branch -D feature/sign-in'\nhint: Disable this message with \"git config set advice.forceDeleteBranch false\"\n\n$ git merge feature/sign-in\nUpdating 9fc45cf..931142a\nFast-forward\n login.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 login.txt\n\n$ git branch -d feature/sign-in\nDeleted branch feature/sign-in (was 931142a).","outKind":"recorded","note":"git branch -D deletes without checking. Use it only when you are sure the work is not needed.","risk":false,"viz":""}],"nav":{"pos":7,"of":31,"prev":{"id":"git-gitignore","title":"Keep junk out with .gitignore"},"next":{"id":"git-merge","title":"Merging: fast-forward and merge commits"}}},{"id":"git-merge","title":"Merging: fast-forward and merge commits","level":2,"icon":"lucide-git-merge","summary":"See the two kinds of merge: a simple fast-forward and a true merge commit with two parents.","qna":[{"q":"In which situation do we use this?","a":"A feature is finished and its history should be preserved in main. A merge commit records where the work joined."},{"q":"What is a fast-forward merge?","a":"When main has not moved, Git just moves the branch pointer and makes no merge commit. Use --no-ff to force one."},{"q":"What comes next?","a":"If both branches changed the same lines, follow git-merge-conflict."}],"steps":[{"title":"Set up the base","icon":"lucide-git-commit","text":"One commit on main to start from.","cmd":"mkdir -p ~/git-lab/merge && cd ~/git-lab/merge\ngit init\necho \"base\" > base.txt\ngit add base.txt\ngit commit -m \"Add base\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/merge/.git/\n\n$ git commit -m \"Add base\"\n[main (root-commit) 2a724e5] Add base\n 1 file changed, 1 insertion(+)\n create mode 100644 base.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A branch that main has not left behind","icon":"lucide-git-branch","text":"Create feature-a and commit once. Because main did not change meanwhile, main can simply catch up.","cmd":"git switch -c feature-a\necho \"a\" > a.txt\ngit add a.txt\ngit commit -m \"Add a\"\ngit switch main","out":"$ git switch -c feature-a\nSwitched to a new branch 'feature-a'\n\n$ git commit -m \"Add a\"\n[feature-a 2b2fa15] Add a\n 1 file changed, 1 insertion(+)\n create mode 100644 a.txt\n\n$ git switch main\nSwitched to branch 'main'","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fast-forward merge","icon":"lucide-arrow-up","text":"No new commit is needed. Git just moves the main label forward to the same commit as feature-a. History stays a straight line.","cmd":"git merge feature-a\ngit log --oneline --graph","out":"$ git merge feature-a\nUpdating 2a724e5..2b2fa15\nFast-forward\n a.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 a.txt\n\n$ git log --oneline --graph\n* 2b2fa15 Add a\n* 2a724e5 Add base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Make the branches diverge","icon":"lucide-repeat","text":"Now give feature-b one commit and main a different one. Neither branch contains the other's work.","cmd":"git switch -c feature-b\necho \"b\" > b.txt\ngit add b.txt\ngit commit -m \"Add b\"\ngit switch main\necho \"main change\" > main.txt\ngit add main.txt\ngit commit -m \"Add main change\"","out":"$ git switch -c feature-b\nSwitched to a new branch 'feature-b'\n\n$ git commit -m \"Add b\"\n[feature-b 07e2d87] Add b\n 1 file changed, 1 insertion(+)\n create mode 100644 b.txt\n\n$ git switch main\nSwitched to branch 'main'\n\n$ git commit -m \"Add main change\"\n[main 44da36e] Add main change\n 1 file changed, 1 insertion(+)\n create mode 100644 main.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A true merge creates a merge commit","icon":"lucide-git-merge","text":"Git combines the two lines of work into a new commit that has two parents. -m gives it a message so no editor opens.","cmd":"git merge feature-b -m \"Merge feature-b\"\ngit log --oneline --graph","out":"$ git merge feature-b -m \"Merge feature-b\"\nMerge made by the 'ort' strategy.\n b.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 b.txt\n\n$ git log --oneline --graph\n*   d9f4c5a Merge feature-b\n|\\\n| * 07e2d87 Add b\n* | 44da36e Add main change\n|/\n* 2b2fa15 Add a\n* 2a724e5 Add base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Read the graph","icon":"lucide-eye","text":"The graph shows the fork and the join. Use --parents to see the two parent hashes of the merge commit, and -m with show to see changes against each parent.","cmd":"git log --oneline --graph --all\ngit show --no-patch --pretty=%P HEAD","out":"$ git log --oneline --graph --all\n*   d9f4c5a Merge feature-b\n|\\\n| * 07e2d87 Add b\n* | 44da36e Add main change\n|/\n* 2b2fa15 Add a\n* 2a724e5 Add base\n\n$ git show --no-patch --pretty=%P HEAD\n44da36e4b91bf4420481cc9df99c085a0ea0300f 07e2d877e1c9ff753cdd71bb5bb808e2727e33e4","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":31,"prev":{"id":"git-branching","title":"Branching: work on a copy without breaking main"},"next":{"id":"git-merge-conflict","title":"Resolve a merge conflict"}}},{"id":"git-merge-conflict","title":"Resolve a merge conflict","level":2,"icon":"lucide-triangle-alert","summary":"Make two branches edit the same line, read the conflict markers, choose the result and finish the merge.","qna":[{"q":"In which situation do we use this?","a":"Two people changed the same lines, or one deleted a file the other edited. Git cannot choose, so you decide."},{"q":"What goes wrong?","a":"Committing with the <<<<<<< markers still in the file. Search for the markers before git add."},{"q":"What comes next?","a":"Run your tests, commit the resolution, and turn on rerere in git-aliases-tips to reuse resolutions."}],"steps":[{"title":"A shared starting file","icon":"lucide-git-commit","text":"One file with one line, committed on main.","cmd":"mkdir -p ~/git-lab/conflict && cd ~/git-lab/conflict\ngit init\necho \"greeting: hello\" > app.txt\ngit add app.txt\ngit commit -m \"Add greeting\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/conflict/.git/\n\n$ git commit -m \"Add greeting\"\n[main (root-commit) a1ab07c] Add greeting\n 1 file changed, 1 insertion(+)\n create mode 100644 app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Change the line on a branch","icon":"lucide-git-branch","text":"On feature, rewrite the line one way.","cmd":"git switch -c feature\necho \"greeting: hello team\" > app.txt\ngit commit -am \"Greet the team\"","out":"$ git switch -c feature\nSwitched to a new branch 'feature'\n\n$ git commit -am \"Greet the team\"\n[feature a0cd16a] Greet the team\n 1 file changed, 1 insertion(+), 1 deletion(-)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Change the same line on main","icon":"lucide-repeat","text":"On main, rewrite the same line a different way. Git cannot know which one you want.","cmd":"git switch main\necho \"greeting: hello world\" > app.txt\ngit commit -am \"Greet the world\"","out":"$ git switch main\nSwitched to branch 'main'\n\n$ git commit -am \"Greet the world\"\n[main 0f0cb73] Greet the world\n 1 file changed, 1 insertion(+), 1 deletion(-)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Merge: Git stops and reports a conflict","icon":"lucide-triangle-alert","text":"The merge pauses with the file marked UU, unmerged on both sides. Nothing is lost. You are in the middle of a merge and can still cancel it with git merge --abort.","cmd":"git merge feature\ngit status --short","out":"$ git merge feature\nAuto-merging app.txt\nCONFLICT (content): Merge conflict in app.txt\nAutomatic merge failed; fix conflicts and then commit the result.\n\n$ git status --short\nUU app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Read the conflict markers","icon":"lucide-eye","text":"Git wrote both versions into the file. Between <<<<<<< and ======= is your side (HEAD), and between ======= and >>>>>>> is the other branch. Edit the file to the final text and delete all three marker lines.","cmd":"cat app.txt","out":"$ cat app.txt\n<<<<<<< HEAD\ngreeting: hello world\n=======\ngreeting: hello team\n>>>>>>> feature","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Resolve, stage and finish the merge","icon":"lucide-check","text":"Write the result you want, mark the file resolved with git add, then commit to complete the merge.","cmd":"echo \"greeting: hello team and world\" > app.txt\ngit add app.txt\ngit commit -m \"Merge feature: combine greetings\"\ngit log --oneline --graph","out":"$ git commit -m \"Merge feature: combine greetings\"\n[main 1ab33a2] Merge feature: combine greetings\n\n$ git log --oneline --graph\n*   1ab33a2 Merge feature: combine greetings\n|\\\n| * a0cd16a Greet the team\n* | 0f0cb73 Greet the world\n|/\n* a1ab07c Add greeting","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":9,"of":31,"prev":{"id":"git-merge","title":"Merging: fast-forward and merge commits"},"next":{"id":"git-rebase","title":"Rebase: a straight line of history"}}},{"id":"git-rebase","title":"Rebase: a straight line of history","level":3,"icon":"lucide-refresh-cw","summary":"Move a branch on top of the latest main, compare it with merging and learn when never to rebase.","qna":[{"q":"In which situation do we use this?","a":"Your feature branch is behind main and you want a straight history without merge commits."},{"q":"When must I not rebase?","a":"Never on commits other people already pulled. Rebase rewrites commit IDs, which breaks their copies."},{"q":"What comes next?","a":"git-rebase-interactive to squash and reword, or git-reset-reflog if it goes wrong."}],"steps":[{"title":"Base commit","icon":"lucide-git-commit","text":"Start with one commit on main.","cmd":"mkdir -p ~/git-lab/rebase && cd ~/git-lab/rebase\ngit init\necho \"base\" > base.txt\ngit add base.txt\ngit commit -m \"Add base\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/rebase/.git/\n\n$ git commit -m \"Add base\"\n[main (root-commit) 2a724e5] Add base\n 1 file changed, 1 insertion(+)\n create mode 100644 base.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Two commits on a feature branch","icon":"lucide-git-branch","text":"The feature work starts from the base commit.","cmd":"git switch -c feature\necho \"one\" > f1.txt\ngit add f1.txt\ngit commit -m \"Feature part 1\"\necho \"two\" > f2.txt\ngit add f2.txt\ngit commit -m \"Feature part 2\"","out":"$ git switch -c feature\nSwitched to a new branch 'feature'\n\n$ git commit -m \"Feature part 1\"\n[feature 4510b9a] Feature part 1\n 1 file changed, 1 insertion(+)\n create mode 100644 f1.txt\n\n$ git commit -m \"Feature part 2\"\n[feature 710c560] Feature part 2\n 1 file changed, 1 insertion(+)\n create mode 100644 f2.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"main moves on","icon":"lucide-repeat","text":"Meanwhile someone adds a commit to main, so the branches have diverged.","cmd":"git switch main\necho \"hotfix\" > hotfix.txt\ngit add hotfix.txt\ngit commit -m \"Add hotfix\"\ngit log --oneline --graph --all","out":"$ git switch main\nSwitched to branch 'main'\n\n$ git commit -m \"Add hotfix\"\n[main 2683d6c] Add hotfix\n 1 file changed, 1 insertion(+)\n create mode 100644 hotfix.txt\n\n$ git log --oneline --graph --all\n* 2683d6c Add hotfix\n| * 710c560 Feature part 2\n| * 4510b9a Feature part 1\n|/\n* 2a724e5 Add base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Rebase feature onto main","icon":"lucide-refresh-cw","text":"Rebase replays your feature commits on top of the latest main. They get new IDs because their parent changed. The history becomes a straight line with no merge commit.","cmd":"git switch feature\ngit rebase main\ngit log --oneline --graph --all","out":"$ git switch feature\nSwitched to branch 'feature'\n\n$ git rebase main\nRebasing (1/2)\nRebasing (2/2)\nSuccessfully rebased and updated refs/heads/feature.\n\n$ git log --oneline --graph --all\n* 3d308b5 Feature part 2\n* 0303a3a Feature part 1\n* 2683d6c Add hotfix\n* 2a724e5 Add base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fast-forward main","icon":"lucide-arrow-up","text":"Now main is an ancestor of feature, so merging is a plain fast-forward.","cmd":"git switch main\ngit merge feature\ngit log --oneline --graph","out":"$ git switch main\nSwitched to branch 'main'\n\n$ git merge feature\nUpdating 2683d6c..3d308b5\nFast-forward\n f1.txt | 1 +\n f2.txt | 1 +\n 2 files changed, 2 insertions(+)\n create mode 100644 f1.txt\n create mode 100644 f2.txt\n\n$ git log --oneline --graph\n* 3d308b5 Feature part 2\n* 0303a3a Feature part 1\n* 2683d6c Add hotfix\n* 2a724e5 Add base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The golden rule","icon":"lucide-shield","text":"Rebase rewrites commits. Only rebase work that is still local to you. Never rebase commits that others have pulled, because their copies will no longer match yours. If you must update a branch you already pushed, use git push --force-with-lease and tell the team.","cmd":"","out":"","outKind":"","note":"When in doubt, merge. It never rewrites history.","risk":false,"viz":""}],"nav":{"pos":10,"of":31,"prev":{"id":"git-merge-conflict","title":"Resolve a merge conflict"},"next":{"id":"git-remote-push","title":"Work with a remote: push, clone and pull"}}},{"id":"git-remote-push","title":"Work with a remote: push, clone and pull","level":2,"icon":"lucide-cloud","summary":"Use a bare repository as a stand-in for GitHub: add a remote, push, clone as a teammate and pull their change.","qna":[{"q":"In which situation do we use this?","a":"To share work or back it up: the first push of a new project, or publishing a branch for review."},{"q":"What does push -u do?","a":"It links your local branch to the remote one, so later git push and git pull need no arguments."},{"q":"What comes next?","a":"git-collaborate for the day-to-day loop with teammates."}],"steps":[{"title":"Create the \"server\" repository","icon":"lucide-server","text":"A bare repository has no working files, just the history. It is what a Git host stores. Here it is only a folder, so everything runs locally.","cmd":"mkdir -p ~/git-lab/remote && cd ~/git-lab/remote\ngit init --bare origin.git","out":"$ git init --bare origin.git\nInitialized empty Git repository in /home/you/git-lab/remote/origin.git/","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Your local project with a commit","icon":"lucide-git-commit","text":"Make an ordinary repo and commit a README.","cmd":"mkdir -p ~/git-lab/project && cd ~/git-lab/project\ngit init\necho \"# Project\" > README.md\ngit add README.md\ngit commit -m \"Add README\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/project/.git/\n\n$ git commit -m \"Add README\"\n[main (root-commit) 999621a] Add README\n 1 file changed, 1 insertion(+)\n create mode 100644 README.md","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Add the remote and push","icon":"lucide-upload","text":"A remote is a named URL. origin is the conventional name. push -u uploads main and remembers it as the default upstream.","cmd":"git remote add origin ~/git-lab/remote/origin.git\ngit remote -v\ngit push -u origin main","out":"$ git remote -v\norigin\t/home/you/git-lab/remote/origin.git (fetch)\norigin\t/home/you/git-lab/remote/origin.git (push)\n\n$ git push -u origin main\nTo /home/you/git-lab/remote/origin.git\n * [new branch]      main -> main\nbranch 'main' set up to track 'origin/main'.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clone as a teammate","icon":"lucide-users","text":"clone copies the whole history and sets origin automatically.","cmd":"git clone ~/git-lab/remote/origin.git ~/git-lab/teammate\ncd ~/git-lab/teammate\ngit log --oneline\ngit branch -vv","out":"$ git clone ~/git-lab/remote/origin.git ~/git-lab/teammate\nCloning into '/home/you/git-lab/teammate'...\ndone.\n\n$ git log --oneline\n999621a Add README\n\n$ git branch -vv\n* main 999621a [origin/main] Add README","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The teammate pushes a change","icon":"lucide-upload","text":"They edit, commit and push, with no extra arguments needed this time.","cmd":"echo \"More docs\" >> README.md\ngit commit -am \"Update README\"\ngit push","out":"$ git commit -am \"Update README\"\n[main a6d1c47] Update README\n 1 file changed, 1 insertion(+)\n\n$ git push\nTo /home/you/git-lab/remote/origin.git\n   999621a..a6d1c47  main -> main","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fetch and pull their change","icon":"lucide-download","text":"fetch downloads new commits without touching your files. status then says you are behind. pull --ff-only brings your branch up to date and refuses to create a surprise merge.","cmd":"cd ~/git-lab/project\ngit fetch\ngit status -sb\ngit pull --ff-only\ngit log --oneline","out":"$ git fetch\nFrom /home/you/git-lab/remote/origin\n   999621a..a6d1c47  main       -> origin/main\n\n$ git status -sb\n## main...origin/main [behind 1]\n\n$ git pull --ff-only\nUpdating 999621a..a6d1c47\nFast-forward\n README.md | 1 +\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline\na6d1c47 Update README\n999621a Add README","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":11,"of":31,"prev":{"id":"git-rebase","title":"Rebase: a straight line of history"},"next":{"id":"git-collaborate","title":"Project: two teammates, one remote"}}},{"id":"git-collaborate","title":"Project: two teammates, one remote","level":3,"icon":"lucide-users","summary":"Simulate Alice and Bob: a rejected push, pull --rebase and a clean shared history.","qna":[{"q":"In which situation do we use this?","a":"Several people push to one repository. The daily loop is fetch, review, pull, commit, push."},{"q":"Why was my push rejected?","a":"Someone pushed first, so your copy is behind. Pull (or pull --rebase), resolve any conflict, then push again."},{"q":"What comes next?","a":"Never force-push a shared branch. Use git push --force-with-lease only on your own branch."}],"steps":[{"title":"Build the shared setup","icon":"lucide-server","text":"A bare remote, Alice's first push and Bob's clone. Two working folders stand in for two people's machines.","cmd":"mkdir -p ~/git-lab/team && cd ~/git-lab/team\ngit init --bare origin.git\ngit clone origin.git alice\ncd alice && echo \"# Team project\" > README.md\ngit add README.md && git commit -m \"Initial commit\"\ngit push -u origin main\ncd .. && git clone origin.git bob","out":"$ git init --bare origin.git\nInitialized empty Git repository in /home/you/git-lab/team/origin.git/\n\n$ git clone origin.git alice\nCloning into 'alice'...\nwarning: You appear to have cloned an empty repository.\ndone.\n\n$ git add README.md && git commit -m \"Initial commit\"\n[main (root-commit) fa879bb] Initial commit\n 1 file changed, 1 insertion(+)\n create mode 100644 README.md\n\n$ git push -u origin main\nTo /home/you/git-lab/team/origin.git\n * [new branch]      main -> main\nbranch 'main' set up to track 'origin/main'.\n\n$ cd .. && git clone origin.git bob\nCloning into 'bob'...\ndone.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bob pushes first","icon":"lucide-upload","text":"Bob adds a file and pushes. The remote now has a commit Alice does not.","cmd":"cd ~/git-lab/team/bob\necho \"bob\" > bob.txt\ngit add bob.txt && git commit -m \"Bob adds a file\"\ngit push","out":"$ git add bob.txt && git commit -m \"Bob adds a file\"\n[main 06cd42d] Bob adds a file\n 1 file changed, 1 insertion(+)\n create mode 100644 bob.txt\n\n$ git push\nTo /home/you/git-lab/team/origin.git\n   fa879bb..06cd42d  main -> main","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Alice commits and her push is rejected","icon":"lucide-triangle-alert","text":"Alice made her own commit from the old state. Git refuses the push because it would erase Bob's work. This is normal, not an error to fear.","cmd":"cd ~/git-lab/team/alice\necho \"alice\" > alice.txt\ngit add alice.txt && git commit -m \"Alice adds a file\"\ngit push","out":"$ git add alice.txt && git commit -m \"Alice adds a file\"\n[main 60aca92] Alice adds a file\n 1 file changed, 1 insertion(+)\n create mode 100644 alice.txt\n\n$ git push\nTo /home/you/git-lab/team/origin.git\n ! [rejected]        main -> main (fetch first)\nerror: failed to push some refs to '/home/you/git-lab/team/origin.git'\nhint: Updates were rejected because the remote contains work that you do not\nhint: have locally. This is usually caused by another repository pushing to\nhint: the same ref. If you want to integrate the remote changes, use\nhint: 'git pull' before pushing again.\nhint: See the 'Note about fast-forwards' in 'git push --help' for details.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bring in Bob's work with pull --rebase","icon":"lucide-refresh-cw","text":"pull --rebase fetches Bob's commit and replays Alice's on top, giving a straight line without an extra merge commit.","cmd":"git pull --rebase\ngit log --oneline --graph","out":"$ git pull --rebase\nFrom /home/you/git-lab/team/origin\n   fa879bb..06cd42d  main       -> origin/main\nRebasing (1/1)\nSuccessfully rebased and updated refs/heads/main.\n\n$ git log --oneline --graph\n* 4027c90 Alice adds a file\n* 06cd42d Bob adds a file\n* fa879bb Initial commit","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Push again","icon":"lucide-upload","text":"Alice's history now contains Bob's, so the push is accepted.","cmd":"git push\ngit status -sb","out":"$ git push\nTo /home/you/git-lab/team/origin.git\n   06cd42d..4027c90  main -> main\n\n$ git status -sb\n## main...origin/main","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bob updates and sees everything","icon":"lucide-download","text":"Bob pulls and has both files. Fetch often, and pull before you start new work.","cmd":"cd ~/git-lab/team/bob\ngit pull --ff-only\nls\ngit log --oneline","out":"$ git pull --ff-only\nFrom /home/you/git-lab/team/origin\n   06cd42d..4027c90  main       -> origin/main\nUpdating 06cd42d..4027c90\nFast-forward\n alice.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 alice.txt\n\n$ ls\nREADME.md\nalice.txt\nbob.txt\n\n$ git log --oneline\n4027c90 Alice adds a file\n06cd42d Bob adds a file\nfa879bb Initial commit","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":12,"of":31,"prev":{"id":"git-remote-push","title":"Work with a remote: push, clone and pull"},"next":{"id":"git-stash","title":"Stash work in progress"}}},{"id":"git-stash","title":"Stash work in progress","level":2,"icon":"lucide-package","summary":"Park half-finished changes, do something urgent, then bring them back.","qna":[{"q":"In which situation do we use this?","a":"You are mid-change and must switch branches, pull, or fix something urgent. Stash parks the work safely."},{"q":"What does stash not save?","a":"Untracked files unless you add -u. Also check git stash list; stashes pile up and are easy to forget."},{"q":"What comes next?","a":"For a longer interruption use git-worktree instead of stashing."}],"steps":[{"title":"A repo with a committed file","icon":"lucide-git-commit","text":"Start with one committed file.","cmd":"mkdir -p ~/git-lab/stash && cd ~/git-lab/stash\ngit init\necho \"search v1\" > search.txt\ngit add search.txt\ngit commit -m \"Add search\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/stash/.git/\n\n$ git commit -m \"Add search\"\n[main (root-commit) be88c7a] Add search\n 1 file changed, 1 insertion(+)\n create mode 100644 search.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Half-finished work","icon":"lucide-pencil","text":"You are mid-change: a modified tracked file and a brand new untracked one.","cmd":"echo \"search v2 (unfinished)\" >> search.txt\necho \"draft\" > ideas.txt\ngit status --short","out":"$ git status --short\n M search.txt\n?? ideas.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Stash it","icon":"lucide-package","text":"stash push saves your changes and restores a clean working directory. -u includes untracked files and -m gives the stash a label.","cmd":"git stash push -u -m \"wip: search page\"\ngit status --short\ngit stash list","out":"$ git stash push -u -m \"wip: search page\"\nSaved working directory and index state On main: wip: search page\n\n$ git stash list\nstash@{0}: On main: wip: search page","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Do the urgent thing","icon":"lucide-zap","text":"With a clean directory, make the hotfix and commit it.","cmd":"echo \"hotfix\" > hotfix.txt\ngit add hotfix.txt\ngit commit -m \"Urgent hotfix\"","out":"$ git commit -m \"Urgent hotfix\"\n[main dbea786] Urgent hotfix\n 1 file changed, 1 insertion(+)\n create mode 100644 hotfix.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bring your work back","icon":"lucide-download","text":"pop re-applies the newest stash and removes it from the list. apply re-applies it but keeps it, which is useful for trying the same changes on several branches.","cmd":"git stash pop\ngit status --short\ngit stash list","out":"$ git stash pop\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\tmodified:   search.txt\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\tideas.txt\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nDropped refs/stash@{0} (12d3378a68a83647757dd25ce0762c98b7772333)\n\n$ git status --short\n M search.txt\n?? ideas.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"apply, list and drop","icon":"lucide-table","text":"Stash a second time, apply it without removing it, then drop it by hand.","cmd":"git stash push -m \"second try\"\ngit stash apply\ngit stash list\ngit stash drop","out":"$ git stash push -m \"second try\"\nSaved working directory and index state On main: second try\n\n$ git stash apply\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\tmodified:   search.txt\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\tideas.txt\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\n\n$ git stash list\nstash@{0}: On main: second try\n\n$ git stash drop\nDropped refs/stash@{0} (aafba89b8a38d04bbc96af6fa5ff572b409688ce)","outKind":"recorded","note":"","risk":true,"viz":""}],"nav":{"pos":13,"of":31,"prev":{"id":"git-collaborate","title":"Project: two teammates, one remote"},"next":{"id":"git-tags-releases","title":"Tags and releases"}}},{"id":"git-tags-releases","title":"Tags and releases","level":2,"icon":"lucide-bookmark","summary":"Mark versions with annotated tags, find them again, check one out and share tags with a remote.","qna":[{"q":"In which situation do we use this?","a":"When a version ships. A tag gives a permanent, readable name (v1.2.0) to one exact commit."},{"q":"Annotated or lightweight tag?","a":"Use annotated (-a) for releases: they store author, date and message. Lightweight tags are only bookmarks."},{"q":"What comes next?","a":"Push tags explicitly with git push origin v1.2.0; a normal push does not send them."}],"steps":[{"title":"A project with three commits","icon":"lucide-git-commit","text":"Build a tiny history with a loop.","cmd":"mkdir -p ~/git-lab/tags && cd ~/git-lab/tags\ngit init\nfor i in 1 2 3; do echo \"feature $i\" >> app.txt; git add app.txt; git commit -m \"Add feature $i\"; done\ngit log --oneline","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/tags/.git/\n\n$ for i in 1 2 3; do echo \"feature $i\" >> app.txt; git add app.txt; git commit -m \"Add feature $i\"; done\n[main (root-commit) bd48a3f] Add feature 1\n 1 file changed, 1 insertion(+)\n create mode 100644 app.txt\n[main 204462e] Add feature 2\n 1 file changed, 1 insertion(+)\n[main fb2fcc6] Add feature 3\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline\nfb2fcc6 Add feature 3\n204462e Add feature 2\nbd48a3f Add feature 1","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create an annotated tag","icon":"lucide-bookmark","text":"A tag is a permanent name for one commit, ideal for releases. An annotated tag (-a) also stores who tagged it, when and a message.","cmd":"git tag -a v1.0.0 -m \"First release\"\ngit tag -n","out":"$ git tag -n\nv1.0.0          First release","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Tag an older commit","icon":"lucide-clock","text":"Give a commit ID or HEAD~1 at the end to tag something that is not the latest commit.","cmd":"git tag -a v0.9.0 -m \"Beta\" HEAD~1\ngit tag --list \"v*\"","out":"$ git tag --list \"v*\"\nv0.9.0\nv1.0.0","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Find the nearest tag","icon":"lucide-search","text":"describe names a commit relative to the closest tag, which is how many build systems create version numbers.","cmd":"git describe --tags\ngit show v1.0.0 --no-patch --pretty=%s","out":"$ git describe --tags\nv1.0.0\n\n$ git show v1.0.0 --no-patch --pretty=%s\ntag v1.0.0\nTagger: Srinivas <srinivas@example.com>\n\nFirst release\nAdd feature 3","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Share tags with a remote","icon":"lucide-upload","text":"Tags are not pushed by default. Push one tag by name, or all with --tags.","cmd":"git init --bare ../tags-origin.git\ngit remote add origin ../tags-origin.git\ngit push origin main\ngit push origin v1.0.0\ngit ls-remote --tags origin","out":"$ git init --bare ../tags-origin.git\nInitialized empty Git repository in /home/you/git-lab/tags-origin.git/\n\n$ git push origin main\nTo ../tags-origin.git\n * [new branch]      main -> main\n\n$ git push origin v1.0.0\nTo ../tags-origin.git\n * [new tag]         v1.0.0 -> v1.0.0\n\n$ git ls-remote --tags origin\nf24209b54fbd102ae6a63a7085bed1d52c261a16\trefs/tags/v1.0.0\nfb2fcc6c0775205fdbd67d8377b15a3a05515ba4\trefs/tags/v1.0.0^{}","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Look at an old release","icon":"lucide-eye","text":"Checking out a tag puts you in a \"detached HEAD\": you can look around, but new commits would belong to no branch. Return to main when done.","cmd":"git switch --detach v0.9.0\ngit status\ngit switch main","out":"$ git switch --detach v0.9.0\nHEAD is now at 204462e Add feature 2\n\n$ git status\nHEAD detached at v0.9.0\nnothing to commit, working tree clean\n\n$ git switch main\nPrevious HEAD position was 204462e Add feature 2\nSwitched to branch 'main'","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Delete a tag","icon":"lucide-eraser","text":"Delete locally with -d. Removing it from the remote needs an explicit push.","cmd":"git tag -d v0.9.0\ngit tag","out":"$ git tag -d v0.9.0\nDeleted tag 'v0.9.0' (was 75c173f)\n\n$ git tag\nv1.0.0","outKind":"recorded","note":"","risk":true,"viz":""}],"nav":{"pos":14,"of":31,"prev":{"id":"git-stash","title":"Stash work in progress"},"next":{"id":"git-history-search","title":"Search and understand history"}}},{"id":"git-history-search","title":"Search and understand history","level":2,"icon":"lucide-search","summary":"Graph, patches, pickaxe search, blame, grep and summaries to answer \"who changed this and why?\".","qna":[{"q":"In which situation do we use this?","a":"You must answer who changed this line, when a word appeared, or what happened last week."},{"q":"Which command for which question?","a":"blame for who touched a line, log -S for when text was added or removed, grep to search a past version."},{"q":"What comes next?","a":"For \"which commit broke it\", use git-bisect."}],"steps":[{"title":"A repo with some history","icon":"lucide-git-commit","text":"Make five commits, each adding a line.","cmd":"mkdir -p ~/git-lab/hist && cd ~/git-lab/hist\ngit init\nfor i in 1 2 3 4 5; do echo \"line $i\" >> log.txt; git add log.txt; git commit -m \"Add line $i\"; done","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/hist/.git/\n\n$ for i in 1 2 3 4 5; do echo \"line $i\" >> log.txt; git add log.txt; git commit -m \"Add line $i\"; done\n[main (root-commit) 3250244] Add line 1\n 1 file changed, 1 insertion(+)\n create mode 100644 log.txt\n[main 1d392c5] Add line 2\n 1 file changed, 1 insertion(+)\n[main 16cc082] Add line 3\n 1 file changed, 1 insertion(+)\n[main 4606d7c] Add line 4\n 1 file changed, 1 insertion(+)\n[main 1b04353] Add line 5\n 1 file changed, 1 insertion(+)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Browse the graph","icon":"lucide-eye","text":"--oneline with --graph and --decorate shows commits, branches and tags in one compact view.","cmd":"git log --oneline --graph --decorate\ngit log -3 --oneline","out":"$ git log --oneline --graph --decorate\n* 1b04353 (HEAD -> main) Add line 5\n* 4606d7c Add line 4\n* 16cc082 Add line 3\n* 1d392c5 Add line 2\n* 3250244 Add line 1\n\n$ git log -3 --oneline\n1b04353 Add line 5\n4606d7c Add line 4\n16cc082 Add line 3","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"See what a commit changed","icon":"lucide-arrow-left-right","text":"show prints one commit with its patch. --stat summarises the files. log -p shows patches for a range.","cmd":"git show HEAD --stat\ngit log -p -1","out":"$ git show HEAD --stat\ncommit 1b04353b03c7e2cfa9f9bcd0c6c33178bab099cf\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:19:50 2026 +0530\n\n    Add line 5\n\n log.txt | 1 +\n 1 file changed, 1 insertion(+)\n\n$ git log -p -1\ncommit 1b04353b03c7e2cfa9f9bcd0c6c33178bab099cf\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:19:50 2026 +0530\n\n    Add line 5\n\ndiff --git a/log.txt b/log.txt\nindex 9c2a709..94c99a3 100644\n--- a/log.txt\n+++ b/log.txt\n@@ -2,3 +2,4 @@ line 1\n line 2\n line 3\n line 4\n+line 5","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Find the commit that introduced text","icon":"lucide-search","text":"-S (the pickaxe) finds commits where the number of occurrences of a string changed. --grep searches the commit messages.","cmd":"git log -S\"line 3\" --oneline\ngit log --grep=\"line 4\" --oneline","out":"$ git log -S\"line 3\" --oneline\n16cc082 Add line 3\n\n$ git log --grep=\"line 4\" --oneline\n4606d7c Add line 4","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Who wrote each line?","icon":"lucide-users","text":"blame annotates every line with the commit and author that last changed it.","cmd":"git blame log.txt","out":"$ git blame log.txt\n^3250244 (Srinivas 2026-10-26 13:07:50 +0530 1) line 1\n1d392c5f (Srinivas 2026-10-26 13:10:50 +0530 2) line 2\n16cc082f (Srinivas 2026-10-26 13:13:50 +0530 3) line 3\n4606d7cf (Srinivas 2026-10-26 13:16:50 +0530 4) line 4\n1b04353b (Srinivas 2026-10-26 13:19:50 +0530 5) line 5","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Search the current files and summarise","icon":"lucide-chart-line","text":"git grep searches tracked files fast. shortlog -sn counts commits per author.","cmd":"git grep -n \"line\"\ngit shortlog -sn\ngit log --author=\"Alice\" --oneline","out":"$ git grep -n \"line\"\nlog.txt:1:line 1\nlog.txt:2:line 2\nlog.txt:3:line 3\nlog.txt:4:line 4\nlog.txt:5:line 5","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":15,"of":31,"prev":{"id":"git-tags-releases","title":"Tags and releases"},"next":{"id":"git-amend-cleanup","title":"Fix the last commit"}}},{"id":"git-amend-cleanup","title":"Fix the last commit","level":2,"icon":"lucide-pencil","summary":"Correct a bad message, add a forgotten file and know when rewriting is safe.","qna":[{"q":"In which situation do we use this?","a":"You just committed and noticed a typo, a forgotten file or a poor message. Amend fixes the last commit."},{"q":"When is amend unsafe?","a":"After you pushed. Amend changes the commit ID, so the remote and your teammates would diverge."},{"q":"What comes next?","a":"For several commits at once use git-rebase-interactive."}],"steps":[{"title":"A commit with a typo","icon":"lucide-git-commit","text":"Make a commit with a mistake in its message.","cmd":"mkdir -p ~/git-lab/amend && cd ~/git-lab/amend\ngit init\necho \"hello\" > greeting.txt\ngit add greeting.txt\ngit commit -m \"Ad greting file\"\ngit log --oneline","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/amend/.git/\n\n$ git commit -m \"Ad greting file\"\n[main (root-commit) 9e555ed] Ad greting file\n 1 file changed, 1 insertion(+)\n create mode 100644 greeting.txt\n\n$ git log --oneline\n9e555ed Ad greting file","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fix the message","icon":"lucide-pencil","text":"commit --amend replaces the last commit. The new commit gets a different ID.","cmd":"git commit --amend -m \"Add greeting file\"\ngit log --oneline","out":"$ git commit --amend -m \"Add greeting file\"\n[main 701b1b5] Add greeting file\n Date: Mon Oct 26 13:07:50 2026 +0530\n 1 file changed, 1 insertion(+)\n create mode 100644 greeting.txt\n\n$ git log --oneline\n701b1b5 Add greeting file","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Add a forgotten file","icon":"lucide-plus","text":"Stage the missing file and amend with --no-edit to keep the message.","cmd":"echo \"bye\" > farewell.txt\ngit add farewell.txt\ngit commit --amend --no-edit\ngit show --stat --oneline HEAD","out":"$ git commit --amend --no-edit\n[main e786a7e] Add greeting file\n Date: Mon Oct 26 13:07:50 2026 +0530\n 2 files changed, 2 insertions(+)\n create mode 100644 farewell.txt\n create mode 100644 greeting.txt\n\n$ git show --stat --oneline HEAD\ne786a7e Add greeting file\n farewell.txt | 1 +\n greeting.txt | 1 +\n 2 files changed, 2 insertions(+)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Check the result","icon":"lucide-check","text":"One clean commit with both files and the right message.","cmd":"git log --oneline\ngit status","out":"$ git log --oneline\ne786a7e Add greeting file\n\n$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The safety rule","icon":"lucide-shield","text":"Amending rewrites history. It is fine for a commit that only exists on your machine. If you already pushed it, a teammate may have it, so make a new commit instead. If you must, push with --force-with-lease, which refuses to overwrite work you have not seen.","cmd":"","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":16,"of":31,"prev":{"id":"git-history-search","title":"Search and understand history"},"next":{"id":"git-cherry-pick-revert","title":"Cherry-pick a fix, revert a mistake"}}},{"id":"git-cherry-pick-revert","title":"Cherry-pick a fix, revert a mistake","level":3,"icon":"lucide-git-merge","summary":"Copy one commit to another branch and cancel a commit without rewriting history.","qna":[{"q":"In which situation do we use this?","a":"Cherry-pick copies one fix onto another branch, such as a hotfix to a release. Revert undoes a bad commit safely."},{"q":"Why revert instead of reset on shared branches?","a":"Revert adds a new commit that cancels the old one, so history stays intact for everyone who pulled."},{"q":"What comes next?","a":"Use git-reset-reflog for local-only mistakes."}],"steps":[{"title":"Main and a release branch","icon":"lucide-git-branch","text":"Create main with a commit and a release branch cut from it.","cmd":"mkdir -p ~/git-lab/pick && cd ~/git-lab/pick\ngit init\necho \"v1\" > app.txt\ngit add app.txt\ngit commit -m \"Release 1 code\"\ngit branch release","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/pick/.git/\n\n$ git commit -m \"Release 1 code\"\n[main (root-commit) 80dbfd3] Release 1 code\n 1 file changed, 1 insertion(+)\n create mode 100644 app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A fix lands on main","icon":"lucide-zap","text":"A bug fix is committed on main, which has moved on from the release branch.","cmd":"echo \"fixed\" > fix.txt\ngit add fix.txt\ngit commit -m \"Fix important bug\"","out":"$ git commit -m \"Fix important bug\"\n[main 4e81e1c] Fix important bug\n 1 file changed, 1 insertion(+)\n create mode 100644 fix.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Cherry-pick the fix onto release","icon":"lucide-git-merge","text":"cherry-pick copies one commit onto the current branch as a new commit with the same change. Use it to backport fixes without merging everything else.","cmd":"git switch release\ngit cherry-pick main\ngit log --oneline --all --graph","out":"$ git switch release\nSwitched to branch 'release'\n\n$ git cherry-pick main\n[release ba9b76f] Fix important bug\n Date: Mon Oct 26 13:12:20 2026 +0530\n 1 file changed, 1 insertion(+)\n create mode 100644 fix.txt\n\n$ git log --oneline --all --graph\n* ba9b76f Fix important bug\n| * 4e81e1c Fix important bug\n|/\n* 80dbfd3 Release 1 code","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Cancel a commit with revert","icon":"lucide-undo-2","text":"revert adds a commit that undoes another. It is the safe way to remove a change that has already been shared.","cmd":"git revert --no-edit HEAD\ngit log --oneline","out":"$ git revert --no-edit HEAD\n[release 2fb519a] Revert \"Fix important bug\"\n Date: Mon Oct 26 13:18:20 2026 +0530\n 1 file changed, 1 deletion(-)\n delete mode 100644 fix.txt\n\n$ git log --oneline\n2fb519a Revert \"Fix important bug\"\nba9b76f Fix important bug\n80dbfd3 Release 1 code","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Compare the branches","icon":"lucide-arrow-left-right","text":"See which commits each branch has and how the files differ.","cmd":"git log main..release --oneline\ngit diff main release --stat","out":"$ git log main..release --oneline\n2fb519a Revert \"Fix important bug\"\nba9b76f Fix important bug\n\n$ git diff main release --stat\n fix.txt | 1 -\n 1 file changed, 1 deletion(-)","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":17,"of":31,"prev":{"id":"git-amend-cleanup","title":"Fix the last commit"},"next":{"id":"git-reset-reflog","title":"Reset modes and recovering \"lost\" commits"}}},{"id":"git-reset-reflog","title":"Reset modes and recovering \"lost\" commits","level":3,"icon":"lucide-clock","summary":"Compare reset --soft, --mixed and --hard, then bring a commit back from the reflog.","qna":[{"q":"In which situation do we use this?","a":"A local mistake: a wrong commit, a bad reset or a lost branch. reflog lists where HEAD has been."},{"q":"Soft, mixed or hard?","a":"soft keeps changes staged, mixed keeps them unstaged, hard throws them away. Check status before using --hard."},{"q":"What comes next?","a":"Entries expire after about 90 days by default, so recover soon."}],"steps":[{"title":"Three commits","icon":"lucide-git-commit","text":"Create a history to experiment with.","cmd":"mkdir -p ~/git-lab/reset && cd ~/git-lab/reset\ngit init\nfor n in one two three; do echo \"$n\" >> f.txt; git add f.txt; git commit -m \"Commit $n\"; done\ngit log --oneline","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/reset/.git/\n\n$ for n in one two three; do echo \"$n\" >> f.txt; git add f.txt; git commit -m \"Commit $n\"; done\n[main (root-commit) 6c27de3] Commit one\n 1 file changed, 1 insertion(+)\n create mode 100644 f.txt\n[main 5b5bc17] Commit two\n 1 file changed, 1 insertion(+)\n[main fd4d616] Commit three\n 1 file changed, 1 insertion(+)\n\n$ git log --oneline\nfd4d616 Commit three\n5b5bc17 Commit two\n6c27de3 Commit one","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"reset --soft: move the branch only","icon":"lucide-arrow-up","text":"The branch moves back one commit. Your files and the staging area keep the changes from the removed commit, so everything is staged and ready.","cmd":"git reset --soft HEAD~1\ngit status --short\ngit log --oneline","out":"$ git status --short\nM  f.txt\n\n$ git log --oneline\n5b5bc17 Commit two\n6c27de3 Commit one","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"reset --mixed: also clear the staging area","icon":"lucide-minus","text":"Mixed is the default. The branch moves back and the staging area is reset, but your edits stay in the working directory as unstaged changes.","cmd":"git reset --mixed HEAD~1\ngit status --short\ngit log --oneline","out":"$ git reset --mixed HEAD~1\nUnstaged changes after reset:\nM\tf.txt\n\n$ git status --short\n M f.txt\n\n$ git log --oneline\n6c27de3 Commit one","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"reset --hard: discard everything","icon":"lucide-eraser","text":"Hard also overwrites your working directory. Uncommitted changes are lost for good. Only the commits remain recoverable, through the reflog.","cmd":"git reset --hard\ngit status --short\ncat f.txt","out":"$ git reset --hard\nHEAD is now at 6c27de3 Commit one\n\n$ cat f.txt\none","outKind":"recorded","note":"","risk":true,"viz":""},{"title":"Recover with the reflog","icon":"lucide-search","text":"The reflog lists where HEAD has been. Find the line for \"Commit three\" and reset to it. The sub-command below picks that commit's ID for you.","cmd":"git reflog\ngit reset --hard $(git reflog | grep \"commit: Commit three\" | head -n 1 | cut -d' ' -f1)\ngit log --oneline","out":"$ git reflog\n6c27de3 HEAD@{0}: reset: moving to HEAD\n6c27de3 HEAD@{1}: reset: moving to HEAD~1\n5b5bc17 HEAD@{2}: reset: moving to HEAD~1\nfd4d616 HEAD@{3}: commit: Commit three\n5b5bc17 HEAD@{4}: commit: Commit two\n6c27de3 HEAD@{5}: commit (initial): Commit one\n\n$ git reset --hard $(git reflog | grep \"commit: Commit three\" | head -n 1 | cut -d' ' -f1)\nHEAD is now at fd4d616 Commit three\n\n$ git log --oneline\nfd4d616 Commit three\n5b5bc17 Commit two\n6c27de3 Commit one","outKind":"recorded","note":"Reflog entries expire after months, so recovery works best soon after the mistake.","risk":true,"viz":""}],"nav":{"pos":18,"of":31,"prev":{"id":"git-cherry-pick-revert","title":"Cherry-pick a fix, revert a mistake"},"next":{"id":"git-feature-workflow","title":"Project: ship a feature end to end"}}},{"id":"git-feature-workflow","title":"Project: ship a feature end to end","level":3,"icon":"lucide-rocket","summary":"Branch, commit, push, review, merge with a merge commit and clean up, the way most teams work.","qna":[{"q":"In which situation do we use this?","a":"A team shipping through pull requests: branch, commit, push, review, merge, delete the branch."},{"q":"What makes it work?","a":"Small branches, clear messages, and updating from main often so merges stay easy."},{"q":"What comes next?","a":"Add automated checks with git-hooks and CI."}],"steps":[{"title":"Shared repo and a local clone","icon":"lucide-server","text":"A bare remote with an initial commit on main, and your clone of it.","cmd":"mkdir -p ~/git-lab/flow && cd ~/git-lab/flow\ngit init --bare origin.git\ngit clone origin.git app && cd app\necho \"# App\" > README.md\ngit add README.md && git commit -m \"Initial commit\"\ngit push -u origin main","out":"$ git init --bare origin.git\nInitialized empty Git repository in /home/you/git-lab/flow/origin.git/\n\n$ git clone origin.git app && cd app\nCloning into 'app'...\nwarning: You appear to have cloned an empty repository.\ndone.\n\n$ git add README.md && git commit -m \"Initial commit\"\n[main (root-commit) 5c4d3bf] Initial commit\n 1 file changed, 1 insertion(+)\n create mode 100644 README.md\n\n$ git push -u origin main\nTo /home/you/git-lab/flow/origin.git\n * [new branch]      main -> main\nbranch 'main' set up to track 'origin/main'.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create a feature branch","icon":"lucide-git-branch","text":"Never work on main directly. Branch from an up-to-date main with a descriptive name.","cmd":"git pull --ff-only\ngit switch -c feature/greeting","out":"$ git pull --ff-only\nAlready up to date.\n\n$ git switch -c feature/greeting\nSwitched to a new branch 'feature/greeting'","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Make small, focused commits","icon":"lucide-save","text":"Each commit does one thing and has a message that explains it.","cmd":"echo \"Hello\" > greeting.txt\ngit add greeting.txt && git commit -m \"Add greeting\"\necho \"Goodbye\" >> greeting.txt\ngit commit -am \"Add farewell\"","out":"$ git add greeting.txt && git commit -m \"Add greeting\"\n[feature/greeting f920bfc] Add greeting\n 1 file changed, 1 insertion(+)\n create mode 100644 greeting.txt\n\n$ git commit -am \"Add farewell\"\n[feature/greeting 0f36094] Add farewell\n 1 file changed, 1 insertion(+)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Push the branch","icon":"lucide-upload","text":"Publishing the branch lets teammates see it. On GitHub or GitLab this is the moment you open a pull request.","cmd":"git push -u origin feature/greeting","out":"$ git push -u origin feature/greeting\nTo /home/you/git-lab/flow/origin.git\n * [new branch]      feature/greeting -> feature/greeting\nbranch 'feature/greeting' set up to track 'origin/feature/greeting'.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Review before merging","icon":"lucide-eye","text":"This is what a reviewer reads: the commits and the combined change compared with main.","cmd":"git log origin/main..feature/greeting --oneline\ngit diff origin/main...feature/greeting --stat","out":"$ git log origin/main..feature/greeting --oneline\n0f36094 Add farewell\nf920bfc Add greeting\n\n$ git diff origin/main...feature/greeting --stat\n greeting.txt | 2 ++\n 1 file changed, 2 insertions(+)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Merge with a merge commit","icon":"lucide-git-merge","text":"--no-ff always records a merge commit, so the history shows that a feature existed. Then publish main.","cmd":"git switch main\ngit merge --no-ff feature/greeting -m \"Merge feature/greeting\"\ngit push\ngit log --oneline --graph","out":"$ git switch main\nSwitched to branch 'main'\nYour branch is up to date with 'origin/main'.\n\n$ git merge --no-ff feature/greeting -m \"Merge feature/greeting\"\nMerge made by the 'ort' strategy.\n greeting.txt | 2 ++\n 1 file changed, 2 insertions(+)\n create mode 100644 greeting.txt\n\n$ git push\nTo /home/you/git-lab/flow/origin.git\n   5c4d3bf..586cba9  main -> main\n\n$ git log --oneline --graph\n*   586cba9 Merge feature/greeting\n|\\\n| * 0f36094 Add farewell\n| * f920bfc Add greeting\n|/\n* 5c4d3bf Initial commit","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Delete the merged branch locally and on the remote, and drop stale remote-tracking references.","cmd":"git branch -d feature/greeting\ngit push origin --delete feature/greeting\ngit fetch --prune\ngit branch -a","out":"$ git branch -d feature/greeting\nDeleted branch feature/greeting (was 0f36094).\n\n$ git push origin --delete feature/greeting\nTo /home/you/git-lab/flow/origin.git\n - [deleted]         feature/greeting\n\n$ git branch -a\n* main\n  remotes/origin/HEAD -> origin/main\n  remotes/origin/main","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":19,"of":31,"prev":{"id":"git-reset-reflog","title":"Reset modes and recovering \"lost\" commits"},"next":{"id":"git-hooks","title":"Project: automate checks with hooks"}}},{"id":"git-hooks","title":"Project: automate checks with hooks","level":3,"icon":"lucide-shield","summary":"Block commits that contain secrets or badly formed messages, then share the hooks with the team.","qna":[{"q":"In which situation do we use this?","a":"To stop mistakes before they reach the server: secrets in a commit, a missing message prefix, failing tests."},{"q":"Why are hooks not shared automatically?","a":".git/hooks is not part of the repository. Share them through core.hooksPath or a tool such as pre-commit."},{"q":"What comes next?","a":"Mirror the same checks in CI, because hooks can be skipped with --no-verify."}],"steps":[{"title":"A repo with one commit","icon":"lucide-git-commit","text":"Start a fresh repository.","cmd":"mkdir -p ~/git-lab/hooks && cd ~/git-lab/hooks\ngit init\necho \"app\" > app.txt\ngit add app.txt\ngit commit -m \"Add app\"","out":"$ git init\nInitialized empty Git repository in /home/you/git-lab/hooks/.git/\n\n$ git commit -m \"Add app\"\n[main (root-commit) 1722a87] Add app\n 1 file changed, 1 insertion(+)\n create mode 100644 app.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Write a pre-commit hook","icon":"lucide-pencil","text":"Hooks are scripts in .git/hooks that Git runs at certain moments. A hook that exits with a non-zero status stops the action. This one blocks staged changes that contain SECRET=.","cmd":"cat > .git/hooks/pre-commit <<'EOF'\n#!/bin/sh\nif git diff --cached | grep -q \"SECRET=\"; then\n  echo \"Blocked: possible secret in staged changes\" >&2\n  exit 1\nfi\nEOF\nchmod +x .git/hooks/pre-commit","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"See it block a commit","icon":"lucide-ban","text":"Stage a file that looks like it has a secret and try to commit it. The hook refuses.","cmd":"echo \"SECRET=abc123\" > config.env\ngit add config.env\ngit commit -m \"Add config\"\ngit status --short","out":"$ git commit -m \"Add config\"\nBlocked: possible secret in staged changes\n\n$ git status --short\nA  config.env","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Fix it and commit","icon":"lucide-check","text":"Take the secret out, restage and the commit goes through.","cmd":"echo \"SECRET_FROM_ENV=true\" > config.env\ngit add config.env\ngit commit -m \"Add config without secret\"\ngit log --oneline","out":"$ git commit -m \"Add config without secret\"\n[main 55d4e49] Add config without secret\n 1 file changed, 1 insertion(+)\n create mode 100644 config.env\n\n$ git log --oneline\n55d4e49 Add config without secret\n1722a87 Add app","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Enforce a commit message style","icon":"lucide-bookmark","text":"commit-msg receives the path of the message file as its first argument. This one demands a prefix such as feat: or fix:.","cmd":"cat > .git/hooks/commit-msg <<'EOF'\n#!/bin/sh\nif ! grep -qE '^(feat|fix|docs|chore): ' \"$1\"; then\n  echo \"Start the message with feat:, fix:, docs: or chore:\" >&2\n  exit 1\nfi\nEOF\nchmod +x .git/hooks/commit-msg\necho \"x\" >> app.txt\ngit commit -am \"update stuff\"\ngit commit -am \"chore: update app\"","out":"$ git commit -am \"update stuff\"\nStart the message with feat:, fix:, docs: or chore:\n\n$ git commit -am \"chore: update app\"\n[main 719fd42] chore: update app\n 1 file changed, 1 insertion(+)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Share hooks with the team","icon":"lucide-users","text":"Files in .git are not versioned. Put hooks in a normal folder and point Git at it with core.hooksPath, then commit that folder. --no-verify skips hooks, so use it only knowingly.","cmd":"mkdir .githooks\ncp .git/hooks/pre-commit .git/hooks/commit-msg .githooks/\ngit config core.hooksPath .githooks\ngit config core.hooksPath","out":"$ git config core.hooksPath\n.githooks","outKind":"recorded","note":"Hooks can be bypassed on purpose, so also enforce important rules on the server side or in CI.","risk":false,"viz":""}],"nav":{"pos":20,"of":31,"prev":{"id":"git-feature-workflow","title":"Project: ship a feature end to end"},"next":{"id":"git-bisect","title":"Find the commit that broke it with git bisect"}}},{"id":"git-bisect","title":"Find the commit that broke it with git bisect","level":3,"icon":"lucide-search","summary":"Binary-search a history for the first bad commit, by hand and then fully automatically.","qna":[{"q":"In which situation do we use this?","a":"Something worked last month and is broken now, and you do not know which of many commits did it."},{"q":"How much work is it?","a":"Binary search: 1,000 commits need about 10 checks. With bisect run a script does all of them."},{"q":"What comes next?","a":"Always run git bisect reset when you finish, or you stay on a detached HEAD."}],"steps":[{"title":"Build a history with a hidden bug","icon":"lucide-folder","text":"Create eight commits. From \"feature 5\" onward a file called flag.txt exists, and that file is our stand-in for a bug. Nobody told Git which commit did it.","cmd":"mkdir -p ~/git-lab/bisect\ncd ~/git-lab/bisect\ngit init -q\nfor i in 1 2 3 4 5 6 7 8; do echo \"feature $i\" >> app.txt; if [ $i -ge 5 ]; then echo broken > flag.txt; fi; git add .; git commit -qm \"Add feature $i\"; done\ngit log --oneline","out":"$ git log --oneline\nb651ee5 Add feature 8\n5eb5aab Add feature 7\nc11b080 Add feature 6\nd32ab54 Add feature 5\n3ccd1b7 Add feature 4\nfb2fcc6 Add feature 3\n204462e Add feature 2\nbd48a3f Add feature 1","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Tell Git one good and one bad commit","icon":"wf-bisect","text":"bisect needs two points: a commit you know is bad (usually HEAD) and one you know is good. Git then checks out the middle commit for you to test. Eight commits need at most three tests.","cmd":"test -f flag.txt && echo \"BAD: flag.txt exists\" || echo \"GOOD\"\ngit bisect start\ngit bisect bad\ngit bisect good HEAD~7","out":"$ test -f flag.txt && echo \"BAD: flag.txt exists\" || echo \"GOOD\"\nBAD: flag.txt exists\n\n$ git bisect start\nstatus: waiting for both good and bad commits\n\n$ git bisect bad\nstatus: waiting for good commit(s), bad commit known\n\n$ git bisect good HEAD~7\nBisecting: 3 revisions left to test after this (roughly 2 steps)\n[3ccd1b72f07df6629d1f5e3201b39fe9eacaf84c] Add feature 4","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Test, mark, repeat","icon":"wf-bisect","text":"Run your check and tell Git the result with git bisect good or git bisect bad. The same one-line check below does both; run it until Git announces the first bad commit. Each answer halves the search.","cmd":"if test -f flag.txt; then git bisect bad; else git bisect good; fi\nif test -f flag.txt; then git bisect bad; else git bisect good; fi\nif test -f flag.txt; then git bisect bad; else git bisect good; fi","out":"$ if test -f flag.txt; then git bisect bad; else git bisect good; fi\nBisecting: 1 revision left to test after this (roughly 1 step)\n[c11b080add88486cc8ef0e3897a8ad30e2d810ac] Add feature 6\n\n$ if test -f flag.txt; then git bisect bad; else git bisect good; fi\nBisecting: 0 revisions left to test after this (roughly 0 steps)\n[d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580] Add feature 5\n\n$ if test -f flag.txt; then git bisect bad; else git bisect good; fi\nd32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580 is the first bad commit\ncommit d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:19:50 2026 +0530\n\n    Add feature 5\n\n app.txt  | 1 +\n flag.txt | 1 +\n 2 files changed, 2 insertions(+)\n create mode 100644 flag.txt","outKind":"recorded","note":"Doubling the history adds only one more step, so 1,000 commits need about 10 tests.","risk":false,"viz":""},{"title":"Read the log and go back","icon":"wf-reflog","text":"bisect log records every answer so you can replay it. reset returns you to the branch you started on. Always reset when you finish, or you stay on a detached HEAD.","cmd":"git bisect log\ngit bisect reset\ngit status","out":"$ git bisect log\ngit bisect start\n# status: waiting for both good and bad commits\n# bad: [b651ee58be6245c7fa2cc167d075e2547d45308e] Add feature 8\ngit bisect bad b651ee58be6245c7fa2cc167d075e2547d45308e\n# status: waiting for good commit(s), bad commit known\n# good: [bd48a3f8b2fd160b16c0e55697963df68e331c48] Add feature 1\ngit bisect good bd48a3f8b2fd160b16c0e55697963df68e331c48\n# good: [3ccd1b72f07df6629d1f5e3201b39fe9eacaf84c] Add feature 4\ngit bisect good 3ccd1b72f07df6629d1f5e3201b39fe9eacaf84c\n# bad: [c11b080add88486cc8ef0e3897a8ad30e2d810ac] Add feature 6\ngit bisect bad c11b080add88486cc8ef0e3897a8ad30e2d810ac\n# bad: [d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580] Add feature 5\ngit bisect bad d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580\n# first bad commit: [d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580] Add feature 5\n\n$ git bisect reset\nPrevious HEAD position was d32ab54 Add feature 5\nSwitched to branch 'main'\n\n$ git status\nOn branch main\nnothing to commit, working tree clean","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Automate it with git bisect run","icon":"lucide-play","text":"Give bisect a command that exits 0 for good and non-zero for bad and it does everything alone. Any script works: a test suite, a build, a curl check.","cmd":"git bisect start HEAD HEAD~7\ngit bisect run sh -c '! test -f flag.txt'\ngit bisect reset","out":"$ git bisect start HEAD HEAD~7\nBisecting: 3 revisions left to test after this (roughly 2 steps)\n[3ccd1b72f07df6629d1f5e3201b39fe9eacaf84c] Add feature 4\n\n$ git bisect run sh -c '! test -f flag.txt'\nrunning 'sh' '-c' ''\\!' test -f flag.txt'\nBisecting: 1 revision left to test after this (roughly 1 step)\n[c11b080add88486cc8ef0e3897a8ad30e2d810ac] Add feature 6\nrunning 'sh' '-c' ''\\!' test -f flag.txt'\nBisecting: 0 revisions left to test after this (roughly 0 steps)\n[d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580] Add feature 5\nrunning 'sh' '-c' ''\\!' test -f flag.txt'\nd32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580 is the first bad commit\ncommit d32ab54c40ac25b4a8ec7bdb5b2f73629e9fa580\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:19:50 2026 +0530\n\n    Add feature 5\n\n app.txt  | 1 +\n flag.txt | 1 +\n 2 files changed, 2 insertions(+)\n create mode 100644 flag.txt\nbisect found first bad commit\n\n$ git bisect reset\nPrevious HEAD position was d32ab54 Add feature 5\nSwitched to branch 'main'","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Inspect the culprit","icon":"lucide-eye","text":"Once you know the commit, read it. Here we ask which commit first added flag.txt.","cmd":"git log --oneline --diff-filter=A -- flag.txt","out":"$ git log --oneline --diff-filter=A -- flag.txt\nd32ab54 Add feature 5","outKind":"recorded","note":"A commit that touches many things is hard to bisect usefully. Small, focused commits make bisect precise.","risk":false,"viz":""}],"nav":{"pos":21,"of":31,"prev":{"id":"git-hooks","title":"Project: automate checks with hooks"},"next":{"id":"git-worktree","title":"Two branches at once with git worktree"}}},{"id":"git-worktree","title":"Two branches at once with git worktree","level":2,"icon":"lucide-git-branch","summary":"Check out a second branch in its own folder so a hotfix never disturbs your half-finished work.","qna":[{"q":"In which situation do we use this?","a":"An urgent fix arrives while you have unfinished work, or you must compare two branches side by side."},{"q":"Why not just clone twice?","a":"Worktrees share one .git database, so they use less disk and see each other's commits at once."},{"q":"What comes next?","a":"Remove the extra folder with git worktree remove when done."}],"steps":[{"title":"Start with a repository","icon":"lucide-folder","text":"One project with a main branch and a single commit. Normally switching branches would replace the files in this folder.","cmd":"mkdir -p ~/git-lab/wt/app\ncd ~/git-lab/wt/app\ngit init -q\necho \"version 1\" > app.txt\ngit add app.txt\ngit commit -qm \"Version 1\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add a worktree for a hotfix","icon":"wf-worktree","text":"git worktree add creates a new folder with another branch checked out. Both folders share one .git database, so nothing is cloned or duplicated.","cmd":"git worktree add ../hotfix -b hotfix\ngit worktree list\nls ~/git-lab/wt","out":"$ git worktree add ../hotfix -b hotfix\nPreparing worktree (new branch 'hotfix')\nHEAD is now at 1ed9621 Version 1\n\n$ git worktree list\n/home/you/git-lab/wt/app    1ed9621 [main]\n/home/you/git-lab/wt/hotfix 1ed9621 [hotfix]\n\n$ ls ~/git-lab/wt\napp\nhotfix","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Work in both places","icon":"lucide-pencil","text":"Commit in the hotfix folder while the main folder stays exactly as it was. No stash, no branch switching.","cmd":"cd ../hotfix\necho \"urgent fix\" > fix.txt\ngit add fix.txt\ngit commit -qm \"Fix the urgent bug\"\ngit log --oneline --graph --all\ncd ../app","out":"$ git log --oneline --graph --all\n* 37b2da2 Fix the urgent bug\n* 1ed9621 Version 1","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Merge and remove the worktree","icon":"lucide-git-merge","text":"Bring the fix into main, then delete the extra folder. Git refuses to remove a worktree that has uncommitted changes, which protects your work.","cmd":"git merge hotfix\ngit worktree remove ../hotfix\ngit branch -d hotfix\ngit worktree list","out":"$ git merge hotfix\nUpdating 1ed9621..37b2da2\nFast-forward\n fix.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 fix.txt\n\n$ git branch -d hotfix\nDeleted branch hotfix (was 37b2da2).\n\n$ git worktree list\n/home/you/git-lab/wt/app 37b2da2 [main]","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clean up stale entries","icon":"lucide-eraser","text":"If you delete a worktree folder by hand, Git still lists it. prune removes entries whose folder is gone.","cmd":"git worktree add ../scratch -b scratch\nrm -rf ../scratch\ngit worktree list\ngit worktree prune\ngit worktree list","out":"$ git worktree add ../scratch -b scratch\nPreparing worktree (new branch 'scratch')\nHEAD is now at 37b2da2 Fix the urgent bug\n\n$ git worktree list\n/home/you/git-lab/wt/app     37b2da2 [main]\n/home/you/git-lab/wt/scratch 37b2da2 [scratch] prunable\n\n$ git worktree list\n/home/you/git-lab/wt/app 37b2da2 [main]","outKind":"recorded","note":"A branch can be checked out in only one worktree at a time.","risk":false,"viz":""}],"nav":{"pos":22,"of":31,"prev":{"id":"git-bisect","title":"Find the commit that broke it with git bisect"},"next":{"id":"git-rebase-interactive","title":"Tidy history with interactive rebase"}}},{"id":"git-rebase-interactive","title":"Tidy history with interactive rebase","level":3,"icon":"lucide-git-merge","summary":"Squash noisy work-in-progress commits and reword a message before you share them.","qna":[{"q":"In which situation do we use this?","a":"Before opening a pull request, to turn \"wip\" and \"fix typo\" commits into a few meaningful ones."},{"q":"What is the safety net?","a":"git rebase --abort during the rebase, and the reflog afterwards."},{"q":"What comes next?","a":"Only rewrite commits that are still local or on your own branch."}],"steps":[{"title":"Create a messy history","icon":"lucide-pencil","text":"Real work leaves commits like \"wip\" and \"fix typo\". They are fine locally but poor history for a team.","cmd":"mkdir -p ~/git-lab/ri\ncd ~/git-lab/ri\ngit init -q\necho \"start\" > form.txt\ngit add form.txt\ngit commit -qm \"Add form\"\nfor m in \"Add login form\" \"wip\" \"fix typo\" \"more wip\"; do echo \"$m\" >> form.txt; git commit -qam \"$m\"; done\ngit log --oneline","out":"$ git log --oneline\ncadcb02 more wip\n2ffe666 fix typo\n8b85d1b wip\n0a54763 Add login form\n5966565 Add form","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Squash with fixup","icon":"wf-squash","text":"rebase -i opens a todo list, oldest commit first. Changing pick to fixup melds a commit into the one above it and discards its message. To keep this lesson scriptable, GIT_SEQUENCE_EDITOR edits the list with sed; normally you edit it by hand in your editor.","cmd":"GIT_SEQUENCE_EDITOR=\"sed -i.bak -e '2,4s/^pick/fixup/'\" git rebase -i HEAD~4\ngit log --oneline","out":"$ GIT_SEQUENCE_EDITOR=\"sed -i.bak -e '2,4s/^pick/fixup/'\" git rebase -i HEAD~4\nRebasing (2/4)\nRebasing (3/4)\nRebasing (4/4)\nSuccessfully rebased and updated refs/heads/main.\n\n$ git log --oneline\n1ad1556 Add login form\n5966565 Add form","outKind":"recorded","note":"Rebase rewrites commits and gives them new IDs. Never rebase commits you already pushed and others use.","risk":true,"viz":""},{"title":"Reword a message","icon":"lucide-pencil","text":"reword keeps the changes but lets you change the message. Here GIT_EDITOR replaces the first line of the message file automatically.","cmd":"GIT_SEQUENCE_EDITOR=\"sed -i.bak -e '1s/^pick/reword/'\" GIT_EDITOR=\"sed -i.bak -e '1s/.*/Add login form page/'\" git rebase -i HEAD~1\ngit log --oneline","out":"$ GIT_SEQUENCE_EDITOR=\"sed -i.bak -e '1s/^pick/reword/'\" GIT_EDITOR=\"sed -i.bak -e '1s/.*/Add login form page/'\" git rebase -i HEAD~1\nRebasing (1/1)\n[detached HEAD f35751f] Add login form page\n Date: Mon Oct 26 13:09:20 2026 +0530\n 1 file changed, 4 insertions(+)\nSuccessfully rebased and updated refs/heads/main.\n\n$ git log --oneline\nf35751f Add login form page\n5966565 Add form","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The other todo commands","icon":"lucide-list-todo","text":"pick keeps a commit, reword changes its message, edit stops so you can amend it, squash merges and combines messages, fixup merges and drops the message, drop deletes the commit. You may also reorder the lines to reorder commits.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Recover with the reflog","icon":"wf-reflog","text":"The old commits still exist. reflog lists where HEAD has been, and reset --hard returns you to a point before the rebase.","cmd":"git reflog | head -n 8","out":"$ git reflog | head -n 8\nf35751f HEAD@{0}: rebase (finish): returning to refs/heads/main\nf35751f HEAD@{1}: rebase (reword): Add login form page\n1ad1556 HEAD@{2}: rebase: fast-forward\n5966565 HEAD@{3}: rebase (start): checkout HEAD~1\n1ad1556 HEAD@{4}: rebase (finish): returning to refs/heads/main\n1ad1556 HEAD@{5}: rebase (fixup): Add login form\n96b8203 HEAD@{6}: rebase (fixup): # This is a combination of 3 commits.\n16fe2fb HEAD@{7}: rebase (fixup): # This is a combination of 2 commits.","outKind":"recorded","note":"If a rebase goes wrong while it is running, git rebase --abort puts everything back.","risk":false,"viz":""}],"nav":{"pos":23,"of":31,"prev":{"id":"git-worktree","title":"Two branches at once with git worktree"},"next":{"id":"git-submodules","title":"Use another repository inside yours"}}},{"id":"git-submodules","title":"Use another repository inside yours","level":3,"icon":"lucide-package","summary":"Pin a library repo at an exact commit with submodules, update it, and clone it back.","qna":[{"q":"In which situation do we use this?","a":"A project depends on another repository at an exact version and you want that pinned inside your repo."},{"q":"What is the common surprise?","a":"A plain clone leaves submodule folders empty. Use clone --recurse-submodules or submodule update --init."},{"q":"What comes next?","a":"If it hurts, consider a package manager instead; submodules suit code you also change."}],"steps":[{"title":"Create the library repository","icon":"lucide-folder","text":"A submodule is a separate repository that your project records by commit ID. First make a tiny library to depend on.","cmd":"mkdir -p ~/git-lab/sub/lib\ncd ~/git-lab/sub/lib\ngit init -q\necho \"v1\" > util.txt\ngit add util.txt\ngit commit -qm \"Library v1\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add it to your project","icon":"wf-submodule","text":"submodule add clones the library into libs/util and records two things: the URL in .gitmodules and the exact commit in your tree. The -c option allows local-folder URLs, which Git blocks by default for safety.","cmd":"mkdir -p ~/git-lab/sub/app\ncd ~/git-lab/sub/app\ngit init -q\ngit -c protocol.file.allow=always submodule add \"$HOME/git-lab/sub/lib\" libs/util\ncat .gitmodules\ngit status --short\ngit commit -qm \"Add util submodule\"\ngit ls-files -s libs/util","out":"$ git -c protocol.file.allow=always submodule add \"$HOME/git-lab/sub/lib\" libs/util\nCloning into '/home/you/git-lab/sub/app/libs/util'...\ndone.\n\n$ cat .gitmodules\n[submodule \"libs/util\"]\n\tpath = libs/util\n\turl = /home/you/git-lab/sub/lib\n\n$ git status --short\nA  .gitmodules\nA  libs/util\n\n$ git ls-files -s libs/util\n160000 9d2c85662a27cd5e8b6a786a3a15409e54436995 0\tlibs/util","outKind":"recorded","note":"Mode 160000 marks a submodule entry: a commit ID, not a folder of files.","risk":false,"viz":""},{"title":"Update the library","icon":"lucide-upload","text":"The library gets a new commit. Your project still points to the old one until you move the pointer and commit it.","cmd":"cd ../lib\necho \"v2\" >> util.txt\ngit commit -qam \"Library v2\"\ncd ../app/libs/util\ngit -c protocol.file.allow=always pull -q\ncd ../..\ngit status --short\ngit diff --submodule\ngit commit -qam \"Bump util to v2\"","out":"$ git status --short\n M libs/util\n\n$ git diff --submodule\nSubmodule libs/util 9d2c856..b143aa2:\n  > Library v2","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clone a project with submodules","icon":"lucide-files","text":"A plain clone leaves the submodule folder empty. Add --recurse-submodules, or run git submodule update --init afterwards.","cmd":"git -c protocol.file.allow=always clone -q --recurse-submodules \"$HOME/git-lab/sub/app\" \"$HOME/git-lab/sub/copy\"\ncat ~/git-lab/sub/copy/libs/util/util.txt\ncd ~/git-lab/sub/copy\ngit submodule status","out":"$ cat ~/git-lab/sub/copy/libs/util/util.txt\nv1\nv2\n\n$ git submodule status\n b143aa2fea20e526e36806505e308b14c4cf4355 libs/util (heads/main)","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Remove a submodule","icon":"lucide-eraser","text":"Removal takes two commands, because the submodule is registered in both .gitmodules and the index.","cmd":"git submodule deinit -f libs/util\ngit rm -qf libs/util\ngit commit -qm \"Remove util submodule\"\nls","out":"$ git submodule deinit -f libs/util\nCleared directory 'libs/util'\nSubmodule 'libs/util' (/home/you/git-lab/sub/lib) unregistered for path 'libs/util'\n\n$ ls\nlibs","outKind":"recorded","note":"","risk":true,"viz":""}],"nav":{"pos":24,"of":31,"prev":{"id":"git-rebase-interactive","title":"Tidy history with interactive rebase"},"next":{"id":"git-sparse-shallow","title":"Clone less: sparse checkout and shallow clones"}}},{"id":"git-sparse-shallow","title":"Clone less: sparse checkout and shallow clones","level":2,"icon":"lucide-filter","summary":"Fetch only recent history or only some folders when a repository is large.","qna":[{"q":"In which situation do we use this?","a":"CI jobs that only build, or huge repositories where you need one folder or the latest commit."},{"q":"Shallow or sparse?","a":"Shallow limits history depth; sparse limits which folders are checked out. They can be combined."},{"q":"What comes next?","a":"Use --filter=blob:none for a partial clone, and Git LFS for large binary files."}],"steps":[{"title":"Create a repository with several folders","icon":"lucide-folder","text":"Imagine src, docs and assets are huge. We will clone only part of it.","cmd":"mkdir -p ~/git-lab/big/src ~/git-lab/big/docs ~/git-lab/big/assets\ncd ~/git-lab/big\ngit init -q\nfor i in 1 2 3 4 5; do echo \"code $i\" > src/a.txt; echo \"doc $i\" > docs/readme.txt; echo \"asset $i\" > assets/logo.txt; git add .; git commit -qm \"Release $i\"; done\ngit rev-list --count HEAD","out":"$ git rev-list --count HEAD\n5","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Shallow clone: recent history only","icon":"lucide-clock","text":"--depth 1 downloads just the latest commit. It is the usual choice for CI jobs that only need to build. A local clone needs the file:// prefix for --depth to apply.","cmd":"git clone -q --depth 1 \"file://$HOME/git-lab/big\" ~/git-lab/shallow\ncd ~/git-lab/shallow\ngit log --oneline\ngit rev-list --count HEAD","out":"$ git log --oneline\n6b4af4b Release 5\n\n$ git rev-list --count HEAD\n1","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Deepen when you need more","icon":"lucide-download","text":"A shallow clone can grow later without starting over.","cmd":"git fetch -q --deepen 2\ngit rev-list --count HEAD\ngit log --oneline","out":"$ git rev-list --count HEAD\n3\n\n$ git log --oneline\n6b4af4b Release 5\n9d86252 Release 4\n69df2bc Release 3","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Sparse checkout: only some folders","icon":"lucide-filter","text":"--no-checkout clones without writing files. sparse-checkout set --cone src then limits the working folder to src, plus top-level files.","cmd":"git clone -q --no-checkout \"file://$HOME/git-lab/big\" ~/git-lab/sparse\ncd ~/git-lab/sparse\ngit sparse-checkout set --cone src\ngit checkout -q main\nls\ngit sparse-checkout list","out":"$ ls\nsrc\n\n$ git sparse-checkout list\nsrc","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Change the selection","icon":"lucide-repeat","text":"add brings in another folder. disable returns to a full checkout. The full history stays in .git throughout.","cmd":"git sparse-checkout add docs\nls\ngit sparse-checkout disable\nls","out":"$ ls\ndocs\nsrc\n\n$ ls\nassets\ndocs\nsrc","outKind":"recorded","note":"For very large hosted repos add --filter=blob:none to the clone (a partial clone) so file contents download only when needed. Git LFS keeps large binary files outside the normal object store: git lfs track \"*.psd\".","risk":false,"viz":""}],"nav":{"pos":25,"of":31,"prev":{"id":"git-submodules","title":"Use another repository inside yours"},"next":{"id":"git-aliases-tips","title":"Daily shortcuts: aliases, tracking and tidy remotes"}}},{"id":"git-aliases-tips","title":"Daily shortcuts: aliases, tracking and tidy remotes","level":1,"icon":"lucide-sliders-horizontal","summary":"Save typing with aliases, see what each branch tracks, and clean up deleted remote branches.","qna":[{"q":"In which situation do we use this?","a":"Once you type the same long command daily. Aliases and a few config settings save hours."},{"q":"Which settings are worth it?","a":"pull.rebase true, fetch.prune true and rerere.enabled true remove most daily friction."},{"q":"What comes next?","a":"Keep aliases in your global config so every repository gets them."}],"steps":[{"title":"Set up a repo with a remote","icon":"lucide-cloud","text":"A bare repository stands in for a server such as GitHub. Clone it, make a first commit and push.","cmd":"mkdir -p ~/git-lab/tips\ngit init -q --bare -b main ~/git-lab/tips/origin.git\ngit clone -q ~/git-lab/tips/origin.git ~/git-lab/tips/work\ncd ~/git-lab/tips/work\necho \"hello\" > a.txt\ngit add a.txt\ngit commit -qm \"First commit\"\ngit push -q -u origin main","out":"$ git clone -q ~/git-lab/tips/origin.git ~/git-lab/tips/work\nwarning: You appear to have cloned an empty repository.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Create aliases","icon":"lucide-sliders-horizontal","text":"An alias is a short name for a long command. --global stores it in your user config so every repository gets it.","cmd":"git config --global alias.st \"status -sb\"\ngit config --global alias.lg \"log --oneline --graph --decorate --all\"\ngit config --global alias.co switch\ngit st\ngit lg\ngit config --global --get-regexp '^alias\\.'","out":"$ git st\n## main...origin/main\n\n$ git lg\n* 7b3874f (HEAD -> main, origin/main) First commit\n\n$ git config --global --get-regexp '^alias\\.'\nalias.st status -sb\nalias.lg log --oneline --graph --decorate --all\nalias.co switch","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"See what each branch tracks","icon":"lucide-eye","text":"A tracking branch knows its remote partner. branch -vv shows it, plus whether you are ahead or behind.","cmd":"git co -c feature\necho \"work\" >> a.txt\ngit commit -qam \"Feature work\"\ngit push -q -u origin feature\ngit branch -vv","out":"$ git co -c feature\nSwitched to a new branch 'feature'\n\n$ git branch -vv\n* feature 95b34f2 [origin/feature] Feature work\n  main    7b3874f [origin/main] First commit","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Safer pulls","icon":"lucide-download","text":"pull.rebase true replays your local commits on top of the remote ones instead of creating a merge commit, which keeps history in a straight line. rerere remembers how you resolved a conflict so Git can reuse it.","cmd":"git config --global pull.rebase true\ngit config --global rerere.enabled true\ngit config --global --get pull.rebase\ngit config --global --get rerere.enabled","out":"$ git config --global --get pull.rebase\ntrue\n\n$ git config --global --get rerere.enabled\ntrue","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Clean up deleted remote branches","icon":"lucide-eraser","text":"After a branch is deleted on the server, your copy keeps a stale remote-tracking name. fetch --prune removes it.","cmd":"git push -q origin --delete feature\ngit branch -r\ngit fetch --prune\ngit branch -r","out":"$ git branch -r\n  origin/main\n\n$ git branch -r\n  origin/HEAD -> origin/main\n  origin/main","outKind":"recorded","note":"Set it once with git config --global fetch.prune true.","risk":false,"viz":""}],"nav":{"pos":26,"of":31,"prev":{"id":"git-sparse-shallow","title":"Clone less: sparse checkout and shallow clones"},"next":{"id":"git-objects","title":"Inside .git: blobs, trees and commits"}}},{"id":"git-objects","title":"Inside .git: blobs, trees and commits","level":3,"icon":"lucide-calculator","summary":"Hash a file by hand and read the three object types Git stores, so commits stop being magic.","qna":[{"q":"In which situation do we use this?","a":"When Git behaves in a way you cannot explain, or you want to understand why branches are cheap and why identical files cost nothing."},{"q":"What are the three object types?","a":"A blob holds file bytes, a tree lists names and blobs like a folder, and a commit points to a tree and its parent."},{"q":"What comes next?","a":"git-reset-reflog and git-large-files make much more sense once you know that refs are just files holding a hash."}],"steps":[{"title":"Hash a file without saving it","icon":"lucide-calculator","text":"Git names every piece of content by a SHA-1 hash of that content. hash-object computes the name; without -w it stores nothing. The same text always gives the same hash, on any computer.","cmd":"mkdir -p ~/git-lab/obj\ncd ~/git-lab/obj\ngit init -q\necho \"hello\" > a.txt\ngit hash-object a.txt","out":"$ git hash-object a.txt\nce013625030ba8dba906f756967f9e9ca394464a","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A blob holds file content","icon":"wf-object","text":"git add stores the file as a blob object named by that hash. A blob has no file name and no folder: only the bytes. cat-file -t prints the type and -p prints the content.","cmd":"git add a.txt\ngit cat-file -t $(git hash-object a.txt)\ngit cat-file -p $(git hash-object a.txt)","out":"$ git cat-file -t $(git hash-object a.txt)\nblob\n\n$ git cat-file -p $(git hash-object a.txt)\nhello","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"A commit points to a tree","icon":"lucide-git-commit","text":"commit creates two more objects. A tree lists names, modes and blob hashes, like a folder. The commit points to that tree and to its parent, and stores author and message.","cmd":"git commit -qm \"Add a.txt\"\ngit cat-file -t HEAD\ngit cat-file -p HEAD\ngit ls-tree HEAD","out":"$ git cat-file -t HEAD\ncommit\n\n$ git cat-file -p HEAD\ntree 2e81171448eb9f2ee3821e3d447aa6b2fe3ddba1\nauthor Srinivas <srinivas@example.com> 1793000540 +0530\ncommitter Srinivas <srinivas@example.com> 1793000540 +0530\n\nAdd a.txt\n\n$ git ls-tree HEAD\n100644 blob ce013625030ba8dba906f756967f9e9ca394464a\ta.txt","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"The same content is stored once","icon":"lucide-files","text":"Copy the file under a new name and commit. The tree now has two names, but both point at the same blob hash, so Git stores the bytes only once.","cmd":"cp a.txt b.txt\ngit add b.txt\ngit commit -qm \"Add b.txt\"\ngit ls-tree HEAD\ngit count-objects -v","out":"$ git ls-tree HEAD\n100644 blob ce013625030ba8dba906f756967f9e9ca394464a\ta.txt\n100644 blob ce013625030ba8dba906f756967f9e9ca394464a\tb.txt\n\n$ git count-objects -v\ncount: 5\nsize: 20\nin-pack: 0\npacks: 0\nsize-pack: 0\nprune-packable: 0\ngarbage: 0\nsize-garbage: 0","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Look at the objects folder","icon":"lucide-folder","text":"Each loose object is a compressed file named by its hash: the first two characters are the folder and the rest is the file name. gc later packs them together to save space.","cmd":"find .git/objects -type f | sort | head -n 6\ngit cat-file --batch-check --batch-all-objects","out":"$ find .git/objects -type f | sort | head -n 6\n.git/objects/1f/05e610f138784de1c4648ee83c02f868e7294b\n.git/objects/2e/81171448eb9f2ee3821e3d447aa6b2fe3ddba1\n.git/objects/a0/ae2ac55e71a058a2a23d69419daec18c35e04c\n.git/objects/b5/b0cccf7401633f12e0fafc6b85731251b86850\n.git/objects/ce/013625030ba8dba906f756967f9e9ca394464a\n\n$ git cat-file --batch-check --batch-all-objects\n1f05e610f138784de1c4648ee83c02f868e7294b commit 172\n2e81171448eb9f2ee3821e3d447aa6b2fe3ddba1 tree 33\na0ae2ac55e71a058a2a23d69419daec18c35e04c commit 220\nb5b0cccf7401633f12e0fafc6b85731251b86850 tree 66\nce013625030ba8dba906f756967f9e9ca394464a blob 6","outKind":"recorded","note":"Branches and tags are only small files that hold one commit hash. Look at .git/refs/heads/main.","risk":false,"viz":""}],"nav":{"pos":27,"of":31,"prev":{"id":"git-aliases-tips","title":"Daily shortcuts: aliases, tracking and tidy remotes"},"next":{"id":"git-large-files","title":"Find big files and keep the repository small"}}},{"id":"git-large-files","title":"Find big files and keep the repository small","level":2,"icon":"lucide-filter","summary":"Measure a repository, find the heaviest objects, stop tracking a big file and compact with gc.","qna":[{"q":"In which situation do we use this?","a":"A clone has become slow or the repository is far larger than the code, and you need to find out why."},{"q":"Does ignoring a file shrink the repository?","a":"No. Old versions stay in history. Only rewriting history (git filter-repo) or never committing the file removes them."},{"q":"What comes next?","a":"Use Git LFS for binaries you must version, and agree on a size limit with the team."}],"steps":[{"title":"Create a repo with a big file","icon":"wf-lfs","text":"A 20,000 line log stands in for a large asset. It is committed twice, so Git keeps two versions.","cmd":"mkdir -p ~/git-lab/large\ncd ~/git-lab/large\ngit init -q\nyes \"log line for the demo\" | head -n 20000 > data.log\ngit add data.log\ngit commit -qm \"Add data.log\"\necho \"more\" >> data.log\ngit commit -qam \"Update data.log\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Measure the repository","icon":"lucide-timer","text":"count-objects -vH reports loose objects and their size in human units. Large histories are slow to clone, so measure before you worry.","cmd":"git count-objects -vH\ngit rev-list --count HEAD","out":"$ git count-objects -vH\ncount: 6\nsize: 24.00 KiB\nin-pack: 0\npacks: 0\nsize-pack: 0 bytes\nprune-packable: 0\ngarbage: 0\nsize-garbage: 0 bytes\n\n$ git rev-list --count HEAD\n2","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Find the heaviest objects","icon":"lucide-search","text":"List every object with its type and size, then sort by size. The path column shows which file the object belongs to.","cmd":"git rev-list --objects --all | git cat-file --batch-check='%(objecttype) %(objectname) %(objectsize) %(rest)' | sort -k3 -n -r | head -n 3","out":"$ git rev-list --objects --all | git cat-file --batch-check='%(objecttype) %(objectname) %(objectsize) %(rest)' | sort -k3 -n -r | head -n 3\nblob 4f7c5f39be1c4cb3c93dcb0bc802895c9c4080bf 440005 data.log\nblob e58a046898f49a79f6b3cbb2311bd951ab911615 440000 data.log\ncommit 57bcbebcbc364b3fb4b0e0aa873e8ffa3c0b4b16 226","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Stop tracking and ignore it","icon":"lucide-ban","text":"rm --cached removes the file from the index but keeps it on disk. Add the pattern to .gitignore so it is not added again. The old versions stay in history.","cmd":"git rm -q --cached data.log\necho \"*.log\" > .gitignore\ngit add .gitignore\ngit commit -qm \"Stop tracking data.log\"\ngit status --short","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Compact with gc","icon":"lucide-package","text":"gc packs loose objects into one pack file and drops unreachable ones. The result is smaller and faster to transfer.","cmd":"git gc -q\ngit count-objects -vH","out":"$ git count-objects -vH\ncount: 0\nsize: 0 bytes\nin-pack: 9\npacks: 1\nsize-pack: 3.03 KiB\nprune-packable: 0\ngarbage: 0\nsize-garbage: 0 bytes","outKind":"recorded","note":"To keep large binaries out of history from the start use Git LFS (git lfs track \"*.psd\"). To remove a file from old commits use git filter-repo, then force-push once everyone is warned. That rewrites history.","risk":false,"viz":""}],"nav":{"pos":28,"of":31,"prev":{"id":"git-objects","title":"Inside .git: blobs, trees and commits"},"next":{"id":"git-notes-range-diff","title":"Review a rebase with git range-diff and notes"}}},{"id":"git-notes-range-diff","title":"Review a rebase with git range-diff and notes","level":3,"icon":"lucide-arrow-left-right","summary":"Compare two versions of a branch after a rebase, and attach notes to commits without changing them.","qna":[{"q":"In which situation do we use this?","a":"A reviewer asked you to rebase and wants proof that nothing else changed, or you need to attach information to commits you cannot amend."},{"q":"How do I read range-diff?","a":"A line with = means the commit is identical after the rebase, ! means its patch changed, < or > means a commit was dropped or added."},{"q":"What comes next?","a":"Remember that notes are not pushed unless you push refs/notes/commits."}],"steps":[{"title":"Build a feature branch","icon":"lucide-git-branch","text":"Two commits on a feature branch, then main moves ahead. Now the feature must be rebased.","cmd":"mkdir -p ~/git-lab/rd\ncd ~/git-lab/rd\ngit init -q\necho \"base\" > base.txt\ngit add base.txt\ngit commit -qm \"Base\"\ngit switch -qc feature\necho \"one\" > f1.txt\ngit add f1.txt\ngit commit -qm \"Feature part 1\"\necho \"two\" > f2.txt\ngit add f2.txt\ngit commit -qm \"Feature part 2\"\ngit switch -q main\necho \"update\" > m.txt\ngit add m.txt\ngit commit -qm \"Main update\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Keep a copy, then rebase","icon":"lucide-refresh-cw","text":"Rebase gives the feature commits new IDs, so you cannot easily see whether anything changed. Save the old tip as a branch first.","cmd":"git branch old-feature feature\ngit switch -q feature\ngit rebase -q main\ngit log --oneline --graph --all","out":"$ git log --oneline --graph --all\n* 6d6184a Feature part 2\n* df5f0b0 Feature part 1\n* ec3aa44 Main update\n| * 94155ec Feature part 2\n| * bc21b89 Feature part 1\n|/\n* a884e8b Base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Compare the two versions","icon":"lucide-arrow-left-right","text":"range-diff pairs up commits from the old and new series. = means identical content, ! means the patch differs. After a clean rebase every pair shows =.","cmd":"git range-diff main old-feature feature","out":"$ git range-diff main old-feature feature\n1:  bc21b89 = 1:  df5f0b0 Feature part 1\n2:  94155ec = 2:  6d6184a Feature part 2","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Add a note to a commit","icon":"lucide-pencil","text":"Notes attach extra text to a commit without changing its hash. git log shows them under Notes. Useful for review sign-off or ticket links.","cmd":"git notes add -m \"Reviewed by Priya on the team call\" HEAD\ngit log -1\ngit notes list","out":"$ git log -1\ncommit 6d6184a74212971506898cc31e44a30d73f520c8\nAuthor: Srinivas <srinivas@example.com>\nDate:   Mon Oct 26 13:15:20 2026 +0530\n\n    Feature part 2\n\nNotes:\n    Reviewed by Priya on the team call\n\n$ git notes list\n7576e2eb6f8a4b011ddfb9193d825f78d7a20d1e 6d6184a74212971506898cc31e44a30d73f520c8","outKind":"recorded","note":"Notes are not pushed by default. Send them with git push origin refs/notes/commits.","risk":false,"viz":""}],"nav":{"pos":29,"of":31,"prev":{"id":"git-large-files","title":"Find big files and keep the repository small"},"next":{"id":"git-patches","title":"Share changes without a server: patches, bundles and archives"}}},{"id":"git-patches","title":"Share changes without a server: patches, bundles and archives","level":2,"icon":"lucide-files","summary":"Turn commits into mailable patch files, apply them elsewhere, bundle a whole repo and export a snapshot.","qna":[{"q":"In which situation do we use this?","a":"There is no shared server: an air-gapped network, an email-based project, or a quick hand-off to one colleague."},{"q":"Patch, bundle or archive?","a":"A patch carries a few commits, a bundle carries a whole repository with history, and an archive carries only files of one commit."},{"q":"What comes next?","a":"Use apply --check before am, so a failure leaves your repository untouched."}],"steps":[{"title":"Two repositories","icon":"lucide-folder","text":"src is where work happens and dst is a colleague's copy. dst starts as a clone, then src gets two new commits.","cmd":"mkdir -p ~/git-lab/patch\ncd ~/git-lab/patch\ngit init -q src\ncd src\necho \"base\" > app.txt\ngit add app.txt\ngit commit -qm \"Base\"\ncd ..\ngit clone -q src dst\ncd src\necho \"greeting\" > greet.txt\ngit add greet.txt\ngit commit -qm \"Add greeting\"\necho \"farewell\" > bye.txt\ngit add bye.txt\ngit commit -qm \"Add farewell\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Export the commits as patches","icon":"wf-patch","text":"format-patch writes one numbered file per commit, in the format email programs and code review tools understand. The file holds the message, author and the diff.","cmd":"git format-patch -2 -o ../patches\nhead -n 14 ../patches/0001-Add-greeting.patch","out":"$ git format-patch -2 -o ../patches\n../patches/0001-Add-greeting.patch\n../patches/0002-Add-farewell.patch\n\n$ head -n 14 ../patches/0001-Add-greeting.patch\nFrom 75448ad540993ca6f1874e38ba9ba9fa980b096a Mon Sep 17 00:00:00 2001\nFrom: Srinivas <srinivas@example.com>\nDate: Mon, 26 Oct 2026 13:12:20 +0530\nSubject: [PATCH 1/2] Add greeting\n\n---\n greet.txt | 1 +\n 1 file changed, 1 insertion(+)\n create mode 100644 greet.txt\n\ndiff --git a/greet.txt b/greet.txt\nnew file mode 100644\nindex 0000000..36baa01\n--- /dev/null","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Apply them in the other repository","icon":"lucide-download","text":"apply --check tests a patch without changing anything. am applies it and creates a real commit, keeping author and message.","cmd":"cd ../dst\ngit apply --check ../patches/0001-Add-greeting.patch && echo \"patch applies cleanly\"\ngit am ../patches/*.patch\ngit log --oneline","out":"$ git apply --check ../patches/0001-Add-greeting.patch && echo \"patch applies cleanly\"\npatch applies cleanly\n\n$ git am ../patches/*.patch\nApplying: Add greeting\nApplying: Add farewell\n\n$ git log --oneline\n256ff19 Add farewell\n9f4f57c Add greeting\n1153d66 Base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bundle the whole repository","icon":"lucide-package","text":"A bundle is a single file that contains commits and refs, so it can travel on a USB stick and be cloned like a remote. verify checks that it is complete.","cmd":"cd ../src\ngit bundle create ../repo.bundle --all\ngit bundle verify ../repo.bundle\ngit clone -q ../repo.bundle ../from-bundle\ngit -C ../from-bundle log --oneline","out":"$ git bundle verify ../repo.bundle\n../repo.bundle is okay\nThe bundle contains these 2 refs:\n55eb5587d5c8a8152f333834b9ac4db559394280 refs/heads/main\n55eb5587d5c8a8152f333834b9ac4db559394280 HEAD\nThe bundle records a complete history.\nThe bundle uses this hash algorithm: sha1\n\n$ git -C ../from-bundle log --oneline\n55eb558 Add farewell\n75448ad Add greeting\n1153d66 Base","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Export a clean snapshot","icon":"lucide-upload","text":"archive writes the files of one commit, without the .git folder, as a tar or zip. Use it for releases and hand-offs.","cmd":"git archive --format=tar.gz -o ../snapshot.tar.gz HEAD\ntar -tzf ../snapshot.tar.gz","out":"$ tar -tzf ../snapshot.tar.gz\napp.txt\nbye.txt\ngreet.txt","outKind":"recorded","note":"","risk":false,"viz":""}],"nav":{"pos":30,"of":31,"prev":{"id":"git-notes-range-diff","title":"Review a rebase with git range-diff and notes"},"next":{"id":"git-force-push-recovery","title":"Recover from a bad force push"}}},{"id":"git-force-push-recovery","title":"Recover from a bad force push","level":3,"icon":"lucide-undo-2","summary":"See why a plain push is rejected, use --force-with-lease, and bring back a commit that was overwritten.","qna":[{"q":"In which situation do we use this?","a":"Someone force-pushed over shared work, or you did and need the lost commits back."},{"q":"Force or force-with-lease?","a":"--force-with-lease refuses when the server has commits you have not seen, so you cannot silently erase a teammate's push."},{"q":"What comes next?","a":"Recover quickly from origin/main@{1} or a teammate's clone before the server cleans up unreachable commits."}],"steps":[{"title":"Set up a shared remote","icon":"lucide-cloud","text":"A bare repository acts as the server. Push three commits.","cmd":"mkdir -p ~/git-lab/fp\ngit init -q --bare -b main ~/git-lab/fp/origin.git\ngit clone -q ~/git-lab/fp/origin.git ~/git-lab/fp/work\ncd ~/git-lab/fp/work\nfor i in 1 2 3; do echo \"change $i\" >> app.txt; git add app.txt; git commit -qm \"Change $i\"; done\ngit push -q -u origin main\ngit log --oneline","out":"$ git clone -q ~/git-lab/fp/origin.git ~/git-lab/fp/work\nwarning: You appear to have cloned an empty repository.\n\n$ git log --oneline\nb10f63b Change 3\n5c9e1e1 Change 2\n2be015e Change 1","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Rewrite history locally","icon":"lucide-pencil","text":"A reset throws away the last commit and a new commit takes its place. History now differs from the server's, so a normal push is refused to protect everyone else's work.","cmd":"git reset -q --hard HEAD~1\necho \"replacement\" >> app.txt\ngit commit -qam \"Replacement change\"\ngit push","out":"$ git push\nTo /home/you/git-lab/fp/origin.git\n ! [rejected]        main -> main (non-fast-forward)\nerror: failed to push some refs to '/home/you/git-lab/fp/origin.git'\nhint: Updates were rejected because the tip of your current branch is behind\nhint: its remote counterpart. If you want to integrate the remote changes,\nhint: use 'git pull' before pushing again.\nhint: See the 'Note about fast-forwards' in 'git push --help' for details.","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Force with a safety check","icon":"lucide-triangle-alert","text":"--force-with-lease overwrites the server only if it still matches what you last fetched. If a teammate pushed meanwhile it refuses. Plain --force skips that check.","cmd":"git push --force-with-lease origin main\ngit log --oneline","out":"$ git push --force-with-lease origin main\nTo /home/you/git-lab/fp/origin.git\n + b10f63b...4011579 main -> main (forced update)\n\n$ git log --oneline\n4011579 Replacement change\n5c9e1e1 Change 2\n2be015e Change 1","outKind":"recorded","note":"Never force-push a shared branch such as main. Protect it on the server so force pushes are blocked.","risk":true,"viz":""},{"title":"Find the overwritten commit","icon":"lucide-search","text":"Nothing is deleted at once. Your remote-tracking branch remembers its previous position, and the reflog lists where HEAD has been.","cmd":"git reflog origin/main | head -n 4\ngit rev-parse origin/main@{1}","out":"$ git reflog origin/main | head -n 4\n4011579 refs/remotes/origin/main@{0}: update by push\nb10f63b refs/remotes/origin/main@{1}: update by push\n\n$ git rev-parse origin/main@{1}\nb10f63b995fb7fb5f4c7440179281bdac89d57de","outKind":"recorded","note":"","risk":false,"viz":""},{"title":"Bring it back on a rescue branch","icon":"wf-reflog","text":"Create a branch at the old position so the commit is reachable again, then decide whether to cherry-pick it or restore the branch.","cmd":"git branch rescue origin/main@{1}\ngit log --oneline rescue\ngit log --oneline main","out":"$ git log --oneline rescue\nb10f63b Change 3\n5c9e1e1 Change 2\n2be015e Change 1\n\n$ git log --oneline main\n4011579 Replacement change\n5c9e1e1 Change 2\n2be015e Change 1","outKind":"recorded","note":"Servers delete unreachable commits during garbage collection, so recover soon.","risk":false,"viz":""}],"nav":{"pos":31,"of":31,"prev":{"id":"git-patches","title":"Share changes without a server: patches, bundles and archives"},"next":null}}]},{"id":"linux","name":"Linux","color":"#CA8A04","tagline":"Boot, files, services, networking, storage and hardening on a Linux host.","icon":"linux-kernel","workflows":[{"id":"lnx-first-day","title":"Module 1: Your first day: where am I, what is here, how do I get help","level":1,"icon":"lucide-terminal","summary":"Learn the prompt, the folder tree, the manual pages and the five commands you will type every day.","qna":[{"q":"In which situation do we use this?","a":"Your first time on a Linux shell, or when you need to orient yourself on an unfamiliar server."},{"q":"What are the five commands to learn first?","a":"pwd, ls, cd, cat and man. With these you can find your way and read anything."},{"q":"What comes next?","a":"Module 2 follows one file through the everyday file commands."}],"steps":[{"title":"Who and where am I?","icon":"lucide-user","text":"whoami prints your user name, hostname the machine name, pwd the folder you are in. The prompt ends in $ for a normal user and # for root.","cmd":"whoami\nhostname\npwd\necho $HOME $SHELL","out":"srinivas\nweb-01\n/home/srinivas\n/home/srinivas /bin/bash","outKind":"example","note":"","risk":false,"viz":""},{"title":"The folder tree starts at /","icon":"lucide-folder","text":"Everything hangs off one root folder, /. Your files live in /home, settings in /etc, programs in /usr, logs and changing data in /var, devices in /dev and temporary files in /tmp.","cmd":"ls /\nls /etc | head -n 5","out":"bin  boot  dev  etc  home  lib  media  mnt  opt  proc  root  run  sbin  srv  sys  tmp  usr  var\nadduser.conf\nalternatives\napparmor\napt\nbash.bashrc","outKind":"example","note":"","risk":false,"viz":""},{"title":"Move around","icon":"lucide-signpost","text":"cd changes folder. cd with no argument goes home, cd .. goes up one level, cd - goes back to the last folder. . means here and ~ means home.","cmd":"cd /var/log\npwd\ncd ..\ncd -\ncd ~","out":"/var/log\n/var\n/var/log","outKind":"example","note":"","risk":false,"viz":""},{"title":"Look at what is in a folder","icon":"lucide-eye","text":"ls lists. -l gives details, -a shows hidden files (names starting with a dot), -h makes sizes readable, -t sorts by time.","cmd":"ls -lah ~\nls -lt /var/log | head -n 4","out":"total 28K\ndrwxr-x--- 4 srinivas srinivas 4.0K Nov  4 10:00 .\ndrwxr-xr-x 3 root     root     4.0K Oct  1 09:00 ..\n-rw-r--r-- 1 srinivas srinivas  220 Oct  1 09:00 .bash_logout","outKind":"example","note":"","risk":false,"viz":""},{"title":"Get help without the internet","icon":"lucide-book-open","text":"man opens the manual, --help prints a short summary, type tells you whether a word is a program, a shell built-in or an alias. In man press / to search and q to quit.","cmd":"man ls | head -n 8\nls --help | head -n 4\ntype cd ls\napropos \"copy files\" | head -n 3","out":"cd is a shell builtin\nls is /usr/bin/ls","outKind":"example","note":"","risk":false,"viz":""},{"title":"Shortcuts that save hours","icon":"lucide-zap","text":"Tab completes names, the Up arrow repeats earlier commands, Ctrl+R searches history, Ctrl+C stops a command, Ctrl+L clears the screen and !! repeats the last command.","cmd":"history | tail -n 5\nsudo !!","out":"","outKind":"","note":"Type the first letters of a name and press Tab twice to see all the choices.","risk":false,"viz":""}],"nav":{"pos":1,"of":41,"prev":null,"next":{"id":"lnx-hello-files","title":"Module 2: hello.txt: create, view, copy, move, rename, delete"}}},{"id":"lnx-hello-files","title":"Module 2: hello.txt: create, view, copy, move, rename, delete","level":1,"icon":"lucide-file-text","summary":"Follow one file, hello.txt, through the everyday file commands. Each command changes the folder, and ls shows how.","qna":[{"q":"In which situation do we use this?","a":"Daily work: creating, copying, moving and deleting files."},{"q":"What is the danger in rm?","a":"There is no recycle bin. Use ls with the same pattern first and add -i when unsure."},{"q":"What comes next?","a":"Module 3 explains who may use these files."}],"steps":[{"title":"Make a folder and a file","icon":"lucide-pencil","text":"mkdir creates a folder (-p makes parents too), echo prints text and > writes it into a file, creating it. The file now holds Hello Srinivas plus an end-of-line character.","cmd":"mkdir -p ~/lab/hello\ncd ~/lab/hello\necho \"Hello Srinivas\" > hello.txt\nls -l","out":"total 4\n-rw-r--r-- 1 srinivas srinivas 15 Nov  4 10:05 hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read it five ways","icon":"lucide-eye","text":"cat prints the whole file, head and tail the first or last lines, wc counts lines, words and bytes, less lets you scroll. The file is 15 bytes: 14 characters plus the newline.","cmd":"cat hello.txt\nhead -n 1 hello.txt\nwc hello.txt\ncat -A hello.txt","out":"Hello Srinivas\nHello Srinivas\n 1  2 15 hello.txt\nHello Srinivas$","outKind":"example","note":"cat -A shows the invisible end-of-line as a $ sign.","risk":false,"viz":""},{"title":"Add lines without erasing","icon":"lucide-plus","text":"> overwrites, >> appends. A very common mistake is using > when you meant >>.","cmd":"echo \"Welcome to Linux\" >> hello.txt\ncat -n hello.txt\necho \"oops\" > hello.txt && cat hello.txt","out":"1  Hello Srinivas\n2  Welcome to Linux\noops","outKind":"example","note":"","risk":true,"viz":""},{"title":"Copy it","icon":"lucide-files","text":"cp makes a second file with the same content. -i asks before overwriting and -a copies a whole folder keeping all details.","cmd":"echo \"Hello Srinivas\" > hello.txt\ncp hello.txt backup.txt\ncp -i hello.txt backup.txt\nls","out":"backup.txt  hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Move and rename","icon":"lucide-repeat","text":"mv both moves and renames: same folder means rename, a different folder means move. There is no separate rename command.","cmd":"mv backup.txt greeting.txt\nmkdir docs\nmv greeting.txt docs/\nls -R","out":".:\ndocs  hello.txt\n\n./docs:\ngreeting.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Delete safely","icon":"lucide-eraser","text":"rm deletes with no recycle bin. -i asks first and -r removes folders. Read the command twice before pressing Enter, especially with *.","cmd":"rm -i docs/greeting.txt\nrmdir docs\nls\nrm -rf ~/lab","out":"","outKind":"","note":"Never run rm -rf with a variable that might be empty, such as rm -rf $DIR/.","risk":true,"viz":""}],"nav":{"pos":2,"of":41,"prev":{"id":"lnx-first-day","title":"Module 1: Your first day: where am I, what is here, how do I get help"},"next":{"id":"lnx-hello-perms","title":"Module 3: Who can read hello.txt? Permissions, owner and groups"}}},{"id":"lnx-hello-perms","title":"Module 3: Who can read hello.txt? Permissions, owner and groups","level":1,"icon":"lucide-lock","summary":"Read the ls -l permission string, change it with chmod in letters and numbers, change owner with chown and see what umask does.","qna":[{"q":"In which situation do we use this?","a":"You see Permission denied, a script will not run, or a web server cannot read its files."},{"q":"What does 644 mean?","a":"The owner can read and write; the group and others can only read."},{"q":"What comes next?","a":"Module 4 finds files and text."}],"steps":[{"title":"Read the permission string","icon":"lucide-eye","text":"-rw-r--r-- has ten characters. The first is the type (- file, d folder). Then three sets of three: owner, group, others, each r (read), w (write), x (execute).","cmd":"mkdir -p ~/lab && cd ~/lab && echo \"Hello Srinivas\" > hello.txt\nls -l hello.txt\nstat -c '%A %a %U:%G %n' hello.txt","out":"-rw-r--r-- 1 srinivas srinivas 15 Nov  4 10:10 hello.txt\n-rw-r--r-- 644 srinivas:srinivas hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Numbers: r=4 w=2 x=1","icon":"lucide-calculator","text":"Add the digits per set. rw- is 4+2=6, r-- is 4, so 644. rwx is 7. A secret file should be 600 and a script 755.","cmd":"chmod 600 hello.txt\nls -l hello.txt\nchmod 644 hello.txt","out":"-rw------- 1 srinivas srinivas 15 Nov  4 10:10 hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Letters: add or remove one right","icon":"lucide-pencil","text":"u is owner, g group, o others, a all. + adds, - removes, = sets exactly. This is easier when you want to change just one bit.","cmd":"chmod g+w hello.txt\nchmod o-r hello.txt\nchmod a+x hello.txt\nls -l hello.txt","out":"-rwxrw---x 1 srinivas srinivas 15 Nov  4 10:10 hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Folders need x to enter","icon":"lucide-folder","text":"On a folder, r lets you list names, w lets you create and delete inside, x lets you enter it. Without x on the folder you cannot reach files in it even if the file is readable.","cmd":"mkdir private && chmod 700 private\nls -ld private\nchmod 000 private && ls private\nchmod 700 private","out":"drwx------ 2 srinivas srinivas 4096 Nov  4 10:12 private\nls: cannot open directory 'private': Permission denied","outKind":"example","note":"","risk":false,"viz":""},{"title":"Change owner and group","icon":"lucide-users","text":"chown changes who owns a file and needs root. chgrp changes only the group. Group sharing is the safe way to let a team use a folder.","cmd":"sudo chown root:root hello.txt\nls -l hello.txt\ncat hello.txt\nsudo chown srinivas:srinivas hello.txt","out":"-rwxrw---x 1 root root 15 Nov  4 10:10 hello.txt\ncat: hello.txt: Permission denied","outKind":"example","note":"","risk":false,"viz":""},{"title":"umask: the default for new files","icon":"lucide-sliders-horizontal","text":"A new file starts as 666 and a new folder as 777; umask removes bits. umask 022 gives files 644 and folders 755.","cmd":"umask\numask 077\ntouch secret.txt && mkdir secretdir && ls -ld secret.txt secretdir\numask 022","out":"0022\n-rw------- 1 srinivas srinivas 0 Nov  4 10:14 secret.txt\ndrwx------ 2 srinivas srinivas 4096 Nov  4 10:14 secretdir","outKind":"example","note":"","risk":false,"viz":""},{"title":"Special bits and sudo","icon":"lucide-shield","text":"A script can run only if it has x. The setuid bit (4xxx) runs a program as its owner, like passwd. Use sudo for one command as root instead of logging in as root.","cmd":"ls -l /usr/bin/passwd\nsudo -l\nid","out":"-rwsr-xr-x 1 root root 59976 Nov  4 2024 /usr/bin/passwd\nuid=1000(srinivas) gid=1000(srinivas) groups=1000(srinivas),27(sudo)","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":41,"prev":{"id":"lnx-hello-files","title":"Module 2: hello.txt: create, view, copy, move, rename, delete"},"next":{"id":"lnx-hello-search","title":"Module 4: Find hello.txt and search inside files"}}},{"id":"lnx-hello-search","title":"Module 4: Find hello.txt and search inside files","level":1,"icon":"lucide-search","summary":"Use find for names, grep for text, and sort, uniq and wc to count, all on a small folder of notes.","qna":[{"q":"In which situation do we use this?","a":"A file is lost, a log is huge, or you need to know where a word appears."},{"q":"find or grep?","a":"find searches names and file properties. grep searches the text inside files."},{"q":"What comes next?","a":"Module 5 joins commands with pipes and redirects."}],"steps":[{"title":"Make a few files to search","icon":"lucide-folder","text":"Three small files in two folders give us something to look for.","cmd":"mkdir -p ~/lab/notes/old && cd ~/lab/notes\necho \"Hello Srinivas\" > hello.txt\nprintf 'hello world\nHELLO again\ngoodbye\n' > old/greet.txt\nprintf 'error: disk full\nwarn: slow\nerror: timeout\n' > old/app.log\nfind . -type f | sort","out":"./hello.txt\n./old/app.log\n./old/greet.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"find by name, type, size and age","icon":"lucide-search","text":"find walks folders. -name matches names (quote the pattern), -type f is files, -mtime -1 is changed in the last day, -size +1M is bigger than a megabyte.","cmd":"find . -name \"*.txt\"\nfind . -name \"hello*\" -type f\nfind . -mmin -60 -type f\nfind / -size +100M -type f 2>/dev/null | head -n 3","out":"./hello.txt\n./old/greet.txt\n./hello.txt\n./old/app.log\n./old/greet.txt\n./hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"grep searches text inside files","icon":"lucide-search","text":"grep prints lines that match. -i ignores case, -n shows line numbers, -r searches folders, -v inverts, -c counts, -w matches whole words.","cmd":"grep -i hello old/greet.txt\ngrep -rn \"error\" .\ngrep -c error old/app.log\ngrep -v error old/app.log","out":"hello world\nHELLO again\n./old/app.log:1:error: disk full\n./old/app.log:3:error: timeout\n2\nwarn: slow","outKind":"example","note":"","risk":false,"viz":""},{"title":"Count and rank","icon":"lucide-chart-line","text":"Put commands together with the pipe. sort orders lines, uniq -c counts neighbours, so sort first. This lists which words start each line of the log and how often.","cmd":"cut -d: -f1 old/app.log | sort | uniq -c | sort -rn\nwc -l old/*.txt old/*.log","out":"      2 error\n      1 warn\n  3 old/greet.txt\n  3 old/app.log\n  6 total","outKind":"example","note":"","risk":false,"viz":""},{"title":"Find and act: -exec and xargs","icon":"lucide-settings","text":"-exec runs a command on every match. xargs turns lines into arguments and is faster for many files. Test with echo before you delete anything.","cmd":"find . -name \"*.log\" -exec ls -l {} \\;\nfind . -name \"*.txt\" | xargs grep -l Srinivas\nfind . -name \"*.log\" -print0 | xargs -0 echo would-delete","out":"-rw-r--r-- 1 srinivas srinivas 44 Nov  4 10:20 ./old/app.log\n./hello.txt\nwould-delete ./old/app.log","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":41,"prev":{"id":"lnx-hello-perms","title":"Module 3: Who can read hello.txt? Permissions, owner and groups"},"next":{"id":"lnx-hello-redirect","title":"Module 5: Streams, redirects and pipes with hello.txt"}}},{"id":"lnx-hello-redirect","title":"Module 5: Streams, redirects and pipes with hello.txt","level":2,"icon":"lucide-arrow-right","summary":"Understand stdin, stdout and stderr, send each one where you want, and chain commands.","qna":[{"q":"In which situation do we use this?","a":"You want to save output, hide errors, or feed one command's result into the next."},{"q":"What is the difference between > and >>?","a":"> replaces the file, >> adds to the end. Mixing them up erases data."},{"q":"What comes next?","a":"Module 6 saves your commands in a script."}],"steps":[{"title":"Three streams","icon":"lucide-arrow-right","text":"Every program has standard input (0), standard output (1) and standard error (2). Normal results go to 1, error messages to 2. Both show on the screen unless you redirect them.","cmd":"cd ~/lab && echo \"Hello Srinivas\" > hello.txt\ncat hello.txt nofile.txt","out":"Hello Srinivas\ncat: nofile.txt: No such file or directory","outKind":"example","note":"","risk":false,"viz":""},{"title":"Redirect output","icon":"lucide-pencil","text":"> sends stdout to a file, >> appends, 2> sends only the errors, 2>&1 sends errors to the same place as stdout, &> sends both.","cmd":"cat hello.txt nofile.txt > out.txt 2> err.txt\ncat out.txt err.txt\ncat hello.txt nofile.txt &> both.txt\ncat nofile.txt 2> /dev/null; echo \"silent, exit $?\"","out":"Hello Srinivas\ncat: nofile.txt: No such file or directory\nsilent, exit 1","outKind":"example","note":"","risk":false,"viz":""},{"title":"Feed input from a file","icon":"lucide-download","text":"< makes a file the standard input. A here-document (<<) writes several lines straight into a command.","cmd":"wc -l < hello.txt\ncat > multi.txt <<'EOF'\nline one\nline two\nline three\nEOF\nsort -r < multi.txt","out":"1\nline two\nline three\nline one","outKind":"example","note":"","risk":false,"viz":""},{"title":"Pipe one command into the next","icon":"lucide-link","text":"| connects stdout of the left command to stdin of the right one. Each tool does one small job. tee also saves what passes through.","cmd":"cat multi.txt | grep line | wc -l\nls /etc | head -n 3 | tee first3.txt\ncat first3.txt | tr a-z A-Z","out":"3\nadduser.conf\nalternatives\napparmor\nADDUSER.CONF\nALTERNATIVES\nAPPARMOR","outKind":"example","note":"","risk":false,"viz":""},{"title":"Exit codes: success, failure and chaining","icon":"lucide-check","text":"Every command ends with a number: 0 means success. $? shows the last one. && runs the next command only on success, || only on failure, ; always.","cmd":"grep -q Srinivas hello.txt && echo found || echo missing\ngrep -q nobody hello.txt && echo found || echo missing\nfalse; echo \"exit code $?\"","out":"found\nmissing\nexit code 1","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":41,"prev":{"id":"lnx-hello-search","title":"Module 4: Find hello.txt and search inside files"},"next":{"id":"lnx-hello-script","title":"Module 6: Turn hello.txt into a script: variables, if, loops, functions"}}},{"id":"lnx-hello-script","title":"Module 6: Turn hello.txt into a script: variables, if, loops, functions","level":2,"icon":"lucide-code","summary":"Write hello.sh, make it executable, read arguments, test conditions, loop over files and set a safe mode.","qna":[{"q":"In which situation do we use this?","a":"A set of commands is run more than once, by you or by cron."},{"q":"Why use set -euo pipefail?","a":"The script stops at the first error instead of carrying on and doing damage."},{"q":"What comes next?","a":"Module 7 moves files between machines."}],"steps":[{"title":"A first script","icon":"lucide-pencil","text":"A script is a text file of commands. The first line, #!/usr/bin/env bash, says which interpreter runs it.","cmd":"cd ~/lab && printf '#!/usr/bin/env bash\necho \"Hello Srinivas\"\n' > hello.sh\ncat hello.sh\n./hello.sh","out":"bash: ./hello.sh: Permission denied","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make it executable and run it","icon":"lucide-play","text":"chmod +x adds the execute right. ./ means run the file in the current folder. You can also run bash hello.sh without it.","cmd":"chmod +x hello.sh\n./hello.sh\nbash hello.sh","out":"Hello Srinivas\nHello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Variables and arguments","icon":"lucide-sliders-horizontal","text":"NAME=value sets a variable with no spaces around =. $1 is the first argument, $# the count, \"$@\" all arguments. Always quote variables.","cmd":"cat > hello.sh <<'EOF'\n#!/usr/bin/env bash\nname=\"${1:-Srinivas}\"\necho \"Hello $name, you gave $# argument(s)\"\nEOF\n./hello.sh\n./hello.sh India Asia","out":"Hello Srinivas, you gave 0 argument(s)\nHello India, you gave 2 argument(s)","outKind":"example","note":"","risk":false,"viz":""},{"title":"Conditions","icon":"lucide-door-open","text":"if [ test ]; then ... fi. Useful tests: -f file exists, -d folder, -z empty text, -eq number equals, == text equals. Use [[ ]] in bash.","cmd":"cat > check.sh <<'EOF'\n#!/usr/bin/env bash\nif [[ -f hello.txt ]]; then\n  echo \"hello.txt exists, $(wc -c < hello.txt) bytes\"\nelse\n  echo \"hello.txt is missing\"; exit 1\nfi\nEOF\nbash check.sh","out":"hello.txt exists, 15 bytes","outKind":"example","note":"","risk":false,"viz":""},{"title":"Loops and functions","icon":"lucide-refresh-cw","text":"for repeats over a list, while repeats while a test is true, a function groups steps you reuse.","cmd":"cat > loop.sh <<'EOF'\n#!/usr/bin/env bash\ngreet() { echo \"Hello $1\"; }\nfor n in Srinivas India Linux; do greet \"$n\"; done\ni=1; while [[ $i -le 3 ]]; do echo \"count $i\"; i=$((i+1)); done\nEOF\nbash loop.sh","out":"Hello Srinivas\nHello India\nHello Linux\ncount 1\ncount 2\ncount 3","outKind":"example","note":"","risk":false,"viz":""},{"title":"Safer scripts","icon":"lucide-shield","text":"set -euo pipefail stops on the first error, on unset variables and on failures inside pipes. Check scripts with shellcheck.","cmd":"printf '#!/usr/bin/env bash\nset -euo pipefail\ncd /nonexistent\necho \"never printed\"\n' > safe.sh\nbash safe.sh; echo \"exit $?\"\nshellcheck hello.sh","out":"safe.sh: line 3: cd: /nonexistent: No such file or directory\nexit 1","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":41,"prev":{"id":"lnx-hello-redirect","title":"Module 5: Streams, redirects and pipes with hello.txt"},"next":{"id":"lnx-hello-remote","title":"Module 7: Send hello.txt to another server: ssh keys, scp and rsync"}}},{"id":"lnx-hello-remote","title":"Module 7: Send hello.txt to another server: ssh keys, scp and rsync","level":2,"icon":"lucide-upload","summary":"Make a key pair, install it on a server, log in without a password, copy hello.txt both ways and keep folders in sync.","qna":[{"q":"In which situation do we use this?","a":"You manage a remote server or copy files to it."},{"q":"Why use keys instead of passwords?","a":"Keys cannot be guessed, and once they work you can switch password logins off."},{"q":"What comes next?","a":"Module 8 protects the server with a firewall."}],"steps":[{"title":"Create a key pair","icon":"lucide-key-round","text":"A key pair has a private key (never share) and a public key (safe to give). ed25519 is short and strong. A passphrase protects the private key if the laptop is stolen.","cmd":"ssh-keygen -t ed25519 -C \"srinivas@laptop\" -f ~/.ssh/id_ed25519\nls -l ~/.ssh","out":"-rw------- 1 srinivas srinivas  411 Nov  4 10:30 id_ed25519\n-rw-r--r-- 1 srinivas srinivas  100 Nov  4 10:30 id_ed25519.pub","outKind":"example","note":"","risk":false,"viz":""},{"title":"Install the public key on the server","icon":"lucide-upload","text":"ssh-copy-id appends your public key to ~/.ssh/authorized_keys on the server. After this you do not need the account password.","cmd":"ssh-copy-id -i ~/.ssh/id_ed25519.pub srinivas@server.example.com\nssh srinivas@server.example.com 'hostname; whoami'","out":"Number of key(s) added: 1\nweb-01\nsrinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save the connection in ~/.ssh/config","icon":"lucide-file-text","text":"A named host saves typing. After this ssh web works, and so do scp and rsync.","cmd":"cat >> ~/.ssh/config <<'EOF'\nHost web\n  HostName server.example.com\n  User srinivas\n  IdentityFile ~/.ssh/id_ed25519\n  ServerAliveInterval 30\nEOF\nchmod 600 ~/.ssh/config\nssh web 'uptime'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Copy hello.txt with scp","icon":"lucide-files","text":"scp copies over SSH. The remote path comes after a colon. Copy to the server, then copy something back.","cmd":"scp hello.txt web:/tmp/hello.txt\nssh web 'cat /tmp/hello.txt'\nscp web:/etc/hostname ./remote-hostname.txt","out":"hello.txt                    100%   15     0.6KB/s   00:00\nHello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Keep a folder in sync with rsync","icon":"lucide-refresh-cw","text":"rsync sends only what changed, so the second run is fast. Use -n for a dry run first. A trailing slash on the source means the contents.","cmd":"rsync -avn ~/lab/ web:/tmp/lab/\nrsync -av ~/lab/ web:/tmp/lab/\nrsync -av --delete ~/lab/ web:/tmp/lab/","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Harden the server's SSH","icon":"lucide-shield","text":"Once keys work, turn off password logins and root login on the server. Test the config first and keep a second session open.","cmd":"sudo sshd -t && echo \"config ok\"\nsudo sed -i 's/^#\\?PasswordAuthentication.*/PasswordAuthentication no/' /etc/ssh/sshd_config\nsudo systemctl reload ssh","out":"config ok","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":41,"prev":{"id":"lnx-hello-script","title":"Module 6: Turn hello.txt into a script: variables, if, loops, functions"},"next":{"id":"lnx-nftables","title":"Module 8: The modern firewall: nftables and ufw"}}},{"id":"lnx-nftables","title":"Module 8: The modern firewall: nftables and ufw","level":3,"icon":"lucide-shield-ban","summary":"Read the rules, write a small default-deny ruleset with nft, test it safely and make it persistent.","qna":[{"q":"In which situation do we use this?","a":"A server is exposed to a network and only some ports should be reachable."},{"q":"What is the safest order?","a":"Allow your own SSH first, test from a second session, then set the default policy to drop."},{"q":"What comes next?","a":"Module 9 covers tools that make daily work faster."}],"steps":[{"title":"nftables replaces iptables","icon":"lucide-shield-ban","text":"nftables is the modern packet filter in the kernel. iptables commands on new systems are often a thin layer over it. One tool, nft, handles IPv4, IPv6 and bridges.","cmd":"nft --version\nsudo nft list ruleset | head -n 15","out":"nftables v1.0.9 (Old Doris #3)\ntable inet filter {\n  chain input {\n    type filter hook input priority filter; policy accept;\n  }\n}","outKind":"example","note":"","risk":false,"viz":""},{"title":"The model: tables, chains, rules","icon":"lucide-layers","text":"A table holds chains, a chain holds rules. A base chain attaches to a hook (input, forward, output) and has a policy. Each rule matches packets and gives a verdict such as accept or drop.","cmd":"sudo nft add table inet lab\nsudo nft 'add chain inet lab input { type filter hook input priority 0; policy accept; }'\nsudo nft list table inet lab","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write a default-deny ruleset","icon":"lucide-lock","text":"Keep established connections, allow loopback, allow SSH from one network and web, then drop the rest. Put SSH first so you cannot lock yourself out.","cmd":"sudo nft add rule inet lab input ct state established,related accept\nsudo nft add rule inet lab input iif lo accept\nsudo nft add rule inet lab input ip saddr 192.168.1.0/24 tcp dport 22 accept\nsudo nft add rule inet lab input tcp dport { 80, 443 } accept\nsudo nft 'add chain inet lab input { policy drop; }'","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"See counters and test","icon":"lucide-search","text":"Add counter to a rule to see how many packets matched. Test from another machine, and check the drop with a port you did not open.","cmd":"sudo nft add rule inet lab input counter\nsudo nft list chain inet lab input\nnc -zv server.example.com 80 22 8080","out":"Connection to server.example.com 80 port [tcp/http] succeeded!\nConnection to server.example.com 8080 port [tcp/*] timed out","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save and load at boot","icon":"lucide-save","text":"Export the running rules to /etc/nftables.conf and enable the service. flush ruleset at the top makes reloads repeatable.","cmd":"sudo nft list ruleset | sudo tee /etc/nftables.conf\nsudo nft -c -f /etc/nftables.conf && echo \"syntax ok\"\nsudo systemctl enable --now nftables","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The easy way: ufw","icon":"lucide-shield","text":"ufw is a simple front end for Ubuntu. Allow SSH before enabling it. Do not mix hand-written nft rules and ufw on the same host.","cmd":"sudo ufw allow OpenSSH\nsudo ufw allow 80,443/tcp\nsudo ufw enable\nsudo ufw status numbered","out":"Status: active\n\n     To                         Action      From\n[ 1] OpenSSH                    ALLOW IN    Anywhere\n[ 2] 80,443/tcp                 ALLOW IN    Anywhere","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":41,"prev":{"id":"lnx-hello-remote","title":"Module 7: Send hello.txt to another server: ssh keys, scp and rsync"},"next":{"id":"lnx-modern-cli","title":"Module 9: Modern command-line tools: jq, yq, rg, fd, bat, fzf"}}},{"id":"lnx-modern-cli","title":"Module 9: Modern command-line tools: jq, yq, rg, fd, bat, fzf","level":2,"icon":"lucide-filter","summary":"Read JSON and YAML, search and find faster, view files nicely and pick things interactively.","qna":[{"q":"In which situation do we use this?","a":"You read JSON or YAML output, search large trees, or want quicker daily work."},{"q":"Why jq?","a":"Cloud tools print JSON. jq pulls out exactly the fields you need."},{"q":"What comes next?","a":"Go deeper in the boot, services and storage modules."}],"steps":[{"title":"Install the tools","icon":"lucide-download","text":"All of these are in the standard repositories. The Debian and Ubuntu packages sometimes use different program names (batcat, fdfind).","cmd":"sudo apt install -y jq ripgrep fd-find bat fzf\njq --version && rg --version | head -n 1","out":"jq-1.7.1\nripgrep 14.1.0","outKind":"example","note":"","risk":false,"viz":""},{"title":"jq: query JSON","icon":"lucide-database","text":"jq reads JSON and prints parts of it. . is the whole thing, .name a field, .[] every item, select filters, -r prints raw text.","cmd":"echo '{\"name\":\"Srinivas\",\"skills\":[\"linux\",\"git\",\"aws\"],\"age\":30}' > me.json\njq . me.json\njq -r '.name' me.json\njq '.skills[]' me.json\njq '.skills | length' me.json","out":"\"Srinivas\"\n\"linux\"\n\"git\"\n\"aws\"\n3","outKind":"example","note":"","risk":false,"viz":""},{"title":"jq on real command output","icon":"lucide-settings","text":"Many tools can print JSON. Combine them to get a clean answer, like only the running container names or only some AWS fields.","cmd":"aws ec2 describe-instances --output json | jq -r '.Reservations[].Instances[] | [.InstanceId,.State.Name] | @tsv'\nkubectl get pods -o json | jq -r '.items[] | select(.status.phase!=\"Running\") | .metadata.name'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"yq: query and edit YAML","icon":"lucide-file-text","text":"yq does for YAML what jq does for JSON, and can edit in place. Handy for Kubernetes manifests and Ansible files.","cmd":"printf 'name: hello\nreplicas: 2\nimage: nginx:1.27\n' > app.yaml\nyq '.replicas' app.yaml\nyq -i '.replicas = 5' app.yaml\ncat app.yaml","out":"2\nname: hello\nreplicas: 5\nimage: nginx:1.27","outKind":"example","note":"","risk":false,"viz":""},{"title":"ripgrep and fd: faster search","icon":"lucide-search","text":"rg searches file contents and skips .git and ignored files by default. fd finds files by name with simple syntax and colour.","cmd":"rg \"Srinivas\" ~/lab\nrg -n --glob '*.sh' \"echo\" ~/lab\nfd '\\.txt$' ~/lab\nfd -e log -x wc -l {}","out":"/home/srinivas/lab/hello.txt:1:Hello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"bat, tree and fzf","icon":"lucide-eye","text":"bat shows a file with line numbers and colour. tree draws folders. fzf gives you a fuzzy picker; press Ctrl+R in the shell for fuzzy history.","cmd":"bat hello.txt\ntree -L 2 ~/lab\nls | fzf\nhistory | fzf --tac | head -n 1","out":"───────┬──────────────────────────────\n       │ File: hello.txt\n───────┼──────────────────────────────\n   1   │ Hello Srinivas\n───────┴──────────────────────────────","outKind":"example","note":"On Ubuntu the programs are batcat and fdfind. Add aliases for bat and fd.","risk":false,"viz":""}],"nav":{"pos":9,"of":41,"prev":{"id":"lnx-nftables","title":"Module 8: The modern firewall: nftables and ufw"},"next":{"id":"lnx-boot","title":"Linux boot process, end to end"}}},{"id":"lnx-boot","title":"Linux boot process, end to end","level":2,"icon":"lucide-power","summary":"Seven steps from power button to login prompt: firmware, boot loader, kernel, initramfs, systemd and services.","qna":[{"q":"In which situation do we use this?","a":"A server will not start, starts slowly, or you need to know whether it uses UEFI or legacy BIOS."},{"q":"What is the order of boot?","a":"Firmware, boot loader (GRUB), kernel plus initramfs, then systemd starts services until the target is reached."},{"q":"What comes next?","a":"lnx-boot-inspect to read the details, lnx-boot-slow to measure."}],"steps":[{"title":"Firmware: BIOS or UEFI","icon":"lucide-cpu","text":"Power on starts the firmware. It runs the power-on self-test (POST), initialises basic hardware and picks a boot device. UEFI loads a boot loader from the EFI System Partition (ESP) using entries stored in NVRAM. Legacy BIOS loads the boot sector (MBR) of the first bootable disk.","cmd":"[ -d /sys/firmware/efi ] && echo \"UEFI boot\" || echo \"Legacy BIOS boot\"\nsudo efibootmgr -v\nfindmnt /boot/efi","out":"$ [ -d /sys/firmware/efi ] && echo \"UEFI boot\" || echo \"Legacy BIOS boot\"\nUEFI boot\n$ findmnt /boot/efi\nTARGET    SOURCE         FSTYPE OPTIONS\n/boot/efi /dev/nvme0n1p1 vfat   rw,relatime","outKind":"example","note":"efibootmgr works only on UEFI systems. Boot order and Secure Boot are changed in the firmware setup screen.","risk":false,"viz":""},{"title":"Boot loader: GRUB","icon":"lucide-list-todo","text":"The firmware starts the boot loader, usually GRUB 2 (often through shim for Secure Boot). GRUB reads its configuration, shows the menu, loads the chosen kernel and the initramfs into memory and passes the kernel command line.","cmd":"cat /proc/cmdline\nls -lh /boot\nsudo grep -E '^\\s*(menuentry|linux|initrd)' /boot/grub/grub.cfg | head -n 6","out":"$ cat /proc/cmdline\nBOOT_IMAGE=/boot/vmlinuz-6.8.0-45-generic root=UUID=3f2a-example ro quiet splash","outKind":"example","note":"Change settings in /etc/default/grub, then run update-grub (Debian, Ubuntu) or grub2-mkconfig -o /boot/grub2/grub.cfg (RHEL 9). Do not edit grub.cfg by hand.","risk":false,"viz":""},{"title":"Kernel initialisation","icon":"lucide-cpu","text":"GRUB runs the kernel. It decompresses itself, sets up memory management and the scheduler, detects hardware, starts built-in drivers and mounts the initramfs as a temporary root filesystem. Everything it reports goes to the kernel ring buffer.","cmd":"uname -r\nsudo dmesg | head -n 12\njournalctl -k -b --no-pager | head -n 12","out":"$ uname -r\n6.8.0-45-generic\n$ sudo dmesg | head -n 2\n[    0.000000] Linux version 6.8.0-45-generic ...\n[    0.000000] Command line: BOOT_IMAGE=/boot/vmlinuz-6.8.0-45-generic ...","outKind":"example","note":"","risk":false,"viz":""},{"title":"initramfs: the temporary root","icon":"lucide-package","text":"The initramfs is a small compressed archive with just enough drivers and tools to find the real root filesystem: storage drivers, LVM or RAID assembly and disk decryption (LUKS). Once the real root is mounted, control switches to it and the init program starts.","cmd":"lsinitramfs /boot/initrd.img-$(uname -r) | head -n 15\nsudo lsinitrd /boot/initramfs-$(uname -r).img | head -n 15\nsudo update-initramfs -u","out":"","outKind":"","note":"The first command is for Debian and Ubuntu, the second for RHEL-family (dracut, rebuild with sudo dracut -f). Rebuild after changing storage, encryption or drivers.","risk":false,"viz":""},{"title":"systemd takes over as PID 1","icon":"lucide-settings","text":"The kernel starts /sbin/init, which on most distributions is systemd. As PID 1 it reads unit files, builds a dependency graph and activates the default target, starting units in parallel.","cmd":"ps -p 1 -o pid,comm\nsystemctl get-default\nsystemctl list-dependencies default.target | head -n 15","out":"$ ps -p 1 -o pid,comm\n    PID COMMAND\n      1 systemd\n$ systemctl get-default\ngraphical.target","outKind":"example","note":"","risk":false,"viz":""},{"title":"User-space services and login","icon":"lucide-log-in","text":"The default target pulls in services such as networking, logging, sshd, cron and a display manager. When the target is reached, getty or the display manager presents the login prompt.","cmd":"systemctl list-units --type=service --state=running | head -n 12\nsystemd-analyze\nsystemd-analyze blame | head -n 5","out":"$ systemd-analyze\nStartup finished in 2.9s (firmware) + 4.1s (loader) + 3.2s (kernel) + 9.8s (userspace) = 20.0s\ngraphical.target reached after 9.7s in userspace","outKind":"example","note":"The timings above are an example. Your numbers will differ.","risk":false,"viz":""},{"title":"Where boot fails: a troubleshooting map","icon":"lucide-search","text":"Firmware: \"No bootable device\" means check boot order, the disk and the ESP.\nGRUB: a grub rescue prompt means the config or kernel is missing, so reinstall GRUB.\nKernel: \"unable to mount root fs\" means a wrong root= or a missing driver in the initramfs.\ninitramfs: dropping to an (initramfs) shell means the root device was not found, so check the UUID, LVM and LUKS.\nsystemd: emergency mode usually means a failed mount in /etc/fstab.\nServices: the system boots but a service is missing, so run systemctl --failed.","cmd":"systemctl --failed\njournalctl -xb -p err --no-pager | tail -n 20","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":10,"of":41,"prev":{"id":"lnx-modern-cli","title":"Module 9: Modern command-line tools: jq, yq, rg, fd, bat, fzf"},"next":{"id":"lnx-boot-inspect","title":"Inspect your last boot"}}},{"id":"lnx-boot-inspect","title":"Inspect your last boot","level":1,"icon":"lucide-search","summary":"Find out when the system booted and read what the kernel and systemd reported.","qna":[{"q":"In which situation do we use this?","a":"After an unexpected reboot, or before changing boot settings. Check what actually ran during the last boot."},{"q":"Which command first?","a":"journalctl -b shows the current boot log; journalctl -b -1 shows the previous one."},{"q":"What comes next?","a":"If the previous boot failed, look at lnx-boot-rescue."}],"steps":[{"title":"When did it boot?","icon":"lucide-clock","text":"Start with the facts: how long the machine has been up, when it started, and whether there were earlier reboots.","cmd":"uptime -p\nuptime -s\nlast reboot | head -n 3","out":"$ uptime -p\nup 3 days, 4 hours, 12 minutes\n$ uptime -s\n2026-11-01 07:30:12","outKind":"example","note":"","risk":false,"viz":""},{"title":"Kernel warnings and errors","icon":"lucide-bug","text":"The kernel ring buffer holds hardware and driver messages from this boot. Filter for warnings and errors first.","cmd":"sudo dmesg --level=err,warn | head -n 20\njournalctl -k -b -p warning --no-pager | head -n 20","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"List boots and read an earlier one","icon":"lucide-file-text","text":"With a persistent journal you can read logs from previous boots, which is how you investigate a crash after the reboot.","cmd":"journalctl --list-boots\njournalctl -b -1 -p err --no-pager | tail -n 20\nsudo mkdir -p /var/log/journal && sudo systemctl restart systemd-journald","out":"","outKind":"","note":"The last command makes the journal persistent on systems where it is stored only in memory.","risk":false,"viz":""},{"title":"Time the boot","icon":"lucide-timer","text":"systemd-analyze shows how long each phase took and which units were slowest.","cmd":"systemd-analyze\nsystemd-analyze blame | head -n 8\nsystemd-analyze critical-chain","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":11,"of":41,"prev":{"id":"lnx-boot","title":"Linux boot process, end to end"},"next":{"id":"lnx-boot-slow","title":"Fix a slow boot"}}},{"id":"lnx-boot-slow","title":"Fix a slow boot","level":2,"icon":"lucide-timer","summary":"Measure, find the slowest units, follow the critical chain and trim what you do not need.","qna":[{"q":"In which situation do we use this?","a":"A machine takes minutes to become usable. Find which unit delays the boot."},{"q":"Which command shows the culprit?","a":"systemd-analyze blame lists units by time; critical-chain shows what the boot actually waited for."},{"q":"What comes next?","a":"Disable only units you understand, and compare with your baseline after the next reboot."}],"steps":[{"title":"Measure first","icon":"lucide-timer","text":"Record a baseline so you can prove an improvement later.","cmd":"systemd-analyze time","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Find the slowest units","icon":"lucide-search","text":"blame lists units by the time they took to start. A long time does not always mean the boot waited for it.","cmd":"systemd-analyze blame | head -n 10","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Follow the critical chain","icon":"lucide-arrow-right","text":"critical-chain shows what the boot actually waited for. Focus on units on this chain.","cmd":"systemd-analyze critical-chain","out":"","outKind":"","note":"The @ value is when a unit started and the + value is how long it took.","risk":false,"viz":""},{"title":"Disable a unit you do not need","icon":"lucide-power","text":"List enabled units, then disable one that is not needed on this machine. Check what depends on it first.","cmd":"systemctl list-unit-files --state=enabled | head -n 20\nsystemctl list-dependencies --reverse <service>\nsudo systemctl disable --now <service>","out":"","outKind":"","note":"Disable only units you understand. Re-enable with systemctl enable if something breaks.","risk":true,"viz":""},{"title":"Visualise and compare","icon":"lucide-chart-line","text":"Generate a timeline of the boot as an SVG and compare the total with your baseline after the next reboot.","cmd":"systemd-analyze plot > boot.svg\nsystemd-analyze","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":12,"of":41,"prev":{"id":"lnx-boot-inspect","title":"Inspect your last boot"},"next":{"id":"lnx-boot-rescue","title":"Rescue a system that will not boot"}}},{"id":"lnx-boot-rescue","title":"Rescue a system that will not boot","level":3,"icon":"lucide-wrench","summary":"Administrator recovery for a machine you own: GRUB, rescue target, remount and repair.","qna":[{"q":"In which situation do we use this?","a":"A machine you own will not boot after a bad update or an fstab mistake. Use rescue mode to repair it."},{"q":"What do I check first?","a":"Whether the root filesystem is mounted read-only, and the last lines of journalctl -xb."},{"q":"What comes next?","a":"After the repair, reboot and re-check; keep a note of what you changed."}],"steps":[{"title":"Reach the GRUB menu","icon":"lucide-list-todo","text":"Restart the machine. Hold Shift (BIOS) or press Esc (UEFI) while it starts to show the GRUB menu. Highlight the normal entry and press e to edit it. Keys vary by distribution.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Boot to the rescue target","icon":"lucide-wrench","text":"On the line that starts with linux, add systemd.unit=rescue.target at the end, then press Ctrl+X. Use emergency.target if rescue also fails. The change is temporary and is not saved.","cmd":"","out":"","outKind":"","note":"Rescue and emergency modes may ask for the root password, depending on the distribution.","risk":true,"viz":""},{"title":"Make the root filesystem writable","icon":"lucide-pencil","text":"In emergency mode the root filesystem is usually mounted read-only. Remount it read-write before fixing files.","cmd":"mount -o remount,rw /","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Find the cause","icon":"lucide-search","text":"Read the errors from this boot and check that every line in fstab can be mounted. A missing disk in fstab is a very common cause.","cmd":"journalctl -xb -p err --no-pager | tail -n 30\nfindmnt --verify\ncat /etc/fstab","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Fix and reboot","icon":"lucide-rocket","text":"Correct or comment out the bad entry, or add the nofail option for non-essential disks. Reload systemd and reboot.","cmd":"systemctl daemon-reload\nsystemctl reboot","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":13,"of":41,"prev":{"id":"lnx-boot-slow","title":"Fix a slow boot"},"next":{"id":"lnx-files-text","title":"Files and text: navigate, create, read"}}},{"id":"lnx-files-text","title":"Files and text: navigate, create, read","level":1,"icon":"lucide-folder","summary":"Start from Hello World: make a folder, create a .txt file and learn what the redirection symbols do.","qna":[{"q":"In which situation do we use this?","a":"Daily work on any server: moving around, reading logs and config, copying and removing files."},{"q":"What is the safe habit?","a":"Run ls and pwd before rm, and preview with ls pattern before using a wildcard in a delete."},{"q":"What comes next?","a":"lnx-permissions explains why some files cannot be opened."}],"steps":[{"title":"Where am I?","icon":"lucide-pin","text":"Every shell session has a current directory. pwd prints it, ls lists it and cd changes it.","cmd":"pwd\nls -la\ncd ~","out":"$ pwd\n/home/alice\n$ ls -la\ntotal 24\ndrwxr-x--- 3 alice alice 4096 Nov  4 10:00 .\n-rw-r--r-- 1 alice alice  220 Nov  4 10:00 .bashrc","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make a working folder","icon":"lucide-folder","text":"mkdir -p creates a folder and any parents that are missing, without an error if it already exists.","cmd":"mkdir -p ~/lab/notes\ncd ~/lab/notes\npwd","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create hello.txt","icon":"lucide-pencil","text":"echo prints text. The symbol > sends that output into a file instead of the screen, creating the file if it does not exist.","cmd":"echo \"Hello World\" > hello.txt\nls -l hello.txt","out":"$ ls -l hello.txt\n-rw-r--r-- 1 alice alice 12 Nov  4 10:05 hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the file and its syntax","icon":"lucide-eye","text":"A .txt file is plain text: characters grouped in lines, each ended by a newline character. cat prints the file, cat -A shows the hidden end of line as $, and wc -l counts lines.","cmd":"cat hello.txt\ncat -A hello.txt\nwc -l hello.txt","out":"$ cat -A hello.txt\nHello World$\n$ wc -l hello.txt\n1 hello.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Append or overwrite","icon":"lucide-plus","text":"> replaces the whole file. >> adds to the end. This is the most common way to lose a file by accident, so check which one you typed.","cmd":"echo \"Second line\" >> hello.txt\ncat hello.txt\necho \"Overwritten\" > hello.txt\ncat hello.txt","out":"","outKind":"","note":"set -o noclobber stops > from overwriting existing files in the current shell.","risk":false,"viz":""},{"title":"Copy, move and delete safely","icon":"lucide-files","text":"cp copies, mv moves or renames, rm deletes. The -i flag asks before acting.","cmd":"cp hello.txt backup.txt\nmv backup.txt archive.txt\nrm -i archive.txt","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":14,"of":41,"prev":{"id":"lnx-boot-rescue","title":"Rescue a system that will not boot"},"next":{"id":"lnx-permissions","title":"File permissions workshop"}}},{"id":"lnx-permissions","title":"File permissions workshop","level":1,"icon":"lucide-lock","summary":"Read ls -l, change permissions with chmod, set owners, understand umask and share a folder with a group.","qna":[{"q":"In which situation do we use this?","a":"You see \"Permission denied\", a script will not run, or a web server cannot read its files."},{"q":"What do the numbers mean?","a":"Read is 4, write is 2, execute is 1, added per owner, group and others. So 640 is rw- for owner, r-- for group."},{"q":"What comes next?","a":"Avoid chmod 777; give the right owner or group instead."}],"steps":[{"title":"Read ls -l","icon":"lucide-table","text":"The first character is the type (- file, d directory). The next nine are three triplets of read, write and execute for the owner, the group and everyone else.","cmd":"ls -l hello.txt","out":"-rw-r--r-- 1 alice alice 12 Nov  4 10:00 hello.txt\n^^^^ type and permissions, then links, owner, group, size, date, name","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add execute with symbolic mode","icon":"lucide-play","text":"A script is not runnable until it has the execute bit. chmod u+x adds execute for the owner only.","cmd":"echo 'echo hi' > run.sh\n./run.sh\nchmod u+x run.sh\n./run.sh","out":"$ ./run.sh\nbash: ./run.sh: Permission denied\n$ chmod u+x run.sh\n$ ./run.sh\nhi","outKind":"example","note":"","risk":false,"viz":""},{"title":"Numeric mode","icon":"lucide-calculator","text":"Read is 4, write is 2, execute is 1. Add them per triplet: 7 is rwx, 6 is rw-, 5 is r-x, 4 is r--. So 640 is rw-r-----, and 755 is rwxr-xr-x.","cmd":"chmod 640 hello.txt\nchmod 755 run.sh\nstat -c '%a %A %U:%G %n' hello.txt run.sh","out":"640 -rw-r----- alice:alice hello.txt\n755 -rwxr-xr-x alice:alice run.sh","outKind":"example","note":"","risk":false,"viz":""},{"title":"Change owner and group","icon":"lucide-users","text":"chown changes the owner and group. Only root can give a file to another user. The user and group must already exist.","cmd":"sudo chown alice:devs hello.txt\nls -l hello.txt","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Default permissions with umask","icon":"lucide-sliders-horizontal","text":"New files start at 666 and new directories at 777, then the umask bits are removed. A umask of 027 gives files 640 and directories 750.","cmd":"umask\numask 027\ntouch new.txt && ls -l new.txt","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Share a folder with setgid","icon":"lucide-users","text":"The setgid bit on a directory makes new files inherit the directory's group, which is what you want for a team folder.","cmd":"sudo mkdir /srv/shared\nsudo chgrp devs /srv/shared\nsudo chmod 2775 /srv/shared\nls -ld /srv/shared","out":"drwxrwsr-x 2 root devs 4096 Nov  4 10:20 /srv/shared","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":15,"of":41,"prev":{"id":"lnx-files-text","title":"Files and text: navigate, create, read"},"next":{"id":"lnx-users-groups","title":"Users and groups"}}},{"id":"lnx-users-groups","title":"Users and groups","level":2,"icon":"lucide-users","summary":"Create users and groups, grant sudo carefully, then lock and remove an account.","qna":[{"q":"In which situation do we use this?","a":"A new colleague, a service account, or access to a shared folder. Groups are cleaner than per-user rules."},{"q":"What goes wrong with usermod -G?","a":"It replaces the group list. Use usermod -aG to add a group and keep the existing ones."},{"q":"What comes next?","a":"Group changes apply at the next login."}],"steps":[{"title":"Who am I?","icon":"lucide-user","text":"id shows your user ID, primary group and every group you belong to.","cmd":"whoami\nid\ngroups","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a user","icon":"lucide-user","text":"On Debian and Ubuntu adduser is interactive and friendly. On RHEL-family systems use useradd, then set a password.","cmd":"sudo adduser alice\nsudo useradd -m -s /bin/bash alice && sudo passwd alice","out":"","outKind":"","note":"Use one of the two commands, depending on your distribution.","risk":false,"viz":""},{"title":"Create a group and add a member","icon":"lucide-users","text":"Always use -aG together. Without -a, usermod replaces all of the user's supplementary groups.","cmd":"sudo groupadd devs\nsudo usermod -aG devs alice\nid alice","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Give sudo rights","icon":"lucide-key-round","text":"Membership of the sudo group (Debian, Ubuntu) or wheel group (RHEL) grants sudo. Always validate sudoers syntax.","cmd":"sudo usermod -aG sudo alice\nsudo usermod -aG wheel alice\nsudo visudo -c","out":"","outKind":"","note":"Use sudo on Debian-family and wheel on RHEL-family systems.","risk":false,"viz":""},{"title":"Lock and remove an account","icon":"lucide-eraser","text":"Lock the password first so you can recover if needed. userdel -r also deletes the home directory.","cmd":"sudo passwd -l alice\nsudo userdel -r alice","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":16,"of":41,"prev":{"id":"lnx-permissions","title":"File permissions workshop"},"next":{"id":"lnx-find-search","title":"Find files and search inside them"}}},{"id":"lnx-find-search","title":"Find files and search inside them","level":1,"icon":"lucide-search","summary":"find by name, size and age, grep for text and combine them with xargs.","qna":[{"q":"In which situation do we use this?","a":"Find a lost file, large files filling a disk, files changed today, or text inside many files."},{"q":"find or grep?","a":"find searches names and file properties; grep searches contents. Combine them with -exec or xargs."},{"q":"What comes next?","a":"Test a find command without -delete first, then add it."}],"steps":[{"title":"Find by name","icon":"lucide-search","text":"find walks a directory tree. Quote patterns so the shell does not expand them.","cmd":"find ~/lab -name \"*.txt\"\nfind /var/log -type f -name \"*.log\" -mtime -1 2>/dev/null","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Find by size and time","icon":"lucide-clock","text":"Filter by size (+100M is larger than 100 MB) or by modification time (-mmin minutes, -mtime days).","cmd":"find / -xdev -type f -size +100M 2>/dev/null | head\nfind . -type f -mmin -30","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Search inside files with grep","icon":"lucide-search","text":"-r searches recursively, -n shows line numbers and -i ignores case. --include limits the files searched.","cmd":"grep -rn \"Hello\" ~/lab\ngrep -ri --include=\"*.conf\" \"listen\" /etc/nginx 2>/dev/null","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Combine find, xargs and locate","icon":"lucide-arrow-right","text":"Use -print0 with xargs -0 so file names with spaces are safe. locate is faster but uses a database that updatedb refreshes.","cmd":"find . -name \"*.log\" -print0 | xargs -0 grep -l \"ERROR\"\nsudo updatedb && locate hosts","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":17,"of":41,"prev":{"id":"lnx-users-groups","title":"Users and groups"},"next":{"id":"lnx-packages","title":"Software packages: apt and dnf"}}},{"id":"lnx-packages","title":"Software packages: apt and dnf","level":1,"icon":"lucide-package","summary":"Refresh, search, install, inspect and remove software on Debian-family and RHEL-family systems.","qna":[{"q":"In which situation do we use this?","a":"Installing, updating or removing software; checking which package owns a file; fixing a broken update."},{"q":"apt, dnf or rpm?","a":"apt (Debian, Ubuntu) and dnf (RHEL, Fedora) use repositories. dpkg and rpm work on single package files."},{"q":"What comes next?","a":"Run update before install, and read what will be removed before you confirm."}],"steps":[{"title":"Refresh the package index","icon":"lucide-refresh-cw","text":"Package managers keep a local index of what the repositories offer. Refresh it before installing.","cmd":"sudo apt update\nsudo dnf makecache","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Search and inspect","icon":"lucide-search","text":"Look at a package before installing it.","cmd":"apt search nginx | head\napt show nginx\ndnf info nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Install and upgrade","icon":"lucide-download","text":"-y answers yes to the prompt. Upgrade regularly for security fixes.","cmd":"sudo apt install -y nginx\nsudo dnf install -y nginx\nsudo apt upgrade -y\nsudo dnf upgrade -y","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Which package owns a file","icon":"lucide-link","text":"Map files back to packages and list what a package installed.","cmd":"dpkg -S /usr/sbin/nginx\ndpkg -L nginx | head\nrpm -qf /usr/sbin/nginx\nrpm -ql nginx | head","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Remove software","icon":"lucide-eraser","text":"remove keeps configuration files. autoremove deletes dependencies nobody needs any more.","cmd":"sudo apt remove nginx && sudo apt autoremove\nsudo dnf remove nginx","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":18,"of":41,"prev":{"id":"lnx-find-search","title":"Find files and search inside them"},"next":{"id":"lnx-systemd-services","title":"Manage services with systemctl"}}},{"id":"lnx-systemd-services","title":"Manage services with systemctl","level":1,"icon":"lucide-settings","summary":"Check, start, stop, enable at boot, read logs and find failed units.","qna":[{"q":"In which situation do we use this?","a":"A service needs to start, stop, restart, start at boot, or you need to know why it failed."},{"q":"start or enable?","a":"start runs it now; enable makes it start at boot. enable --now does both."},{"q":"What comes next?","a":"Read systemctl status and journalctl -u name for the reason."}],"steps":[{"title":"Check a service","icon":"lucide-eye","text":"status shows state, recent log lines and the main process. is-active and is-enabled are scriptable.","cmd":"systemctl status nginx --no-pager\nsystemctl is-active nginx\nsystemctl is-enabled nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Start, stop, restart, reload","icon":"lucide-play","text":"reload asks the service to re-read its configuration without dropping connections, if it supports that. restart stops and starts it.","cmd":"sudo systemctl start nginx\nsudo systemctl stop nginx\nsudo systemctl restart nginx\nsudo systemctl reload nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Enable at boot","icon":"lucide-check-check","text":"Start now and on every boot with enable --now. disable removes the boot link but does not stop a running service.","cmd":"sudo systemctl enable --now nginx\nsudo systemctl disable nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Read the logs","icon":"lucide-file-text","text":"journalctl -u shows the logs of one unit. -f follows new lines.","cmd":"journalctl -u nginx --since \"1 hour ago\" --no-pager\njournalctl -u nginx -f","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Find failed units","icon":"lucide-triangle-alert","text":"List everything that failed since boot, read why, fix it, then clear the failed state.","cmd":"systemctl --failed\nsudo systemctl reset-failed","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":19,"of":41,"prev":{"id":"lnx-packages","title":"Software packages: apt and dnf"},"next":{"id":"lnx-custom-service","title":"Project: run your own script as a service"}}},{"id":"lnx-custom-service","title":"Project: run your own script as a service","level":3,"icon":"lucide-rocket","summary":"Write a script, wrap it in a systemd unit, start it, watch it restart after a crash and clean up.","qna":[{"q":"In which situation do we use this?","a":"Your own script or app must run in the background, restart on failure and start at boot."},{"q":"What must I do after writing the unit file?","a":"Run systemctl daemon-reload so systemd reads it, then enable --now."},{"q":"What comes next?","a":"Add Restart=on-failure and a dedicated non-root user."}],"steps":[{"title":"Write the script","icon":"lucide-pencil","text":"A tiny script that logs a line every ten seconds. Under systemd, anything it prints goes to the journal.","cmd":"sudo tee /usr/local/bin/hello.sh > /dev/null <<'EOF'\n#!/usr/bin/env bash\nwhile true; do\n  echo \"hello from systemd at $(date)\"\n  sleep 10\ndone\nEOF\nsudo chmod 755 /usr/local/bin/hello.sh","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the unit file","icon":"lucide-file-text","text":"[Unit] describes it and its ordering, [Service] says what to run and when to restart, and [Install] says which target enables it at boot.","cmd":"sudo tee /etc/systemd/system/hello.service > /dev/null <<'EOF'\n[Unit]\nDescription=Hello demo service\nAfter=network.target\n\n[Service]\nExecStart=/usr/local/bin/hello.sh\nRestart=on-failure\nDynamicUser=yes\n\n[Install]\nWantedBy=multi-user.target\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Load and start it","icon":"lucide-play","text":"systemd must re-read unit files after you create or change one.","cmd":"sudo systemctl daemon-reload\nsudo systemctl enable --now hello.service\nsystemctl status hello.service --no-pager","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Read logs and test a crash","icon":"lucide-bug","text":"Kill the process with SIGKILL. Restart=on-failure treats that as a failure and starts it again.","cmd":"journalctl -u hello.service -n 5 --no-pager\nsudo systemctl kill -s KILL hello.service\nsystemctl status hello.service --no-pager","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Stop and disable the service, remove the files and reload systemd.","cmd":"sudo systemctl disable --now hello.service\nsudo rm /etc/systemd/system/hello.service /usr/local/bin/hello.sh\nsudo systemctl daemon-reload","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":20,"of":41,"prev":{"id":"lnx-systemd-services","title":"Manage services with systemctl"},"next":{"id":"lnx-processes","title":"Processes, signals and priority"}}},{"id":"lnx-processes","title":"Processes, signals and priority","level":2,"icon":"lucide-timer","summary":"List processes, watch resource use, stop them politely, run jobs in the background and change priority.","qna":[{"q":"In which situation do we use this?","a":"A program hangs, uses all the CPU, or you need to find what is listening on a port."},{"q":"kill or kill -9?","a":"kill sends a polite TERM so the program can clean up. Use -9 only when it ignores that."},{"q":"What comes next?","a":"lnx-diagnose-process goes deeper with lsof and strace."}],"steps":[{"title":"List processes","icon":"lucide-table","text":"ps takes a snapshot. pgrep finds process IDs by name.","cmd":"ps aux --sort=-%mem | head -n 6\nps -ef | grep [n]ginx\npgrep -a nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Watch live usage","icon":"lucide-timer","text":"top updates continuously. Batch mode prints one frame, which is handy in scripts and tickets.","cmd":"top -b -n 1 | head -n 15\nhtop","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Stop a process properly","icon":"lucide-circle-slash","text":"kill sends SIGTERM (15) by default, which lets the program clean up. SIGKILL (9) cannot be caught, so use it only as a last resort.","cmd":"sleep 300 &\nkill -15 %1\nkill -9 <pid>","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Foreground and background jobs","icon":"lucide-layers","text":"Append & to start a job in the background. Ctrl+Z suspends the foreground job, bg resumes it in the background and fg brings it forward.","cmd":"sleep 300\njobs\nbg %1\nfg %1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Change priority","icon":"lucide-arrow-up","text":"Niceness runs from -20 (highest priority) to 19 (lowest). Only root can lower the number.","cmd":"nice -n 10 sleep 60 &\nrenice -n 5 -p <pid>\nps -o pid,ni,comm -p <pid>","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":21,"of":41,"prev":{"id":"lnx-custom-service","title":"Project: run your own script as a service"},"next":{"id":"lnx-cron-timers","title":"Schedule jobs with cron and systemd timers"}}},{"id":"lnx-cron-timers","title":"Schedule jobs with cron and systemd timers","level":2,"icon":"lucide-clock","summary":"Read cron syntax, add a job, check its logs, then build the same schedule as a systemd timer.","qna":[{"q":"In which situation do we use this?","a":"Anything that must run on a schedule: backups, cleanup, reports, certificate renewal."},{"q":"Why does a cron job work by hand but not on schedule?","a":"Cron has a minimal environment and PATH. Use full paths and redirect output to a log file."},{"q":"What comes next?","a":"systemd timers add logging and catch-up runs with Persistent=true."}],"steps":[{"title":"Read the cron syntax","icon":"lucide-calendar","text":"Five fields then the command: minute, hour, day of month, month, day of week. */5 * * * * means every five minutes. Cron runs with a minimal environment, so use full paths.","cmd":"crontab -l","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add a job","icon":"lucide-plus","text":"Append a line to your crontab without opening an editor.","cmd":"(crontab -l 2>/dev/null; echo \"*/5 * * * * date >> $HOME/cron-test.log\") | crontab -\ntail -n 3 ~/cron-test.log","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check that cron ran it","icon":"lucide-file-text","text":"The cron daemon logs each run. The unit is cron on Debian and crond on RHEL.","cmd":"journalctl -u cron --since \"30 min ago\" --no-pager\njournalctl -u crond --since \"30 min ago\" --no-pager","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The same job as a systemd timer","icon":"lucide-clock","text":"A timer unit triggers a service unit of the same name. Persistent=true runs a missed job after the machine was off.","cmd":"sudo tee /etc/systemd/system/report.service > /dev/null <<'EOF'\n[Service]\nType=oneshot\nExecStart=/usr/bin/date\nEOF\nsudo tee /etc/systemd/system/report.timer > /dev/null <<'EOF'\n[Timer]\nOnCalendar=*-*-* 02:00:00\nPersistent=true\n\n[Install]\nWantedBy=timers.target\nEOF\nsudo systemctl daemon-reload && sudo systemctl enable --now report.timer\nsystemctl list-timers --all | head","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Remove the test jobs","icon":"lucide-eraser","text":"Remove the cron line and disable the timer.","cmd":"crontab -l | grep -v cron-test | crontab -\nsudo systemctl disable --now report.timer","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":22,"of":41,"prev":{"id":"lnx-processes","title":"Processes, signals and priority"},"next":{"id":"lnx-disks-mount","title":"Project: add a new disk"}}},{"id":"lnx-disks-mount","title":"Project: add a new disk","level":3,"icon":"lucide-database","summary":"Identify the disk, partition, format, mount and make the mount permanent.","qna":[{"q":"In which situation do we use this?","a":"Adding a new disk or volume to a server, or finding what is mounted where."},{"q":"What is the dangerous step?","a":"mkfs erases the target. Confirm the device name with lsblk and blkid before formatting."},{"q":"What comes next?","a":"Make it permanent in fstab (lnx-swap-fstab) and test with mount -a."}],"steps":[{"title":"Identify the disk","icon":"lucide-search","text":"List block devices and confirm which one is the new, empty disk. Double-check the name before touching anything: it is often sdb or nvme1n1.","cmd":"lsblk -f\nsudo fdisk -l /dev/sdb","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a partition table","icon":"lucide-pencil","text":"This writes a new GPT label and one partition covering the disk. Anything already on the disk becomes unreachable.","cmd":"sudo parted /dev/sdb --script mklabel gpt mkpart data ext4 0% 100%","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Format the partition","icon":"lucide-settings","text":"Create an ext4 filesystem with a label. This erases the partition.","cmd":"sudo mkfs.ext4 -L data /dev/sdb1","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Mount it","icon":"lucide-plug","text":"A mount point is just an empty directory. After mounting, the disk's space appears under it.","cmd":"sudo mkdir -p /mnt/data\nsudo mount /dev/sdb1 /mnt/data\ndf -h /mnt/data","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Make it permanent","icon":"lucide-save","text":"Use the UUID so the mount survives device renames. nofail stops a missing disk from blocking boot. Test with findmnt --verify and mount -a before rebooting.","cmd":"sudo blkid /dev/sdb1\necho 'UUID=<uuid> /mnt/data ext4 defaults,nofail 0 2' | sudo tee -a /etc/fstab\nsudo findmnt --verify\nsudo mount -a","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":23,"of":41,"prev":{"id":"lnx-cron-timers","title":"Schedule jobs with cron and systemd timers"},"next":{"id":"lnx-lvm-grow","title":"Grow a volume with LVM"}}},{"id":"lnx-lvm-grow","title":"Grow a volume with LVM","level":3,"icon":"lucide-layers","summary":"Inspect physical volumes, volume groups and logical volumes, then extend a volume online.","qna":[{"q":"In which situation do we use this?","a":"A filesystem is almost full and you need to grow it without downtime."},{"q":"What is the order?","a":"Extend the volume group with a new disk, extend the logical volume, then grow the filesystem. lvextend -r does the last two."},{"q":"What comes next?","a":"Shrinking is riskier than growing; plan sizes with room to expand."}],"steps":[{"title":"Inspect the layers","icon":"lucide-search","text":"Physical volumes (PV) are disks, volume groups (VG) pool them and logical volumes (LV) are what you mount.","cmd":"sudo pvs\nsudo vgs\nsudo lvs\ndf -h /data","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add a disk to the group","icon":"lucide-plus","text":"If the group has no free space, turn a new disk into a PV and add it. Skip this step if free space already exists.","cmd":"sudo pvcreate /dev/sdc\nsudo vgextend vg0 /dev/sdc","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Extend the volume and filesystem","icon":"lucide-arrow-up","text":"lvextend -r grows the filesystem together with the logical volume, in one step and online for ext4 and XFS.","cmd":"sudo lvextend -r -L +5G /dev/vg0/data","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify","icon":"lucide-check","text":"Confirm the new size at both the LVM and filesystem levels.","cmd":"df -h /data\nsudo lvs","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Snapshot before risky changes","icon":"lucide-camera","text":"A snapshot lets you roll back a change. It needs free space in the volume group. Remove it when you are done.","cmd":"sudo lvcreate -s -n data_snap -L 2G /dev/vg0/data\nsudo lvremove /dev/vg0/data_snap","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":24,"of":41,"prev":{"id":"lnx-disks-mount","title":"Project: add a new disk"},"next":{"id":"lnx-net-troubleshoot","title":"Troubleshoot Linux networking"}}},{"id":"lnx-net-troubleshoot","title":"Troubleshoot Linux networking","level":2,"icon":"lucide-network","summary":"Work from the interface outward: address, route, gateway, internet, DNS and ports.","qna":[{"q":"In which situation do we use this?","a":"A server cannot reach something, or cannot be reached. Work from your own interface outward."},{"q":"What is the order?","a":"Interface and IP, gateway, DNS, then the remote port. Stop at the first step that fails."},{"q":"What comes next?","a":"net-troubleshoot-method gives a layered checklist."}],"steps":[{"title":"Check the interface and address","icon":"lucide-plug","text":"Is the interface up and does it have an address?","cmd":"ip -br addr\nip -br link","out":"$ ip -br addr\nlo      UNKNOWN 127.0.0.1/8\neth0    UP      192.168.1.10/24","outKind":"example","note":"","risk":false,"viz":""},{"title":"Check the route and gateway","icon":"lucide-signpost","text":"The default route says where traffic to the internet goes. Ping that gateway.","cmd":"ip route\nping -c 2 $(ip route | awk '/default/ {print $3; exit}')","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Internet by IP, then by name","icon":"lucide-globe","text":"If the IP works but the name does not, the problem is DNS, not connectivity.","cmd":"ping -c 2 1.1.1.1\nping -c 2 example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check DNS","icon":"lucide-search","text":"See which resolver you use and query it directly.","cmd":"resolvectl status | head -n 15\ndig +short example.com","out":"","outKind":"","note":"resolvectl exists on systemd-resolved systems. Otherwise read /etc/resolv.conf.","risk":false,"viz":""},{"title":"Check listening ports and web access","icon":"lucide-plug","text":"Which services listen locally, and does an HTTPS request succeed?","cmd":"sudo ss -tulpn | head\ncurl -sS -o /dev/null -w \"%{http_code}\\n\" https://example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":25,"of":41,"prev":{"id":"lnx-lvm-grow","title":"Grow a volume with LVM"},"next":{"id":"lnx-harden-ssh-firewall","title":"Harden SSH and the firewall"}}},{"id":"lnx-harden-ssh-firewall","title":"Harden SSH and the firewall","level":3,"icon":"lucide-shield","summary":"Key login, safer sshd settings, a default-deny firewall and brute-force protection.","qna":[{"q":"In which situation do we use this?","a":"A new server on the internet: disable password logins and root login, allow only needed ports, ban repeated failures."},{"q":"What goes wrong if I rush?","a":"You can lock yourself out. Keep a second session open and test with sshd -t before restarting."},{"q":"What comes next?","a":"Add fail2ban and automatic security updates."}],"steps":[{"title":"Set up key login","icon":"lucide-key-round","text":"Generate a key pair on your workstation and install the public key on the server before you disable passwords.","cmd":"ssh-keygen -t ed25519 -C \"you@example.com\"\nssh-copy-id user@server\nssh user@server","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Harden sshd","icon":"lucide-lock","text":"Put your changes in a drop-in file, test the syntax with sshd -t, then reload. Keep your current session open until you have tested a new one.","cmd":"sudo cp /etc/ssh/sshd_config /etc/ssh/sshd_config.bak\nsudo tee /etc/ssh/sshd_config.d/10-hardening.conf > /dev/null <<'EOF'\nPermitRootLogin no\nPasswordAuthentication no\nEOF\nsudo sshd -t && sudo systemctl reload ssh","out":"","outKind":"","note":"The service is called ssh on Debian and Ubuntu and sshd on RHEL-family. Drop-in files need the default Include line in sshd_config.","risk":true,"viz":""},{"title":"Default-deny firewall with UFW","icon":"lucide-shield-ban","text":"Allow SSH first, then enable the firewall. Enabling it without that rule can lock you out of a remote machine.","cmd":"sudo ufw default deny incoming\nsudo ufw default allow outgoing\nsudo ufw allow OpenSSH\nsudo ufw allow 443/tcp\nsudo ufw enable\nsudo ufw status verbose","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Block brute-force attempts","icon":"lucide-shield","text":"fail2ban watches logs and bans addresses with repeated failures.","cmd":"sudo apt install -y fail2ban\nsudo tee /etc/fail2ban/jail.local > /dev/null <<'EOF'\n[sshd]\nenabled = true\nmaxretry = 5\nbantime = 1h\nEOF\nsudo systemctl enable --now fail2ban\nsudo fail2ban-client status sshd","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify the result","icon":"lucide-check","text":"Confirm the effective sshd settings and the firewall rules. Then test a login from a second terminal.","cmd":"sudo sshd -T | grep -E 'permitrootlogin|passwordauthentication'\nsudo ss -tulpn\nsudo ufw status numbered","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":26,"of":41,"prev":{"id":"lnx-net-troubleshoot","title":"Troubleshoot Linux networking"},"next":{"id":"lnx-logs","title":"Read and manage logs"}}},{"id":"lnx-logs","title":"Read and manage logs","level":2,"icon":"lucide-file-text","summary":"journalctl, the classic files in /var/log, login history and log rotation.","qna":[{"q":"In which situation do we use this?","a":"Something failed and you need to know what and when: a service crash, a login attempt, a disk error."},{"q":"journalctl or /var/log?","a":"journalctl queries the systemd journal by unit, time and priority. Plain files in /var/log hold text logs from other programs."},{"q":"What comes next?","a":"Rotate logs with logrotate so they do not fill the disk."}],"steps":[{"title":"journalctl basics","icon":"lucide-file-text","text":"The journal collects logs from the kernel, services and login sessions in one place.","cmd":"journalctl -n 20 --no-pager\njournalctl -p err -b --no-pager | tail -n 20","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Filter by unit and time","icon":"lucide-clock","text":"Combine -u with --since and --until to answer when and what.","cmd":"journalctl -u ssh --since today --no-pager\njournalctl --since \"2 hours ago\" --until \"1 hour ago\" --no-pager","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Follow logs live","icon":"lucide-eye","text":"-f follows new entries, the same idea as tail -f for classic files.","cmd":"journalctl -f\nsudo tail -f /var/log/syslog","out":"","outKind":"","note":"On RHEL-family systems the general log is /var/log/messages.","risk":false,"viz":""},{"title":"Classic files and login history","icon":"lucide-folder","text":"Authentication logs are in auth.log on Debian-family and secure on RHEL-family. last shows logins and lastb shows failed ones.","cmd":"ls /var/log\nsudo tail -n 20 /var/log/auth.log\nlast -n 5\nsudo lastb | head","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Rotation and disk use","icon":"lucide-refresh-cw","text":"logrotate keeps log files from growing forever. Test its configuration in debug mode, which changes nothing. Trim the journal only when you need space.","cmd":"sudo logrotate -d /etc/logrotate.conf\njournalctl --disk-usage\nsudo journalctl --vacuum-time=7d","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":27,"of":41,"prev":{"id":"lnx-harden-ssh-firewall","title":"Harden SSH and the firewall"},"next":{"id":"lnx-backup-restore","title":"Back up and restore, and prove it works"}}},{"id":"lnx-backup-restore","title":"Back up and restore, and prove it works","level":2,"icon":"lucide-files","summary":"tar archive, checksum, rsync mirror, a real restore test and a schedule.","qna":[{"q":"In which situation do we use this?","a":"Before any risky change, and on a schedule for data you cannot recreate."},{"q":"What is the rule people forget?","a":"A backup is only real after a restore test. Verify checksums and practise restoring to another folder."},{"q":"What comes next?","a":"Keep a copy off the machine, and automate with cron or a timer."}],"steps":[{"title":"Create an archive","icon":"lucide-package","text":"tar -czf creates a compressed archive. -C changes into a directory first, so the paths inside stay relative.","cmd":"tar -czf ~/backup-$(date +%F).tar.gz -C ~ lab\nls -lh ~/backup-*.tar.gz","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify the archive","icon":"lucide-check","text":"List the contents and store a checksum so you can detect corruption later.","cmd":"tar -tzf ~/backup-$(date +%F).tar.gz | head\nsha256sum ~/backup-$(date +%F).tar.gz > ~/backup.sha256\nsha256sum -c ~/backup.sha256","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Mirror with rsync","icon":"lucide-repeat","text":"Always do a dry run first. A trailing slash on the source means copy the contents. --delete removes files in the destination that no longer exist in the source.","cmd":"rsync -avh --dry-run ~/lab/ /mnt/backup/lab/\nrsync -avh ~/lab/ /mnt/backup/lab/","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Test a restore","icon":"lucide-flask-conical","text":"A backup you have never restored is only a hope. Restore into a temporary folder and compare.","cmd":"mkdir -p /tmp/restore-test && tar -xzf ~/backup-$(date +%F).tar.gz -C /tmp/restore-test\ndiff -r ~/lab /tmp/restore-test/lab && echo \"restore OK\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Schedule it","icon":"lucide-clock","text":"Run it nightly from cron. In a crontab the percent sign is special and must be escaped.","cmd":"(crontab -l 2>/dev/null; echo '0 2 * * * tar -czf $HOME/backup-$(date +\\%F).tar.gz -C $HOME lab') | crontab -","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":28,"of":41,"prev":{"id":"lnx-logs","title":"Read and manage logs"},"next":{"id":"lnx-health-script","title":"Project: a health-check script"}}},{"id":"lnx-health-script","title":"Project: a health-check script","level":2,"icon":"lucide-heart","summary":"Write a bash script that checks disk, memory and a service, returns a proper exit code and runs from cron.","qna":[{"q":"In which situation do we use this?","a":"You want a quick daily answer to \"is this server healthy?\": disk, memory, load and failed services."},{"q":"Why use thresholds?","a":"A script that only prints numbers is ignored. Exit non-zero when a limit is crossed so cron or monitoring can alert."},{"q":"What comes next?","a":"Run it from a timer and send the output to a log."}],"steps":[{"title":"Decide what to check","icon":"lucide-target","text":"Pick a few signals you can measure with standard tools and a threshold for each. Here: root disk under 90 percent, memory under 90 percent and the SSH service running.","cmd":"df -h /\nfree -m\nsystemctl is-active ssh","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the script","icon":"lucide-pencil","text":"set -euo pipefail makes the script stop on errors and unset variables. The script prints one line per failure and exits non-zero if anything failed.","cmd":"cat > ~/health.sh <<'EOF'\n#!/usr/bin/env bash\nset -euo pipefail\ndisk_pct=$(df --output=pcent / | tail -n 1 | tr -dc '0-9')\nmem_pct=$(free | awk '/Mem:/ {printf \"%d\", $3/$2*100}')\nfail=0\n[ \"$disk_pct\" -lt 90 ] || { echo \"FAIL disk ${disk_pct}%\"; fail=1; }\n[ \"$mem_pct\" -lt 90 ] || { echo \"FAIL memory ${mem_pct}%\"; fail=1; }\nsystemctl is-active --quiet sshd || systemctl is-active --quiet ssh || { echo \"FAIL ssh service\"; fail=1; }\n[ \"$fail\" -eq 0 ] && echo \"OK disk=${disk_pct}% mem=${mem_pct}%\"\nexit \"$fail\"\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run it and read the exit code","icon":"lucide-play","text":"Exit code 0 means healthy and anything else means a problem. Other tools, including cron wrappers and monitoring, rely on that.","cmd":"chmod +x ~/health.sh\n~/health.sh; echo \"exit code: $?\"","out":"OK disk=42% mem=57%\nexit code: 0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Schedule it","icon":"lucide-clock","text":"Run it every ten minutes and keep a log.","cmd":"(crontab -l 2>/dev/null; echo '*/10 * * * * $HOME/health.sh >> $HOME/health.log 2>&1') | crontab -","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Report failures to the journal","icon":"lucide-bell","text":"logger writes to the system journal with a tag you can search for later.","cmd":"~/health.sh || logger -t health -p user.err \"health check failed\"\njournalctl -t health -n 3 --no-pager","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":29,"of":41,"prev":{"id":"lnx-backup-restore","title":"Back up and restore, and prove it works"},"next":{"id":"lnx-text-pipeline","title":"Text pipelines: grep, awk, sed, sort and uniq"}}},{"id":"lnx-text-pipeline","title":"Text pipelines: grep, awk, sed, sort and uniq","level":2,"icon":"lucide-filter","summary":"Answer real questions about a log file by chaining small tools with the pipe.","qna":[{"q":"In which situation do we use this?","a":"A log or CSV is too large to read: count errors, rank top IPs, extract one column, clean text."},{"q":"Why sort before uniq?","a":"uniq only merges neighbouring duplicates, so unsorted input gives wrong counts."},{"q":"What comes next?","a":"For heavier analysis move to a script or a log tool."}],"steps":[{"title":"Make a sample access log","icon":"lucide-file-text","text":"Five lines are enough to practise. Each line holds an IP address, a status code and a path.","cmd":"printf '10.0.0.5 200 /home\n10.0.0.9 404 /missing\n10.0.0.5 200 /about\n10.0.0.7 500 /api\n10.0.0.9 404 /old\n' > access.log\ncat access.log","out":"$ cat access.log\n10.0.0.5 200 /home\n10.0.0.9 404 /missing\n10.0.0.5 200 /about\n10.0.0.7 500 /api\n10.0.0.9 404 /old","outKind":"example","note":"","risk":false,"viz":""},{"title":"The pipe connects commands","icon":"wf-pipe","text":"The pipe | sends the output of the left command into the input of the right one. Each tool does one small job; the chain does the big one.","cmd":"grep \" 404 \" access.log\ngrep -c \" 404 \" access.log","out":"$ grep \" 404 \" access.log\n10.0.0.9 404 /missing\n10.0.0.9 404 /old\n$ grep -c \" 404 \" access.log\n2","outKind":"example","note":"","risk":false,"viz":""},{"title":"awk and cut: pick columns","icon":"lucide-table","text":"awk splits each line into fields: $1 is the first word, $2 the second. cut does the same with a fixed delimiter. Both print only the columns you ask for.","cmd":"awk '{print $1}' access.log\ncut -d' ' -f3 access.log","out":"$ awk '{print $1}' access.log\n10.0.0.5\n10.0.0.9\n10.0.0.5\n10.0.0.7\n10.0.0.9","outKind":"example","note":"","risk":false,"viz":""},{"title":"sort and uniq: count and rank","icon":"lucide-chart-line","text":"uniq only collapses neighbouring duplicates, so sort first. uniq -c prefixes each line with its count and sort -rn ranks the biggest first. This is the classic \"top talkers\" pipeline.","cmd":"awk '{print $1}' access.log | sort | uniq -c | sort -rn","out":"$ awk '{print $1}' access.log | sort | uniq -c | sort -rn\n      2 10.0.0.9\n      2 10.0.0.5\n      1 10.0.0.7","outKind":"example","note":"","risk":false,"viz":""},{"title":"sed: search and replace","icon":"lucide-pencil","text":"sed edits a stream. s/old/new/ replaces the first match on each line, and the g flag replaces all of them. Without -i the file is left untouched.","cmd":"sed 's#/api#/v2/api#' access.log\nsed -n '2,3p' access.log","out":"","outKind":"","note":"On macOS use sed -i '' for in-place edits; on Linux use sed -i.","risk":false,"viz":""},{"title":"Count with awk and combine tools","icon":"lucide-timer","text":"awk can keep totals. This sums how many requests returned each status code. xargs turns lines into arguments for another command.","cmd":"awk '{c[$2]++} END {for (s in c) print s, c[s]}' access.log | sort\ngrep \" 500 \" access.log | tee errors.log | wc -l","out":"$ awk '{c[$2]++} END {for (s in c) print s, c[s]}' access.log | sort\n200 2\n404 2\n500 1","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":30,"of":41,"prev":{"id":"lnx-health-script","title":"Project: a health-check script"},"next":{"id":"lnx-links","title":"Symbolic and hard links explained"}}},{"id":"lnx-links","title":"Symbolic and hard links explained","level":1,"icon":"lucide-link","summary":"See the difference between a shortcut and a second name for the same data, using inode numbers.","qna":[{"q":"In which situation do we use this?","a":"Switching versions with a current -> v2 link, sharing one file under two names, or saving disk space."},{"q":"Hard or symbolic?","a":"Symbolic links point at a path and can break; hard links share the data and survive deleting the original name."},{"q":"What comes next?","a":"Use ln -sfn to replace a symlink safely."}],"steps":[{"title":"Create a file","icon":"lucide-file-text","text":"Every file is stored under an inode number, and names point at inodes. ls -i shows that number.","cmd":"mkdir -p ~/link-lab && cd ~/link-lab\necho \"original\" > a.txt\nls -li a.txt","out":"$ ls -li a.txt\n1049113 -rw-r--r-- 1 you you 9 Nov  4 10:00 a.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make a hard link","icon":"wf-hardlink","text":"A hard link is a second name for the same inode. Both names are equal: neither is the original, and the link count rises to 2.","cmd":"ln a.txt hard.txt\nls -li a.txt hard.txt","out":"$ ls -li a.txt hard.txt\n1049113 -rw-r--r-- 2 you you 9 Nov  4 10:00 a.txt\n1049113 -rw-r--r-- 2 you you 9 Nov  4 10:00 hard.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make a symbolic link","icon":"wf-symlink","text":"A symbolic link is a tiny file that stores a path. It has its own inode and ls shows an arrow to its target.","cmd":"ln -s a.txt soft.txt\nls -li soft.txt\nreadlink soft.txt","out":"$ ls -li soft.txt\n1049130 lrwxrwxrwx 1 you you 5 Nov  4 10:01 soft.txt -> a.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Edit through each link","icon":"lucide-pencil","text":"Writing through either kind of link changes the same data, because they all lead to one inode.","cmd":"echo \"changed\" >> hard.txt\ncat soft.txt","out":"$ cat soft.txt\noriginal\nchanged","outKind":"example","note":"","risk":false,"viz":""},{"title":"Delete the original and see what breaks","icon":"lucide-eraser","text":"Remove a.txt. The hard link still holds the data because the inode has another name. The symbolic link now points at nothing and is called dangling.","cmd":"rm a.txt\ncat hard.txt\ncat soft.txt\nls -l soft.txt","out":"$ cat soft.txt\ncat: soft.txt: No such file or directory","outKind":"example","note":"Hard links cannot cross filesystems or point at folders. Symbolic links can do both. Use ln -sf to replace an existing link.","risk":true,"viz":""}],"nav":{"pos":31,"of":41,"prev":{"id":"lnx-text-pipeline","title":"Text pipelines: grep, awk, sed, sort and uniq"},"next":{"id":"lnx-tmux-jobs","title":"Background jobs, nohup and tmux sessions"}}},{"id":"lnx-tmux-jobs","title":"Background jobs, nohup and tmux sessions","level":2,"icon":"lucide-terminal","summary":"Keep long tasks running, bring them back, and survive a closed terminal.","qna":[{"q":"In which situation do we use this?","a":"A long task runs over a remote session that might drop: builds, downloads, migrations."},{"q":"nohup or tmux?","a":"nohup just survives logout. tmux lets you detach and reattach, and see the live screen."},{"q":"What comes next?","a":"For real services use systemd, not a terminal session."}],"steps":[{"title":"Run a command in the background","icon":"lucide-play","text":"A trailing & starts the command and gives the prompt back. The shell prints a job number and the process ID.","cmd":"sleep 300 &\njobs","out":"$ sleep 300 &\n[1] 4821\n$ jobs\n[1]+  Running                 sleep 300 &","outKind":"example","note":"","risk":false,"viz":""},{"title":"Move jobs between foreground and background","icon":"lucide-repeat","text":"fg brings job 1 to the foreground. Press Ctrl+Z to suspend it, then bg lets it continue in the background.","cmd":"fg %1\nbg %1\njobs","out":"","outKind":"","note":"Ctrl+C stops a foreground job; kill %1 stops a background one.","risk":false,"viz":""},{"title":"nohup: survive closing the terminal","icon":"lucide-shield","text":"Closing a terminal sends SIGHUP to its jobs, which kills them. nohup ignores that signal and writes output to nohup.out.","cmd":"nohup ./long-task.sh > task.log 2>&1 &\ntail -f task.log","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"tmux: sessions you can leave and return to","icon":"wf-tmux","text":"tmux keeps a session alive on the machine even if your SSH connection drops. new -s names it, Ctrl+B then D detaches, and attach returns.","cmd":"tmux new -s build\ntmux ls\ntmux attach -t build","out":"$ tmux ls\nbuild: 1 windows (created Wed Nov  4 10:20:00 2026)","outKind":"example","note":"","risk":false,"viz":""},{"title":"tmux keys that matter","icon":"lucide-list-checks","text":"Every command starts with the prefix Ctrl+B. Then press: c new window, n next window, % split left/right, \" split top/bottom, arrow keys move between panes, d detach, [ scroll mode.","cmd":"tmux kill-session -t build\nwatch -n 2 'df -h /'","out":"","outKind":"","note":"watch reruns a command every N seconds, handy for disk and memory checks.","risk":false,"viz":""}],"nav":{"pos":32,"of":41,"prev":{"id":"lnx-links","title":"Symbolic and hard links explained"},"next":{"id":"lnx-diagnose-process","title":"Why is it slow? lsof, strace and vmstat"}}},{"id":"lnx-diagnose-process","title":"Why is it slow? lsof, strace and vmstat","level":3,"icon":"lucide-bug","summary":"Find which process holds a file or port, what system calls it makes, and whether memory or I/O is the bottleneck.","qna":[{"q":"In which situation do we use this?","a":"The server is slow, a port is busy, a file cannot be deleted, or a program fails with a vague error."},{"q":"Which tool for which symptom?","a":"vmstat for CPU, memory and I/O; lsof for open files and ports; strace for the failing system call."},{"q":"What comes next?","a":"Use strace briefly; it slows the program a lot."}],"steps":[{"title":"See overall load","icon":"lucide-timer","text":"uptime shows the load averages for 1, 5 and 15 minutes. As a rule of thumb, a load above the number of CPU cores means work is waiting. nproc gives the core count.","cmd":"uptime\nnproc\nvmstat 1 5","out":"$ uptime\n 10:31:02 up 4 days,  2:11,  1 user,  load average: 0.52, 0.48, 0.40\n$ nproc\n4","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read vmstat","icon":"lucide-chart-line","text":"Watch four columns. r is processes waiting for CPU, si/so is swapping to and from disk (should be 0), wa is CPU time spent waiting for I/O, and id is idle CPU.","cmd":"vmstat 1 3","out":"procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 0  0      0 812340  90112 1520000    0    0     4     9  210  380  3  1 96  0  0","outKind":"example","note":"","risk":false,"viz":""},{"title":"lsof: who has this file or port open?","icon":"lucide-search","text":"lsof lists open files, and on Linux a port or a deleted-but-still-open file counts as one. -i :80 finds whatever is using port 80; +L1 shows deleted files that still eat disk space.","cmd":"sudo lsof -i :80\nsudo lsof -p 1234 | head -n 20\nsudo lsof +L1","out":"$ sudo lsof -i :80\nCOMMAND  PID  USER  FD  TYPE DEVICE NODE NAME\nnginx    912  root  6u  IPv4  21345 TCP *:http (LISTEN)","outKind":"example","note":"","risk":false,"viz":""},{"title":"strace: watch system calls","icon":"lucide-eye","text":"strace prints every request a program makes to the kernel, such as open, read and connect. When a program fails with a vague error, the last failed call usually names the file or permission.","cmd":"strace -f -e trace=openat,connect -o trace.txt ls /nonexistent\ngrep -i enoent trace.txt | head -n 3","out":"$ grep -i enoent trace.txt | head -n 3\nopenat(AT_FDCWD, \"/nonexistent\", O_RDONLY) = -1 ENOENT (No such file or directory)","outKind":"example","note":"strace slows the program a lot. Use it for diagnosis, not on busy production services for long.","risk":false,"viz":""},{"title":"Check shared libraries and per-process memory","icon":"lucide-box","text":"ldd shows which libraries a binary needs, and a missing one is a frequent cause of \"cannot open shared object file\". ps sorted by memory finds the biggest consumers.","cmd":"ldd /usr/bin/curl | head -n 5\nps -eo pid,comm,%mem,%cpu --sort=-%mem | head -n 5","out":"$ ps -eo pid,comm,%mem,%cpu --sort=-%mem | head -n 5\n  PID COMMAND         %MEM %CPU\n 1530 java            12.4  8.1\n  912 nginx            0.6  0.1","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":33,"of":41,"prev":{"id":"lnx-tmux-jobs","title":"Background jobs, nohup and tmux sessions"},"next":{"id":"lnx-selinux-basics","title":"SELinux basics: modes, contexts and booleans"}}},{"id":"lnx-selinux-basics","title":"SELinux basics: modes, contexts and booleans","level":3,"icon":"lucide-shield","summary":"Understand why SELinux denies an action, read the denial, and fix the label instead of turning it off.","qna":[{"q":"In which situation do we use this?","a":"Permissions look right but access is still denied on a RHEL-family machine, often for web content or custom folders."},{"q":"What should I avoid?","a":"Disabling SELinux. Fix the label with restorecon or semanage fcontext, or set the right boolean."},{"q":"What comes next?","a":"Use setenforce 0 only to test the theory, then switch back with setenforce 1."}],"steps":[{"title":"Check the mode","icon":"lucide-eye","text":"SELinux is mandatory access control on top of normal permissions. Enforcing blocks and logs; permissive only logs; disabled is off. getenforce shows the current mode and sestatus shows more.","cmd":"getenforce\nsestatus","out":"$ getenforce\nEnforcing","outKind":"example","note":"SELinux is standard on RHEL, Fedora and Rocky. Ubuntu uses AppArmor instead (aa-status).","risk":false,"viz":""},{"title":"Look at labels","icon":"wf-label","text":"Every file and process has a context: user:role:type:level. The type is what policy rules mostly use. -Z adds contexts to ls and ps.","cmd":"ls -Z /var/www/html\nps -eZ | grep httpd | head -n 2","out":"$ ls -Z /var/www/html\nunconfined_u:object_r:httpd_sys_content_t:s0 index.html","outKind":"example","note":"","risk":false,"viz":""},{"title":"Reproduce a denial","icon":"lucide-ban","text":"Web content must carry the type httpd_sys_content_t. A file moved in from a home folder keeps its old label, so Apache is refused even though normal permissions look fine.","cmd":"sudo cp ~/page.html /var/www/html/\ncurl -I http://localhost/page.html\nls -Z /var/www/html/page.html","out":"$ curl -I http://localhost/page.html\nHTTP/1.1 403 Forbidden","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the denial","icon":"lucide-file-text","text":"Denials go to the audit log. ausearch filters it and sealert (if installed) explains the cause and a suggested fix in plain language.","cmd":"sudo ausearch -m avc -ts recent\nsudo journalctl -t setroubleshoot --since \"10 min ago\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Fix the label, not the mode","icon":"lucide-wrench","text":"restorecon resets a file to the label that policy defines for its path. For a custom folder, register the rule once with semanage fcontext and then restorecon -R. Booleans such as httpd_can_network_connect toggle common behaviours.","cmd":"sudo restorecon -v /var/www/html/page.html\nsudo semanage fcontext -a -t httpd_sys_content_t \"/srv/site(/.*)?\"\nsudo restorecon -Rv /srv/site\ngetsebool httpd_can_network_connect\nsudo setsebool -P httpd_can_network_connect on","out":"","outKind":"","note":"setenforce 0 only switches to permissive until reboot. Use it to test whether SELinux is the cause, then fix the label and set it back with setenforce 1.","risk":true,"viz":""}],"nav":{"pos":34,"of":41,"prev":{"id":"lnx-diagnose-process","title":"Why is it slow? lsof, strace and vmstat"},"next":{"id":"lnx-swap-fstab","title":"Swap space and permanent mounts with fstab"}}},{"id":"lnx-swap-fstab","title":"Swap space and permanent mounts with fstab","level":2,"icon":"lucide-database","summary":"Add a swap file, mount a disk automatically at boot, and test the file before you reboot.","qna":[{"q":"In which situation do we use this?","a":"Memory pressure on a small server, or a data disk that must mount automatically at boot."},{"q":"What protects me from a bad fstab?","a":"Run mount -a and findmnt --verify before rebooting, and use nofail on non-essential disks."},{"q":"What comes next?","a":"Keep a backup copy of fstab before editing."}],"steps":[{"title":"Check memory and swap","icon":"lucide-timer","text":"free shows RAM and swap. swapon --show lists active swap devices. If swap is heavily used while RAM is full, the machine is short of memory.","cmd":"free -h\nswapon --show","out":"$ free -h\n               total        used        free      shared  buff/cache   available\nMem:           7.7Gi       2.1Gi       3.4Gi       0.1Gi       2.2Gi       5.3Gi\nSwap:             0B          0B          0B","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a swap file","icon":"wf-swap-space","text":"A swap file is an ordinary file the kernel treats as extra memory on disk. It must have no gaps (so no sparse files) and be readable only by root.","cmd":"sudo fallocate -l 1G /swapfile\nsudo chmod 600 /swapfile\nsudo mkswap /swapfile\nsudo swapon /swapfile\nswapon --show","out":"$ swapon --show\nNAME      TYPE SIZE USED PRIO\n/swapfile file   1G   0B   -2","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make swap permanent","icon":"lucide-save","text":"Swap enabled by swapon disappears at reboot. The fstab file lists everything to mount at boot, one line per entry with six fields.","cmd":"echo '/swapfile none swap sw 0 0' | sudo tee -a /etc/fstab\ncat /etc/fstab","out":"","outKind":"","note":"Always back up first: sudo cp /etc/fstab /etc/fstab.bak","risk":true,"viz":""},{"title":"Understand the fstab fields","icon":"wf-mount","text":"In order: device (a UUID is safest), mount point, filesystem type, options, dump flag (0) and fsck pass (0 skip, 1 root, 2 others). nofail stops a missing disk from blocking boot.","cmd":"blkid /dev/sdb1\necho 'UUID=1234-ABCD /data ext4 defaults,nofail 0 2' | sudo tee -a /etc/fstab","out":"$ blkid /dev/sdb1\n/dev/sdb1: UUID=\"1234-ABCD\" TYPE=\"ext4\"","outKind":"example","note":"","risk":true,"viz":""},{"title":"Test before you reboot","icon":"lucide-check","text":"A mistake in fstab can stop the system booting. mount -a mounts everything listed and reports errors now, while you can still fix them. findmnt --verify checks the syntax.","cmd":"sudo mount -a\nfindmnt --verify\nfindmnt /data\nsudo sysctl vm.swappiness","out":"$ sudo sysctl vm.swappiness\nvm.swappiness = 60","outKind":"example","note":"Lower swappiness (for example 10) makes the kernel prefer RAM. Persist it in /etc/sysctl.d/99-swap.conf.","risk":false,"viz":""}],"nav":{"pos":35,"of":41,"prev":{"id":"lnx-selinux-basics","title":"SELinux basics: modes, contexts and booleans"},"next":{"id":"lnx-csv-report","title":"Build a report from CSV with awk, sort and column"}}},{"id":"lnx-csv-report","title":"Build a report from CSV with awk, sort and column","level":2,"icon":"lucide-table","summary":"Turn raw rows into totals, averages and a tidy table using only standard tools.","qna":[{"q":"In which situation do we use this?","a":"A quick answer is needed from a CSV or log: totals per group, the largest value, an average. No spreadsheet is available on the server."},{"q":"When is awk the wrong tool?","a":"When fields contain quoted commas or newlines. Use a CSV-aware tool or Python for those files."},{"q":"What comes next?","a":"Save the one-liner as a script and run it from cron for a daily report."}],"steps":[{"title":"Create a small CSV","icon":"lucide-file-text","text":"Comma separated values are one record per line. This sample lists orders with a region and an amount.","cmd":"printf 'region,item,amount\nnorth,disk,120\nsouth,cpu,300\nnorth,ram,80\neast,disk,150\nsouth,ram,95\n' > orders.csv\ncat orders.csv","out":"$ cat orders.csv\nregion,item,amount\nnorth,disk,120\nsouth,cpu,300\nnorth,ram,80\neast,disk,150\nsouth,ram,95","outKind":"example","note":"","risk":false,"viz":""},{"title":"Skip the header, pick columns","icon":"lucide-filter","text":"awk -F, sets the field separator. NR>1 skips line 1, the header. $1 and $3 are the first and third fields.","cmd":"awk -F, 'NR>1 {print $1, $3}' orders.csv","out":"$ awk -F, 'NR>1 {print $1, $3}' orders.csv\nnorth 120\nsouth 300\nnorth 80\neast 150\nsouth 95","outKind":"example","note":"","risk":false,"viz":""},{"title":"Total per region","icon":"lucide-chart-line","text":"awk arrays sum by key. The END block runs after the last line. Sort the result to make it stable.","cmd":"awk -F, 'NR>1 {sum[$1]+=$3} END {for (r in sum) print r, sum[r]}' orders.csv | sort","out":"$ awk -F, 'NR>1 {sum[$1]+=$3} END {for (r in sum) print r, sum[r]}' orders.csv | sort\neast 150\nnorth 200\nsouth 395","outKind":"example","note":"","risk":false,"viz":""},{"title":"Average and the biggest order","icon":"lucide-timer","text":"Keep a running total and count, and track a maximum. printf formats the numbers.","cmd":"awk -F, 'NR>1 {t+=$3; n++; if ($3>m) {m=$3; who=$2}} END {printf \"orders=%d average=%.1f biggest=%s (%d)\n\", n, t/n, who, m}' orders.csv","out":"$ awk -F, 'NR>1 {t+=$3; n++; if ($3>m) {m=$3; who=$2}} END {printf \"orders=%d average=%.1f biggest=%s (%d)\n\", n, t/n, who, m}' orders.csv\norders=5 average=149.0 biggest=cpu (300)","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make it readable with column","icon":"lucide-list-todo","text":"column -t aligns text into a table. Pipe the report through it before you paste it in a ticket.","cmd":"awk -F, 'NR>1 {sum[$1]+=$3} END {for (r in sum) print r, sum[r]}' orders.csv | sort -k2 -nr | column -t","out":"$ ... | column -t\nsouth  395\nnorth  200\neast   150","outKind":"example","note":"For quoted fields that contain commas use a real CSV tool such as csvkit or Python's csv module, not awk.","risk":false,"viz":""}],"nav":{"pos":36,"of":41,"prev":{"id":"lnx-swap-fstab","title":"Swap space and permanent mounts with fstab"},"next":{"id":"lnx-namespaces-cgroups","title":"Containers underneath: namespaces and cgroups"}}},{"id":"lnx-namespaces-cgroups","title":"Containers underneath: namespaces and cgroups","level":4,"icon":"lucide-box","summary":"See that a container is a process with its own view (namespaces) and limits (cgroups).","qna":[{"q":"In which situation do we use this?","a":"Understanding what a container really is, or debugging why a container hits a memory or CPU limit."},{"q":"What is the difference between the two?","a":"Namespaces limit what a process can see; cgroups limit how much it can use."},{"q":"What comes next?","a":"Read docker inspect and the pod resource limits with these two ideas in mind."}],"steps":[{"title":"Look at the namespaces of a process","icon":"lucide-eye","text":"Each process belongs to namespaces that control what it can see: PID, network, mount, user and more. lsns lists them and /proc shows the links.","cmd":"lsns | head -n 8\nls -l /proc/$$/ns","out":"$ ls -l /proc/$$/ns\nlrwxrwxrwx 1 you you 0 Nov  4 10:00 net -> 'net:[4026531840]'\nlrwxrwxrwx 1 you you 0 Nov  4 10:00 pid -> 'pid:[4026531836]'","outKind":"example","note":"","risk":false,"viz":""},{"title":"A new PID namespace","icon":"wf-namespace","text":"unshare starts a program in new namespaces. With a private PID namespace the shell sees itself as process 1 and sees none of the host's processes.","cmd":"sudo unshare --pid --fork --mount-proc bash\nps -ef\nexit","out":"$ ps -ef\nUID  PID PPID C STIME TTY TIME CMD\nroot   1    0 0 10:05 pts/0 00:00:00 bash\nroot   8    1 0 10:05 pts/0 00:00:00 ps -ef","outKind":"example","note":"Run this only on a machine you administer, such as a test VM.","risk":true,"viz":""},{"title":"A private network","icon":"lucide-network","text":"ip netns creates a named network namespace with its own interfaces and routing table. Initially it has only a loopback that is down.","cmd":"sudo ip netns add demo\nsudo ip netns exec demo ip -br addr\nsudo ip netns delete demo","out":"$ sudo ip netns exec demo ip -br addr\nlo               DOWN           127.0.0.1/8","outKind":"example","note":"","risk":false,"viz":""},{"title":"Limit resources with cgroups","icon":"wf-cgroup","text":"Control groups limit CPU, memory and I/O. systemd-run starts a command in a temporary scope with limits, here 200 MB of memory and 20% of one CPU.","cmd":"systemd-run --user --scope -p MemoryMax=200M -p CPUQuota=20% sleep 60 &\nsystemd-cgls --user | head -n 12","out":"$ systemd-run --user --scope -p MemoryMax=200M -p CPUQuota=20% sleep 60 &\nRunning scope as unit: run-r2f3a.scope","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the limit from cgroup files","icon":"lucide-file-text","text":"cgroup v2 exposes every setting as a file under /sys/fs/cgroup. Docker and Kubernetes write the same files for each container.","cmd":"stat -fc %T /sys/fs/cgroup\ncat /sys/fs/cgroup/user.slice/memory.max","out":"$ stat -fc %T /sys/fs/cgroup\ncgroup2fs","outKind":"example","note":"A container runtime combines these primitives plus a root filesystem image. There is no virtual machine involved.","risk":false,"viz":""}],"nav":{"pos":37,"of":41,"prev":{"id":"lnx-csv-report","title":"Build a report from CSV with awk, sort and column"},"next":{"id":"lnx-audit-gpg","title":"Audit file changes and encrypt a file"}}},{"id":"lnx-audit-gpg","title":"Audit file changes and encrypt a file","level":3,"icon":"lucide-lock","summary":"Record who touches a sensitive file with auditd, then protect a file with gpg and check its checksum.","qna":[{"q":"In which situation do we use this?","a":"You must know who changed a sensitive file, or you must store a secret in a file safely."},{"q":"Is a checksum a signature?","a":"No. A checksum shows the file changed; only a signature shows who produced it."},{"q":"What comes next?","a":"Ship audit logs to a central place so an intruder cannot erase them."}],"steps":[{"title":"Check that auditd is running","icon":"lucide-eye","text":"The audit daemon records security events from the kernel. auditctl -s shows its status.","cmd":"sudo systemctl status auditd --no-pager | head -n 4\nsudo auditctl -s","out":"$ sudo auditctl -s\nenabled 1\nfailure 1\npid 812","outKind":"example","note":"","risk":false,"viz":""},{"title":"Watch a file","icon":"lucide-search","text":"-w sets a watch on a path, -p wa logs writes and attribute changes, and -k adds a key for searching later.","cmd":"sudo auditctl -w /etc/hosts -p wa -k hosts_change\necho \"# test\" | sudo tee -a /etc/hosts\nsudo ausearch -k hosts_change -i | tail -n 6","out":"$ sudo ausearch -k hosts_change -i | tail -n 6\ntype=SYSCALL ... comm=tee exe=/usr/bin/tee key=hosts_change","outKind":"example","note":"","risk":true,"viz":""},{"title":"Make the rule permanent","icon":"lucide-save","text":"Rules added with auditctl vanish at reboot. Put them in a file under /etc/audit/rules.d and load them.","cmd":"echo '-w /etc/hosts -p wa -k hosts_change' | sudo tee /etc/audit/rules.d/hosts.rules\nsudo augenrules --load\nsudo auditctl -l","out":"$ sudo auditctl -l\n-w /etc/hosts -p wa -k hosts_change","outKind":"example","note":"","risk":false,"viz":""},{"title":"Encrypt a file with gpg","icon":"lucide-lock","text":"gpg --symmetric encrypts with a passphrase using AES256. The result has the extension .gpg. Keep the passphrase in a password manager.","cmd":"echo \"api token 12345\" > secret.txt\ngpg --symmetric --cipher-algo AES256 secret.txt\nshred -u secret.txt\nls -l secret.txt.gpg","out":"$ ls -l secret.txt.gpg\n-rw-r--r-- 1 you you 98 Nov  4 10:30 secret.txt.gpg","outKind":"example","note":"","risk":false,"viz":""},{"title":"Decrypt and verify integrity","icon":"lucide-check","text":"Decrypt to standard output to read it without writing the plain text again. sha256sum gives a checksum you can compare to detect any change of a file.","cmd":"gpg --decrypt secret.txt.gpg\nsha256sum secret.txt.gpg > secret.sha256\nsha256sum -c secret.sha256","out":"$ sha256sum -c secret.sha256\nsecret.txt.gpg: OK","outKind":"example","note":"A checksum proves the file is unchanged, not who made it. Use signatures for that.","risk":false,"viz":""}],"nav":{"pos":38,"of":41,"prev":{"id":"lnx-namespaces-cgroups","title":"Containers underneath: namespaces and cgroups"},"next":{"id":"lnx-rsync-tar","title":"Copy and archive safely with rsync and tar"}}},{"id":"lnx-rsync-tar","title":"Copy and archive safely with rsync and tar","level":2,"icon":"lucide-files","summary":"Preview a sync with a dry run, mirror a folder, and create, inspect and restore a tar archive.","qna":[{"q":"In which situation do we use this?","a":"Backups, migrating data between servers, deploying a folder, or packaging files for transfer."},{"q":"What is the main danger?","a":"--delete with a wrong path or a missing trailing slash. Always run with -n first and read the list."},{"q":"What comes next?","a":"Add a restore test, as in lnx-backup-restore."}],"steps":[{"title":"Prepare two folders","icon":"lucide-folder","text":"A source with a few files and an empty destination.","cmd":"mkdir -p ~/rs/src/docs ~/rs/dst && cd ~/rs\necho one > src/a.txt && echo two > src/docs/b.txt\nfind src -type f","out":"$ find src -type f\nsrc/a.txt\nsrc/docs/b.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Always preview first","icon":"lucide-eye","text":"-a keeps permissions, times and folders; -v lists files. --dry-run (-n) shows what would happen without doing it. A trailing slash on the source means \"the contents of\".","cmd":"rsync -avn src/ dst/","out":"$ rsync -avn src/ dst/\nsending incremental file list\n./\na.txt\ndocs/\ndocs/b.txt\n\n(DRY RUN)","outKind":"example","note":"","risk":false,"viz":""},{"title":"Sync, change, and sync again","icon":"lucide-refresh-cw","text":"The second run copies only what changed, which is why rsync is fast for backups.","cmd":"rsync -av src/ dst/\necho three >> src/a.txt\nrsync -av src/ dst/","out":"$ rsync -av src/ dst/\nsending incremental file list\na.txt","outKind":"example","note":"","risk":false,"viz":""},{"title":"Mirror with --delete","icon":"lucide-eraser","text":"--delete removes files from the destination that no longer exist in the source, making it an exact mirror. Check with a dry run first.","cmd":"rm src/docs/b.txt\nrsync -avn --delete src/ dst/\nrsync -av --delete src/ dst/","out":"","outKind":"","note":"A wrong source or a missing trailing slash with --delete can remove the wrong data.","risk":true,"viz":""},{"title":"tar: archive, list, restore","icon":"lucide-package","text":"c creates, t lists, x extracts, z compresses with gzip, f names the file. Use -C to extract into a chosen folder and --exclude to skip files.","cmd":"tar -czf backup.tar.gz --exclude='*.tmp' src\ntar -tzf backup.tar.gz\nmkdir restore && tar -xzf backup.tar.gz -C restore\ndiff -r src restore/src && echo \"restore matches\"","out":"$ diff -r src restore/src && echo \"restore matches\"\nrestore matches","outKind":"example","note":"To copy to another machine use rsync -av -e ssh src/ user@host:/backup/ with a key-based login.","risk":false,"viz":""}],"nav":{"pos":39,"of":41,"prev":{"id":"lnx-audit-gpg","title":"Audit file changes and encrypt a file"},"next":{"id":"lnx-time-chrony","title":"Keep the clock right: timedatectl and chrony"}}},{"id":"lnx-time-chrony","title":"Keep the clock right: timedatectl and chrony","level":2,"icon":"lucide-clock","summary":"Check and fix time, time zone and host name, and see whether time synchronisation is healthy.","qna":[{"q":"In which situation do we use this?","a":"TLS errors, odd log times, failing token or Kerberos logins, or database clusters that disagree about order."},{"q":"Why UTC on servers?","a":"Logs from many machines and regions line up, and daylight saving never creates repeated or missing hours."},{"q":"What comes next?","a":"Monitor the clock offset and alert if it passes a few hundred milliseconds."}],"steps":[{"title":"Read the clock settings","icon":"lucide-clock","text":"timedatectl shows local time, UTC, the time zone and whether NTP synchronisation is active. Wrong time breaks TLS, logs and Kerberos.","cmd":"timedatectl","out":"$ timedatectl\n               Local time: Wed 2026-11-04 13:20:00 IST\n           Universal time: Wed 2026-11-04 07:50:00 UTC\n                Time zone: Asia/Kolkata (IST, +0530)\nSystem clock synchronized: yes\n              NTP service: active","outKind":"example","note":"","risk":false,"viz":""},{"title":"Set the time zone","icon":"lucide-globe","text":"Servers are often kept in UTC so logs from different places line up. List the zones, then set one.","cmd":"timedatectl list-timezones | grep -i kolkata\nsudo timedatectl set-timezone UTC\ndate","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"See how chrony is doing","icon":"lucide-timer","text":"chronyc tracking shows the offset from the reference clock. System time is the current error. Anything under a few milliseconds is healthy.","cmd":"chronyc tracking\nchronyc sources -v","out":"$ chronyc tracking\nReference ID    : A9FEA97B (169.254.169.123)\nStratum         : 4\nSystem time     : 0.000012 seconds fast of NTP time\nLeap status     : Normal","outKind":"example","note":"","risk":false,"viz":""},{"title":"Step a large error","icon":"lucide-wrench","text":"chrony slews the clock gently. If it is minutes off, makestep jumps it once. Do not step time on a database server while it is running.","cmd":"sudo chronyc makestep\nsudo systemctl restart chronyd\nchronyc tracking | grep \"System time\"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Set the host name","icon":"lucide-bookmark","text":"hostnamectl sets a static name that survives reboots. Use lower-case letters, digits and hyphens.","cmd":"hostnamectl\nsudo hostnamectl set-hostname app-01\nhostname","out":"","outKind":"","note":"In a cloud VM the provider's tool (cloud-init) may reset the name. Set preserve_hostname there.","risk":false,"viz":""}],"nav":{"pos":40,"of":41,"prev":{"id":"lnx-rsync-tar","title":"Copy and archive safely with rsync and tar"},"next":{"id":"lnx-kernel-sysctl","title":"Kernel modules, sysctl and limits"}}},{"id":"lnx-kernel-sysctl","title":"Kernel modules, sysctl and limits","level":3,"icon":"lucide-cpu","summary":"Load a module, tune a kernel setting temporarily and permanently, and raise a file limit.","qna":[{"q":"In which situation do we use this?","a":"Preparing a machine for Kubernetes or routing, tuning network limits, or fixing \"too many open files\"."},{"q":"Why do changes disappear after reboot?","a":"sysctl -w and ulimit change only the running system. Put the setting in /etc/sysctl.d, a systemd unit or limits.d."},{"q":"What comes next?","a":"Change one value at a time and record the old value."}],"steps":[{"title":"List loaded modules","icon":"lucide-cpu","text":"Modules are drivers loaded into the running kernel. lsmod lists them and modinfo describes one.","cmd":"lsmod | head -n 6\nmodinfo br_netfilter | head -n 5","out":"$ lsmod | head -n 6\nModule                  Size  Used by\nbr_netfilter           32768  0\nbridge                311296  1 br_netfilter","outKind":"example","note":"","risk":false,"viz":""},{"title":"Load and unload one","icon":"lucide-repeat","text":"modprobe loads a module with its dependencies; -r removes it. To load one at every boot, list it in /etc/modules-load.d/.","cmd":"sudo modprobe br_netfilter\nlsmod | grep br_netfilter\necho br_netfilter | sudo tee /etc/modules-load.d/k8s.conf","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Read kernel settings","icon":"lucide-search","text":"sysctl reads and writes values under /proc/sys. The same value can be read as a file.","cmd":"sysctl net.ipv4.ip_forward\ncat /proc/sys/net/ipv4/ip_forward\nsysctl -a 2>/dev/null | grep -c .","out":"$ sysctl net.ipv4.ip_forward\nnet.ipv4.ip_forward = 0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Change a setting now and forever","icon":"lucide-sliders-horizontal","text":"sysctl -w changes it until the next reboot. To make it permanent write a file in /etc/sysctl.d and reload all of them with sysctl --system.","cmd":"sudo sysctl -w net.ipv4.ip_forward=1\necho 'net.ipv4.ip_forward = 1' | sudo tee /etc/sysctl.d/99-forward.conf\nsudo sysctl --system | tail -n 3","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Raise the open file limit","icon":"lucide-arrow-up","text":"ulimit -n is the limit of open files for the current shell. Servers with many connections need more. For services set LimitNOFILE in the systemd unit; for logins use /etc/security/limits.d.","cmd":"ulimit -n\nprintf '[Service]\nLimitNOFILE=65536\n' | sudo tee /etc/systemd/system/myapp.service.d/limits.conf\nsudo systemctl daemon-reload","out":"$ ulimit -n\n1024","outKind":"example","note":"Change one setting at a time and note the old value so you can revert.","risk":false,"viz":""}],"nav":{"pos":41,"of":41,"prev":{"id":"lnx-time-chrony","title":"Keep the clock right: timedatectl and chrony"},"next":null}}]},{"id":"docker","name":"Docker: containers from scratch","color":"#2496ED","tagline":"Run, build, connect and ship containers step by step, from your first docker run to multi-stage images. Commands target Docker Engine 27 and Compose v2. Outputs are examples, because Docker is not installed on the machine that built this library.","icon":"docker-engine","workflows":[{"id":"dkr-first-container","title":"Module 1: What a container is, and your first one","level":1,"icon":"docker-engine","summary":"A container is a normal process with its own filesystem view and limits. Run one, look at it, remove it.","qna":[{"q":"In which situation do we use this?","a":"You need to run software without installing it on the host, or give every teammate the same environment."},{"q":"Is a container a small virtual machine?","a":"No. It shares the host kernel and is only an isolated process with its own filesystem view and limits."},{"q":"What comes next?","a":"Module 2 pulls real images and publishes ports."}],"steps":[{"title":"Check that Docker works","icon":"docker-engine","text":"The docker command talks to the Docker daemon, which does the real work. version proves both parts answer.","cmd":"docker version --format 'client {{.Client.Version}}  server {{.Server.Version}}'\ndocker info --format '{{.ServerVersion}} on {{.OperatingSystem}}'","out":"$ docker version --format 'client {{.Client.Version}}  server {{.Server.Version}}'\nclient 27.3.1  server 27.3.1\n$ docker info --format '{{.ServerVersion}} on {{.OperatingSystem}}'\n27.3.1 on Ubuntu 24.04.1 LTS","outKind":"example","note":"","risk":false,"viz":""},{"title":"Container versus virtual machine","icon":"lucide-box","text":"A virtual machine boots a whole second operating system. A container shares your kernel and only isolates what a process can see and use.","cmd":"uname -r\ndocker run --rm alpine:3.20 uname -r","out":"$ uname -r\n6.8.0-45-generic\n$ docker run --rm alpine:3.20 uname -r\n6.8.0-45-generic","outKind":"example","note":"Same kernel version inside and outside: that is the proof. On Docker Desktop for Mac the shared kernel is a small Linux VM.","risk":false,"viz":""},{"title":"Run hello-world","icon":"lucide-play","text":"Docker pulls the image if it is missing, creates a container, runs it once and exits. --rm deletes the container afterwards.","cmd":"docker run --rm hello-world","out":"Unable to find image 'hello-world:latest' locally\nlatest: Pulling from library/hello-world\nDigest: sha256:d211f485f2dd1dee407a80973c8f129f00d54604d2c90732e8e320e5038a0348\nStatus: Downloaded newer image for hello-world:latest\n\nHello from Docker!\nThis message shows that your installation appears to be working correctly.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run a command in a fresh Linux userland","icon":"lucide-terminal","text":"Each run starts from the image, so tools here are not on your host. Add -it for an interactive shell.","cmd":"docker run --rm alpine:3.20 cat /etc/os-release\ndocker run -it --rm alpine:3.20 sh","out":"$ docker run --rm alpine:3.20 cat /etc/os-release\nNAME=\"Alpine Linux\"\nID=alpine\nVERSION_ID=3.20.3\nPRETTY_NAME=\"Alpine Linux v3.20\"","outKind":"example","note":"Inside the interactive shell type exit to leave. The container stops when its main process ends.","risk":false,"viz":""},{"title":"A container is just a process","icon":"lucide-eye","text":"Start one in the background and find it in the host process list.","cmd":"docker run -d --name sleeper alpine:3.20 sleep 300\ndocker ps\nps aux | grep \"[s]leep 300\"","out":"$ docker ps\nCONTAINER ID   IMAGE         COMMAND       CREATED         STATUS         NAMES\n3f2a9c1d8e7b   alpine:3.20   \"sleep 300\"   4 seconds ago   Up 3 seconds   sleeper\n$ ps aux | grep \"[s]leep 300\"\nroot  21873  0.0  0.0  1600  768 ?  Ss  10:02  0:00 sleep 300","outKind":"example","note":"","risk":false,"viz":""},{"title":"Stop and remove it","icon":"lucide-eraser","text":"stop sends a polite signal, rm deletes the stopped container. ps -a also lists stopped ones.","cmd":"docker stop sleeper\ndocker rm sleeper\ndocker ps -a","out":"$ docker ps -a\nCONTAINER ID   IMAGE   COMMAND   CREATED   STATUS   PORTS   NAMES","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":8,"prev":null,"next":{"id":"dkr-images-run","title":"Module 2: Images, ports, logs and exec"}}},{"id":"dkr-images-run","title":"Module 2: Images, ports, logs and exec","level":1,"icon":"docker-image","summary":"Pull an image, run a web server and a database in the background, and look inside them.","qna":[{"q":"In which situation do we use this?","a":"Running a ready-made service such as nginx or PostgreSQL for development, tests or a quick demo."},{"q":"Why avoid the latest tag?","a":"It moves. Pin a version such as nginx:1.27 so today's test and tomorrow's deploy use the same image."},{"q":"What comes next?","a":"Module 3 builds your own image."}],"steps":[{"title":"Pull an image and list it","icon":"lucide-download","text":"An image is a read-only template made of layers. Always use an explicit tag, not latest.","cmd":"docker pull nginx:1.27\ndocker images","out":"$ docker images\nREPOSITORY   TAG    IMAGE ID       CREATED       SIZE\nnginx        1.27   3b25b682ea82   2 weeks ago   192MB","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run nginx in the background with a published port","icon":"lucide-play","text":"-d detaches, --name names it, and -p 8080:80 maps host port 8080 to container port 80.","cmd":"docker run -d --name web -p 8080:80 nginx:1.27\ndocker ps\ncurl -I http://localhost:8080","out":"$ curl -I http://localhost:8080\nHTTP/1.1 200 OK\nServer: nginx/1.27.2\nContent-Type: text/html","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read logs, run a command inside","icon":"lucide-search","text":"logs shows what the main process printed. exec starts another process inside the running container.","cmd":"docker logs --tail 3 web\ndocker exec web nginx -v\ndocker exec -it web sh","out":"$ docker exec web nginx -v\nnginx version: nginx/1.27.2","outKind":"example","note":"","risk":false,"viz":""},{"title":"Pass settings with environment variables","icon":"lucide-sliders-horizontal","text":"-e sets an environment variable, which is how most images are configured. --restart keeps the container alive across reboots.","cmd":"docker run -d --name db -e POSTGRES_PASSWORD=demo --restart unless-stopped postgres:16\ndocker exec db psql -U postgres -c \"select version();\"","out":"$ docker exec db psql -U postgres -c \"select version();\"\n version\n PostgreSQL 16.4 (Debian 16.4-1.pgdg120+1) on x86_64-pc-linux-gnu","outKind":"example","note":"demo is only a lab password. Use secrets for anything real.","risk":true,"viz":""},{"title":"Stop and clean up","icon":"lucide-eraser","text":"Remove both containers. The images stay on disk, so the next run starts instantly.","cmd":"docker stop web db\ndocker rm web db\ndocker ps -a","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":8,"prev":{"id":"dkr-first-container","title":"Module 1: What a container is, and your first one"},"next":{"id":"dkr-dockerfile","title":"Module 3: Build your own image with a Dockerfile"}}},{"id":"dkr-dockerfile","title":"Module 3: Build your own image with a Dockerfile","level":2,"icon":"lucide-package","summary":"Write a tiny app that prints Hello Srinivas, describe it in a Dockerfile, build, run and see the layers.","qna":[{"q":"In which situation do we use this?","a":"Your application must run the same on a laptop, in CI and in production."},{"q":"Why does instruction order matter?","a":"Each instruction is a cached layer. Put rarely changing steps first and your code last so rebuilds are fast."},{"q":"What comes next?","a":"Module 4 adds storage and networking."}],"steps":[{"title":"Write the app","icon":"lucide-pencil","text":"A 6-line Python web server that answers every request with Hello Srinivas.","cmd":"mkdir -p ~/hello-app && cd ~/hello-app\ncat > app.py <<'EOF'\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\n\nclass Handler(BaseHTTPRequestHandler):\n    def do_GET(self):\n        self.send_response(200); self.end_headers(); self.wfile.write(b\"Hello Srinivas\\n\")\n\nHTTPServer((\"0.0.0.0\", 8000), Handler).serve_forever()\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Describe the image in a Dockerfile","icon":"lucide-file-text","text":"FROM picks the base, WORKDIR sets the folder, COPY adds files, EXPOSE documents the port, CMD is what runs at start.","cmd":"cat > Dockerfile <<'EOF'\nFROM python:3.12-slim\nWORKDIR /app\nCOPY app.py .\nEXPOSE 8000\nCMD [\"python\", \"app.py\"]\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Build the image","icon":"lucide-settings","text":"build reads the Dockerfile in . and tags the result name:version. Each instruction becomes one layer.","cmd":"docker build -t hello-app:1.0 .\ndocker images hello-app","out":"$ docker build -t hello-app:1.0 .\n[+] Building 6.2s (8/8) FINISHED\n => [1/3] FROM docker.io/library/python:3.12-slim\n => [2/3] WORKDIR /app\n => [3/3] COPY app.py .\n => exporting to image\n$ docker images hello-app\nREPOSITORY   TAG   IMAGE ID       SIZE\nhello-app    1.0   a1b2c3d4e5f6   130MB","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run it and call it","icon":"lucide-play","text":"Publish port 8000 and call it with curl. The container prints the greeting from your code.","cmd":"docker run -d --name hello -p 8000:8000 hello-app:1.0\ncurl http://localhost:8000","out":"$ curl http://localhost:8000\nHello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"See the layers and the build cache","icon":"lucide-layers","text":"history lists the layers. Change only app.py and rebuild: unchanged steps are reused from the cache and the build takes a moment.","cmd":"docker history hello-app:1.0\nsed -i.bak 's/Hello Srinivas/Hello Srinivas, v2/' app.py\ndocker build -t hello-app:2.0 .","out":"=> CACHED [1/3] FROM docker.io/library/python:3.12-slim\n => CACHED [2/3] WORKDIR /app\n => [3/3] COPY app.py .","outKind":"example","note":"Put the lines that change least first (dependencies) and the ones that change most (your code) last.","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Stop and remove the container. The images stay for the next modules.","cmd":"docker rm -f hello\ndocker ps -a","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":8,"prev":{"id":"dkr-images-run","title":"Module 2: Images, ports, logs and exec"},"next":{"id":"dkr-volumes-networks","title":"Module 4: Keep data with volumes, connect containers with networks"}}},{"id":"dkr-volumes-networks","title":"Module 4: Keep data with volumes, connect containers with networks","level":2,"icon":"lucide-database","summary":"Show that container files vanish, keep data in a volume, edit a site with a bind mount, and let two containers talk by name.","qna":[{"q":"In which situation do we use this?","a":"A database must keep its data, or several containers must talk to each other."},{"q":"Volume or bind mount?","a":"Use a volume for data Docker should manage, and a bind mount to share your own source folder into a container."},{"q":"What comes next?","a":"Module 5 describes the whole group in one Compose file."}],"steps":[{"title":"Container files are temporary","icon":"lucide-triangle-alert","text":"Data written inside a container is deleted with it. Write a file, remove the container, start a new one: the file is gone.","cmd":"docker run --name tmp alpine:3.20 sh -c 'echo \"Hello Srinivas\" > /data.txt && cat /data.txt'\ndocker rm tmp\ndocker run --rm alpine:3.20 cat /data.txt","out":"Hello Srinivas\ncat: can't open '/data.txt': No such file or directory","outKind":"example","note":"","risk":false,"viz":""},{"title":"A named volume survives","icon":"lucide-database","text":"A volume is storage managed by Docker. Mount it at /data and the file lives on after the container is removed.","cmd":"docker volume create hello-data\ndocker run --rm -v hello-data:/data alpine:3.20 sh -c 'echo \"Hello Srinivas\" > /data/hello.txt'\ndocker run --rm -v hello-data:/data alpine:3.20 cat /data/hello.txt\ndocker volume ls","out":"Hello Srinivas\nDRIVER    VOLUME NAME\nlocal     hello-data","outKind":"example","note":"","risk":false,"viz":""},{"title":"A bind mount shares a host folder","icon":"lucide-folder","text":"-v host-folder:container-folder maps your own files into the container, so you can edit and refresh. :ro makes it read-only.","cmd":"mkdir -p ~/site && echo \"<h1>Hello Srinivas</h1>\" > ~/site/index.html\ndocker run -d --name site -p 8081:80 -v ~/site:/usr/share/nginx/html:ro nginx:1.27\ncurl http://localhost:8081","out":"<h1>Hello Srinivas</h1>","outKind":"example","note":"","risk":false,"viz":""},{"title":"A user-defined network gives names","icon":"lucide-network","text":"Containers on the same user-defined network reach each other by name through Docker's built-in DNS.","cmd":"docker network create appnet\ndocker run -d --name api --network appnet nginx:1.27\ndocker run --rm --network appnet alpine:3.20 wget -qO- http://api","out":"<!DOCTYPE html>\n<html>\n<title>Welcome to nginx!</title>","outKind":"example","note":"","risk":false,"viz":""},{"title":"Published versus internal ports","icon":"wf-port","text":"-p opens a container port to the outside world. Containers on the same network need no -p to talk to each other.","cmd":"docker port site\ndocker network inspect appnet --format '{{range .Containers}}{{.Name}} {{.IPv4Address}}{{\"\\n\"}}{{end}}'","out":"80/tcp -> 0.0.0.0:8081\napi 172.18.0.2/16","outKind":"example","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Remove containers, the network and the volume you created.","cmd":"docker rm -f site api\ndocker network rm appnet\ndocker volume rm hello-data","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":8,"prev":{"id":"dkr-dockerfile","title":"Module 3: Build your own image with a Dockerfile"},"next":{"id":"dkr-compose","title":"Module 5: Run several containers with Docker Compose"}}},{"id":"dkr-compose","title":"Module 5: Run several containers with Docker Compose","level":2,"icon":"docker-compose","summary":"Describe a web app and a Redis cache in one file and start, inspect, scale and remove them together.","qna":[{"q":"In which situation do we use this?","a":"An application has more than one container, such as web, API and database, and you want one command to start them all."},{"q":"How do containers find each other?","a":"By service name. Compose puts them on a private network with built-in DNS."},{"q":"What comes next?","a":"Module 6 ships the image to a registry."}],"steps":[{"title":"Write compose.yaml","icon":"lucide-file-text","text":"One file lists every service, its image, ports and settings. Compose creates a private network for them automatically.","cmd":"mkdir -p ~/compose-demo && cd ~/compose-demo\ncat > compose.yaml <<'EOF'\nservices:\n  web:\n    image: nginx:1.27\n    ports:\n      - \"8082:80\"\n    depends_on:\n      cache:\n        condition: service_healthy\n  cache:\n    image: redis:7\n    healthcheck:\n      test: [\"CMD\", \"redis-cli\", \"ping\"]\n      interval: 5s\n      retries: 5\n    volumes:\n      - cache-data:/data\nvolumes:\n  cache-data:\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Start everything","icon":"lucide-play","text":"up -d creates the network, volume and both containers, and waits for the health check before starting web.","cmd":"docker compose up -d\ndocker compose ps","out":"$ docker compose ps\nNAME                  IMAGE        STATUS                  PORTS\ncompose-demo-cache-1  redis:7      Up 8 seconds (healthy)  6379/tcp\ncompose-demo-web-1    nginx:1.27   Up 3 seconds            0.0.0.0:8082->80/tcp","outKind":"example","note":"","risk":false,"viz":""},{"title":"Talk between the services","icon":"lucide-link","text":"The service name is the host name. From web you can reach the cache at cache:6379.","cmd":"docker compose exec cache redis-cli set greeting \"Hello Srinivas\"\ndocker compose exec web sh -c 'getent hosts cache'\ndocker compose exec cache redis-cli get greeting","out":"OK\n172.19.0.2   cache\n\"Hello Srinivas\"","outKind":"example","note":"","risk":false,"viz":""},{"title":"Logs and config values","icon":"lucide-search","text":"logs merges all services, config prints the final file after variables are filled in.","cmd":"docker compose logs --tail 2\ndocker compose config --services","out":"cache\nweb","outKind":"example","note":"","risk":false,"viz":""},{"title":"Stop and remove","icon":"lucide-eraser","text":"down removes containers and the network but keeps volumes. Add -v to delete the data too.","cmd":"docker compose down\ndocker volume ls\ndocker compose down -v","out":"","outKind":"","note":"down -v deletes the cache-data volume for good.","risk":true,"viz":""}],"nav":{"pos":5,"of":8,"prev":{"id":"dkr-volumes-networks","title":"Module 4: Keep data with volumes, connect containers with networks"},"next":{"id":"dkr-registry-push","title":"Module 6: Tag, push and pull images with a registry (Docker Hub or ECR)"}}},{"id":"dkr-registry-push","title":"Module 6: Tag, push and pull images with a registry (Docker Hub or ECR)","level":2,"icon":"docker-registry","summary":"Name an image for a registry, log in, push it, and pull the exact same image on another machine.","qna":[{"q":"In which situation do we use this?","a":"A server, a teammate or a pipeline needs the exact image you built."},{"q":"Tag or digest?","a":"A tag can be moved to another image. A digest (sha256) never changes, so pin by digest for production."},{"q":"What comes next?","a":"Module 7 makes images smaller and safer."}],"steps":[{"title":"Image names have four parts","icon":"lucide-bookmark","text":"registry/repository:tag. If the registry is missing Docker Hub is assumed. A tag can move; a digest (sha256:...) never does.","cmd":"docker image ls --digests hello-app","out":"REPOSITORY   TAG   DIGEST    IMAGE ID\nhello-app    1.0   <none>    a1b2c3d4e5f6","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a private repository in Amazon ECR","icon":"aws-ecr","text":"ECR is AWS's registry. One repository holds all versions of one image. Turn on scan-on-push.","cmd":"export AWS_REGION=ap-south-1 ACCOUNT=$(aws sts get-caller-identity --query Account --output text)\naws ecr create-repository --repository-name hello-app --image-scanning-configuration scanOnPush=true --region $AWS_REGION","out":"{\n  \"repository\": {\n    \"repositoryName\": \"hello-app\",\n    \"repositoryUri\": \"123456789012.dkr.ecr.ap-south-1.amazonaws.com/hello-app\"\n  }\n}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Log in to the registry","icon":"lucide-lock","text":"ECR gives a token valid for 12 hours that docker login accepts. For Docker Hub use docker login with your user name.","cmd":"aws ecr get-login-password --region $AWS_REGION | docker login --username AWS --password-stdin $ACCOUNT.dkr.ecr.$AWS_REGION.amazonaws.com","out":"Login Succeeded","outKind":"example","note":"","risk":false,"viz":""},{"title":"Tag and push","icon":"lucide-upload","text":"tag adds a second name that points at the same image. push uploads only the layers the registry does not have.","cmd":"docker tag hello-app:1.0 $ACCOUNT.dkr.ecr.$AWS_REGION.amazonaws.com/hello-app:1.0\ndocker push $ACCOUNT.dkr.ecr.$AWS_REGION.amazonaws.com/hello-app:1.0","out":"1.0: digest: sha256:8d9c0b1f... size: 1573","outKind":"example","note":"","risk":false,"viz":""},{"title":"Pull it anywhere","icon":"lucide-download","text":"On another machine log in the same way and pull. Pin by digest in production so the image cannot change under you.","cmd":"docker pull $ACCOUNT.dkr.ecr.$AWS_REGION.amazonaws.com/hello-app:1.0\naws ecr describe-images --repository-name hello-app --query 'imageDetails[].[imageTags[0],imageDigest,imagePushedAt]' --output text","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Keep the registry tidy","icon":"lucide-eraser","text":"A lifecycle policy deletes old images automatically so storage cost stays small.","cmd":"cat > lifecycle.json <<'EOF'\n{\"rules\":[{\"rulePriority\":1,\"description\":\"keep last 10\",\"selection\":{\"tagStatus\":\"any\",\"countType\":\"imageCountMoreThan\",\"countNumber\":10},\"action\":{\"type\":\"expire\"}}]}\nEOF\naws ecr put-lifecycle-policy --repository-name hello-app --lifecycle-policy-text file://lifecycle.json","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":8,"prev":{"id":"dkr-compose","title":"Module 5: Run several containers with Docker Compose"},"next":{"id":"dkr-multistage-secure","title":"Module 7: Small and safe images: multi-stage builds"}}},{"id":"dkr-multistage-secure","title":"Module 7: Small and safe images: multi-stage builds","level":3,"icon":"lucide-shield","summary":"Compile in one stage, ship only the result, run as a non-root user with a read-only filesystem.","qna":[{"q":"In which situation do we use this?","a":"The image holds compilers and build tools that production does not need, or a security review asks for a smaller attack surface."},{"q":"Which settings help most?","a":"A non-root user, a read-only filesystem, dropped capabilities and a vulnerability scan in CI."},{"q":"What comes next?","a":"Module 8 covers debugging and disk clean-up."}],"steps":[{"title":"The problem: build tools in production","icon":"lucide-triangle-alert","text":"A normal Go image holds the compiler, sources and caches, hundreds of MB that production never needs and attackers can use.","cmd":"mkdir -p ~/go-hello && cd ~/go-hello\ncat > main.go <<'EOF'\npackage main\n\nimport \"fmt\"\n\nfunc main() { fmt.Println(\"Hello Srinivas\") }\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Two stages in one Dockerfile","icon":"lucide-layers","text":"The first stage builds the binary. The second starts empty (distroless) and copies only that binary.","cmd":"cat > Dockerfile <<'EOF'\nFROM golang:1.23 AS build\nWORKDIR /src\nCOPY main.go .\nRUN CGO_ENABLED=0 go build -o /out/hello main.go\n\nFROM gcr.io/distroless/static-debian12:nonroot\nCOPY --from=build /out/hello /hello\nUSER nonroot\nENTRYPOINT [\"/hello\"]\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Build, run and compare sizes","icon":"lucide-timer","text":"The final image has no shell and no package manager, so there is very little to attack.","cmd":"docker build -t go-hello:slim .\ndocker run --rm go-hello:slim\ndocker images --format '{{.Repository}}:{{.Tag}} {{.Size}}' | grep -E 'go-hello|golang'","out":"Hello Srinivas\ngolang:1.23 842MB\ngo-hello:slim 2.4MB","outKind":"example","note":"","risk":false,"viz":""},{"title":"Exclude files with .dockerignore","icon":"lucide-filter","text":"Anything in the build folder is sent to the daemon. Ignore .git, secrets and caches to keep builds fast and safe.","cmd":"printf '.git\n.env\n*.log\nnode_modules\n' > .dockerignore\ncat .dockerignore","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run with least privilege","icon":"lucide-lock","text":"Drop all Linux capabilities, make the filesystem read-only, forbid privilege escalation and limit memory.","cmd":"docker run --rm --read-only --cap-drop ALL --security-opt no-new-privileges --memory 64m go-hello:slim\ndocker inspect --format '{{.Config.User}}' go-hello:slim","out":"Hello Srinivas\nnonroot","outKind":"example","note":"","risk":false,"viz":""},{"title":"Scan for known vulnerabilities","icon":"lucide-search","text":"A scanner compares the packages in the image with public vulnerability lists. Run it in CI and fail on high severity.","cmd":"trivy image --severity HIGH,CRITICAL go-hello:slim","out":"go-hello:slim (debian 12.7)\nTotal: 0 (HIGH: 0, CRITICAL: 0)","outKind":"example","note":"Trivy is a separate tool. Docker Scout (docker scout cves) does the same job.","risk":false,"viz":""}],"nav":{"pos":7,"of":8,"prev":{"id":"dkr-registry-push","title":"Module 6: Tag, push and pull images with a registry (Docker Hub or ECR)"},"next":{"id":"dkr-debug-cleanup","title":"Module 8: Debug a container and clean up disk"}}},{"id":"dkr-debug-cleanup","title":"Module 8: Debug a container and clean up disk","level":2,"icon":"lucide-bug","summary":"Find out why a container will not start or keeps dying, watch resources, set limits and reclaim space.","qna":[{"q":"In which situation do we use this?","a":"A container exits at once, restarts in a loop, uses too much memory, or the disk is full of old images."},{"q":"What does exit code 137 mean?","a":"The process was killed, most often because it ran out of memory. Check OOMKilled in docker inspect."},{"q":"What comes next?","a":"Use these images in Jenkins or Kubernetes."}],"steps":[{"title":"Find the failure","icon":"lucide-search","text":"ps -a lists stopped containers with their exit code. Exit 0 is success, 1 is an app error, 137 means killed (often out of memory), 143 is SIGTERM.","cmd":"docker run --name broken alpine:3.20 sh -c 'echo starting; exit 3'\ndocker ps -a --filter name=broken --format '{{.Names}} {{.Status}}'\ndocker logs broken","out":"starting\nbroken Exited (3) 2 seconds ago","outKind":"example","note":"","risk":false,"viz":""},{"title":"Inspect the full configuration","icon":"lucide-eye","text":"inspect prints everything Docker knows. Pull out one field with --format.","cmd":"docker inspect broken --format '{{.State.ExitCode}} {{.Config.Image}} {{.HostConfig.RestartPolicy.Name}}'\ndocker rm broken","out":"3 alpine:3.20 no","outKind":"example","note":"","risk":false,"viz":""},{"title":"Watch CPU, memory and processes","icon":"lucide-timer","text":"stats is a live view per container, top lists the processes inside one, events shows what the daemon does.","cmd":"docker run -d --name busy alpine:3.20 sh -c 'while true; do :; done'\ndocker stats --no-stream busy\ndocker top busy","out":"CONTAINER ID   NAME   CPU %    MEM USAGE / LIMIT\n8c1f2e3d4b5a   busy   99.8%    1.1MiB / 7.6GiB","outKind":"example","note":"","risk":false,"viz":""},{"title":"Set limits so one container cannot hurt others","icon":"lucide-shield","text":"--cpus and --memory cap resources. A process that exceeds its memory limit is killed and marked OOMKilled.","cmd":"docker rm -f busy\ndocker run -d --name limited --cpus 0.5 --memory 128m alpine:3.20 sleep 300\ndocker inspect limited --format '{{.HostConfig.Memory}} {{.HostConfig.NanoCpus}}'","out":"134217728 500000000","outKind":"example","note":"","risk":false,"viz":""},{"title":"See and reclaim disk space","icon":"lucide-eraser","text":"system df shows what images, containers and volumes use. prune removes unused ones.","cmd":"docker rm -f limited\ndocker system df\ndocker image prune -f\ndocker system prune --volumes","out":"","outKind":"","note":"system prune --volumes also deletes unused volumes. Read the list it prints before you answer y.","risk":true,"viz":""}],"nav":{"pos":8,"of":8,"prev":{"id":"dkr-multistage-secure","title":"Module 7: Small and safe images: multi-stage builds"},"next":null}}]},{"id":"k8s","name":"Kubernetes: from pod to production","color":"#326CE5","tagline":"Learn Kubernetes one object at a time: pods, deployments, services, config, storage, ingress, probes, scaling, access control, Helm and Kustomize, debugging and node maintenance. Practise on a local kind or minikube cluster, never on a shared one. Output is example output, because commands that talk to a cluster cannot run on the machine that built this library.","icon":"k8s-cluster","workflows":[{"id":"k8s-first-look","title":"Module 1: Cluster, context and the first kubectl commands","level":1,"icon":"k8s-cluster","summary":"Know which cluster you are pointed at before you type anything, then look around with get, describe and explain.","qna":[{"q":"In which situation do we use this?","a":"Before any kubectl work on a new or unfamiliar cluster: confirm which cluster and namespace you are pointed at."},{"q":"What is the most common costly mistake?","a":"Running a change against the wrong context. Read kubectl config current-context first, and practise on a local kind cluster."},{"q":"What comes next?","a":"Module 2 runs your first pod."}],"steps":[{"title":"Check which cluster you are talking to","icon":"k8s-cluster","text":"kubectl sends every command to the cluster named in your current context. Read it first, every time, so you never change the wrong cluster.","cmd":"kubectl config current-context\nkubectl config get-contexts","out":"platformsbx\nCURRENT   NAME          CLUSTER       AUTHINFO      NAMESPACE\n*         platformsbx   platformsbx   platformsbx   default\n          kind-lab      kind-lab      kind-lab","outKind":"example","note":"Use a throwaway local cluster to learn. kind create cluster --name lab starts one in Docker.","risk":false,"viz":""},{"title":"Create a safe practice cluster","icon":"k8s-node","text":"kind runs a whole cluster inside Docker containers on your laptop. Delete it when you finish and nothing is left behind.","cmd":"kind create cluster --name lab\nkubectl cluster-info --context kind-lab","out":"Creating cluster \"lab\" ...\n Ensuring node image (kindest/node:v1.31.0)\n Starting control-plane\nSet kubectl context to \"kind-lab\"\nKubernetes control plane is running at https://127.0.0.1:41233","outKind":"example","note":"","risk":false,"viz":""},{"title":"Switch context and namespace on purpose","icon":"k8s-namespace","text":"use-context changes the cluster, and --current --namespace changes the default namespace for the context. Namespaces split one cluster into separate areas.","cmd":"kubectl config use-context kind-lab\nkubectl create namespace demo\nkubectl config set-context --current --namespace=demo\nkubectl config view --minify --output 'jsonpath={..namespace}'","out":"Switched to context \"kind-lab\".\nnamespace/demo created\nContext \"kind-lab\" modified.\ndemo","outKind":"example","note":"","risk":false,"viz":""},{"title":"Look at the nodes and the system pods","icon":"k8s-apiserver","text":"A node is a machine that runs pods. The control plane pods in kube-system run the API server, the scheduler and etcd (the database).","cmd":"kubectl get nodes -o wide\nkubectl get pods -n kube-system","out":"NAME                STATUS   ROLES           AGE   VERSION\nlab-control-plane   Ready    control-plane   2m    v1.31.0\nNAME                                        READY   STATUS    RESTARTS\netcd-lab-control-plane                      1/1     Running   0\nkube-apiserver-lab-control-plane            1/1     Running   0","outKind":"example","note":"","risk":false,"viz":""},{"title":"get, describe, explain, api-resources","icon":"k8s-etcd","text":"get lists objects, describe shows details and recent events, explain documents every field offline, api-resources lists all object kinds.","cmd":"kubectl api-resources --namespaced=true | head -n 8\nkubectl explain pod.spec.containers.resources\nkubectl get pods -A","out":"NAME         SHORTNAMES   APIVERSION   NAMESPACED   KIND\nconfigmaps   cm           v1           true         ConfigMap\npods         po           v1           true         Pod\nservices     svc          v1           true         Service","outKind":"example","note":"","risk":false,"viz":""},{"title":"Shortcuts for daily work","icon":"k8s-cm","text":"Short names save typing, -o yaml shows the full object, and an alias plus completion make kubectl fast.","cmd":"alias k=kubectl\nsource <(kubectl completion bash)\nk get po,svc,deploy\nk get pod -o name","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":13,"prev":null,"next":{"id":"k8s-pod-hello","title":"Module 2: Your first pod: Hello Srinivas"}}},{"id":"k8s-pod-hello","title":"Module 2: Your first pod: Hello Srinivas","level":1,"icon":"k8s-pod","summary":"Write a pod manifest, create it, read its logs, run a command inside it, and delete it.","qna":[{"q":"In which situation do we use this?","a":"Trying an image quickly, or learning how a pod starts and what its events say."},{"q":"Why not run bare pods in production?","a":"Nothing recreates a deleted or crashed bare pod. Use a Deployment."},{"q":"What comes next?","a":"Module 3 adds self-healing and updates."}],"steps":[{"title":"What a pod is","icon":"k8s-pod","text":"A pod is the smallest thing Kubernetes runs: one or more containers that share an IP address and storage. Pods are disposable, so you rarely create them directly.","cmd":"kubectl config current-context\nkubectl get pods","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Generate the YAML instead of typing it","icon":"k8s-deployment","text":"--dry-run=client -o yaml prints the manifest without creating anything. This is the fastest way to start a new file.","cmd":"kubectl run hello --image=nginx:1.27 --port=80 --labels=app=hello --dry-run=client -o yaml > pod.yaml\ncat pod.yaml","out":"apiVersion: v1\nkind: Pod\nmetadata:\n  labels:\n    app: hello\n  name: hello\nspec:\n  containers:\n  - image: nginx:1.27\n    name: hello\n    ports:\n    - containerPort: 80","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create it and watch it start","icon":"k8s-pod","text":"apply creates the object from the file. -w watches the status change from Pending to ContainerCreating to Running.","cmd":"kubectl apply -f pod.yaml\nkubectl get pod hello -w","out":"pod/hello created\nNAME    READY   STATUS              RESTARTS   AGE\nhello   0/1     ContainerCreating   0          2s\nhello   1/1     Running             0          6s","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read logs and run commands inside","icon":"k8s-node","text":"logs shows what the container printed. exec runs a command inside it. port-forward lets your laptop reach it without a Service.","cmd":"kubectl logs hello\nkubectl exec hello -- nginx -v\nkubectl exec -it hello -- sh\nkubectl port-forward pod/hello 8080:80","out":"nginx version: nginx/1.27.2","outKind":"example","note":"","risk":false,"viz":""},{"title":"Describe and read the events","icon":"k8s-etcd","text":"describe ends with an Events table that explains what the scheduler and the kubelet did. It is the first place to look when something is wrong.","cmd":"kubectl describe pod hello | tail -n 8","out":"Events:\n  Type    Reason     Message\n  Normal  Scheduled  Successfully assigned demo/hello to lab-control-plane\n  Normal  Pulled     Container image \"nginx:1.27\" already present\n  Normal  Created    Created container hello\n  Normal  Started    Started container hello","outKind":"example","note":"","risk":false,"viz":""},{"title":"Delete it","icon":"k8s-job","text":"A bare pod is gone for good: nothing recreates it. That is why deployments exist.","cmd":"kubectl delete pod hello\nkubectl get pods","out":"pod \"hello\" deleted\nNo resources found in demo namespace.","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":13,"prev":{"id":"k8s-first-look","title":"Module 1: Cluster, context and the first kubectl commands"},"next":{"id":"k8s-deployment-rollout","title":"Module 3: Deployments, scaling, rolling updates and rollback"}}},{"id":"k8s-deployment-rollout","title":"Module 3: Deployments, scaling, rolling updates and rollback","level":2,"icon":"k8s-deployment","summary":"Run two copies, change the image with zero downtime, watch the rollout and go back to the previous version.","qna":[{"q":"In which situation do we use this?","a":"Running a stateless application with several copies that must stay up during updates."},{"q":"What happens when a rollout goes wrong?","a":"New pods fail to become ready while the old ones keep serving. kubectl rollout undo returns to the last good version."},{"q":"What comes next?","a":"Module 4 gives the pods a stable address."}],"steps":[{"title":"Create a deployment","icon":"k8s-deployment","text":"A deployment keeps the number of pods you asked for. If one dies, a new one is created. It owns a ReplicaSet, which owns the pods.","cmd":"kubectl create deployment hello --image=nginx:1.26 --replicas=2\nkubectl get deploy,rs,pods","out":"deployment.apps/hello created\nNAME                    READY   UP-TO-DATE   AVAILABLE\ndeployment.apps/hello   2/2     2            2\nNAME                         DESIRED   CURRENT   READY\nreplicaset.apps/hello-6b9f   2         2         2","outKind":"example","note":"","risk":false,"viz":""},{"title":"Self-healing in action","icon":"k8s-hpa","text":"Delete one pod. The deployment notices it is below two and starts a new one within seconds.","cmd":"POD=$(kubectl get pods -l app=hello -o name | head -n 1)\nkubectl delete $POD --wait=false\nkubectl get pods -l app=hello","out":"pod \"hello-6b9f-x7k2p\" deleted\nNAME             READY   STATUS              AGE\nhello-6b9f-m4c8d   1/1   Running             3m\nhello-6b9f-t9q5w   0/1   ContainerCreating   1s","outKind":"example","note":"","risk":false,"viz":""},{"title":"Scale up and down","icon":"k8s-hpa","text":"scale changes the replica count at once. Edit the file and apply for a change you want to keep in Git.","cmd":"kubectl scale deployment hello --replicas=4\nkubectl get deploy hello","out":"deployment.apps/hello scaled\nNAME    READY   UP-TO-DATE   AVAILABLE\nhello   4/4     4            4","outKind":"example","note":"","risk":false,"viz":""},{"title":"Rolling update to a new image","icon":"k8s-ds","text":"set image starts a new ReplicaSet and moves pods over gradually, so the service stays up. rollout status waits until it finishes.","cmd":"kubectl set image deployment/hello nginx=nginx:1.27\nkubectl rollout status deployment/hello\nkubectl get rs","out":"Waiting for deployment \"hello\" rollout to finish: 2 out of 4 new replicas have been updated...\ndeployment \"hello\" successfully rolled out\nNAME           DESIRED   CURRENT   READY\nhello-6b9f     0         0         0\nhello-7c4d     4         4         4","outKind":"example","note":"","risk":false,"viz":""},{"title":"A bad update and the rollback","icon":"k8s-sts","text":"A wrong image tag leaves new pods in ImagePullBackOff, but the old pods keep serving because the rollout never completes. undo goes back.","cmd":"kubectl set image deployment/hello nginx=nginx:does-not-exist\nkubectl rollout status deployment/hello --timeout=30s\nkubectl rollout undo deployment/hello\nkubectl rollout history deployment/hello","out":"error: timed out waiting for the condition\ndeployment.apps/hello rolled back\nREVISION  CHANGE-CAUSE\n3         <none>\n4         <none>","outKind":"example","note":"","risk":false,"viz":""},{"title":"Tune the strategy","icon":"k8s-mesh","text":"maxUnavailable and maxSurge control how many pods may be down or extra during an update. Zero unavailable gives the safest rollout.","cmd":"kubectl patch deployment hello -p '{\"spec\":{\"strategy\":{\"rollingUpdate\":{\"maxUnavailable\":0,\"maxSurge\":1}}}}'\nkubectl get deploy hello -o jsonpath='{.spec.strategy}'","out":"{\"rollingUpdate\":{\"maxSurge\":1,\"maxUnavailable\":0},\"type\":\"RollingUpdate\"}","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":13,"prev":{"id":"k8s-pod-hello","title":"Module 2: Your first pod: Hello Srinivas"},"next":{"id":"k8s-service-expose","title":"Module 4: Services: ClusterIP, NodePort and LoadBalancer"}}},{"id":"k8s-service-expose","title":"Module 4: Services: ClusterIP, NodePort and LoadBalancer","level":2,"icon":"k8s-service","summary":"Give pods a stable address, find them by label, reach them from inside and outside the cluster.","qna":[{"q":"In which situation do we use this?","a":"Other pods or users need a stable name and address for a changing set of pods."},{"q":"What does an empty ENDPOINTS list mean?","a":"The selector matches no ready pod. Compare the service selector with the pod labels and check readiness."},{"q":"What comes next?","a":"Module 5 moves settings out of the image."}],"steps":[{"title":"Why pods need a Service","icon":"k8s-service","text":"Pod IPs change every time a pod is replaced. A Service is a fixed virtual IP and DNS name that sends traffic to whichever pods match its label selector.","cmd":"kubectl get pods -l app=hello -o wide","out":"NAME             READY   STATUS    IP\nhello-7c4d-aaaaa  1/1    Running   10.244.0.5\nhello-7c4d-bbbbb  1/1    Running   10.244.0.6","outKind":"example","note":"","risk":false,"viz":"Client → Service hello: ClusterIP 10.96.12.7:80\nService hello → Pod 10.244.0.5: forward\nService hello → Pod 10.244.0.6: forward"},{"title":"Create a ClusterIP service","icon":"k8s-svc","text":"ClusterIP is reachable only inside the cluster. port is what clients call, targetPort is the container port.","cmd":"kubectl expose deployment hello --port=80 --target-port=80 --name=hello\nkubectl get svc hello\nkubectl get endpoints hello","out":"NAME    TYPE        CLUSTER-IP     PORT(S)   AGE\nhello   ClusterIP   10.96.12.7     80/TCP    4s\nNAME    ENDPOINTS                         AGE\nhello   10.244.0.5:80,10.244.0.6:80       4s","outKind":"example","note":"An empty ENDPOINTS column means the selector matches no ready pod. This is the most common service problem.","risk":false,"viz":""},{"title":"Call it from another pod by name","icon":"k8s-node","text":"CoreDNS gives every service a name: hello inside the same namespace, hello.demo from another, hello.demo.svc.cluster.local in full.","cmd":"kubectl run tmp --rm -it --restart=Never --image=busybox:1.36 -- wget -qO- http://hello\nkubectl run tmp --rm -it --restart=Never --image=busybox:1.36 -- nslookup hello","out":"<!DOCTYPE html>\n<html>\n<title>Welcome to nginx!</title>\nName: hello.demo.svc.cluster.local\nAddress: 10.96.12.7","outKind":"example","note":"","risk":false,"viz":""},{"title":"Reach it from your laptop","icon":"k8s-ing","text":"port-forward is the simplest way to test. NodePort opens a port on every node. LoadBalancer asks your cloud for a public address.","cmd":"kubectl port-forward svc/hello 8080:80\ncurl -s http://localhost:8080 | head -n 3\nkubectl patch svc hello -p '{\"spec\":{\"type\":\"NodePort\"}}'\nkubectl get svc hello","out":"NAME    TYPE       CLUSTER-IP    PORT(S)\nhello   NodePort   10.96.12.7    80:31845/TCP","outKind":"example","note":"","risk":false,"viz":""},{"title":"Selectors and labels are the glue","icon":"k8s-pvc","text":"The service finds pods only by label. Change a pod's label and it leaves the service without being deleted. This is how blue-green and canary tricks work.","cmd":"kubectl get pods --show-labels\nkubectl label pod hello-7c4d-aaaaa app=debug --overwrite\nkubectl get endpoints hello","out":"NAME    ENDPOINTS\nhello   10.244.0.6:80","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":13,"prev":{"id":"k8s-deployment-rollout","title":"Module 3: Deployments, scaling, rolling updates and rollback"},"next":{"id":"k8s-config-secrets","title":"Module 5: ConfigMaps and Secrets"}}},{"id":"k8s-config-secrets","title":"Module 5: ConfigMaps and Secrets","level":2,"icon":"k8s-configmap","summary":"Keep settings outside the image: put hello.txt in a ConfigMap, use it as an environment variable and as a file, and store a Secret.","qna":[{"q":"In which situation do we use this?","a":"The same image must run in dev and prod with different settings, or needs a password."},{"q":"Is a Secret encrypted?","a":"Not by default. It is base64 encoded. Limit access with RBAC and enable encryption at rest or use an external secret store."},{"q":"What comes next?","a":"Module 6 keeps data beyond a pod's life."}],"steps":[{"title":"Create a ConfigMap from hello.txt","icon":"k8s-configmap","text":"A ConfigMap holds non-secret settings. --from-file stores a whole file, --from-literal stores a key and value. Generate the YAML first to see it.","cmd":"echo \"Hello Srinivas\" > hello.txt\nkubectl create configmap hello-config --from-file=hello.txt --from-literal=GREETING=Namaste --dry-run=client -o yaml\nkubectl create configmap hello-config --from-file=hello.txt --from-literal=GREETING=Namaste","out":"apiVersion: v1\ndata:\n  GREETING: Namaste\n  hello.txt: |\n    Hello Srinivas\nkind: ConfigMap\nmetadata:\n  name: hello-config","outKind":"example","note":"","risk":false,"viz":""},{"title":"Use it as environment variables","icon":"k8s-cm","text":"envFrom turns every key into an environment variable. Changing the ConfigMap later does not change a running pod, so restart it.","cmd":"kubectl set env deployment/hello --from=configmap/hello-config\nkubectl exec deploy/hello -- printenv GREETING","out":"Namaste","outKind":"example","note":"","risk":false,"viz":""},{"title":"Mount it as a file","icon":"k8s-pvc","text":"A configMap volume appears as files. Mounted files update by themselves after a short delay, while environment variables do not.","cmd":"kubectl patch deployment hello --type=json -p '[{\"op\":\"add\",\"path\":\"/spec/template/spec/volumes\",\"value\":[{\"name\":\"cfg\",\"configMap\":{\"name\":\"hello-config\"}}]},{\"op\":\"add\",\"path\":\"/spec/template/spec/containers/0/volumeMounts\",\"value\":[{\"name\":\"cfg\",\"mountPath\":\"/etc/hello\"}]}]'\nkubectl exec deploy/hello -- cat /etc/hello/hello.txt","out":"Hello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a Secret","icon":"k8s-secret","text":"A Secret holds passwords and tokens. Its values are only base64 encoded, which is not encryption. Anyone who can read the Secret can decode it.","cmd":"kubectl create secret generic hello-secret --from-literal=password=s3cret\nkubectl get secret hello-secret -o jsonpath='{.data.password}' | base64 -d; echo","out":"secret/hello-secret created\ns3cret","outKind":"example","note":"s3cret is a lab value. Restrict who can read Secrets with RBAC and consider an external store such as AWS Secrets Manager.","risk":true,"viz":""},{"title":"Use the Secret in a pod","icon":"k8s-secret","text":"Reference one key with secretKeyRef. Prefer mounting as a file over environment variables, because variables show up in process listings and crash dumps.","cmd":"kubectl set env deployment/hello --from=secret/hello-secret --prefix=APP_\nkubectl exec deploy/hello -- printenv APP_PASSWORD\nkubectl rollout restart deployment/hello","out":"s3cret\ndeployment.apps/hello restarted","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":13,"prev":{"id":"k8s-service-expose","title":"Module 4: Services: ClusterIP, NodePort and LoadBalancer"},"next":{"id":"k8s-storage","title":"Module 6: Storage: volumes, PersistentVolumeClaims and StatefulSets"}}},{"id":"k8s-storage","title":"Module 6: Storage: volumes, PersistentVolumeClaims and StatefulSets","level":3,"icon":"k8s-pvc","summary":"Show that pod files vanish, keep data with a PersistentVolumeClaim, and run a database as a StatefulSet.","qna":[{"q":"In which situation do we use this?","a":"A database, upload folder or any data that must survive pod restarts."},{"q":"Deployment or StatefulSet for a database?","a":"StatefulSet. It gives stable names and a separate disk per pod."},{"q":"What comes next?","a":"Module 7 brings outside traffic in."}],"steps":[{"title":"Pod storage is temporary","icon":"k8s-pod","text":"An emptyDir lives as long as the pod. Write a file, delete the pod, and the replacement starts empty.","cmd":"kubectl run scratch --image=busybox:1.36 --restart=Never -- sh -c 'echo \"Hello Srinivas\" > /tmp/hello.txt; sleep 3600'\nkubectl exec scratch -- cat /tmp/hello.txt\nkubectl delete pod scratch","out":"Hello Srinivas\npod \"scratch\" deleted","outKind":"example","note":"","risk":false,"viz":""},{"title":"Ask for durable storage with a PVC","icon":"k8s-pvc","text":"A PersistentVolumeClaim is a request for disk. The cluster's StorageClass creates the volume. Check which classes exist first.","cmd":"kubectl get storageclass\nprintf 'apiVersion: v1\nkind: PersistentVolumeClaim\nmetadata:\n  name: hello-data\nspec:\n  accessModes: [ReadWriteOnce]\n  resources:\n    requests:\n      storage: 1Gi\n' | kubectl apply -f -\nkubectl get pvc","out":"NAME       PROVISIONER             DEFAULT\nstandard   rancher.io/local-path   (default)\nNAME         STATUS    VOLUME      CAPACITY   ACCESS MODES\nhello-data   Pending                                   \n","outKind":"example","note":"With WaitForFirstConsumer the claim stays Pending until a pod uses it. That is normal.","risk":false,"viz":""},{"title":"Mount the claim and keep the file","icon":"k8s-deployment","text":"Mount the claim at /data. After the pod is deleted and recreated the file is still there, because the disk outlives the pod.","cmd":"printf 'apiVersion: v1\nkind: Pod\nmetadata:\n  name: writer\nspec:\n  containers:\n  - name: c\n    image: busybox:1.36\n    command: [\"sh\",\"-c\",\"echo Hello Srinivas > /data/hello.txt; sleep 3600\"]\n    volumeMounts:\n    - {name: d, mountPath: /data}\n  volumes:\n  - name: d\n    persistentVolumeClaim:\n      claimName: hello-data\n' | kubectl apply -f -\nkubectl delete pod writer --wait && kubectl get pvc hello-data","out":"NAME         STATUS   VOLUME             CAPACITY   ACCESS MODES\nhello-data   Bound    pvc-3f2a...        1Gi        RWO","outKind":"example","note":"","risk":false,"viz":""},{"title":"StatefulSet for a database","icon":"k8s-sts","text":"A StatefulSet gives each pod a stable name (db-0, db-1) and its own disk. Use it for databases and anything that needs identity.","cmd":"printf 'apiVersion: apps/v1\nkind: StatefulSet\nmetadata:\n  name: db\nspec:\n  serviceName: db\n  replicas: 2\n  selector: {matchLabels: {app: db}}\n  template:\n    metadata: {labels: {app: db}}\n    spec:\n      containers:\n      - name: pg\n        image: postgres:16\n        env: [{name: POSTGRES_PASSWORD, value: demo}]\n  volumeClaimTemplates:\n  - metadata: {name: data}\n    spec:\n      accessModes: [ReadWriteOnce]\n      resources: {requests: {storage: 1Gi}}\n' | kubectl apply -f -\nkubectl get sts,pods,pvc -l app=db","out":"NAME                  READY\nstatefulset.apps/db   2/2\nNAME       READY   STATUS\npod/db-0   1/1     Running\npod/db-1   1/1     Running\nNAME                       STATUS   VOLUME\npersistentvolumeclaim/data-db-0   Bound\npersistentvolumeclaim/data-db-1   Bound","outKind":"example","note":"","risk":false,"viz":""},{"title":"Reclaim policy and clean-up","icon":"k8s-job","text":"Deleting a claim may delete the data, depending on the reclaim policy. A StatefulSet leaves its claims behind on purpose, so delete them yourself.","cmd":"kubectl delete sts db\nkubectl delete pvc -l app=db\nkubectl get pv -o custom-columns=NAME:.metadata.name,RECLAIM:.spec.persistentVolumeReclaimPolicy","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":6,"of":13,"prev":{"id":"k8s-config-secrets","title":"Module 5: ConfigMaps and Secrets"},"next":{"id":"k8s-ingress-dns","title":"Module 7: Ingress: one entrance for many services"}}},{"id":"k8s-ingress-dns","title":"Module 7: Ingress: one entrance for many services","level":3,"icon":"k8s-ingress","summary":"Install an ingress controller, route two paths to two services, and add TLS.","qna":[{"q":"In which situation do we use this?","a":"Several web services share one public address and need host or path routing and HTTPS."},{"q":"Why is my Ingress ignored?","a":"There is no ingress controller, or ingressClassName does not match the controller's class."},{"q":"What comes next?","a":"Module 8 makes pods healthy and well sized."}],"steps":[{"title":"Controller and resource","icon":"k8s-ingress","text":"An Ingress is a set of routing rules. A controller such as ingress-nginx reads them and does the work. Without a controller the Ingress object does nothing.","cmd":"kubectl get ingressclass\nkubectl get pods -n ingress-nginx","out":"NAME    CONTROLLER             PARAMETERS   AGE\nnginx   k.io/ingress-nginx     <none>       5d","outKind":"example","note":"","risk":false,"viz":"Browser → Ingress controller: hello.example.com\nIngress controller → Service web: /\nIngress controller → Service api: /api"},{"title":"Two services to route to","icon":"k8s-service","text":"Create two small deployments, web and api, and expose each as a Service.","cmd":"kubectl create deployment web --image=nginx:1.27 && kubectl expose deployment web --port=80\nkubectl create deployment api --image=hashicorp/http-echo:1.0 -- /http-echo -text=\"Hello Srinivas API\" && kubectl expose deployment api --port=5678","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the Ingress","icon":"k8s-ing","text":"The host rule matches the name in the request. Each path points to a service and port. pathType Prefix matches everything below the path.","cmd":"printf 'apiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata:\n  name: hello\nspec:\n  ingressClassName: nginx\n  rules:\n  - host: hello.example.com\n    http:\n      paths:\n      - {path: /, pathType: Prefix, backend: {service: {name: web, port: {number: 80}}}}\n      - {path: /api, pathType: Prefix, backend: {service: {name: api, port: {number: 5678}}}}\n' | kubectl apply -f -\nkubectl get ingress hello","out":"NAME    CLASS   HOSTS               ADDRESS        PORTS\nhello   nginx   hello.example.com   203.0.113.10   80","outKind":"example","note":"","risk":false,"viz":""},{"title":"Test it with a Host header","icon":"k8s-pod","text":"No DNS yet? Send the host name yourself with curl --resolve. A 404 from the controller means the host or path did not match.","cmd":"curl -s --resolve hello.example.com:80:203.0.113.10 http://hello.example.com/api\ncurl -sI --resolve hello.example.com:80:203.0.113.10 http://hello.example.com/ | head -n 1","out":"Hello Srinivas API\nHTTP/1.1 200 OK","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add HTTPS","icon":"k8s-secret","text":"A TLS Secret holds the certificate and key. In production cert-manager creates and renews it for you from Let's Encrypt.","cmd":"kubectl create secret tls hello-tls --cert=tls.crt --key=tls.key\nkubectl patch ingress hello --type=json -p '[{\"op\":\"add\",\"path\":\"/spec/tls\",\"value\":[{\"hosts\":[\"hello.example.com\"],\"secretName\":\"hello-tls\"}]}]'\ncurl -sI https://hello.example.com | head -n 1","out":"HTTP/2 200","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":13,"prev":{"id":"k8s-storage","title":"Module 6: Storage: volumes, PersistentVolumeClaims and StatefulSets"},"next":{"id":"k8s-probes-resources","title":"Module 8: Health checks, requests and limits"}}},{"id":"k8s-probes-resources","title":"Module 8: Health checks, requests and limits","level":2,"icon":"k8s-pod","summary":"Tell Kubernetes when a pod is alive and ready, and how much CPU and memory it needs and may use.","qna":[{"q":"In which situation do we use this?","a":"Pods receive traffic before they are ready, hang without restarting, or hog a node."},{"q":"Readiness or liveness?","a":"Readiness controls traffic. Liveness restarts a stuck container. A wrong liveness probe can cause restart loops."},{"q":"What comes next?","a":"Module 9 scales on load."}],"steps":[{"title":"Liveness, readiness and startup","icon":"k8s-pod","text":"Readiness decides if the pod receives traffic. Liveness restarts a stuck container. Startup gives slow applications time before the other two begin.","cmd":"kubectl explain pod.spec.containers.readinessProbe | head -n 8","out":"FIELD: readinessProbe <Probe>\nDESCRIPTION:\n  Periodic probe of container service readiness. Container will be removed from service endpoints if the probe fails.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add probes to the deployment","icon":"k8s-deployment","text":"The readiness probe calls / every 5 seconds. A failing probe removes the pod from the Service without restarting it.","cmd":"kubectl patch deployment hello --type=json -p '[{\"op\":\"add\",\"path\":\"/spec/template/spec/containers/0/readinessProbe\",\"value\":{\"httpGet\":{\"path\":\"/\",\"port\":80},\"periodSeconds\":5}},{\"op\":\"add\",\"path\":\"/spec/template/spec/containers/0/livenessProbe\",\"value\":{\"httpGet\":{\"path\":\"/\",\"port\":80},\"initialDelaySeconds\":10,\"periodSeconds\":10}}]'\nkubectl rollout status deployment/hello","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Requests and limits","icon":"k8s-hpa","text":"A request is what the scheduler reserves. A limit is the ceiling. Exceed the memory limit and the container is killed with OOMKilled. CPU over the limit is only slowed down.","cmd":"kubectl set resources deployment hello --requests=cpu=100m,memory=64Mi --limits=cpu=250m,memory=128Mi\nkubectl get pod -l app=hello -o jsonpath='{.items[0].spec.containers[0].resources}'","out":"{\"limits\":{\"cpu\":\"250m\",\"memory\":\"128Mi\"},\"requests\":{\"cpu\":\"100m\",\"memory\":\"64Mi\"}}","outKind":"example","note":"","risk":false,"viz":""},{"title":"See the usage","icon":"k8s-node","text":"top reads metrics from metrics-server. Compare real use with requests to right-size your pods.","cmd":"kubectl top pods\nkubectl top nodes","out":"NAME             CPU(cores)   MEMORY(bytes)\nhello-8d5c-abc   2m           7Mi","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read a failing probe","icon":"k8s-etcd","text":"Break the path on purpose. Events show Readiness probe failed, the pod shows 0/1 Ready, and the Service drops it from its endpoints.","cmd":"kubectl patch deployment hello --type=json -p '[{\"op\":\"replace\",\"path\":\"/spec/template/spec/containers/0/readinessProbe/httpGet/path\",\"value\":\"/missing\"}]'\nkubectl describe pod -l app=hello | grep -A2 -i \"readiness probe failed\" | head -n 4","out":"Warning  Unhealthy  Readiness probe failed: HTTP probe failed with statuscode: 404","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":13,"prev":{"id":"k8s-ingress-dns","title":"Module 7: Ingress: one entrance for many services"},"next":{"id":"k8s-scaling-hpa","title":"Module 9: Autoscaling with the Horizontal Pod Autoscaler"}}},{"id":"k8s-scaling-hpa","title":"Module 9: Autoscaling with the Horizontal Pod Autoscaler","level":3,"icon":"k8s-hpa","summary":"Scale on CPU automatically, generate load, watch pods increase and decrease.","qna":[{"q":"In which situation do we use this?","a":"Traffic changes over the day and you want pods added and removed automatically."},{"q":"Why does the HPA show unknown?","a":"Metrics-server is missing, or the pods have no CPU request to compare with."},{"q":"What comes next?","a":"Module 10 controls who can do what."}],"steps":[{"title":"What the HPA does","icon":"k8s-hpa","text":"The Horizontal Pod Autoscaler compares average CPU use with the target and changes replicas between a minimum and a maximum. It needs metrics-server and CPU requests on the pods.","cmd":"kubectl get apiservices v1beta1.metrics.k8s.io\nkubectl top pods","out":"NAME                     SERVICE                      AVAILABLE\nv1beta1.metrics.k8s.io   kube-system/metrics-server   True","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create the autoscaler","icon":"k8s-hpa","text":"autoscale makes a target of 50 percent CPU with two to six pods. It looks at the request value, so the request must be set.","cmd":"kubectl autoscale deployment hello --cpu-percent=50 --min=2 --max=6\nkubectl get hpa hello","out":"NAME    REFERENCE          TARGETS   MINPODS   MAXPODS   REPLICAS\nhello   Deployment/hello   2%/50%    2         6         2","outKind":"example","note":"TARGETS shows unknown when the pods have no CPU request.","risk":false,"viz":""},{"title":"Generate load","icon":"k8s-job","text":"A busybox pod calls the service in a tight loop. Leave it running and watch in a second terminal.","cmd":"kubectl run load --image=busybox:1.36 --restart=Never -- sh -c 'while true; do wget -q -O- http://hello > /dev/null; done'\nkubectl get hpa hello -w","out":"NAME    TARGETS    REPLICAS\nhello   2%/50%     2\nhello   180%/50%   2\nhello   180%/50%   4\nhello   72%/50%    6","outKind":"example","note":"","risk":false,"viz":""},{"title":"Watch it scale back","icon":"k8s-pvc","text":"After the load stops, pods are removed slowly. A five-minute stabilisation window stops the count from bouncing up and down.","cmd":"kubectl delete pod load\nkubectl describe hpa hello | grep -A4 Events","out":"Normal  SuccessfulRescale  New size: 6; reason: cpu resource utilization above target\nNormal  SuccessfulRescale  New size: 2; reason: All metrics below target","outKind":"example","note":"","risk":false,"viz":""},{"title":"Other kinds of scaling","icon":"k8s-node","text":"The Vertical Pod Autoscaler changes requests, the Cluster Autoscaler or Karpenter adds nodes, and KEDA scales on queues and events.","cmd":"kubectl get nodes\nkubectl get pods -A | grep -iE \"autoscaler|karpenter|keda\"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":9,"of":13,"prev":{"id":"k8s-probes-resources","title":"Module 8: Health checks, requests and limits"},"next":{"id":"k8s-rbac","title":"Module 10: Who can do what: ServiceAccounts, Roles and RBAC"}}},{"id":"k8s-rbac","title":"Module 10: Who can do what: ServiceAccounts, Roles and RBAC","level":3,"icon":"k8s-secret","summary":"Create a service account that may only read pods, then test what it can and cannot do.","qna":[{"q":"In which situation do we use this?","a":"Giving a person, pipeline or pod only the access it needs."},{"q":"How do I check what an account can do?","a":"kubectl auth can-i with --as, or --list for everything."},{"q":"What comes next?","a":"Module 11 packages and reuses manifests."}],"steps":[{"title":"The four pieces","icon":"k8s-secret","text":"A ServiceAccount is an identity for a pod. A Role lists allowed verbs on resources in one namespace. A RoleBinding gives a role to a subject. ClusterRole and ClusterRoleBinding do the same cluster-wide.","cmd":"kubectl auth whoami\nkubectl auth can-i create deployments","out":"ATTRIBUTE   VALUE\nUsername    kubernetes-admin\nyes","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create an identity","icon":"k8s-namespace","text":"A new service account can do nothing until you bind a role to it.","cmd":"kubectl create serviceaccount reader\nkubectl auth can-i list pods --as=system:serviceaccount:demo:reader","out":"serviceaccount/reader created\nno","outKind":"example","note":"","risk":false,"viz":""},{"title":"Define a read-only role","icon":"k8s-cm","text":"get, list and watch on pods is enough to look but not to change. Name the exact verbs and resources.","cmd":"kubectl create role pod-reader --verb=get,list,watch --resource=pods\nkubectl create rolebinding read-pods --role=pod-reader --serviceaccount=demo:reader\nkubectl get role,rolebinding","out":"role.rbac.authorization.k8s.io/pod-reader created\nrolebinding.rbac.authorization.k8s.io/read-pods created","outKind":"example","note":"","risk":false,"viz":""},{"title":"Test the permissions","icon":"k8s-hpa","text":"can-i with --as impersonates the account. Allowed to list pods, but not to delete them or read Secrets.","cmd":"kubectl auth can-i list pods --as=system:serviceaccount:demo:reader\nkubectl auth can-i delete pods --as=system:serviceaccount:demo:reader\nkubectl auth can-i get secrets --as=system:serviceaccount:demo:reader\nkubectl auth can-i --list --as=system:serviceaccount:demo:reader","out":"yes\nno\nno","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run a pod as that account","icon":"k8s-pod","text":"Set serviceAccountName in the pod. A token is mounted, so code inside can call the API with only the rights you gave.","cmd":"kubectl run api-test --image=bitnami/kubectl:1.31 --overrides='{\"spec\":{\"serviceAccountName\":\"reader\"}}' --command -- sleep 3600\nkubectl exec api-test -- kubectl get pods\nkubectl exec api-test -- kubectl delete pod api-test","out":"NAME       READY   STATUS\napi-test   1/1     Running\nError from server (Forbidden): pods \"api-test\" is forbidden: User \"system:serviceaccount:demo:reader\" cannot delete resource \"pods\"","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":10,"of":13,"prev":{"id":"k8s-scaling-hpa","title":"Module 9: Autoscaling with the Horizontal Pod Autoscaler"},"next":{"id":"k8s-helm-kustomize","title":"Module 11: Package and reuse: Helm charts and Kustomize"}}},{"id":"k8s-helm-kustomize","title":"Module 11: Package and reuse: Helm charts and Kustomize","level":3,"icon":"k8s-deploy","summary":"Create a chart, change values, template and lint it offline, install and roll back, then do the same job with Kustomize overlays.","qna":[{"q":"In which situation do we use this?","a":"The same application must be deployed many times with different values, or you install third-party software."},{"q":"Helm or Kustomize?","a":"Helm for packaged, versioned applications. Kustomize for patching your own plain YAML per environment."},{"q":"What comes next?","a":"Module 12 fixes what breaks."}],"steps":[{"title":"Create a chart","icon":"k8s-deploy","text":"A chart is a folder of templates plus default values. helm create gives a working example with a Deployment, a Service and more.","cmd":"helm create hello-chart\nls hello-chart hello-chart/templates","out":"hello-chart:\nChart.yaml  charts  templates  values.yaml\nhello-chart/templates:\nNOTES.txt  _helpers.tpl  deployment.yaml  hpa.yaml  ingress.yaml  service.yaml  serviceaccount.yaml","outKind":"example","note":"","risk":false,"viz":""},{"title":"Check it without a cluster","icon":"k8s-deployment","text":"lint finds mistakes. template renders the YAML locally, so you can read exactly what would be created.","cmd":"helm lint hello-chart\nhelm template hello hello-chart --set replicaCount=2 --set image.tag=1.27.2 | grep -E \"^kind:|replicas:|image:\"","out":"==> Linting hello-chart\n[INFO] Chart.yaml: icon is recommended\n\n1 chart(s) linted, 0 chart(s) failed\nkind: ServiceAccount\nkind: Service\nkind: Deployment\n  replicas: 2\n          image: \"nginx:1.27.2\"","outKind":"example","note":"","risk":false,"viz":""},{"title":"Install, upgrade, roll back","icon":"k8s-sts","text":"install creates a release. upgrade changes it using new values, and each change is a numbered revision you can return to.","cmd":"helm install hello hello-chart --set replicaCount=2\nhelm upgrade hello hello-chart --set replicaCount=3\nhelm history hello\nhelm rollback hello 1","out":"REVISION  STATUS      DESCRIPTION\n1         superseded  Install complete\n2         superseded  Upgrade complete\n3         deployed    Rollback to 1","outKind":"example","note":"","risk":false,"viz":""},{"title":"Kustomize: patch without templates","icon":"k8s-cm","text":"A base holds plain YAML and an overlay changes it: a name prefix, a replica count, an image tag. No template language.","cmd":"mkdir -p base overlays/prod\nkubectl create deployment hello --image=nginx:1.27 --dry-run=client -o yaml > base/deployment.yaml\nprintf 'resources:\n  - deployment.yaml\n' > base/kustomization.yaml\nprintf 'resources:\n  - ../../base\nnamePrefix: prod-\nreplicas:\n  - name: hello\n    count: 4\nimages:\n  - name: nginx\n    newTag: 1.27.2\n' > overlays/prod/kustomization.yaml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Build and apply the overlay","icon":"k8s-job","text":"kubectl kustomize prints the result. kubectl apply -k builds and applies it in one step.","cmd":"kubectl kustomize overlays/prod | grep -E \"name:|replicas:|image:\"\nkubectl apply -k overlays/prod","out":"  name: prod-hello\n  replicas: 4\n      - image: nginx:1.27.2\n        name: nginx","outKind":"example","note":"Helm suits software you install from others. Kustomize suits your own manifests across environments. Many teams use both.","risk":false,"viz":""}],"nav":{"pos":11,"of":13,"prev":{"id":"k8s-rbac","title":"Module 10: Who can do what: ServiceAccounts, Roles and RBAC"},"next":{"id":"k8s-debug","title":"Module 12: Debug a broken workload step by step"}}},{"id":"k8s-debug","title":"Module 12: Debug a broken workload step by step","level":2,"icon":"k8s-etcd","summary":"A repeatable method for Pending, ImagePullBackOff, CrashLoopBackOff and a Service that does not answer.","qna":[{"q":"In which situation do we use this?","a":"A pod is Pending, crashing, not pulling its image, or a service does not answer."},{"q":"What is the first command?","a":"kubectl describe on the object, and read the Events at the bottom."},{"q":"What comes next?","a":"Module 13 covers planned node work."}],"steps":[{"title":"Method: state, events, logs, config","icon":"k8s-etcd","text":"Ask in this order: what is the status, what do the events say, what do the logs say, and is the configuration what you meant.","cmd":"kubectl get pods\nkubectl describe pod <name>\nkubectl logs <name> --previous\nkubectl get events --sort-by=.lastTimestamp | tail -n 10","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Pending: nothing can place the pod","icon":"k8s-node","text":"Events say 0/3 nodes are available, with the reason: not enough CPU or memory, a taint with no toleration, or a claim that cannot bind.","cmd":"kubectl run big --image=nginx --overrides='{\"spec\":{\"containers\":[{\"name\":\"big\",\"image\":\"nginx\",\"resources\":{\"requests\":{\"cpu\":\"100\"}}}]}}'\nkubectl describe pod big | grep -A3 Events","out":"Warning  FailedScheduling  0/1 nodes are available: 1 Insufficient cpu.","outKind":"example","note":"","risk":false,"viz":""},{"title":"ImagePullBackOff: wrong image or no access","icon":"k8s-deployment","text":"A typo in the tag, a private registry without a pull secret, or no network. The event shows the exact error from the registry.","cmd":"kubectl run bad --image=nginx:nope\nkubectl describe pod bad | grep -E \"Failed|Back-off\" | head -n 3","out":"Failed to pull image \"nginx:nope\": manifest for nginx:nope not found\nBack-off pulling image \"nginx:nope\"","outKind":"example","note":"","risk":false,"viz":""},{"title":"CrashLoopBackOff: the app keeps exiting","icon":"k8s-pod","text":"Read the logs of the previous run. Exit code 1 is an app error, 137 means killed (often out of memory), 126 or 127 means the command was not found.","cmd":"kubectl run crash --image=busybox:1.36 -- sh -c 'echo starting; exit 3'\nkubectl logs crash --previous\nkubectl get pod crash -o jsonpath='{.status.containerStatuses[0].lastState.terminated}'","out":"starting\n{\"exitCode\":3,\"reason\":\"Error\"}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Service answers nothing","icon":"k8s-service","text":"Check endpoints first. If it is empty, the selector does not match or no pod is ready. Then test the pod IP directly, then the DNS name.","cmd":"kubectl get endpoints hello\nkubectl get svc hello -o jsonpath='{.spec.selector}'\nkubectl get pods --show-labels\nkubectl run tmp --rm -it --restart=Never --image=busybox:1.36 -- wget -qO- -T 3 http://hello","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"A debug shell without changing the pod","icon":"k8s-ing","text":"kubectl debug adds a temporary container to a running pod, or makes a copy. Use it when the image has no shell.","cmd":"kubectl debug -it <pod> --image=busybox:1.36 --target=<container>\nkubectl debug <pod> --copy-to=debug-copy --container=<container> -it -- sh","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":12,"of":13,"prev":{"id":"k8s-helm-kustomize","title":"Module 11: Package and reuse: Helm charts and Kustomize"},"next":{"id":"k8s-node-maintenance","title":"Module 13: Upgrades and node maintenance: cordon, drain and uncordon"}}},{"id":"k8s-node-maintenance","title":"Module 13: Upgrades and node maintenance: cordon, drain and uncordon","level":4,"icon":"k8s-node","summary":"Take a node out of service safely, protect apps with a PodDisruptionBudget, and always put the node back.","qna":[{"q":"In which situation do we use this?","a":"Patching, resizing or replacing a node, or upgrading the cluster."},{"q":"What must I always do after a drain?","a":"Uncordon the node and confirm no node shows SchedulingDisabled."},{"q":"What comes next?","a":"Combine these skills with the Terraform and Jenkins topics for full delivery."}],"steps":[{"title":"See where pods run","icon":"k8s-node","text":"Before touching a node, know what is on it. Check the cluster has spare room to take the pods.","cmd":"kubectl config current-context\nkubectl get nodes\nkubectl get pods -A -o wide --field-selector spec.nodeName=<node>","out":"platformsbx\nNAME        STATUS   ROLES    VERSION\nnode-a      Ready    <none>   v1.31.0\nnode-b      Ready    <none>   v1.31.0","outKind":"example","note":"Managed platforms such as Kyma or EKS have their own upgrade process. Check it before draining by hand, because the platform may reconcile node state.","risk":false,"viz":""},{"title":"Protect the app with a PodDisruptionBudget","icon":"k8s-hpa","text":"A PDB says how many pods may be down at once during voluntary changes. A drain waits instead of breaking the budget.","cmd":"kubectl create pdb hello-pdb --selector=app=hello --min-available=1\nkubectl get pdb","out":"NAME        MIN AVAILABLE   ALLOWED DISRUPTIONS\nhello-pdb   1               1","outKind":"example","note":"","risk":false,"viz":""},{"title":"Cordon: stop new pods landing","icon":"k8s-ns","text":"cordon marks the node unschedulable. Existing pods keep running. STATUS shows SchedulingDisabled.","cmd":"kubectl cordon <node>\nkubectl get nodes","out":"node/node-a cordoned\nNAME     STATUS                     ROLES\nnode-a   Ready,SchedulingDisabled   <none>","outKind":"example","note":"","risk":false,"viz":""},{"title":"Drain: move the pods away","icon":"k8s-ds","text":"drain evicts pods politely, respecting PDBs, and the controllers recreate them elsewhere. DaemonSet pods stay, and pods with local storage need a flag.","cmd":"kubectl drain <node> --ignore-daemonsets --delete-emptydir-data --timeout=300s\nkubectl get pods -o wide","out":"evicting pod demo/hello-8d5c-abc\npod/hello-8d5c-abc evicted\nnode/node-a drained","outKind":"example","note":"","risk":true,"viz":""},{"title":"Uncordon and verify, every time","icon":"k8s-service","text":"After the work, uncordon makes the node schedulable again. Always check the status afterwards, because a cordon that stays behind quietly removes capacity.","cmd":"kubectl uncordon <node>\nkubectl get nodes\nkubectl get nodes | grep -c SchedulingDisabled","out":"node/node-a uncordoned\nNAME     STATUS   ROLES\nnode-a   Ready    <none>\n0","outKind":"example","note":"Zero lines with SchedulingDisabled means every node is back in service. On Gardener-managed clusters reconciliation can change cordon state, so check again after a few minutes.","risk":false,"viz":""},{"title":"Version skew and the upgrade order","icon":"k8s-cluster","text":"Upgrade the control plane first, then the nodes, one minor version at a time. kubectl may be one minor version older or newer than the API server.","cmd":"kubectl version\nkubectl get nodes -o custom-columns=NAME:.metadata.name,KUBELET:.status.nodeInfo.kubeletVersion","out":"Client Version: v1.31.0\nServer Version: v1.31.2","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":13,"of":13,"prev":{"id":"k8s-debug","title":"Module 12: Debug a broken workload step by step"},"next":null}}]},{"id":"jenkins","name":"Jenkins: CI/CD from scratch","color":"#D24939","tagline":"Run Jenkins in a container, create jobs, write a Jenkinsfile, trigger builds from Git, handle credentials and agents, deploy a Docker image, and keep the setup as code. Outputs are examples.","icon":"cicd-jenkins","workflows":[{"id":"jen-install-tour","title":"Module 1: Run Jenkins and take a first look","level":1,"icon":"cicd-jenkins","summary":"Understand the controller and agents, start Jenkins in Docker, unlock it and find where its data lives.","qna":[{"q":"In which situation do we use this?","a":"A team wants automatic builds and tests on every change instead of running them by hand."},{"q":"What is the controller and what is an agent?","a":"The controller schedules jobs and shows the UI. Agents run the actual builds."},{"q":"What comes next?","a":"Module 2 creates and runs a first job."}],"steps":[{"title":"The pieces of Jenkins","icon":"cicd-pipeline","text":"The controller schedules jobs and shows the web UI. Agents (nodes) run the builds. Plugins add features such as Git, Docker and credentials.","cmd":"docker --version\njava -version","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Start the controller in Docker","icon":"lucide-play","text":"Port 8080 is the web UI and 50000 is for inbound agents. The named volume jenkins_home keeps your data when the container is replaced.","cmd":"docker run -d --name jenkins -p 8080:8080 -p 50000:50000 -v jenkins_home:/var/jenkins_home jenkins/jenkins:lts-jdk17\ndocker logs -f jenkins","out":"Jenkins initial setup is required. An admin user has been created and a password generated.\nPlease use the following password to proceed to installation:\n\n4f1b2c9a8d7e4a3b9c0d1e2f3a4b5c6d","outKind":"example","note":"","risk":false,"viz":""},{"title":"Unlock and finish setup","icon":"lucide-key-round","text":"Open http://localhost:8080, paste the password, choose Install suggested plugins, then create your admin user.","cmd":"docker exec jenkins cat /var/jenkins_home/secrets/initialAdminPassword\ncurl -s -I http://localhost:8080/login | grep -i x-jenkins","out":"X-Jenkins: 2.462.3","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create an API token for the command line","icon":"lucide-lock","text":"In the UI open your user, Configure, API Token, Add new token. Use the token instead of your password for scripts.","cmd":"export JENKINS_URL=http://localhost:8080 JENKINS_USER=admin JENKINS_TOKEN=<paste-token>\ncurl -s -u $JENKINS_USER:$JENKINS_TOKEN $JENKINS_URL/api/json?tree=mode,numExecutors","out":"{\"mode\":\"NORMAL\",\"numExecutors\":2}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Where Jenkins keeps its data","icon":"lucide-folder","text":"Everything is plain files under JENKINS_HOME: jobs, plugins, credentials (encrypted) and config.xml. Back up this folder.","cmd":"docker exec jenkins ls /var/jenkins_home\ndocker exec jenkins ls /var/jenkins_home/plugins | head -n 5","out":"config.xml  jobs  nodes  plugins  secrets  users  war","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":7,"prev":null,"next":{"id":"jen-freestyle-job","title":"Module 2: Your first job: Hello Srinivas"}}},{"id":"jen-freestyle-job","title":"Module 2: Your first job: Hello Srinivas","level":1,"icon":"lucide-play","summary":"Create a freestyle job from the command line, run it, read the console and inspect the workspace.","qna":[{"q":"In which situation do we use this?","a":"A quick one-off task or a learning exercise where a shell command is enough."},{"q":"Why not stay with freestyle jobs?","a":"The configuration lives only in Jenkins. A Jenkinsfile in Git can be reviewed, versioned and reused."},{"q":"What comes next?","a":"Module 3 writes a pipeline as code."}],"steps":[{"title":"Download the Jenkins CLI","icon":"lucide-download","text":"The CLI is a jar served by your own controller. It can create, build and inspect jobs.","cmd":"curl -sO $JENKINS_URL/jnlpJars/jenkins-cli.jar\njava -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN who-am-i","out":"Authenticated as: admin\nAuthorities:\n  authenticated","outKind":"example","note":"","risk":false,"viz":""},{"title":"Describe the job in XML","icon":"lucide-file-text","text":"A freestyle job is an XML file with one shell build step. The same XML is what Jenkins stores in jobs/hello/config.xml.","cmd":"cat > hello-job.xml <<'EOF'\n<?xml version='1.1' encoding='UTF-8'?>\n<project>\n  <description>Hello Srinivas job</description>\n  <builders>\n    <hudson.tasks.Shell>\n      <command>echo \"Hello Srinivas from build $BUILD_NUMBER\"\ndate</command>\n    </hudson.tasks.Shell>\n  </builders>\n</project>\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create it","icon":"lucide-plus","text":"create-job reads the XML from standard input. list-jobs confirms it exists.","cmd":"java -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN create-job hello < hello-job.xml\njava -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN list-jobs","out":"hello","outKind":"example","note":"","risk":false,"viz":""},{"title":"Build it and watch","icon":"lucide-rocket","text":"-s waits for the result, -v streams the console. Each run gets a number.","cmd":"java -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN build hello -s -v","out":"Started hello #1\nHello Srinivas from build 1\nMon Nov  4 10:15:02 UTC 2026\nFinished: SUCCESS","outKind":"example","note":"","risk":false,"viz":""},{"title":"Console, workspace and history","icon":"lucide-eye","text":"Every build keeps its console log. The workspace is the folder where the job ran.","cmd":"java -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN console hello 1\ncurl -s -u $JENKINS_USER:$JENKINS_TOKEN \"$JENKINS_URL/job/hello/api/json?tree=builds[number,result]\"","out":"{\"builds\":[{\"number\":1,\"result\":\"SUCCESS\"}]}","outKind":"example","note":"Freestyle jobs are fine for learning. Real projects use a Jenkinsfile (next module) so the pipeline lives in Git.","risk":false,"viz":""}],"nav":{"pos":2,"of":7,"prev":{"id":"jen-install-tour","title":"Module 1: Run Jenkins and take a first look"},"next":{"id":"jen-pipeline-jenkinsfile","title":"Module 3: A pipeline as code: the Jenkinsfile"}}},{"id":"jen-pipeline-jenkinsfile","title":"Module 3: A pipeline as code: the Jenkinsfile","level":2,"icon":"cicd-pipeline","summary":"Write a declarative pipeline with stages, environment, post actions and an archive, validate it and run it.","qna":[{"q":"In which situation do we use this?","a":"Your build has stages such as build, test, package and deploy, and you want each stage visible."},{"q":"Declarative or scripted?","a":"Declarative is simpler and enforces structure. Use scripted Groovy only for logic it cannot express."},{"q":"What comes next?","a":"Module 4 reads the Jenkinsfile from Git and triggers builds on push."}],"steps":[{"title":"The shape of a declarative pipeline","icon":"lucide-file-text","text":"pipeline contains agent (where), stages (what) and post (what happens afterwards). Each stage has steps.","cmd":"mkdir -p ~/pipe-demo && cd ~/pipe-demo\ncat > Jenkinsfile <<'EOF'\npipeline {\n  agent any\n  environment { APP = 'hello-srinivas' }\n  stages {\n    stage('Checkout') { steps { echo \"Building ${env.APP}\" } }\n    stage('Build')    { steps { sh 'echo Hello Srinivas > hello.txt && cat hello.txt' } }\n    stage('Test')     { steps { sh 'grep -q Srinivas hello.txt' } }\n    stage('Archive')  { steps { archiveArtifacts artifacts: 'hello.txt' } }\n  }\n  post {\n    success { echo 'passed' }\n    failure { echo 'failed' }\n    always  { cleanWs() }\n  }\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Validate it before you commit","icon":"lucide-check","text":"Jenkins can lint a Jenkinsfile for syntax errors without running anything.","cmd":"curl -s -X POST -u $JENKINS_USER:$JENKINS_TOKEN -F \"jenkinsfile=<Jenkinsfile\" $JENKINS_URL/pipeline-model-converter/validate","out":"Jenkinsfile successfully validated.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a pipeline job from it","icon":"lucide-plus","text":"The simplest way is New Item, Pipeline, and paste the script. In the next module the job reads it from Git instead.","cmd":"cat > pipe-job.xml <<'EOF'\n<flow-definition plugin=\"workflow-job\">\n  <definition class=\"org.jenkinsci.plugins.workflow.cps.CpsFlowDefinition\" plugin=\"workflow-cps\">\n    <script>@@SCRIPT@@</script>\n    <sandbox>true</sandbox>\n  </definition>\n</flow-definition>\nEOF\npython3 -c \"import html;s=open('Jenkinsfile').read();print(open('pipe-job.xml').read().replace('@@SCRIPT@@',html.escape(s)))\" > pipe-job-final.xml\njava -jar ../jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN create-job pipe-demo < pipe-job-final.xml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run and read the stages","icon":"lucide-rocket","text":"The Stage View shows each stage with its time. A red stage tells you exactly where it failed.","cmd":"java -jar ../jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN build pipe-demo -s -v","out":"[Pipeline] stage\n[Pipeline] { (Build)\n+ echo Hello Srinivas\n+ cat hello.txt\nHello Srinivas\n[Pipeline] archiveArtifacts\nFinished: SUCCESS","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add parameters, conditions and a timeout","icon":"lucide-sliders-horizontal","text":"parameters ask for input, when skips a stage, options set a timeout and retry. Add them inside the pipeline block.","cmd":"printf \"parameters { string(name: 'WHO', defaultValue: 'Srinivas') }\noptions { timeout(time: 10, unit: 'MINUTES'); timestamps() }\n\"\nprintf \"stage('Deploy') { when { branch 'main' }\n  steps { echo \\\"Deploying for \\${params.WHO}\\\" } }\n\"","out":"","outKind":"","note":"Use a Groovy double-quoted string when you need ${params.WHO}. Use single quotes in sh steps so secrets are never expanded by Groovy.","risk":false,"viz":""}],"nav":{"pos":3,"of":7,"prev":{"id":"jen-freestyle-job","title":"Module 2: Your first job: Hello Srinivas"},"next":{"id":"jen-scm-webhook","title":"Module 4: Pipeline from Git and automatic builds with webhooks"}}},{"id":"jen-scm-webhook","title":"Module 4: Pipeline from Git and automatic builds with webhooks","level":2,"icon":"git-github","summary":"Keep the Jenkinsfile in the repository, build every branch with a multibranch pipeline and trigger builds on push.","qna":[{"q":"In which situation do we use this?","a":"Every branch and pull request should be built and tested automatically."},{"q":"Webhook or polling?","a":"A webhook starts a build at once. Polling is the fallback when the host cannot reach Jenkins."},{"q":"What comes next?","a":"Module 5 handles secrets and agents."}],"steps":[{"title":"Put the Jenkinsfile in the repo","icon":"git-repo","text":"The Jenkinsfile sits next to the code, so changing the pipeline is a normal commit that can be reviewed.","cmd":"cd ~/pipe-demo && git init -q -b main\ngit add Jenkinsfile && git commit -qm \"Add Jenkinsfile\"\ngit remote add origin https://github.com/<you>/hello-srinivas.git\ngit push -u origin main","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a multibranch pipeline","icon":"lucide-git-branch","text":"New Item, Multibranch Pipeline, add a Git source (GitHub, GitLab or Bitbucket), save. Jenkins scans the repository and creates one job per branch that has a Jenkinsfile.","cmd":"git switch -c feature/greeting\ngit push -u origin feature/greeting","out":"Scan Multibranch Pipeline: Examining you/hello-srinivas\n  Checking branch main\n    'Jenkinsfile' found\n  Checking branch feature/greeting\n    'Jenkinsfile' found\nFinished: SUCCESS","outKind":"example","note":"","risk":false,"viz":""},{"title":"Trigger on push with a webhook","icon":"lucide-zap","text":"Polling wastes time. Add a webhook in the repository settings so the host tells Jenkins when something changes. GitHub uses /github-webhook/, GitLab uses /project/<job>, Bitbucket uses /bitbucket-scmsource-hook/notify.","cmd":"curl -s -o /dev/null -w '%{http_code}\n' -X POST $JENKINS_URL/github-webhook/ -H 'X-GitHub-Event: ping' -H 'Content-Type: application/json' -d '{}'","out":"200","outKind":"example","note":"Jenkins must be reachable from GitHub, GitLab or Bitbucket. Behind a firewall use polling or a reverse proxy.","risk":false,"viz":""},{"title":"Fallback: poll the repository","icon":"lucide-clock","text":"If webhooks cannot reach Jenkins, ask it to check on a schedule. H spreads the load.","cmd":"printf \"triggers { pollSCM('H/5 * * * *') }\n\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Branches and pull requests","icon":"lucide-git-merge","text":"Each branch and pull request gets its own build and reports a status check back to the host, so merges can be blocked until the build is green.","cmd":"git switch main && git merge --no-ff feature/greeting -m \"Merge greeting\"\ngit push","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":7,"prev":{"id":"jen-pipeline-jenkinsfile","title":"Module 3: A pipeline as code: the Jenkinsfile"},"next":{"id":"jen-credentials-agents","title":"Module 5: Secrets and agents"}}},{"id":"jen-credentials-agents","title":"Module 5: Secrets and agents","level":3,"icon":"lucide-key-round","summary":"Store a secret safely, use it in a pipeline without leaking it, and run builds on a separate agent.","qna":[{"q":"In which situation do we use this?","a":"A pipeline needs a password, token or key, or builds are heavy and should not run on the controller."},{"q":"How do I keep a secret out of the log?","a":"Use withCredentials with single-quoted shell strings. Jenkins masks the value."},{"q":"What comes next?","a":"Module 6 builds and deploys an image."}],"steps":[{"title":"Where secrets go","icon":"lucide-lock","text":"Never write passwords in a Jenkinsfile or job. Manage Jenkins, Credentials stores secret text, username and password, SSH keys and files, encrypted on disk.","cmd":"curl -s -u $JENKINS_USER:$JENKINS_TOKEN \"$JENKINS_URL/credentials/store/system/domain/_/api/json?tree=credentials[id,typeName]\"","out":"{\"credentials\":[{\"id\":\"api-token\",\"typeName\":\"Secret text\"}]}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Use a credential in a pipeline","icon":"lucide-key-round","text":"withCredentials puts the secret in an environment variable for these steps only. Jenkins masks it in the log.","cmd":"cat > Jenkinsfile <<'EOF'\npipeline {\n  agent any\n  stages {\n    stage('Call API') {\n      steps {\n        withCredentials([string(credentialsId: 'api-token', variable: 'TOKEN')]) {\n          sh 'curl -s -H \"Authorization: Bearer $TOKEN\" https://api.example.com/health'\n        }\n      }\n    }\n  }\n}\nEOF","out":"+ curl -s -H 'Authorization: Bearer ****' https://api.example.com/health","outKind":"example","note":"Use single quotes around the sh script. Double quotes make Groovy substitute the secret into the command line.","risk":false,"viz":""},{"title":"Start an agent","icon":"lucide-server","text":"Create a node in Manage Jenkins, Nodes. It shows a secret. An inbound agent container connects to the controller with it.","cmd":"docker run -d --init --name agent1 jenkins/inbound-agent -url http://host.docker.internal:8080 -workDir=/home/jenkins/agent <agent-secret> agent1\njava -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN list-computers","out":"Built-In Node\nagent1","outKind":"example","note":"","risk":false,"viz":""},{"title":"Send a job to the agent by label","icon":"lucide-target","text":"Give the node a label such as docker. A pipeline with agent label asks for any node with that label.","cmd":"printf \"pipeline { agent { label 'docker' }\n  stages { stage('Where') { steps { sh 'hostname' } } } }\n\"","out":"Running on agent1 in /home/jenkins/agent/workspace/where\n+ hostname\n8f3c1a2b9d4e","outKind":"example","note":"","risk":false,"viz":""},{"title":"Keep the controller clean","icon":"lucide-shield","text":"Set the built-in node to 0 executors so builds run only on agents. Give jobs the least access they need and rotate tokens.","cmd":"curl -s -u $JENKINS_USER:$JENKINS_TOKEN \"$JENKINS_URL/computer/api/json?tree=computer[displayName,numExecutors]\"","out":"{\"computer\":[{\"displayName\":\"Built-In Node\",\"numExecutors\":0},{\"displayName\":\"agent1\",\"numExecutors\":2}]}","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":7,"prev":{"id":"jen-scm-webhook","title":"Module 4: Pipeline from Git and automatic builds with webhooks"},"next":{"id":"jen-docker-deploy","title":"Module 6: Pipeline that tests, builds a Docker image and deploys"}}},{"id":"jen-docker-deploy","title":"Module 6: Pipeline that tests, builds a Docker image and deploys","level":3,"icon":"docker-image","summary":"Build and push an image to ECR, deploy it with an approval step, and roll back if it fails.","qna":[{"q":"In which situation do we use this?","a":"A merge to main should test, build an image, push it and deploy, with approval for production."},{"q":"Why tag the image with the commit?","a":"Every deployed version can be traced to the exact code and rolled back by tag."},{"q":"What comes next?","a":"Module 7 rebuilds Jenkins itself from code."}],"steps":[{"title":"The plan","icon":"lucide-signpost","text":"Checkout, test, build the image, push it tagged with the commit, ask for approval, deploy, and notify.","cmd":"git rev-parse --short HEAD","out":"3a9f2c1","outKind":"example","note":"","risk":false,"viz":""},{"title":"The Jenkinsfile","icon":"cicd-jenkins","text":"The image tag is the short Git commit, so every build is traceable. A parameter chooses the environment.","cmd":"cat > Jenkinsfile <<'EOF'\npipeline {\n  agent { label 'docker' }\n  parameters { choice(name: 'ENV', choices: ['dev', 'prod']) }\n  environment {\n    REGISTRY = '123456789012.dkr.ecr.ap-south-1.amazonaws.com'\n    IMAGE = \"${REGISTRY}/hello-app:${GIT_COMMIT.take(7)}\"\n  }\n  stages {\n    stage('Test')  { steps { sh 'python3 -m unittest discover || true' } }\n    stage('Build') { steps { sh 'docker build -t $IMAGE .' } }\n    stage('Push')  {\n      steps {\n        withCredentials([usernamePassword(credentialsId: 'aws-ecr', usernameVariable: 'U', passwordVariable: 'P')]) {\n          sh 'echo $P | docker login --username $U --password-stdin $REGISTRY && docker push $IMAGE'\n        }\n      }\n    }\n    stage('Approve') { when { expression { params.ENV == 'prod' } } steps { input message: 'Deploy to production?' } }\n    stage('Deploy') { steps { sh 'kubectl set image deployment/hello hello=$IMAGE && kubectl rollout status deployment/hello --timeout=120s' } }\n  }\n  post { failure { sh 'kubectl rollout undo deployment/hello || true' } }\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run it for dev","icon":"lucide-rocket","text":"Dev has no approval. Watch each stage turn green and read the rollout message.","cmd":"java -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN build hello-deploy -p ENV=dev -s -v","out":"The push refers to repository [123456789012.dkr.ecr.ap-south-1.amazonaws.com/hello-app]\n3a9f2c1: digest: sha256:8d9c... size: 1573\ndeployment \"hello\" successfully rolled out","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run for production with approval","icon":"lucide-door-open","text":"The pipeline pauses at Approve. Someone with permission clicks Proceed or Abort.","cmd":"java -jar jenkins-cli.jar -s $JENKINS_URL -auth $JENKINS_USER:$JENKINS_TOKEN build hello-deploy -p ENV=prod","out":"Input requested: Deploy to production?","outKind":"example","note":"","risk":false,"viz":""},{"title":"Roll back","icon":"lucide-undo-2","text":"post failure undoes a bad deploy automatically. You can also roll back by hand or redeploy an older tag.","cmd":"kubectl rollout history deployment/hello\nkubectl rollout undo deployment/hello","out":"deployment.apps/hello rolled back","outKind":"example","note":"","risk":false,"viz":""},{"title":"Tell people","icon":"lucide-bell","text":"Add a post section that sends a message to Slack or email with the job name, build number and link.","cmd":"printf \"post { failure { mail to: 'team@example.com', subject: \\\"FAILED: \\${env.JOB_NAME} #\\${env.BUILD_NUMBER}\\\", body: \\\"\\${env.BUILD_URL}\\\" } }\n\"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":7,"prev":{"id":"jen-credentials-agents","title":"Module 5: Secrets and agents"},"next":{"id":"jen-config-as-code","title":"Module 7: Jenkins as code: plugins, JCasC and backups"}}},{"id":"jen-config-as-code","title":"Module 7: Jenkins as code: plugins, JCasC and backups","level":3,"icon":"lucide-settings","summary":"Rebuild the same Jenkins from files: a plugin list, a YAML configuration and a custom image, plus a backup routine.","qna":[{"q":"In which situation do we use this?","a":"Jenkins must be rebuilt quickly, or several instances must be identical."},{"q":"What goes in the repository?","a":"The plugin list, the JCasC YAML and the Dockerfile. Secrets come from the environment or a secret store."},{"q":"What comes next?","a":"Back up JENKINS_HOME and test a restore."}],"steps":[{"title":"List plugins in a file","icon":"lucide-list-checks","text":"A plugins.txt pins what the controller needs. jenkins-plugin-cli installs it while the image is built.","cmd":"mkdir -p ~/jenkins-as-code && cd ~/jenkins-as-code\nprintf \"configuration-as-code\ngit\nworkflow-aggregator\ncredentials-binding\ndocker-workflow\n\" > plugins.txt\ncat plugins.txt","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Describe the configuration in YAML","icon":"lucide-file-text","text":"Configuration as Code reads jenkins.yaml at start-up. The admin password comes from an environment variable, not the file.","cmd":"cat > jenkins.yaml <<'EOF'\njenkins:\n  systemMessage: \"Hello Srinivas CI\"\n  numExecutors: 0\n  securityRealm:\n    local:\n      allowsSignup: false\n      users:\n        - id: \"admin\"\n          password: \"${ADMIN_PASSWORD}\"\nunclassified:\n  location:\n    url: http://localhost:8080/\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Build your own image","icon":"lucide-package","text":"The Dockerfile installs the plugins and copies the YAML, so every start gives the same Jenkins.","cmd":"cat > Dockerfile <<'EOF'\nFROM jenkins/jenkins:lts-jdk17\nCOPY plugins.txt /usr/share/jenkins/ref/plugins.txt\nRUN jenkins-plugin-cli --plugin-file /usr/share/jenkins/ref/plugins.txt\nCOPY jenkins.yaml /var/jenkins_home/casc_configs/jenkins.yaml\nENV CASC_JENKINS_CONFIG=/var/jenkins_home/casc_configs/jenkins.yaml JAVA_OPTS=-Djenkins.install.runSetupWizard=false\nEOF\ndocker build -t my-jenkins:1 .","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Start it, no setup wizard","icon":"lucide-play","text":"It starts configured: no unlock screen, no clicking. Throw it away and start again whenever you like.","cmd":"docker run -d --name jenkins2 -p 8090:8080 -e ADMIN_PASSWORD=change-me -v jenkins2_home:/var/jenkins_home my-jenkins:1\ncurl -s -u admin:change-me http://localhost:8090/api/json?tree=description,numExecutors","out":"","outKind":"","note":"change-me is a lab value. Pass real secrets from a secret store.","risk":true,"viz":""},{"title":"Back up and upgrade","icon":"lucide-save","text":"Back up JENKINS_HOME and keep it off the host. To upgrade, build the image with the new tag and start it on the same volume.","cmd":"docker run --rm -v jenkins2_home:/data -v $PWD:/backup alpine:3.20 tar -czf /backup/jenkins-backup.tar.gz -C /data .\nls -lh jenkins-backup.tar.gz","out":"-rw-r--r-- 1 you you 38M Nov  4 10:40 jenkins-backup.tar.gz","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":7,"prev":{"id":"jen-docker-deploy","title":"Module 6: Pipeline that tests, builds a Docker image and deploys"},"next":null}}]},{"id":"aws","name":"AWS: cloud from scratch","color":"#FF9900","tagline":"Sign in, secure access with IAM, store files, launch servers, balance and scale them, add a database, DNS and HTTPS, monitor cost, and run a function. Commands use AWS CLI v2 in ap-south-1 (Mumbai). Outputs are examples with placeholder IDs. Many steps create billable resources, so every module ends with clean-up.","icon":"aws-vpc","workflows":[{"id":"aws-cli-sso","title":"Module 1: AWS CLI, sign-in with SSO, and reading output","level":1,"icon":"lucide-terminal","summary":"Install-check the CLI, sign in with short-lived SSO credentials, confirm who you are and shape the output.","qna":[{"q":"In which situation do we use this?","a":"You manage AWS from a terminal or scripts. Sign in first and confirm which account you are in."},{"q":"SSO or access keys?","a":"Prefer SSO. Its credentials expire on their own, while long-lived keys can leak."},{"q":"What comes next?","a":"Module 2 sets up least-privilege access."}],"steps":[{"title":"Check the CLI","icon":"lucide-terminal","text":"AWS CLI v2 is one program for every service. The version should start with aws-cli/2.","cmd":"aws --version\nwhich aws","out":"$ aws --version\naws-cli/2.17.40 Python/3.12.6 Linux/6.8.0-45-generic exe/x86_64.ubuntu.24","outKind":"example","note":"","risk":false,"viz":""},{"title":"Sign in with IAM Identity Center (SSO)","icon":"lucide-key-round","text":"SSO gives short-lived credentials that expire on their own, which is safer than long-lived access keys. configure sso asks for your start URL and region and saves a named profile.","cmd":"aws configure sso\naws sso login --profile dev","out":"Attempting to automatically open the SSO authorization page in your default browser.\nSuccessfully logged into Start URL: https://example.awsapps.com/start","outKind":"example","note":"Never commit access keys to Git. If you must use keys, put them only in ~/.aws/credentials with file permission 600.","risk":false,"viz":""},{"title":"Who am I?","icon":"lucide-users","text":"sts get-caller-identity is the safest first command: it changes nothing and shows the account and the role you are using.","cmd":"export AWS_PROFILE=dev AWS_REGION=ap-south-1\naws sts get-caller-identity","out":"{\n  \"UserId\": \"AROAXXXXXXXXXXXXXXXXX:srinivas\",\n  \"Account\": \"123456789012\",\n  \"Arn\": \"arn:aws:sts::123456789012:assumed-role/AdministratorAccess/srinivas\"\n}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Shape the output with --query and --output","icon":"lucide-filter","text":"--query uses JMESPath to pick fields. --output text is easy to use in scripts, table is easy to read, json is the default.","cmd":"aws ec2 describe-regions --query 'Regions[].RegionName' --output text\naws ec2 describe-vpcs --query 'Vpcs[].{id:VpcId,cidr:CidrBlock,default:IsDefault}' --output table","out":"---------------------------------------------\n|               DescribeVpcs                |\n+-------------+--------------+--------------+\n|    cidr     |   default    |     id       |\n+-------------+--------------+--------------+\n|  172.31.0.0/16 |  True     | vpc-0a1b2c3d |\n+-------------+--------------+--------------+","outKind":"example","note":"","risk":false,"viz":""},{"title":"Ask the CLI for help and try a dry run","icon":"lucide-book-open","text":"Every command has built-in help. --dry-run checks permissions without creating anything: a message saying DryRunOperation means the call would have worked.","cmd":"aws ec2 run-instances help | head -n 12\naws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.micro --dry-run","out":"An error occurred (DryRunOperation) when calling the RunInstances operation: Request would have succeeded, but DryRun flag is set.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Profiles and the config files","icon":"lucide-folder","text":"Profiles live in ~/.aws/config. Switch with AWS_PROFILE or --profile. Keep one profile per account and role.","cmd":"cat ~/.aws/config\naws configure list","out":"[profile dev]\nsso_session = corp\nsso_account_id = 123456789012\nsso_role_name = AdministratorAccess\nregion = ap-south-1\noutput = json","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":9,"prev":null,"next":{"id":"aws-iam-roles-policies","title":"Module 2: IAM users, roles and least-privilege policies"}}},{"id":"aws-iam-roles-policies","title":"Module 2: IAM users, roles and least-privilege policies","level":2,"icon":"lucide-lock","summary":"Write a policy that allows one thing, give it to a role that EC2 can assume, then prove with the simulator what is allowed.","qna":[{"q":"In which situation do we use this?","a":"A server, function or person needs exactly the access it requires, and nothing more."},{"q":"Why a role and not an access key on the server?","a":"A role gives temporary credentials automatically, with nothing on disk to steal."},{"q":"What comes next?","a":"Module 3 stores data in S3 using this access model."}],"steps":[{"title":"The four ideas","icon":"lucide-shield","text":"A user or role is who. A policy is a JSON list of allowed or denied actions. A role has no password: a trusted service or person assumes it and receives temporary credentials. Everything is denied unless a policy allows it.","cmd":"aws iam get-account-summary --query 'SummaryMap.{Users:Users,Groups:Groups,Roles:Roles,Policies:Policies}'","out":"{\"Users\": 2, \"Groups\": 1, \"Roles\": 14, \"Policies\": 5}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Write a least-privilege policy","icon":"lucide-file-text","text":"This policy lets a server read objects from one bucket and nothing else. Resource names the exact bucket, so other buckets stay unreachable.","cmd":"cat > s3-read.json <<'EOF'\n{\n  \"Version\": \"2012-10-17\",\n  \"Statement\": [\n    {\"Effect\": \"Allow\", \"Action\": [\"s3:ListBucket\"], \"Resource\": \"arn:aws:s3:::hello-srinivas-bucket\"},\n    {\"Effect\": \"Allow\", \"Action\": [\"s3:GetObject\"], \"Resource\": \"arn:aws:s3:::hello-srinivas-bucket/*\"}\n  ]\n}\nEOF\naws iam create-policy --policy-name hello-s3-read --policy-document file://s3-read.json --query Policy.Arn --output text","out":"arn:aws:iam::123456789012:policy/hello-s3-read","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a role EC2 is allowed to assume","icon":"lucide-users","text":"The trust policy answers who may use this role. Here only the EC2 service can. Servers then get credentials automatically, with no keys on disk.","cmd":"cat > trust.json <<'EOF'\n{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Principal\":{\"Service\":\"ec2.amazonaws.com\"},\"Action\":\"sts:AssumeRole\"}]}\nEOF\naws iam create-role --role-name hello-ec2-role --assume-role-policy-document file://trust.json --query Role.Arn --output text","out":"arn:aws:iam::123456789012:role/hello-ec2-role","outKind":"example","note":"","risk":false,"viz":""},{"title":"Attach the policy and make an instance profile","icon":"lucide-link","text":"attach-role-policy connects permissions to the role. An instance profile is the wrapper that lets an EC2 instance carry the role.","cmd":"aws iam attach-role-policy --role-name hello-ec2-role --policy-arn arn:aws:iam::123456789012:policy/hello-s3-read\naws iam create-instance-profile --instance-profile-name hello-ec2-profile\naws iam add-role-to-instance-profile --instance-profile-name hello-ec2-profile --role-name hello-ec2-role\naws iam list-attached-role-policies --role-name hello-ec2-role --output table","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Test it with the policy simulator","icon":"lucide-flask-conical","text":"The simulator answers allowed or denied without touching any data. Reading is allowed; deleting is not.","cmd":"aws iam simulate-principal-policy --policy-source-arn arn:aws:iam::123456789012:role/hello-ec2-role --action-names s3:GetObject s3:DeleteObject --resource-arns arn:aws:s3:::hello-srinivas-bucket/hello.txt --query 'EvaluationResults[].[EvalActionName,EvalDecision]' --output text","out":"s3:GetObject\\tallowed\ns3:DeleteObject\\timplicitDeny","outKind":"example","note":"","risk":false,"viz":""},{"title":"Review, then clean up in order","icon":"lucide-eraser","text":"Detach policies before deleting a role, and remove the role from the profile before deleting the profile. Review access regularly with a credential report.","cmd":"aws iam generate-credential-report --query State --output text\naws iam remove-role-from-instance-profile --instance-profile-name hello-ec2-profile --role-name hello-ec2-role\naws iam delete-instance-profile --instance-profile-name hello-ec2-profile\naws iam detach-role-policy --role-name hello-ec2-role --policy-arn arn:aws:iam::123456789012:policy/hello-s3-read\naws iam delete-role --role-name hello-ec2-role\naws iam delete-policy --policy-arn arn:aws:iam::123456789012:policy/hello-s3-read","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":2,"of":9,"prev":{"id":"aws-cli-sso","title":"Module 1: AWS CLI, sign-in with SSO, and reading output"},"next":{"id":"aws-s3-storage","title":"Module 3: S3 buckets, versioning, presigned links and lifecycle"}}},{"id":"aws-s3-storage","title":"Module 3: S3 buckets, versioning, presigned links and lifecycle","level":2,"icon":"lucide-database","summary":"Create a private bucket, upload hello.txt, keep old versions, share a temporary link and clean up properly.","qna":[{"q":"In which situation do we use this?","a":"Storing files, backups, logs, static sites or Terraform state."},{"q":"What should always be turned on?","a":"Block Public Access, default encryption and, for important data, versioning."},{"q":"What comes next?","a":"Module 4 launches a server that can read this bucket."}],"steps":[{"title":"Create a bucket with a unique name","icon":"lucide-database","text":"Bucket names are global, so add your account ID. Outside us-east-1 you must give the location.","cmd":"ACCOUNT=$(aws sts get-caller-identity --query Account --output text)\nBUCKET=hello-srinivas-$ACCOUNT\naws s3api create-bucket --bucket $BUCKET --region ap-south-1 --create-bucket-configuration LocationConstraint=ap-south-1","out":"{\n  \"Location\": \"http://hello-srinivas-123456789012.s3.amazonaws.com/\"\n}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Make it private and encrypted","icon":"lucide-shield","text":"Block Public Access stops accidental exposure for good. Default encryption protects data at rest with no extra work.","cmd":"aws s3api put-public-access-block --bucket $BUCKET --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true\naws s3api put-bucket-encryption --bucket $BUCKET --server-side-encryption-configuration '{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"AES256\"}}]}'\naws s3api get-public-access-block --bucket $BUCKET --query PublicAccessBlockConfiguration","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Upload hello.txt and read it back","icon":"lucide-upload","text":"s3 cp copies in either direction. A trailing - as the destination prints to the screen.","cmd":"echo \"Hello Srinivas\" > hello.txt\naws s3 cp hello.txt s3://$BUCKET/hello.txt\naws s3 ls s3://$BUCKET/\naws s3 cp s3://$BUCKET/hello.txt -","out":"upload: ./hello.txt to s3://hello-srinivas-123456789012/hello.txt\n2026-11-04 10:02:11         15 hello.txt\nHello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Turn on versioning and overwrite","icon":"lucide-git-commit","text":"With versioning, an overwrite or delete keeps the old copy. It is the cloud version of Git history for objects.","cmd":"aws s3api put-bucket-versioning --bucket $BUCKET --versioning-configuration Status=Enabled\necho \"Hello Srinivas, version 2\" > hello.txt\naws s3 cp hello.txt s3://$BUCKET/hello.txt\naws s3api list-object-versions --bucket $BUCKET --prefix hello.txt --query 'Versions[].[VersionId,IsLatest]' --output text","out":"3sL4kqtJlcpXroDTDmJ.rRSRpBPU3ByA\\tTrue\nnull\\tFalse","outKind":"example","note":"","risk":false,"viz":""},{"title":"Restore the first version","icon":"lucide-undo-2","text":"Fetch a specific version by its ID, or copy it over the current one to make it current again.","cmd":"aws s3api get-object --bucket $BUCKET --key hello.txt --version-id null old.txt\ncat old.txt","out":"Hello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Share with a temporary link","icon":"lucide-link","text":"A presigned URL lets someone download a private object for a short time, with no AWS account needed.","cmd":"aws s3 presign s3://$BUCKET/hello.txt --expires-in 300\ncurl -s \"$(aws s3 presign s3://$BUCKET/hello.txt --expires-in 300)\"","out":"Hello Srinivas, version 2","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save money with a lifecycle rule","icon":"lucide-clock","text":"A rule can move old data to cheaper storage and delete it later. This one expires old versions after 30 days.","cmd":"aws s3api put-bucket-lifecycle-configuration --bucket $BUCKET --lifecycle-configuration '{\"Rules\":[{\"ID\":\"old-versions\",\"Status\":\"Enabled\",\"Filter\":{},\"NoncurrentVersionExpiration\":{\"NoncurrentDays\":30}}]}'\naws s3api get-bucket-lifecycle-configuration --bucket $BUCKET --query 'Rules[].ID'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Delete everything, versions included","icon":"lucide-eraser","text":"A versioned bucket cannot be removed until every version is gone. List them all, delete them, then delete the bucket.","cmd":"aws s3api delete-objects --bucket $BUCKET --delete \"$(aws s3api list-object-versions --bucket $BUCKET --query '{Objects: Versions[].{Key:Key,VersionId:VersionId}}' --output json)\"\naws s3api delete-bucket --bucket $BUCKET","out":"","outKind":"","note":"Add delete markers to the same list if the bucket contains any.","risk":true,"viz":""}],"nav":{"pos":3,"of":9,"prev":{"id":"aws-iam-roles-policies","title":"Module 2: IAM users, roles and least-privilege policies"},"next":{"id":"aws-ec2-launch","title":"Module 4: Launch a web server on EC2"}}},{"id":"aws-ec2-launch","title":"Module 4: Launch a web server on EC2","level":2,"icon":"lucide-server","summary":"Find an image, create a key and a firewall, boot an instance with a start-up script that serves Hello Srinivas, and shut it down.","qna":[{"q":"In which situation do we use this?","a":"You need a virtual server of your own: a web host, a build machine, a test box."},{"q":"How should SSH be restricted?","a":"Allow port 22 only from your own address, and prefer Systems Manager Session Manager for real work."},{"q":"What comes next?","a":"Module 5 puts several servers behind a load balancer."}],"steps":[{"title":"Find the latest Amazon Linux image","icon":"lucide-search","text":"AWS publishes the newest image ID as a public parameter, so you never copy an outdated AMI ID.","cmd":"AMI=$(aws ssm get-parameter --name /aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64 --query Parameter.Value --output text)\necho $AMI","out":"ami-0c1a2b3c4d5e6f789","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a key pair","icon":"lucide-key-round","text":"The key pair lets you log in by SSH. The private key is shown only once, so save it with strict permissions.","cmd":"aws ec2 create-key-pair --key-name srinivas-key --query KeyMaterial --output text > srinivas-key.pem\nchmod 400 srinivas-key.pem\nls -l srinivas-key.pem","out":"-r-------- 1 you you 1675 Nov  4 10:10 srinivas-key.pem","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a security group (the instance firewall)","icon":"lucide-shield-ban","text":"Allow web traffic from anywhere and SSH only from your own address. Everything else is blocked by default.","cmd":"VPC=$(aws ec2 describe-vpcs --filters Name=is-default,Values=true --query 'Vpcs[0].VpcId' --output text)\nSG=$(aws ec2 create-security-group --group-name hello-web --description \"Hello Srinivas web\" --vpc-id $VPC --query GroupId --output text)\nMYIP=$(curl -s https://checkip.amazonaws.com)\naws ec2 authorize-security-group-ingress --group-id $SG --protocol tcp --port 80 --cidr 0.0.0.0/0\naws ec2 authorize-security-group-ingress --group-id $SG --protocol tcp --port 22 --cidr $MYIP/32","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the start-up script","icon":"lucide-file-text","text":"User data runs once as root when the instance first boots. It installs nginx and writes the page.","cmd":"cat > user-data.sh <<'EOF'\n#!/bin/bash\ndnf install -y nginx\necho \"Hello Srinivas from $(hostname)\" > /usr/share/nginx/html/index.html\nsystemctl enable --now nginx\nEOF\ncat user-data.sh","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Launch and wait","icon":"lucide-rocket","text":"run-instances starts the server. wait instance-running blocks until it is up, then describe shows its public address.","cmd":"ID=$(aws ec2 run-instances --image-id $AMI --instance-type t3.micro --key-name srinivas-key --security-group-ids $SG --user-data file://user-data.sh --tag-specifications 'ResourceType=instance,Tags=[{Key=Name,Value=hello-srinivas}]' --query 'Instances[0].InstanceId' --output text)\naws ec2 wait instance-running --instance-ids $ID\nIP=$(aws ec2 describe-instances --instance-ids $ID --query 'Reservations[0].Instances[0].PublicIpAddress' --output text)\necho $ID $IP","out":"i-0abc123def4567890 13.233.10.45","outKind":"example","note":"","risk":false,"viz":""},{"title":"Test it","icon":"lucide-check","text":"Give the script a minute to finish, then call the web server and log in by SSH.","cmd":"curl http://$IP\nssh -i srinivas-key.pem ec2-user@$IP 'uptime'","out":"Hello Srinivas from ip-172-31-5-20.ap-south-1.compute.internal","outKind":"example","note":"","risk":false,"viz":""},{"title":"Stop, start and delete","icon":"lucide-eraser","text":"A stopped instance costs nothing for compute but still bills for its disk. Terminate it and delete the security group and key to leave no charges.","cmd":"aws ec2 stop-instances --instance-ids $ID\naws ec2 terminate-instances --instance-ids $ID\naws ec2 wait instance-terminated --instance-ids $ID\naws ec2 delete-security-group --group-id $SG\naws ec2 delete-key-pair --key-name srinivas-key","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":4,"of":9,"prev":{"id":"aws-s3-storage","title":"Module 3: S3 buckets, versioning, presigned links and lifecycle"},"next":{"id":"aws-alb-asg","title":"Module 5: Load balancer and Auto Scaling group"}}},{"id":"aws-alb-asg","title":"Module 5: Load balancer and Auto Scaling group","level":3,"icon":"lucide-network","summary":"Put an Application Load Balancer in front of servers that scale themselves, then test, scale and remove it all.","qna":[{"q":"In which situation do we use this?","a":"One server is a single point of failure, or traffic changes during the day."},{"q":"What does the health check do?","a":"The load balancer stops sending requests to unhealthy servers, and the Auto Scaling group replaces them."},{"q":"What comes next?","a":"Module 6 adds a database."}],"steps":[{"title":"The picture","icon":"lucide-network","text":"The ALB is the single public entry. It forwards to a target group, which sends requests to healthy instances that an Auto Scaling group keeps at the size you set.","cmd":"aws elbv2 describe-load-balancers --query 'LoadBalancers[].LoadBalancerName' --output text","out":"","outKind":"","note":"","risk":false,"viz":"Browser → ALB: HTTP 80\nALB → Target group: forward\nTarget group → EC2 instances: health check /"},{"title":"Collect network IDs","icon":"lucide-signpost","text":"You need a VPC, two subnets in different zones and a security group that allows port 80. The default VPC has them.","cmd":"VPC=$(aws ec2 describe-vpcs --filters Name=is-default,Values=true --query 'Vpcs[0].VpcId' --output text)\nSUBNETS=$(aws ec2 describe-subnets --filters Name=vpc-id,Values=$VPC --query 'Subnets[0:2].SubnetId' --output text)\nset -- $SUBNETS; S1=$1; S2=$2\nSG=$(aws ec2 create-security-group --group-name hello-alb-sg --description \"web\" --vpc-id $VPC --query GroupId --output text)\naws ec2 authorize-security-group-ingress --group-id $SG --protocol tcp --port 80 --cidr 0.0.0.0/0","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a launch template","icon":"lucide-file-text","text":"The template is the recipe for every new instance: image, size, firewall and start-up script. The script puts the instance name in the page so you can see balancing.","cmd":"cat > user-data.sh <<'EOF'\n#!/bin/bash\ndnf install -y nginx\necho \"Hello Srinivas from $(hostname)\" > /usr/share/nginx/html/index.html\nsystemctl enable --now nginx\nEOF\nAMI=$(aws ssm get-parameter --name /aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64 --query Parameter.Value --output text)\naws ec2 create-launch-template --launch-template-name hello-lt --launch-template-data \"{\\\"ImageId\\\":\\\"$AMI\\\",\\\"InstanceType\\\":\\\"t3.micro\\\",\\\"SecurityGroupIds\\\":[\\\"$SG\\\"],\\\"UserData\\\":\\\"$(base64 -w0 user-data.sh)\\\"}\" --query LaunchTemplate.LaunchTemplateId --output text","out":"","outKind":"","note":"On macOS replace base64 -w0 with base64 -b 0.","risk":false,"viz":""},{"title":"Create the target group and the load balancer","icon":"lucide-network","text":"The target group defines the health check. The listener sends HTTP port 80 to it.","cmd":"TG=$(aws elbv2 create-target-group --name hello-tg --protocol HTTP --port 80 --vpc-id $VPC --health-check-path / --query 'TargetGroups[0].TargetGroupArn' --output text)\nALB=$(aws elbv2 create-load-balancer --name hello-alb --subnets $S1 $S2 --security-groups $SG --query 'LoadBalancers[0].LoadBalancerArn' --output text)\naws elbv2 create-listener --load-balancer-arn $ALB --protocol HTTP --port 80 --default-actions Type=forward,TargetGroupArn=$TG","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create the Auto Scaling group","icon":"lucide-layers","text":"Keep 2 to 4 instances, replace unhealthy ones using the load balancer's health check, and give new ones two minutes before judging.","cmd":"aws autoscaling create-auto-scaling-group --auto-scaling-group-name hello-asg --launch-template LaunchTemplateName=hello-lt,Version='$Latest' --min-size 2 --max-size 4 --desired-capacity 2 --vpc-zone-identifier \"$S1,$S2\" --target-group-arns $TG --health-check-type ELB --health-check-grace-period 120\naws autoscaling describe-auto-scaling-groups --auto-scaling-group-names hello-asg --query 'AutoScalingGroups[0].Instances[].[InstanceId,HealthStatus]' --output text","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Scale on CPU automatically","icon":"lucide-timer","text":"Target tracking adds instances when average CPU is above 50 percent and removes them when it falls.","cmd":"aws autoscaling put-scaling-policy --auto-scaling-group-name hello-asg --policy-name cpu50 --policy-type TargetTrackingScaling --target-tracking-configuration '{\"PredefinedMetricSpecification\":{\"PredefinedMetricType\":\"ASGAverageCPUUtilization\"},\"TargetValue\":50.0}'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Test the balancing","icon":"lucide-check","text":"Call the load balancer repeatedly. The host name in the answer changes as requests are spread across instances.","cmd":"DNS=$(aws elbv2 describe-load-balancers --names hello-alb --query 'LoadBalancers[0].DNSName' --output text)\nfor i in 1 2 3 4; do curl -s http://$DNS; done","out":"Hello Srinivas from ip-172-31-5-20.ap-south-1.compute.internal\nHello Srinivas from ip-172-31-21-8.ap-south-1.compute.internal\nHello Srinivas from ip-172-31-5-20.ap-south-1.compute.internal\nHello Srinivas from ip-172-31-21-8.ap-south-1.compute.internal","outKind":"example","note":"","risk":false,"viz":""},{"title":"Delete in reverse order","icon":"lucide-eraser","text":"Remove the group first so it stops launching servers, then the load balancer, the target group and the template. Leaving the ALB running costs money every hour.","cmd":"aws autoscaling delete-auto-scaling-group --auto-scaling-group-name hello-asg --force-delete\naws elbv2 delete-load-balancer --load-balancer-arn $ALB\naws elbv2 delete-target-group --target-group-arn $TG\naws ec2 delete-launch-template --launch-template-name hello-lt","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":5,"of":9,"prev":{"id":"aws-ec2-launch","title":"Module 4: Launch a web server on EC2"},"next":{"id":"aws-rds-secrets","title":"Module 6: A managed database with the password in Secrets Manager"}}},{"id":"aws-rds-secrets","title":"Module 6: A managed database with the password in Secrets Manager","level":3,"icon":"lucide-database","summary":"Create a PostgreSQL database in private subnets, let AWS manage the master password, connect with it and delete safely.","qna":[{"q":"In which situation do we use this?","a":"The application needs a relational database without managing backups, patches and failover."},{"q":"Why is the database not public?","a":"Only the application should reach it. Use private subnets and a security group that allows the app's group."},{"q":"What comes next?","a":"Module 7 gives the site a name and HTTPS."}],"steps":[{"title":"Decide what to manage yourself","icon":"lucide-equal","text":"RDS runs the database engine, backups, patching and failover for you. You still choose size, network access and who can connect. A database must never be open to the internet.","cmd":"aws rds describe-db-engine-versions --engine postgres --default-only --query 'DBEngineVersions[0].EngineVersion' --output text","out":"16.4","outKind":"example","note":"","risk":false,"viz":""},{"title":"Subnet group in private subnets","icon":"lucide-network","text":"The subnet group tells RDS which subnets it may use. Choose private ones in at least two zones.","cmd":"aws rds create-db-subnet-group --db-subnet-group-name hello-db-subnets --db-subnet-group-description \"private subnets\" --subnet-ids subnet-0aaa111 subnet-0bbb222","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a security group that only the app can reach","icon":"lucide-shield-ban","text":"Allow port 5432 only from the application's security group, not from an address range.","cmd":"DBSG=$(aws ec2 create-security-group --group-name hello-db-sg --description \"db\" --vpc-id $VPC --query GroupId --output text)\naws ec2 authorize-security-group-ingress --group-id $DBSG --protocol tcp --port 5432 --source-group $SG","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create the database; AWS stores the password","icon":"lucide-lock","text":"--manage-master-user-password makes RDS create the secret in Secrets Manager and rotate it. You never see or write the password in a script.","cmd":"aws rds create-db-instance --db-instance-identifier hello-db --engine postgres --db-instance-class db.t4g.micro --allocated-storage 20 --master-username appadmin --manage-master-user-password --db-subnet-group-name hello-db-subnets --vpc-security-group-ids $DBSG --no-publicly-accessible --backup-retention-period 7 --storage-encrypted\naws rds wait db-instance-available --db-instance-identifier hello-db","out":"Waiting for the instance to become available (about 8 minutes)","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the endpoint and connect","icon":"lucide-plug","text":"Look up the host name, fetch the password from the secret at the moment you need it, and connect from a server inside the VPC.","cmd":"HOST=$(aws rds describe-db-instances --db-instance-identifier hello-db --query 'DBInstances[0].Endpoint.Address' --output text)\nSECRET=$(aws rds describe-db-instances --db-instance-identifier hello-db --query 'DBInstances[0].MasterUserSecret.SecretArn' --output text)\nPGPASSWORD=$(aws secretsmanager get-secret-value --secret-id $SECRET --query SecretString --output text | python3 -c 'import sys,json;print(json.load(sys.stdin)[\"password\"])') psql -h $HOST -U appadmin -d postgres -c \"select 'Hello Srinivas' as greeting;\"","out":"greeting\n----------------\n Hello Srinivas","outKind":"example","note":"","risk":false,"viz":""},{"title":"Snapshot and delete","icon":"lucide-eraser","text":"Take a final snapshot if the data matters. Deleting without one is permanent. Turn off deletion protection first if it is on.","cmd":"aws rds create-db-snapshot --db-instance-identifier hello-db --db-snapshot-identifier hello-db-final\naws rds delete-db-instance --db-instance-identifier hello-db --skip-final-snapshot --delete-automated-backups","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":6,"of":9,"prev":{"id":"aws-alb-asg","title":"Module 5: Load balancer and Auto Scaling group"},"next":{"id":"aws-route53-acm","title":"Module 7: Your own domain name with HTTPS"}}},{"id":"aws-route53-acm","title":"Module 7: Your own domain name with HTTPS","level":3,"icon":"lucide-globe","summary":"Point a name at the load balancer with Route 53, get a free certificate from ACM and serve HTTPS with a redirect.","qna":[{"q":"In which situation do we use this?","a":"Users should reach the app at a friendly name over HTTPS."},{"q":"Alias or CNAME?","a":"An alias works at the zone root and is free for AWS targets. A CNAME cannot sit at the root."},{"q":"What comes next?","a":"Module 8 watches logs, alarms and cost."}],"steps":[{"title":"Create a hosted zone","icon":"lucide-globe","text":"A hosted zone holds the DNS records of one domain. The command returns four name servers; set them at your domain registrar.","cmd":"aws route53 create-hosted-zone --name example.com --caller-reference $(date +%s) --query 'DelegationSet.NameServers' --output text","out":"ns-111.awsdns-01.com ns-222.awsdns-02.net ns-333.awsdns-03.org ns-444.awsdns-04.co.uk","outKind":"example","note":"","risk":false,"viz":""},{"title":"Point app.example.com at the load balancer","icon":"lucide-link","text":"An alias record points at an AWS resource, works at the zone root and costs nothing for queries. Zone IDs come from the load balancer description.","cmd":"ZONE=$(aws route53 list-hosted-zones-by-name --dns-name example.com --query 'HostedZones[0].Id' --output text)\nALBZONE=$(aws elbv2 describe-load-balancers --names hello-alb --query 'LoadBalancers[0].CanonicalHostedZoneId' --output text)\ncat > record.json <<'EOF'\n{\"Changes\":[{\"Action\":\"UPSERT\",\"ResourceRecordSet\":{\"Name\":\"app.example.com\",\"Type\":\"A\",\"AliasTarget\":{\"HostedZoneId\":\"ALBZONE_ID\",\"DNSName\":\"DNS_NAME\",\"EvaluateTargetHealth\":true}}}]}\nEOF\naws route53 change-resource-record-sets --hosted-zone-id $ZONE --change-batch file://record.json","out":"","outKind":"","note":"Replace ALBZONE_ID and DNS_NAME with the values from the load balancer.","risk":false,"viz":""},{"title":"Request a certificate","icon":"lucide-lock","text":"ACM issues free certificates for AWS services. DNS validation proves you control the domain by adding one special record.","cmd":"CERT=$(aws acm request-certificate --domain-name app.example.com --validation-method DNS --query CertificateArn --output text)\naws acm describe-certificate --certificate-arn $CERT --query 'Certificate.DomainValidationOptions[0].ResourceRecord'","out":"{\"Name\": \"_a1b2.app.example.com.\", \"Type\": \"CNAME\", \"Value\": \"_c3d4.acm-validations.aws.\"}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add the validation record and wait","icon":"lucide-clock","text":"Create that CNAME in the same hosted zone. When ACM sees it the certificate becomes ISSUED.","cmd":"aws acm wait certificate-validated --certificate-arn $CERT\naws acm describe-certificate --certificate-arn $CERT --query Certificate.Status --output text","out":"ISSUED","outKind":"example","note":"","risk":false,"viz":""},{"title":"Add an HTTPS listener and redirect HTTP","icon":"lucide-shield","text":"Port 443 serves the site with the certificate. The old port 80 listener now answers with a redirect, so everyone ends on HTTPS.","cmd":"aws elbv2 create-listener --load-balancer-arn $ALB --protocol HTTPS --port 443 --certificates CertificateArn=$CERT --ssl-policy ELBSecurityPolicy-TLS13-1-2-2021-06 --default-actions Type=forward,TargetGroupArn=$TG\naws elbv2 modify-listener --listener-arn $HTTP_LISTENER --default-actions 'Type=redirect,RedirectConfig={Protocol=HTTPS,Port=443,StatusCode=HTTP_301}'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify","icon":"lucide-check","text":"Check that the name resolves, the certificate is trusted and HTTP redirects.","cmd":"dig +short app.example.com\ncurl -sI https://app.example.com | head -n 1\ncurl -sI http://app.example.com | grep -i location","out":"HTTP/2 200\nlocation: https://app.example.com:443/","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":9,"prev":{"id":"aws-rds-secrets","title":"Module 6: A managed database with the password in Secrets Manager"},"next":{"id":"aws-monitor-cost","title":"Module 8: Logs, alarms and cost control"}}},{"id":"aws-monitor-cost","title":"Module 8: Logs, alarms and cost control","level":2,"icon":"lucide-chart-line","summary":"Read logs, check a metric, get an e-mail when CPU is high, and put a budget on your spending.","qna":[{"q":"In which situation do we use this?","a":"Before going live: you want to know when something breaks and when spending climbs."},{"q":"What is the first cost protection?","a":"A budget with an e-mail alert, tags on every resource, and deleting what you do not use."},{"q":"What comes next?","a":"Module 9 runs code without servers."}],"steps":[{"title":"Create a log group and read logs","icon":"lucide-file-text","text":"Logs live in log groups. logs tail follows new lines like tail -f. Set a retention period so old logs do not cost money forever.","cmd":"aws logs create-log-group --log-group-name /hello/app\naws logs put-retention-policy --log-group-name /hello/app --retention-in-days 14\naws logs tail /hello/app --since 10m","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Read a metric","icon":"lucide-chart-line","text":"Metrics are numbers over time. This asks for the average CPU of one instance in five-minute steps.","cmd":"aws cloudwatch get-metric-statistics --namespace AWS/EC2 --metric-name CPUUtilization --dimensions Name=InstanceId,Value=i-0abc123def4567890 --start-time $(date -u -d '-1 hour' +%FT%TZ) --end-time $(date -u +%FT%TZ) --period 300 --statistics Average --query 'Datapoints[].Average'","out":"[2.31, 2.28, 5.9, 3.4]","outKind":"example","note":"","risk":false,"viz":""},{"title":"Create a topic and subscribe by e-mail","icon":"lucide-bell","text":"SNS delivers alerts. After subscribing you receive a confirmation e-mail that you must accept.","cmd":"TOPIC=$(aws sns create-topic --name hello-alerts --query TopicArn --output text)\naws sns subscribe --topic-arn $TOPIC --protocol email --notification-endpoint you@example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Alarm on high CPU","icon":"lucide-zap","text":"The alarm checks the metric every five minutes and sends a message when it stays above 80 percent for two periods.","cmd":"aws cloudwatch put-metric-alarm --alarm-name hello-cpu-high --namespace AWS/EC2 --metric-name CPUUtilization --dimensions Name=InstanceId,Value=i-0abc123def4567890 --statistic Average --period 300 --evaluation-periods 2 --threshold 80 --comparison-operator GreaterThanThreshold --alarm-actions $TOPIC\naws cloudwatch describe-alarms --alarm-names hello-cpu-high --query 'MetricAlarms[0].StateValue' --output text","out":"OK","outKind":"example","note":"","risk":false,"viz":""},{"title":"Budget with an alert","icon":"lucide-timer","text":"A budget watches your spending. This one e-mails you when the actual cost passes 80 percent of 10 US dollars a month.","cmd":"ACCOUNT=$(aws sts get-caller-identity --query Account --output text)\naws budgets create-budget --account-id $ACCOUNT --budget '{\"BudgetName\":\"hello-monthly\",\"BudgetLimit\":{\"Amount\":\"10\",\"Unit\":\"USD\"},\"TimeUnit\":\"MONTHLY\",\"BudgetType\":\"COST\"}' --notifications-with-subscribers '[{\"Notification\":{\"NotificationType\":\"ACTUAL\",\"ComparisonOperator\":\"GREATER_THAN\",\"Threshold\":80,\"ThresholdType\":\"PERCENTAGE\"},\"Subscribers\":[{\"SubscriptionType\":\"EMAIL\",\"Address\":\"you@example.com\"}]}]'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"See what you spent","icon":"lucide-table","text":"Cost Explorer shows spending by service. Tag every resource (Project, Owner) so you can also group by tag.","cmd":"aws ce get-cost-and-usage --time-period Start=$(date -u +%Y-%m-01),End=$(date -u +%F) --granularity MONTHLY --metrics UnblendedCost --group-by Type=DIMENSION,Key=SERVICE --query 'ResultsByTime[0].Groups[].[Keys[0],Metrics.UnblendedCost.Amount]' --output text","out":"Amazon Elastic Compute Cloud - Compute\\t1.84\nAmazon Simple Storage Service\\t0.02","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":9,"prev":{"id":"aws-route53-acm","title":"Module 7: Your own domain name with HTTPS"},"next":{"id":"aws-lambda-hello","title":"Module 9: A serverless function: Lambda and a function URL"}}},{"id":"aws-lambda-hello","title":"Module 9: A serverless function: Lambda and a function URL","level":2,"icon":"lucide-zap","summary":"Write a Python function, create the role it needs, deploy it, call it, publish a URL and read its logs.","qna":[{"q":"In which situation do we use this?","a":"Small event-driven jobs or APIs where you do not want to manage a server."},{"q":"Why is a public function URL risky?","a":"Anyone can call it. Use AWS_IAM authentication for anything that is not a public demo."},{"q":"What comes next?","a":"Describe all of this as code in the Terraform topic."}],"steps":[{"title":"Write the function","icon":"lucide-code","text":"Lambda runs your code on demand and charges per millisecond. The handler receives an event and returns a result.","cmd":"mkdir -p ~/lambda-hello && cd ~/lambda-hello\ncat > lambda_function.py <<'EOF'\nimport json\n\ndef lambda_handler(event, context):\n    name = (event or {}).get(\"name\", \"Srinivas\")\n    return {\"statusCode\": 200, \"body\": json.dumps({\"message\": f\"Hello {name}\"})}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create an execution role","icon":"lucide-users","text":"The function needs a role so it can write its logs. The managed policy AWSLambdaBasicExecutionRole grants exactly that.","cmd":"cat > trust.json <<'EOF'\n{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Principal\":{\"Service\":\"lambda.amazonaws.com\"},\"Action\":\"sts:AssumeRole\"}]}\nEOF\nROLE=$(aws iam create-role --role-name hello-lambda-role --assume-role-policy-document file://trust.json --query Role.Arn --output text)\naws iam attach-role-policy --role-name hello-lambda-role --policy-arn arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Package and deploy","icon":"lucide-package","text":"Zip the file and create the function. A new role can take a few seconds to become usable.","cmd":"zip function.zip lambda_function.py\nsleep 10\naws lambda create-function --function-name hello --runtime python3.12 --role $ROLE --handler lambda_function.lambda_handler --zip-file fileb://function.zip --query FunctionArn --output text","out":"arn:aws:lambda:ap-south-1:123456789012:function:hello","outKind":"example","note":"","risk":false,"viz":""},{"title":"Invoke it","icon":"lucide-play","text":"invoke runs the function once. The reply is written to out.json. --cli-binary-format lets you pass plain JSON.","cmd":"aws lambda invoke --function-name hello --payload '{\"name\":\"Srinivas\"}' --cli-binary-format raw-in-base64-out out.json\ncat out.json","out":"{\"statusCode\": 200, \"body\": \"{\\\\\"message\\\\\": \\\\\"Hello Srinivas\\\\\"}\"}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Publish an HTTPS address","icon":"lucide-globe","text":"A function URL gives the function a public address. NONE means anyone can call it, which is right for a demo but wrong for private data; use AWS_IAM for that.","cmd":"aws lambda create-function-url-config --function-name hello --auth-type NONE --query FunctionUrl --output text\naws lambda add-permission --function-name hello --statement-id public-url --action lambda:InvokeFunctionUrl --principal \"*\" --function-url-auth-type NONE\ncurl -s \"https://abc123xyz.lambda-url.ap-south-1.on.aws/?name=Srinivas\"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Logs and clean-up","icon":"lucide-eraser","text":"Every invocation writes to the log group /aws/lambda/hello. Delete the function and role when you are done.","cmd":"aws logs tail /aws/lambda/hello --since 5m\naws lambda delete-function --function-name hello\naws iam detach-role-policy --role-name hello-lambda-role --policy-arn arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole\naws iam delete-role --role-name hello-lambda-role","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":9,"of":9,"prev":{"id":"aws-monitor-cost","title":"Module 8: Logs, alarms and cost control"},"next":null}}]},{"id":"terraform","name":"Terraform: infrastructure as code","color":"#7B42F4","tagline":"Describe infrastructure in files, preview it, create it, change it and delete it. Modules 1 to 3 use the built-in provider, so every command runs on your laptop with no cloud account. I ran module 1 and the console expressions with Terraform 1.9.8; the rest of the output is written by hand. Modules 4 to 8 build a VPC and a web server on AWS. The code was checked with terraform fmt and a reference check, but not against the AWS provider schema, so run terraform validate yourself. Their plan and apply output is an example.","icon":"iac-terraform","workflows":[{"id":"tf-first-config","title":"Module 1: Your first Terraform config: Hello Srinivas","level":1,"icon":"iac-terraform","summary":"Write main.tf, then run init, validate, apply, output and destroy and see what each command does.","qna":[{"q":"In which situation do we use this?","a":"Infrastructure should be written down, reviewed and repeatable instead of clicked together."},{"q":"What do init, plan and apply do?","a":"init prepares providers, plan previews the changes, apply makes them real."},{"q":"What comes next?","a":"Module 2 makes the configuration flexible."}],"steps":[{"title":"Check the install","icon":"lucide-terminal","text":"Terraform is one program. It reads .tf files, compares them with what exists, and makes the difference real.","cmd":"terraform version\nmkdir -p ~/tf-hello && cd ~/tf-hello","out":"Terraform v1.9.8\non darwin_arm64","outKind":"example","note":"","risk":false,"viz":""},{"title":"Write main.tf","icon":"lucide-pencil","text":"A resource block describes one thing to create. terraform_data is built into Terraform, so nothing is downloaded. An output prints a value after apply.","cmd":"cat > main.tf <<'EOF'\nvariable \"who\" {\n  type    = string\n  default = \"Srinivas\"\n}\n\nresource \"terraform_data\" \"greeting\" {\n  input = \"Hello ${var.who}\"\n}\n\noutput \"message\" {\n  value = terraform_data.greeting.output\n}\nEOF\ncat main.tf","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"terraform init: prepare the folder","icon":"lucide-settings","text":"init downloads the providers named in the config and sets up the backend. Run it once per folder and again after adding a provider or module.","cmd":"terraform init","out":"Initializing the backend...\nInitializing provider plugins...\n- terraform.io/builtin/terraform is built in to Terraform\n\nTerraform has been successfully initialized!","outKind":"example","note":"","risk":false,"viz":""},{"title":"fmt and validate: tidy and check","icon":"lucide-check","text":"fmt rewrites files into the standard style and validate checks syntax and references. Neither touches real infrastructure.","cmd":"terraform fmt -check && echo \"formatted\"\nterraform validate","out":"formatted\nSuccess! The configuration is valid.","outKind":"example","note":"","risk":false,"viz":""},{"title":"terraform plan then apply","icon":"lucide-rocket","text":"plan is a preview. apply shows the same preview and, after you type yes (or use -auto-approve), creates the resource. The + sign means create. \"known after apply\" means the value does not exist yet.","cmd":"terraform apply -auto-approve","out":"Terraform will perform the following actions:\n\n  # terraform_data.greeting will be created\n  + resource \"terraform_data\" \"greeting\" {\n      + id     = (known after apply)\n      + input  = \"Hello Srinivas\"\n      + output = (known after apply)\n    }\n\nPlan: 1 to add, 0 to change, 0 to destroy.\n\nChanges to Outputs:\n  + message = (known after apply)\nterraform_data.greeting: Creating...\nterraform_data.greeting: Creation complete after 0s [id=b4160acb-e877-22ae-a454-0ddfca1eebf6]","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the result","icon":"lucide-eye","text":"output prints values; -raw prints one value with no quotes, which is handy in scripts. The files created are main.tf, the state file and a lock file.","cmd":"terraform output\nterraform output -raw message\nls -a","out":"message = \"Hello Srinivas\"\nHello Srinivas\n.\n..\n.terraform\n.terraform.lock.hcl\nmain.tf\nterraform.tfstate","outKind":"example","note":"","risk":false,"viz":""},{"title":"terraform destroy","icon":"lucide-eraser","text":"destroy removes everything this configuration created. The - sign means delete. Your .tf files stay, so apply can recreate it.","cmd":"terraform destroy -auto-approve","out":"terraform_data.greeting: Destroying... [id=b4160acb-e877-22ae-a454-0ddfca1eebf6]\nterraform_data.greeting: Destruction complete after 0s\n\nDestroy complete! Resources: 1 destroyed.","outKind":"example","note":"","risk":true,"viz":""}],"nav":{"pos":1,"of":8,"prev":null,"next":{"id":"tf-variables-functions","title":"Module 2: Variables, locals, functions and loops"}}},{"id":"tf-variables-functions","title":"Module 2: Variables, locals, functions and loops","level":2,"icon":"lucide-sliders-horizontal","summary":"Make a config flexible: typed variables, a tfvars file, locals, built-in functions, count and for_each.","qna":[{"q":"In which situation do we use this?","a":"The same code must serve dev and prod with different sizes, names and ranges."},{"q":"count or for_each?","a":"Prefer for_each. Removing one item from a count list renumbers the rest and can replace resources."},{"q":"What comes next?","a":"Module 3 explains the state file."}],"steps":[{"title":"Typed variables with checks","icon":"lucide-sliders-horizontal","text":"A variable has a type, a default and optionally a validation rule. Invalid input stops before anything is created.","cmd":"mkdir -p ~/tf-vars && cd ~/tf-vars\ncat > variables.tf <<'EOF'\nvariable \"env\" {\n  type    = string\n  default = \"dev\"\n  validation {\n    condition     = contains([\"dev\", \"prod\"], var.env)\n    error_message = \"env must be dev or prod.\"\n  }\n}\n\nvariable \"names\" {\n  type    = list(string)\n  default = [\"srinivas\", \"india\"]\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Locals and expressions","icon":"lucide-code","text":"A local is a named expression you reuse. Terraform has no assignment: values are computed from other values.","cmd":"cat > main.tf <<'EOF'\nlocals {\n  prefix = \"hello-${var.env}\"\n  upper  = [for n in var.names : upper(n)]\n}\n\nresource \"terraform_data\" \"item\" {\n  for_each = toset(var.names)\n  input    = \"${local.prefix}-${each.key}\"\n}\n\noutput \"upper\" {\n  value = local.upper\n}\n\noutput \"items\" {\n  value = { for k, v in terraform_data.item : k => v.output }\n}\nEOF\nterraform init -no-color | tail -n 1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Try functions in the console","icon":"lucide-search","text":"terraform console evaluates expressions. cidrsubnet is the one you will use most for network design: it cuts a smaller block out of a larger one.","cmd":"echo 'upper(\"hello\")' | terraform console\necho 'cidrsubnet(\"10.0.0.0/16\", 8, 10)' | terraform console\necho 'cidrsubnet(\"10.0.0.0/16\", 8, 1)' | terraform console\necho 'format(\"%s-%s\", \"hello\", \"srinivas\")' | terraform console\necho 'cidrhost(\"10.0.0.0/24\", 5)' | terraform console","out":"\"HELLO\"\n\"10.0.10.0/24\"\n\"10.0.1.0/24\"\n\"hello-srinivas\"\n\"10.0.0.5\"","outKind":"example","note":"","risk":false,"viz":""},{"title":"Override a variable","icon":"lucide-pencil","text":"Three ways, in order of strength: -var on the command line, a terraform.tfvars file, and the default. An invalid value is rejected at once.","cmd":"echo 'env = \"prod\"' > terraform.tfvars\nterraform apply -auto-approve | tail -n 8\nterraform apply -var 'env=staging' -auto-approve","out":"Error: Invalid value for variable\n\n  on variables.tf line 1:\n   1: variable \"env\" {\n     var.env is \"staging\"\n\nenv must be dev or prod.","outKind":"example","note":"","risk":false,"viz":""},{"title":"count and for_each","icon":"lucide-layers","text":"count makes numbered copies (a list), for_each makes one per key (a map or set). Prefer for_each: removing the middle item does not renumber the rest.","cmd":"terraform state list\nterraform output items","out":"terraform_data.item[\"india\"]\nterraform_data.item[\"srinivas\"]\n{\n  \"india\" = \"hello-prod-india\"\n  \"srinivas\" = \"hello-prod-srinivas\"\n}","outKind":"example","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Remove everything this folder created.","cmd":"terraform destroy -auto-approve | tail -n 2","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":8,"prev":{"id":"tf-first-config","title":"Module 1: Your first Terraform config: Hello Srinivas"},"next":{"id":"tf-state-lifecycle","title":"Module 3: State, plan, change and destroy"}}},{"id":"tf-state-lifecycle","title":"Module 3: State, plan, change and destroy","level":2,"icon":"lucide-database","summary":"Understand the state file: see a change as a plan, save a plan, inspect state and recover from drift.","qna":[{"q":"In which situation do we use this?","a":"You must understand what Terraform believes exists, or why a plan shows an unexpected change."},{"q":"Why is the state file sensitive?","a":"It can hold secrets and is the only link between your code and real resources."},{"q":"What comes next?","a":"Module 4 builds a real network."}],"steps":[{"title":"Create something to track","icon":"lucide-rocket","text":"Apply once so there is state to look at. The state file maps your config to real objects, and without it Terraform cannot know what it owns.","cmd":"mkdir -p ~/tf-state && cd ~/tf-state\ncat > main.tf <<'EOF'\nvariable \"who\" {\n  type    = string\n  default = \"Srinivas\"\n}\n\nresource \"terraform_data\" \"greeting\" {\n  input = \"Hello ${var.who}\"\n}\nEOF\nterraform init -no-color | tail -n 1\nterraform apply -auto-approve | tail -n 2","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Look at the state","icon":"lucide-database","text":"state list shows every resource Terraform manages and show prints the saved attributes. The file is JSON, but never edit it by hand.","cmd":"terraform state list\nterraform show\nhead -c 220 terraform.tfstate","out":"terraform_data.greeting\n# terraform_data.greeting:\nresource \"terraform_data\" \"greeting\" {\n    id     = \"b4160acb-e877-22ae-a454-0ddfca1eebf6\"\n    input  = \"Hello Srinivas\"\n    output = \"Hello Srinivas\"\n}","outKind":"example","note":"State can contain secrets. Keep it out of Git and store it in a protected remote backend (module 7).","risk":false,"viz":""},{"title":"Change the config and read the plan","icon":"lucide-arrow-left-right","text":"The ~ sign means change in place. The arrow shows the old and new value. -> forces replacement is shown when a change cannot be done in place.","cmd":"terraform plan -var 'who=India'","out":"Terraform will perform the following actions:\n\n  # terraform_data.greeting will be updated in-place\n  ~ resource \"terraform_data\" \"greeting\" {\n        id     = \"b4160acb-e877-22ae-a454-0ddfca1eebf6\"\n      ~ input  = \"Hello Srinivas\" -> \"Hello India\"\n      ~ output = \"Hello Srinivas\" -> (known after apply)\n    }\n\nPlan: 0 to add, 1 to change, 0 to destroy.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save a plan and apply exactly that","icon":"lucide-save","text":"plan -out saves the decision. apply with that file does exactly what was reviewed, which is how pipelines separate review from execution.","cmd":"terraform plan -var 'who=India' -out=tfplan\nterraform show tfplan | tail -n 4\nterraform apply tfplan","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Replace on purpose","icon":"lucide-refresh-cw","text":"-replace forces a resource to be destroyed and created again, for example to rebuild a broken server.","cmd":"terraform apply -replace=terraform_data.greeting -auto-approve | tail -n 3","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Remove from state without deleting","icon":"lucide-wrench","text":"state rm makes Terraform forget a resource. The real object stays. This is useful when you move ownership to another configuration.","cmd":"terraform state rm terraform_data.greeting\nterraform state list","out":"","outKind":"","note":"Afterwards plan would try to create it again. Use import to bring an existing object back under control.","risk":true,"viz":""}],"nav":{"pos":3,"of":8,"prev":{"id":"tf-variables-functions","title":"Module 2: Variables, locals, functions and loops"},"next":{"id":"tf-aws-vpc","title":"Module 4: Build a basic VPC with public and private subnets"}}},{"id":"tf-aws-vpc","title":"Module 4: Build a basic VPC with public and private subnets","level":3,"icon":"lucide-cloud","summary":"Describe a network: VPC, two public and two private subnets, an internet gateway and route tables. Optional NAT stays off to avoid cost.","qna":[{"q":"In which situation do we use this?","a":"Every project that needs its own network with public and private tiers across two zones."},{"q":"Why is NAT behind a variable?","a":"A NAT gateway bills every hour. Turn it on only when private servers truly need internet access."},{"q":"What comes next?","a":"Module 5 deploys an application into this VPC."}],"steps":[{"title":"The picture before the code","icon":"lucide-network","text":"A VPC is your private network. Public subnets route to an internet gateway. Private subnets have no route out unless you add a NAT. Two zones give resilience.","cmd":"mkdir -p ~/tf-vpc && cd ~/tf-vpc","out":"","outKind":"","note":"","risk":false,"viz":"Internet → Internet gateway: public traffic\nInternet gateway → Public route table: 0.0.0.0/0\nPublic route table → Public subnets: associated\nPrivate route table → Private subnets: local only"},{"title":"versions.tf and variables.tf","icon":"lucide-file-text","text":"Pin the AWS provider so a new major version cannot surprise you. Variables hold the choices: region, name, address range, zones and whether to pay for a NAT gateway.","cmd":"cat > versions.tf <<'EOF'\nterraform {\n  required_version = \">= 1.6\"\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 5.0\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\nEOF\ncat > variables.tf <<'EOF'\nvariable \"region\" {\n  type    = string\n  default = \"ap-south-1\"\n}\n\nvariable \"name\" {\n  type    = string\n  default = \"hello-srinivas\"\n}\n\nvariable \"vpc_cidr\" {\n  type    = string\n  default = \"10.0.0.0/16\"\n}\n\nvariable \"azs\" {\n  type    = list(string)\n  default = [\"ap-south-1a\", \"ap-south-1b\"]\n}\n\nvariable \"enable_nat\" {\n  description = \"A NAT gateway costs money every hour. Keep false for the lesson.\"\n  type        = bool\n  default     = false\n}\n\nvariable \"instance_type\" {\n  type    = string\n  default = \"t3.micro\"\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The VPC, subnets and gateway","icon":"lucide-cloud","text":"cidrsubnet cuts 10.0.0.0/16 into /24 blocks: public subnets get 10.0.0.0 and 10.0.1.0, private ones 10.0.10.0 and 10.0.11.0. count creates one subnet per zone.","cmd":"cat > network.tf <<'EOF'\nresource \"aws_vpc\" \"main\" {\n  cidr_block           = var.vpc_cidr\n  enable_dns_hostnames = true\n  tags                 = { Name = \"${var.name}-vpc\" }\n}\n\nresource \"aws_internet_gateway\" \"igw\" {\n  vpc_id = aws_vpc.main.id\n  tags   = { Name = \"${var.name}-igw\" }\n}\n\nresource \"aws_subnet\" \"public\" {\n  count                   = length(var.azs)\n  vpc_id                  = aws_vpc.main.id\n  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)\n  availability_zone       = var.azs[count.index]\n  map_public_ip_on_launch = true\n  tags                    = { Name = \"${var.name}-public-${count.index + 1}\" }\n}\n\nresource \"aws_subnet\" \"private\" {\n  count             = length(var.azs)\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)\n  availability_zone = var.azs[count.index]\n  tags              = { Name = \"${var.name}-private-${count.index + 1}\" }\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Route tables","icon":"lucide-signpost","text":"The public route table sends 0.0.0.0/0 (everything else) to the internet gateway. Each subnet must be associated with a table, otherwise it uses the VPC default.","cmd":"cat >> network.tf <<'EOF'\n\nresource \"aws_route_table\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  route {\n    cidr_block = \"0.0.0.0/0\"\n    gateway_id = aws_internet_gateway.igw.id\n  }\n  tags = { Name = \"${var.name}-public-rt\" }\n}\n\nresource \"aws_route_table_association\" \"public\" {\n  count          = length(var.azs)\n  subnet_id      = aws_subnet.public[count.index].id\n  route_table_id = aws_route_table.public.id\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Optional NAT for the private subnets","icon":"lucide-arrow-left-right","text":"A NAT gateway lets private servers reach the internet for updates without being reachable from it. It bills by the hour, so it is behind a switch. dynamic adds the route only when the switch is on.","cmd":"cat >> network.tf <<'EOF'\n\nresource \"aws_eip\" \"nat\" {\n  count  = var.enable_nat ? 1 : 0\n  domain = \"vpc\"\n}\n\nresource \"aws_nat_gateway\" \"nat\" {\n  count         = var.enable_nat ? 1 : 0\n  allocation_id = aws_eip.nat[0].id\n  subnet_id     = aws_subnet.public[0].id\n  tags          = { Name = \"${var.name}-nat\" }\n  depends_on    = [aws_internet_gateway.igw]\n}\n\nresource \"aws_route_table\" \"private\" {\n  vpc_id = aws_vpc.main.id\n  dynamic \"route\" {\n    for_each = var.enable_nat ? [1] : []\n    content {\n      cidr_block     = \"0.0.0.0/0\"\n      nat_gateway_id = aws_nat_gateway.nat[0].id\n    }\n  }\n  tags = { Name = \"${var.name}-private-rt\" }\n}\n\nresource \"aws_route_table_association\" \"private\" {\n  count          = length(var.azs)\n  subnet_id      = aws_subnet.private[count.index].id\n  route_table_id = aws_route_table.private.id\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Outputs, init, validate and plan","icon":"lucide-rocket","text":"Outputs expose IDs for other modules and for you. init downloads the AWS provider, validate checks the code and plan previews 12 resources. Nothing is created yet.","cmd":"cat > outputs.tf <<'EOF'\noutput \"vpc_id\" {\n  value = aws_vpc.main.id\n}\n\noutput \"public_subnet_ids\" {\n  value = aws_subnet.public[*].id\n}\n\noutput \"private_subnet_ids\" {\n  value = aws_subnet.private[*].id\n}\nEOF\nterraform init\nterraform fmt -check && terraform validate\nterraform plan -out=tfplan","out":"Plan: 12 to add, 0 to change, 0 to destroy.\n\nChanges to Outputs:\n  + private_subnet_ids = [(known after apply), (known after apply)]\n  + public_subnet_ids  = [(known after apply), (known after apply)]\n  + vpc_id             = (known after apply)","outKind":"example","note":"","risk":false,"viz":""},{"title":"Apply and verify with the AWS CLI","icon":"lucide-check","text":"apply builds the network in about a minute. Confirm with the CLI that the subnets and routes are what you expected.","cmd":"terraform apply tfplan\naws ec2 describe-subnets --filters Name=vpc-id,Values=$(terraform output -raw vpc_id) --query 'Subnets[].[Tags[0].Value,CidrBlock,AvailabilityZone]' --output table","out":"---------------------------------------------------------\n|                    DescribeSubnets                    |\n+--------------------------+--------------+-------------+\n|  hello-srinivas-public-1 |  10.0.0.0/24 | ap-south-1a |\n|  hello-srinivas-public-2 |  10.0.1.0/24 | ap-south-1b |\n|  hello-srinivas-private-1|  10.0.10.0/24| ap-south-1a |\n|  hello-srinivas-private-2|  10.0.11.0/24| ap-south-1b |\n+--------------------------+--------------+-------------+","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":8,"prev":{"id":"tf-state-lifecycle","title":"Module 3: State, plan, change and destroy"},"next":{"id":"tf-app-deploy","title":"Module 5: Deploy a web app into the VPC"}}},{"id":"tf-app-deploy","title":"Module 5: Deploy a web app into the VPC","level":3,"icon":"lucide-server","summary":"Add a security group and an EC2 server that installs nginx and serves Hello Srinivas, then test it in the browser.","qna":[{"q":"In which situation do we use this?","a":"You want a server, its firewall and its start-up script created together and removed together."},{"q":"Why does a user_data change replace the server?","a":"It only runs at first boot, so Terraform rebuilds the instance. The plan shows forces replacement."},{"q":"What comes next?","a":"Module 6 turns the network into a reusable module."}],"steps":[{"title":"Find the newest Linux image automatically","icon":"lucide-search","text":"A data source reads existing information. This one asks AWS for the current Amazon Linux 2023 image, so you never paste an out-of-date AMI ID.","cmd":"cd ~/tf-vpc\ncat > app.tf <<'EOF'\ndata \"aws_ssm_parameter\" \"al2023\" {\n  name = \"/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64\"\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"A security group as the firewall","icon":"lucide-shield-ban","text":"Allow HTTP in from anywhere and everything out. Anything not allowed is blocked.","cmd":"cat >> app.tf <<'EOF'\n\nresource \"aws_security_group\" \"web\" {\n  name        = \"${var.name}-web\"\n  description = \"Allow HTTP from anywhere\"\n  vpc_id      = aws_vpc.main.id\n\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The server and its start-up script","icon":"lucide-server","text":"user_data runs once on first boot. It installs nginx and writes the page. The server is placed in the first public subnet and uses the security group.","cmd":"cat >> app.tf <<'EOF'\n\nresource \"aws_instance\" \"web\" {\n  ami                    = data.aws_ssm_parameter.al2023.value\n  instance_type          = var.instance_type\n  subnet_id              = aws_subnet.public[0].id\n  vpc_security_group_ids = [aws_security_group.web.id]\n\n  user_data = <<-EOT\n    #!/bin/bash\n    dnf install -y nginx\n    echo \"Hello Srinivas from Terraform\" > /usr/share/nginx/html/index.html\n    systemctl enable --now nginx\n  EOT\n\n  tags = { Name = \"${var.name}-web\" }\n}\nEOF\ncat >> outputs.tf <<'EOF'\n\noutput \"web_url\" {\n  value = \"http://${aws_instance.web.public_ip}\"\n}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Plan and apply","icon":"lucide-rocket","text":"The plan now shows 14 resources: the network from module 4 plus the group and the server. Dependencies are worked out from the references, so the server waits for the subnet.","cmd":"terraform validate\nterraform plan -out=tfplan\nterraform apply tfplan","out":"Plan: 14 to add, 0 to change, 0 to destroy.\n\naws_vpc.main: Creating...\naws_instance.web: Creation complete after 17s [id=i-0abc123def4567890]\n\nApply complete! Resources: 14 added, 0 changed, 0 destroyed.\n\nOutputs:\nweb_url = \"http://13.233.10.45\"","outKind":"example","note":"","risk":false,"viz":""},{"title":"Test it","icon":"lucide-check","text":"Wait about a minute for the start-up script, then call the address from the output.","cmd":"curl $(terraform output -raw web_url)\nterraform state list | head -n 8","out":"Hello Srinivas from Terraform\ndata.aws_ssm_parameter.al2023\naws_instance.web\naws_internet_gateway.igw\naws_route_table.private\naws_route_table.public","outKind":"example","note":"","risk":false,"viz":""},{"title":"Change the page and see an in-place or replace plan","icon":"lucide-arrow-left-right","text":"Changing user_data replaces the server because it only runs at first boot. The plan says \"forces replacement\" in red, a clear warning before you apply.","cmd":"sed -i.bak 's/from Terraform/from Terraform v2/' app.tf\nterraform plan | grep -E \"forces replacement|Plan:\"","out":"# aws_instance.web must be replaced\n      ~ user_data = \"...\" -> (known after apply) # forces replacement\nPlan: 1 to add, 0 to change, 1 to destroy.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Destroy it all","icon":"lucide-eraser","text":"Destroy in the right order automatically: server, groups, subnets, gateway, then the VPC. Confirm nothing is left.","cmd":"terraform destroy -auto-approve\naws ec2 describe-vpcs --filters Name=tag:Name,Values=hello-srinivas-vpc --query 'Vpcs[]' --output text","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":5,"of":8,"prev":{"id":"tf-aws-vpc","title":"Module 4: Build a basic VPC with public and private subnets"},"next":{"id":"tf-modules-envs","title":"Module 6: Reuse code with modules and environments"}}},{"id":"tf-modules-envs","title":"Module 6: Reuse code with modules and environments","level":3,"icon":"lucide-package","summary":"Move the network into a module, call it twice with different settings, and use workspaces or folders for dev and prod.","qna":[{"q":"In which situation do we use this?","a":"The same design is needed in several environments."},{"q":"Why separate folders and state per environment?","a":"A mistake in dev cannot touch prod, and each plan stays small and easy to review."},{"q":"What comes next?","a":"Module 7 moves the state to a safe shared place."}],"steps":[{"title":"Why modules","icon":"lucide-package","text":"A module is a folder of .tf files with inputs (variables) and outputs. You write the VPC once and use it for dev, test and prod.","cmd":"mkdir -p ~/tf-modules/modules/vpc ~/tf-modules/envs/dev ~/tf-modules/envs/prod\ncd ~/tf-modules && find . -type d | sort","out":".\n./envs\n./envs/dev\n./envs/prod\n./modules\n./modules/vpc","outKind":"example","note":"","risk":false,"viz":""},{"title":"Move the network code into the module","icon":"lucide-folder","text":"Copy network.tf into modules/vpc and keep only variables and outputs beside it. Everything that differs between environments becomes an input.","cmd":"cp ~/tf-vpc/network.tf modules/vpc/main.tf\nprintf 'variable \"name\" {\n  type = string\n}\n\nvariable \"vpc_cidr\" {\n  type = string\n}\n\nvariable \"azs\" {\n  type = list(string)\n}\n\nvariable \"enable_nat\" {\n  type    = bool\n  default = false\n}\n' > modules/vpc/variables.tf\nprintf 'output \"vpc_id\" {\n  value = aws_vpc.main.id\n}\n\noutput \"public_subnet_ids\" {\n  value = aws_subnet.public[*].id\n}\n' > modules/vpc/outputs.tf","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Call it from dev","icon":"lucide-link","text":"The module block gives the source folder and the inputs. Dev uses a small range and no NAT.","cmd":"printf 'terraform {\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 5.0\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = \"ap-south-1\"\n}\n\nmodule \"vpc\" {\n  source     = \"../../modules/vpc\"\n  name       = \"dev\"\n  vpc_cidr   = \"10.10.0.0/16\"\n  azs        = [\"ap-south-1a\", \"ap-south-1b\"]\n  enable_nat = false\n}\n\noutput \"vpc_id\" {\n  value = module.vpc.vpc_id\n}\n' > envs/dev/main.tf","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Call it from prod with different values","icon":"lucide-equal","text":"Same module, different inputs: another address range and a NAT gateway for private servers.","cmd":"sed -e 's/\"dev\"/\"prod\"/' -e 's#10.10.0.0/16#10.20.0.0/16#' -e 's/enable_nat = false/enable_nat = true/' envs/dev/main.tf > envs/prod/main.tf\ndiff envs/dev/main.tf envs/prod/main.tf","out":"15c15\n<   name       = \"dev\"\n---\n>   name       = \"prod\"\n16c16\n<   vpc_cidr   = \"10.10.0.0/16\"\n---\n>   vpc_cidr   = \"10.20.0.0/16\"\n18c18\n<   enable_nat = false\n---\n>   enable_nat = true","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run each environment separately","icon":"lucide-rocket","text":"Each folder has its own state, so a mistake in dev can never touch prod. Run init and plan inside the one you mean.","cmd":"cd envs/dev && terraform init && terraform plan\ncd ../prod && terraform init && terraform plan","out":"Plan: 12 to add, 0 to change, 0 to destroy.\nPlan: 14 to add, 0 to change, 0 to destroy.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Public modules and workspaces","icon":"lucide-globe","text":"The Terraform Registry has ready-made modules, for example terraform-aws-modules/vpc/aws. Workspaces give one folder several states, but separate folders are easier to review.","cmd":"terraform workspace list\nterraform workspace new staging\nterraform workspace show","out":"* default\nCreated and switched to workspace \"staging\"!\nstaging","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":8,"prev":{"id":"tf-app-deploy","title":"Module 5: Deploy a web app into the VPC"},"next":{"id":"tf-remote-state","title":"Module 7: Remote state in S3 with locking"}}},{"id":"tf-remote-state","title":"Module 7: Remote state in S3 with locking","level":3,"icon":"lucide-lock","summary":"Store state safely so a team can share it: create the bucket, configure the backend, migrate and test the lock.","qna":[{"q":"In which situation do we use this?","a":"More than one person or pipeline runs Terraform on the same infrastructure."},{"q":"What does locking prevent?","a":"Two applies writing the state at once, which can corrupt it."},{"q":"What comes next?","a":"Module 8 covers safe change practices."}],"steps":[{"title":"Why not keep state on a laptop","icon":"lucide-triangle-alert","text":"A local file is lost with the laptop, cannot be shared, and two people applying at once can corrupt it. A remote backend fixes all three.","cmd":"ls terraform.tfstate* 2>/dev/null","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create the state bucket","icon":"lucide-database","text":"Create it once, outside the project that uses it. Turn on versioning so any bad write can be undone, encryption, and block public access.","cmd":"BUCKET=tfstate-$(aws sts get-caller-identity --query Account --output text)-ap-south-1\naws s3api create-bucket --bucket $BUCKET --region ap-south-1 --create-bucket-configuration LocationConstraint=ap-south-1\naws s3api put-bucket-versioning --bucket $BUCKET --versioning-configuration Status=Enabled\naws s3api put-bucket-encryption --bucket $BUCKET --server-side-encryption-configuration '{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"AES256\"}}]}'\naws s3api put-public-access-block --bucket $BUCKET --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Configure the backend","icon":"lucide-file-text","text":"use_lockfile (Terraform 1.10 and newer) locks the state with a file in S3. Older versions use a DynamoDB table named in dynamodb_table. The key is the path of this project's state.","cmd":"cat > backend.tf <<'EOF'\nterraform {\n  backend \"s3\" {\n    bucket       = \"tfstate-123456789012-ap-south-1\"\n    key          = \"hello-srinivas/vpc/terraform.tfstate\"\n    region       = \"ap-south-1\"\n    encrypt      = true\n    use_lockfile = true\n  }\n}\nEOF","out":"","outKind":"","note":"Backend blocks cannot use variables. Put real values or pass them with terraform init -backend-config.","risk":false,"viz":""},{"title":"Migrate the existing state","icon":"lucide-upload","text":"init sees the new backend and asks to copy local state into it. Answer yes. Afterwards the local file is empty and S3 holds the state.","cmd":"terraform init -migrate-state -force-copy\naws s3 ls s3://$BUCKET/hello-srinivas/vpc/","out":"Successfully configured the backend \"s3\"!\n2026-11-04 11:02:44       9124 terraform.tfstate","outKind":"example","note":"","risk":false,"viz":""},{"title":"Prove the lock works","icon":"lucide-shield","text":"Start an apply in one terminal and a second in another. The second waits or fails with Error acquiring the state lock and shows who holds it.","cmd":"terraform plan -lock-timeout=5s","out":"Error: Error acquiring the state lock\n\nLock Info:\n  ID:        6f1f0c5e-9c1e-5f0a-8b3d-1f0c2e9a7b11\n  Operation: OperationTypeApply\n  Who:       srinivas@laptop","outKind":"example","note":"","risk":false,"viz":""},{"title":"Break a stuck lock safely","icon":"lucide-wrench","text":"If a run crashed, the lock may stay. Check that nobody is really running, then force-unlock with the ID from the error.","cmd":"terraform force-unlock 6f1f0c5e-9c1e-5f0a-8b3d-1f0c2e9a7b11","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":7,"of":8,"prev":{"id":"tf-modules-envs","title":"Module 6: Reuse code with modules and environments"},"next":{"id":"tf-safe-changes","title":"Module 8: Safe changes: import, moved, lifecycle and pipelines"}}},{"id":"tf-safe-changes","title":"Module 8: Safe changes: import, moved, lifecycle and pipelines","level":4,"icon":"lucide-shield","summary":"Bring existing resources under Terraform, rename without destroying, protect critical resources and run it in CI.","qna":[{"q":"In which situation do we use this?","a":"Adopting existing resources, renaming code, protecting data, or running Terraform in a pipeline."},{"q":"How do I avoid a surprise destroy?","a":"Read every destroy and replace line in the plan, use prevent_destroy on critical resources, and apply only a reviewed saved plan."},{"q":"What comes next?","a":"Combine Terraform with Jenkins from the CI/CD topic."}],"steps":[{"title":"Import something that already exists","icon":"lucide-download","text":"A resource created by hand can be adopted. Write the resource block, then import it by its real ID. Run plan afterwards and fix the config until it shows no changes.","cmd":"aws ec2 create-security-group --group-name manual-sg --description manual --vpc-id $(terraform output -raw vpc_id) --query GroupId --output text\nterraform import aws_security_group.manual sg-0abc123def456789\nterraform plan","out":"aws_security_group.manual: Import prepared!\nImport successful!\nNo changes. Your infrastructure matches the configuration.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Rename without destroying: moved blocks","icon":"lucide-repeat","text":"Renaming a resource in code looks like delete-and-create to Terraform. A moved block says it is the same object, so nothing is rebuilt.","cmd":"printf 'moved {\n  from = aws_instance.web\n  to   = aws_instance.app\n}\n' > moved.tf\nterraform plan | grep -E \"has moved|Plan:\"","out":"# aws_instance.web has moved to aws_instance.app\nPlan: 0 to add, 0 to change, 0 to destroy.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Protect critical resources","icon":"lucide-lock","text":"prevent_destroy makes any plan that would delete the resource fail. ignore_changes stops Terraform fighting changes made elsewhere, such as autoscaling.","cmd":"printf 'resource \"aws_s3_bucket\" \"data\" {\n  bucket = \"hello-srinivas-data-123456789012\"\n  lifecycle {\n    prevent_destroy = true\n  }\n}\n' > protect.tf\nterraform destroy","out":"Error: Instance cannot be destroyed\n\n  Resource aws_s3_bucket.data has lifecycle.prevent_destroy set, but the plan calls for it to be destroyed.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Detect drift","icon":"lucide-eye","text":"Drift means reality no longer matches the state, usually because someone changed it in the console. plan -refresh-only shows it without changing anything.","cmd":"terraform plan -refresh-only","out":"Note: Objects have changed outside of Terraform\n  ~ aws_security_group.web has changed","outKind":"example","note":"","risk":false,"viz":""},{"title":"Check the code in a pipeline","icon":"lucide-rocket","text":"Run fmt, validate, a security scan and a saved plan on every pull request. Apply the saved plan only after approval, from the main branch.","cmd":"terraform fmt -check -recursive\nterraform validate\ntflint\ntrivy config .\nterraform plan -out=tfplan -input=false","out":"","outKind":"","note":"tflint and trivy are separate tools. Checkov does a similar job.","risk":false,"viz":""},{"title":"Delete safely","icon":"lucide-eraser","text":"Remove protection first, then destroy. Always read the destroy plan out loud with someone else before you answer yes.","cmd":"terraform plan -destroy | tail -n 3\nterraform destroy","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":8,"of":8,"prev":{"id":"tf-remote-state","title":"Module 7: Remote state in S3 with locking"},"next":null}}]},{"id":"ansible","name":"Ansible","color":"#EE0000","tagline":"Agentless automation: inventory, playbooks, roles, templates, vault and real projects.","icon":"cfg-ansible","workflows":[{"id":"ans-what-is","title":"What is Ansible? Start here","level":1,"icon":"lucide-settings","summary":"Eight plain steps: the problem, the agentless idea, inventory, playbook, modules, idempotence and where Ansible fits.","qna":[{"q":"In which situation do we use this?","a":"You manage more than a few servers and repeat the same setup by hand. Ansible describes the result once and applies it everywhere."},{"q":"Why Ansible and not a shell script?","a":"Modules check state first, so rerunning is safe, and there is no agent to install on the managed hosts."},{"q":"What comes next?","a":"ans-architecture to see how the control node reaches the hosts."}],"steps":[{"title":"The problem: the same job on many servers","icon":"lucide-users","text":"Imagine installing a web server on ten machines. Typing the same commands ten times is slow, and the machines slowly drift apart because a step was missed on number seven. You need a way to describe the result you want once and apply it everywhere.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Ansible in one sentence","icon":"lucide-settings","text":"Ansible is an automation tool. You write down the state you want (a package installed, a file in place, a service running) and Ansible makes each machine match it. It is free, open source and uses plain text files that you can keep in Git.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Agentless: nothing to install on the servers","icon":"lucide-network","text":"There is no agent or background program on the managed servers. Your own computer, the control node, connects over SSH, runs small tasks and disconnects. The servers only need SSH access and Python.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Control node → web1: SSH, run task\nControl node → web2: SSH, run task\nweb1 → Control node: result\nweb2 → Control node: result"},{"title":"Inventory: which machines","icon":"lucide-table","text":"The inventory is a list of your servers, organised into groups such as web and db. It answers the question \"where?\".","cmd":"cat inventory.ini","out":"[web]\nweb1.example.com\nweb2.example.com\n\n[db]\ndb1.example.com","outKind":"example","note":"","risk":false,"viz":""},{"title":"Playbook: what to do","icon":"lucide-file-text","text":"A playbook is a YAML file that lists tasks for a group of hosts. It answers the question \"what?\". Read it top to bottom like a checklist.","cmd":"cat site.yml","out":"- name: Install and start Apache\n  hosts: web\n  become: true\n  tasks:\n    - name: Install the package\n      ansible.builtin.package:\n        name: apache2\n        state: present","outKind":"example","note":"","risk":false,"viz":""},{"title":"Modules: the building blocks","icon":"lucide-package","text":"Each task calls a module, a small tested program such as package, copy, template, service or user. Modules are written to be safe to repeat. You rarely write shell commands yourself.","cmd":"ansible-doc -l | head -n 5\nansible-doc ansible.builtin.copy | head -n 20","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Idempotent: safe to run again","icon":"lucide-refresh-cw","text":"Idempotent means running it twice gives the same result as running it once. Ansible checks first and only changes what is different. The summary shows ok for things already correct and changed for things it fixed.","cmd":"","out":"PLAY RECAP *********************************************\nweb1.example.com : ok=3 changed=0 unreachable=0 failed=0","outKind":"example","note":"The first run usually shows changed. A second run showing changed=0 is the proof that the system matches your description.","risk":false,"viz":""},{"title":"Where Ansible fits","icon":"lucide-layers","text":"Terraform creates infrastructure (servers, networks, load balancers). Ansible configures what runs on it (packages, files, users, services). Docker packages an application with its dependencies. Teams often use the three together: Terraform builds the server, Ansible prepares it and Docker runs the app.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":25,"prev":null,"next":{"id":"ans-architecture","title":"Ansible architecture: control node to managed nodes"}}},{"id":"ans-architecture","title":"Ansible architecture: control node to managed nodes","level":1,"icon":"lucide-network","summary":"Follow one command through the control node, inventory, modules, SSH and the managed nodes.","qna":[{"q":"In which situation do we use this?","a":"Before you design a setup: where Ansible runs, how it connects, and what it needs on the target."},{"q":"What does a managed node need?","a":"SSH access and Python. Nothing else is installed permanently."},{"q":"What comes next?","a":"ans-install-first-ping to prove the connection."}],"steps":[{"title":"Control node","icon":"lucide-laptop","text":"The control node is the machine where Ansible is installed and where you run commands. It can be a laptop or a small jump server. It holds your inventory, playbooks and roles. Managed nodes never need Ansible.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Managed nodes","icon":"lucide-server","text":"Managed nodes are the servers and devices you configure. They need SSH and a Python interpreter for most modules. Windows hosts use WinRM or SSH instead.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Inventory selects the targets","icon":"lucide-table","text":"When you run a command, Ansible reads the inventory, expands groups and patterns into a list of hosts and loads variables for each.","cmd":"ansible-inventory -i inventory.ini --graph","out":"@all:\n  |--@ungrouped:\n  |--@web:\n  |  |--web1.example.com\n  |  |--web2.example.com","outKind":"example","note":"","risk":false,"viz":""},{"title":"One task, step by step","icon":"lucide-arrow-right","text":"For each task and each host Ansible connects, copies a small module script to a temporary folder, runs it with the arguments, collects the JSON result and removes the temporary files. Hosts run in parallel, 5 at a time by default (forks).","cmd":"ansible-config dump --only-changed\nansible-config dump | grep -i forks","out":"","outKind":"","note":"","risk":false,"viz":"Control node → web1: 1 connect (SSH)\nControl node → web1: 2 copy module to temp dir\nControl node → web1: 3 run module\nweb1 → Control node: 4 JSON result\nControl node → web1: 5 remove temp files"},{"title":"Playbooks, roles and collections","icon":"lucide-package","text":"A playbook is a list of plays, each mapping a host group to tasks. Roles package related tasks for reuse. Collections distribute modules, roles and plugins, for example ansible.posix or community.docker.","cmd":"ansible-galaxy collection list","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Facts and results","icon":"lucide-search","text":"At the start of each play Ansible gathers facts about each host (OS, IP addresses, memory). It reports ok, changed, failed or unreachable per host, then a recap.","cmd":"ansible web1.example.com -i inventory.ini -m ansible.builtin.setup -a \"filter=ansible_distribution*\"","out":"web1.example.com | SUCCESS => {\n    \"ansible_facts\": {\n        \"ansible_distribution\": \"Ubuntu\",\n        \"ansible_distribution_release\": \"noble\"\n    },\n    \"changed\": false\n}","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":25,"prev":{"id":"ans-what-is","title":"What is Ansible? Start here"},"next":{"id":"ans-install-first-ping","title":"Install Ansible and run your first ping"}}},{"id":"ans-install-first-ping","title":"Install Ansible and run your first ping","level":1,"icon":"lucide-download","summary":"Install with pipx, create an inventory, check SSH access and run the ping module.","qna":[{"q":"In which situation do we use this?","a":"A new control machine, or a new host that must be proven reachable before any automation."},{"q":"What does \"pong\" prove?","a":"The ping module logs in and runs Python, which is more than a network ping. It confirms SSH, user and Python."},{"q":"What comes next?","a":"Fix any failure here first; every later step depends on it."}],"steps":[{"title":"Check Python","icon":"lucide-code","text":"Ansible is a Python program. Check the version on the control node. Use the Python that your OS ships or one you installed yourself.","cmd":"python3 --version","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Install Ansible","icon":"lucide-download","text":"The Ansible documentation recommends pipx, which installs a command-line tool in its own isolated environment. --include-deps exposes the ansible commands. If you prefer, python3 -m pip install --user ansible also works.","cmd":"pipx install --include-deps ansible\nansible --version","out":"ansible [core 2.18.x]\n  config file = None\n  python version = 3.12.x","outKind":"example","note":"The package named ansible includes many collections. The package ansible-core is the minimal engine. Version numbers move quickly, so yours will differ.","risk":false,"viz":""},{"title":"Create a project folder and inventory","icon":"lucide-folder","text":"Keep everything for one automation project in one folder. The inventory lists your servers. Replace the names with your own servers.","cmd":"mkdir -p ~/ansible-lab && cd ~/ansible-lab\nprintf '[web]\nweb1.example.com\nweb2.example.com\n' > inventory.ini\ncat inventory.ini","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Set defaults in ansible.cfg","icon":"lucide-sliders-horizontal","text":"A local ansible.cfg saves repeating options on every command. Here it sets the inventory file, the login user and the SSH settings.","cmd":"cat > ansible.cfg <<'EOF'\n[defaults]\ninventory = inventory.ini\nremote_user = ubuntu\nhost_key_checking = True\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check that you can log in by hand","icon":"lucide-key-round","text":"Ansible uses the same SSH access you use. If this fails, Ansible will fail too. Fix SSH first.","cmd":"ssh ubuntu@web1.example.com hostname","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run the ping module","icon":"lucide-zap","text":"This is not an ICMP network ping. The ping module logs in over SSH, finds Python and returns \"pong\". SUCCESS means SSH, login and Python are all working.","cmd":"ansible all -m ansible.builtin.ping","out":"web1.example.com | SUCCESS => {\n    \"changed\": false,\n    \"ping\": \"pong\"\n}\nweb2.example.com | UNREACHABLE! => {\n    \"msg\": \"Failed to connect to the host via ssh: ...Connection timed out\"\n}","outKind":"example","note":"UNREACHABLE means a connection problem (name, network, firewall, key or user). FAILED means it connected but the task failed.","risk":false,"viz":""},{"title":"Read errors and use -v","icon":"lucide-bug","text":"Add -v for more detail, up to -vvvv for connection debugging. Most first-day problems are SSH keys, the wrong user, a missing Python or a host key prompt.","cmd":"ansible web1.example.com -m ansible.builtin.ping -vvv\nansible all -m ansible.builtin.ping -u ubuntu --private-key ~/.ssh/id_ed25519","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":25,"prev":{"id":"ans-architecture","title":"Ansible architecture: control node to managed nodes"},"next":{"id":"ans-inventory-ini","title":"Inventory in INI format"}}},{"id":"ans-inventory-ini","title":"Inventory in INI format","level":1,"icon":"lucide-table","summary":"From a flat list of hosts to groups, variables and groups of groups, then inspect and target them.","qna":[{"q":"In which situation do we use this?","a":"To name your servers and group them (web, db) so a command or play can target one group."},{"q":"What is a good group layout?","a":"By role and by environment, with a parent group such as prod:children to combine them."},{"q":"What comes next?","a":"ans-inventory-yaml when you need variables per group."}],"steps":[{"title":"A flat list of hosts","icon":"lucide-table","text":"The simplest inventory is one host per line. Hosts outside any group belong to the built-in groups all and ungrouped.","cmd":"cat > inventory.ini <<'EOF'\nweb1.example.com\nweb2.example.com\ndb1.example.com\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Put hosts into groups","icon":"lucide-layers","text":"A group name in square brackets starts a section. Playbooks target groups, so grouping is how you say \"all web servers\".","cmd":"cat > inventory.ini <<'EOF'\n[web]\nweb1.example.com\nweb2.example.com\n\n[db]\ndb1.example.com\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Variables on hosts and groups","icon":"lucide-sliders-horizontal","text":"ansible_host sets the real address when the name is not resolvable. [group:vars] sets variables for every host in the group.","cmd":"cat > inventory.ini <<'EOF'\n[web]\nweb1 ansible_host=10.0.1.11\nweb2 ansible_host=10.0.1.12\n\n[db]\ndb1 ansible_host=10.0.2.21\n\n[web:vars]\nhttp_port=80\n\n[all:vars]\nansible_user=ubuntu\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Groups of groups","icon":"lucide-git-branch","text":"[parent:children] lists groups instead of hosts. Targeting prod now covers both web and db.","cmd":"printf '\n[prod:children]\nweb\ndb\n' >> inventory.ini\nansible-inventory -i inventory.ini --graph","out":"@all:\n  |--@ungrouped:\n  |--@prod:\n  |  |--@web:\n  |  |  |--web1\n  |  |  |--web2\n  |  |--@db:\n  |  |  |--db1","outKind":"example","note":"","risk":false,"viz":""},{"title":"Inspect what Ansible sees","icon":"lucide-search","text":"--host prints all variables for one host, merged from every level. --list prints everything as JSON.","cmd":"ansible-inventory -i inventory.ini --host web1\nansible-inventory -i inventory.ini --list | head -n 20","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Target with patterns","icon":"lucide-filter","text":"Patterns pick hosts. A colon means OR, :& means AND, :! means NOT. --list-hosts shows the result without running anything.","cmd":"ansible 'web' -i inventory.ini --list-hosts\nansible 'prod:!db' -i inventory.ini --list-hosts\nansible 'web:&prod' -i inventory.ini --list-hosts","out":"  hosts (2):\n    web1\n    web2","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":25,"prev":{"id":"ans-install-first-ping","title":"Install Ansible and run your first ping"},"next":{"id":"ans-inventory-yaml","title":"Inventory in YAML, group_vars and host_vars"}}},{"id":"ans-inventory-yaml","title":"Inventory in YAML, group_vars and host_vars","level":2,"icon":"lucide-folder","summary":"The same inventory as YAML, then move variables into group_vars and host_vars files.","qna":[{"q":"In which situation do we use this?","a":"Inventories grow and need per-group or per-host settings such as ports, users and package names."},{"q":"Where do variables go?","a":"group_vars/groupname.yml for a group and host_vars/hostname.yml for one host, kept next to the inventory."},{"q":"What comes next?","a":"Check the result with ansible-inventory --list."}],"steps":[{"title":"The YAML inventory shape","icon":"lucide-file-text","text":"Everything sits under all. Groups live under children, each with hosts and optional vars. YAML is indentation-sensitive: use spaces, never tabs.","cmd":"cat > inventory.yml <<'EOF'\nall:\n  children:\n    web:\n      hosts:\n        web1.example.com:\n        web2.example.com:\n      vars:\n        http_port: 80\n    db:\n      hosts:\n        db1.example.com:\n          ansible_host: 10.0.20.5\n  vars:\n    ansible_user: ubuntu\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check it parses","icon":"lucide-check","text":"Let Ansible read it back. A syntax mistake shows up as a clear error, usually a wrong indent.","cmd":"ansible-inventory -i inventory.yml --graph\nansible-inventory -i inventory.yml --host db1.example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Move variables to group_vars","icon":"lucide-folder","text":"Files named after a group inside group_vars are loaded automatically. This keeps the inventory short and the variables easy to find.","cmd":"mkdir -p group_vars host_vars\nprintf 'http_port: 8080\nserver_admin: ops@example.com\n' > group_vars/web.yml\nansible-inventory -i inventory.yml --host web1.example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Per-host overrides","icon":"lucide-pencil","text":"host_vars/<host>.yml sets values for one machine. It beats group_vars for the same variable, which is how you make one exception.","cmd":"printf 'http_port: 9090\n' > host_vars/web2.example.com.yml\nansible-inventory -i inventory.yml --host web2.example.com | grep http_port","out":"    \"http_port\": 9090,","outKind":"example","note":"","risk":false,"viz":""},{"title":"Precedence in one sentence","icon":"lucide-arrow-up","text":"More specific wins: group_vars/all is overridden by a specific group, which is overridden by host_vars, then playbook variables, and finally -e on the command line beats everything. When a value surprises you, check with ansible-inventory --host.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":25,"prev":{"id":"ans-inventory-ini","title":"Inventory in INI format"},"next":{"id":"ans-adhoc","title":"Ad-hoc commands for quick jobs"}}},{"id":"ans-adhoc","title":"Ad-hoc commands for quick jobs","level":1,"icon":"lucide-terminal","summary":"One-line commands for checks and small changes, and when to switch to a playbook.","qna":[{"q":"In which situation do we use this?","a":"One-off jobs: check uptime on all hosts, restart a service, copy a file, gather facts."},{"q":"When should I write a playbook instead?","a":"When you will repeat it, need several steps, or want it reviewed and stored in Git."},{"q":"What comes next?","a":"Use -m with a module name rather than raw shell where you can."}],"steps":[{"title":"The shape of an ad-hoc command","icon":"lucide-terminal","text":"ansible <pattern> -m <module> -a \"<arguments>\". It runs one module on the chosen hosts, right now, without a playbook.","cmd":"ansible web -i inventory.ini -m ansible.builtin.ping","out":"","outKind":"","note":"","risk":false,"viz":"You → Control node: ansible web -m ping\nControl node → web1: run module\nControl node → web2: run module\nweb1 → You: pong\nweb2 → You: pong"},{"title":"Run a command","icon":"lucide-play","text":"The command module runs a program without a shell. The shell module uses a shell, so pipes and redirects work, at the cost of safety. Prefer command.","cmd":"ansible web -i inventory.ini -m ansible.builtin.command -a \"uptime\"\nansible web -i inventory.ini -m ansible.builtin.shell -a \"df -h / | tail -n 1\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Gather facts","icon":"lucide-search","text":"The setup module returns facts. Use filter to keep the output short.","cmd":"ansible web -i inventory.ini -m ansible.builtin.setup -a \"filter=ansible_memtotal_mb\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Copy a file","icon":"lucide-upload","text":"The copy module sends a local file to the servers and sets the owner and mode. It only reports changed if the content differs.","cmd":"echo \"managed by ansible\" > motd.txt\nansible web -i inventory.ini -b -m ansible.builtin.copy -a \"src=motd.txt dest=/etc/motd mode=0644\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Become root and manage a service","icon":"lucide-key-round","text":"-b (become) uses sudo. The package and service modules work on any distribution, so the same command works on Ubuntu and RHEL.","cmd":"ansible web -i inventory.ini -b -m ansible.builtin.package -a \"name=htop state=present\"\nansible web -i inventory.ini -b -m ansible.builtin.service -a \"name=cron state=restarted\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"When to write a playbook instead","icon":"lucide-file-text","text":"Ad-hoc is for checks and one-off jobs. As soon as you want to repeat it, review it, share it or run several steps in order, put it in a playbook and commit it to Git.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":25,"prev":{"id":"ans-inventory-yaml","title":"Inventory in YAML, group_vars and host_vars"},"next":{"id":"ans-yaml-basics","title":"YAML basics for Ansible"}}},{"id":"ans-yaml-basics","title":"YAML basics for Ansible","level":1,"icon":"lucide-file-text","summary":"The handful of YAML rules that cause most beginner errors: indentation, lists, dictionaries, quoting and booleans.","qna":[{"q":"In which situation do we use this?","a":"Every playbook, variable file and inventory is YAML, and most early errors are indentation."},{"q":"What are the usual mistakes?","a":"Tabs instead of spaces, a missing space after a colon, and unquoted values like yes, no or 1.10."},{"q":"What comes next?","a":"Run yamllint before ansible-playbook."}],"steps":[{"title":"Key and value","icon":"lucide-pencil","text":"A dictionary is a set of key: value pairs. There must be a space after the colon.","cmd":"printf 'name: web1\nport: 80\n' > demo.yml\ncat demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Lists","icon":"lucide-list-todo","text":"A list item starts with a dash and a space. Items line up at the same indentation. Playbooks and task lists are lists of dictionaries.","cmd":"printf 'packages:\n  - nginx\n  - git\n  - curl\n' > demo.yml\npython3 -c \"import yaml,sys;print(yaml.safe_load(open('demo.yml')))\"","out":"{'packages': ['nginx', 'git', 'curl']}","outKind":"example","note":"This check needs PyYAML (pip install pyyaml). yamllint is a better tool for style checks.","risk":false,"viz":""},{"title":"Indentation","icon":"lucide-layers","text":"Use two spaces per level and never tabs. Children must be indented more than their parent. Mixed indentation is the most common cause of \"mapping values are not allowed here\" errors.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Quote values that start with a Jinja2 expression","icon":"lucide-triangle-alert","text":"A value that begins with {{ must be quoted, otherwise YAML reads it as a dictionary. This is the most common Ansible-specific mistake.","cmd":"printf 'good: \"{{ http_port }}\"\nbad: {{ http_port }}\n' > demo.yml\npython3 -c \"import yaml;yaml.safe_load(open('demo.yml'))\"","out":"yaml.scanner.ScannerError or ConstructorError: found unhashable key","outKind":"example","note":"The second line is deliberately wrong to show the error.","risk":false,"viz":""},{"title":"Booleans and strings","icon":"lucide-check","text":"In YAML 1.1 words such as yes, no, on and off can become booleans. Use true and false in new files. Quote anything that must stay a string, such as a version 3.10 or a file mode \"0644\".","cmd":"printf 'enabled: true\nversion: \"3.10\"\nmode: \"0644\"\n' > demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Multi-line text","icon":"lucide-file-text","text":"A | keeps line breaks (good for scripts and file content). A > folds lines into one (good for long sentences).","cmd":"printf 'motd: |\n  Welcome to the server.\n  Managed by Ansible.\n' > demo.yml\npython3 -c \"import yaml;print(repr(yaml.safe_load(open('demo.yml'))['motd']))\"","out":"'Welcome to the server.\nManaged by Ansible.\n'","outKind":"example","note":"","risk":false,"viz":""},{"title":"Validate before you run","icon":"lucide-check","text":"yamllint catches style and syntax problems. ansible-playbook --syntax-check understands Ansible structure. Use both.","cmd":"yamllint site.yml\nansible-playbook site.yml --syntax-check","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":25,"prev":{"id":"ans-adhoc","title":"Ad-hoc commands for quick jobs"},"next":{"id":"ans-first-playbook","title":"Your first playbook"}}},{"id":"ans-first-playbook","title":"Your first playbook","level":1,"icon":"lucide-file-text","summary":"Write a playbook that installs a package and starts a service, then check, preview, run and rerun it.","qna":[{"q":"In which situation do we use this?","a":"A repeatable task list for hosts: install a package, copy a file, start a service."},{"q":"What are plays and tasks?","a":"A play maps a host group to tasks; each task calls one module with arguments, in order."},{"q":"What comes next?","a":"Always run with --check first on real servers."}],"steps":[{"title":"The anatomy of a playbook","icon":"lucide-file-text","text":"A playbook is a list of plays. Each play has a name, the hosts it targets, whether to become root and a list of tasks. Each task has a name and calls one module with arguments.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write site.yml","icon":"lucide-pencil","text":"Two tasks: install Apache and make sure it is running and enabled at boot. The package name is apache2 on Debian and Ubuntu (it is httpd on RHEL).","cmd":"cat > site.yml <<'EOF'\n- name: Install and start Apache\n  hosts: web\n  become: true\n  tasks:\n    - name: Install Apache\n      ansible.builtin.package:\n        name: apache2\n        state: present\n    - name: Start and enable Apache\n      ansible.builtin.service:\n        name: apache2\n        state: started\n        enabled: true\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check the syntax","icon":"lucide-check","text":"--syntax-check parses the playbook without connecting to any host.","cmd":"ansible-playbook site.yml --syntax-check","out":"playbook: site.yml","outKind":"example","note":"","risk":false,"viz":""},{"title":"Preview with check and diff","icon":"lucide-eye","text":"--check predicts what would change without changing anything. --diff shows file differences. Some modules cannot predict, so use it as a guide, not a guarantee.","cmd":"ansible-playbook site.yml --check --diff","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run it","icon":"lucide-rocket","text":"Watch the task names go by. changed means the module changed something, ok means it was already right.","cmd":"ansible-playbook site.yml","out":"PLAY [Install and start Apache] ***\nTASK [Gathering Facts] ***\nok: [web1]\nTASK [Install Apache] ***\nchanged: [web1]\nTASK [Start and enable Apache] ***\nchanged: [web1]\nPLAY RECAP ***\nweb1 : ok=3 changed=2 unreachable=0 failed=0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run it again: idempotence","icon":"lucide-refresh-cw","text":"The second run should report changed=0. If something always shows changed, it is probably a command or shell task, which cannot tell whether work is needed.","cmd":"ansible-playbook site.yml","out":"PLAY RECAP ***\nweb1 : ok=3 changed=0 unreachable=0 failed=0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Verify the result","icon":"lucide-check","text":"Check from the outside, the way a user would.","cmd":"ansible web -b -m ansible.builtin.command -a \"systemctl is-active apache2\"\ncurl -sI http://web1.example.com | head -n 1","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":25,"prev":{"id":"ans-yaml-basics","title":"YAML basics for Ansible"},"next":{"id":"ans-variables-facts","title":"Variables and facts"}}},{"id":"ans-variables-facts","title":"Variables and facts","level":2,"icon":"lucide-sliders-horizontal","summary":"Define variables, override them from the command line, and use facts that Ansible discovers about each host.","qna":[{"q":"In which situation do we use this?","a":"The same playbook must behave differently by host, OS or environment without copying it."},{"q":"What are facts?","a":"Data Ansible gathers from each host, such as OS family and IP addresses, available as ansible_facts."},{"q":"What comes next?","a":"Use debug to print a variable while you learn what is available."}],"steps":[{"title":"Variables in a play","icon":"lucide-sliders-horizontal","text":"vars: defines values you can reuse with {{ name }}. Quote the whole value when it starts with a Jinja2 expression.","cmd":"cat > vars-demo.yml <<'EOF'\n- name: Variables demo\n  hosts: web\n  vars:\n    greeting: Hello\n    port: 8080\n  tasks:\n    - name: Show variables\n      ansible.builtin.debug:\n        msg: \"{{ greeting }} from {{ inventory_hostname }} on port {{ port }}\"\nEOF\nansible-playbook vars-demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Override from the command line","icon":"lucide-arrow-up","text":"-e (extra vars) has the highest precedence of all. It is handy for one-off changes and for passing values from CI.","cmd":"ansible-playbook vars-demo.yml -e \"greeting=Hi port=9000\"\nansible-playbook vars-demo.yml -e @extra.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Magic variables","icon":"lucide-search","text":"Ansible provides built-in variables. inventory_hostname is the name in the inventory, groups lists all groups and hostvars lets you read another host's variables.","cmd":"ansible web -m ansible.builtin.debug -a \"var=groups\"\nansible web -m ansible.builtin.debug -a \"var=inventory_hostname\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Facts: what Ansible learns about a host","icon":"lucide-database","text":"At the start of each play Ansible runs the setup module and stores the results under ansible_facts. Access them with ansible_facts['key'].","cmd":"ansible web1.example.com -m ansible.builtin.setup -a \"filter=ansible_distribution*\"\nansible web1.example.com -m ansible.builtin.setup -a \"filter=ansible_default_ipv4\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Use facts in a task","icon":"lucide-check","text":"Facts let one playbook adapt to the host, for example choosing the right package name.","cmd":"cat > facts-demo.yml <<'EOF'\n- name: Facts demo\n  hosts: web\n  tasks:\n    - name: Show OS and memory\n      ansible.builtin.debug:\n        msg: \"{{ ansible_facts['distribution'] }} {{ ansible_facts['distribution_version'] }} with {{ ansible_facts['memtotal_mb'] }} MB\"\nEOF\nansible-playbook facts-demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Set and register your own values","icon":"lucide-pencil","text":"set_fact creates a variable during the run. register stores a task's result so later tasks can use it.","cmd":"cat > register-demo.yml <<'EOF'\n- name: Register demo\n  hosts: web\n  tasks:\n    - name: Read the kernel version\n      ansible.builtin.command: uname -r\n      register: kernel\n      changed_when: false\n    - name: Show it\n      ansible.builtin.debug:\n        msg: \"Kernel is {{ kernel.stdout }}\"\nEOF\nansible-playbook register-demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":9,"of":25,"prev":{"id":"ans-first-playbook","title":"Your first playbook"},"next":{"id":"ans-conditionals-loops","title":"Conditionals and loops"}}},{"id":"ans-conditionals-loops","title":"Conditionals and loops","level":2,"icon":"lucide-filter","summary":"Run tasks only when a condition holds and repeat a task over a list.","qna":[{"q":"In which situation do we use this?","a":"A task should run only on some hosts (when), or repeat for several items such as packages or users (loop)."},{"q":"What is a typical use?","a":"Install apache2 on Debian and httpd on RedHat with a when on ansible_os_family."},{"q":"What comes next?","a":"Keep conditions simple; complex logic belongs in variables or roles."}],"steps":[{"title":"when: run a task conditionally","icon":"lucide-filter","text":"when takes a Jinja2 expression without braces. The task is skipped, not failed, when the condition is false.","cmd":"cat > when-demo.yml <<'EOF'\n- name: Conditional demo\n  hosts: all\n  tasks:\n    - name: Only on Debian family\n      ansible.builtin.debug:\n        msg: \"This is a Debian-family host\"\n      when: ansible_facts['os_family'] == \"Debian\"\nEOF\nansible-playbook when-demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Combine conditions","icon":"lucide-layers","text":"Use and, or and not, or give when a list, which means all items must be true.","cmd":"cat > when-demo2.yml <<'EOF'\n- name: Several conditions\n  hosts: all\n  tasks:\n    - name: Big Ubuntu hosts only\n      ansible.builtin.debug:\n        msg: \"match\"\n      when:\n        - ansible_facts['distribution'] == \"Ubuntu\"\n        - ansible_facts['memtotal_mb'] > 1024\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"loop: repeat over a list","icon":"lucide-refresh-cw","text":"loop runs the task once per item. The current item is {{ item }}. Giving the package module a list is faster than looping, but loop works for every module.","cmd":"cat > loop-demo.yml <<'EOF'\n- name: Loop demo\n  hosts: web\n  become: true\n  tasks:\n    - name: Create several users\n      ansible.builtin.user:\n        name: \"{{ item }}\"\n        state: present\n      loop:\n        - alice\n        - bob\n        - carol\nEOF\nansible-playbook loop-demo.yml --check","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Loop over dictionaries","icon":"lucide-table","text":"Each item can be a small dictionary. Access fields with item.name and item.groups.","cmd":"cat > loop-demo2.yml <<'EOF'\n- name: Users with groups\n  hosts: web\n  become: true\n  tasks:\n    - name: Create users\n      ansible.builtin.user:\n        name: \"{{ item.name }}\"\n        groups: \"{{ item.groups }}\"\n      loop:\n        - { name: alice, groups: sudo }\n        - { name: bob, groups: users }\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Conditions on results","icon":"lucide-check","text":"Register a task result and branch on it. Use failed_when and changed_when to define what counts as a failure or a change.","cmd":"cat > result-demo.yml <<'EOF'\n- name: React to a result\n  hosts: web\n  tasks:\n    - name: Is the app config present\n      ansible.builtin.stat:\n        path: /etc/myapp.conf\n      register: conf\n    - name: Warn when missing\n      ansible.builtin.debug:\n        msg: \"config is missing\"\n      when: not conf.stat.exists\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":10,"of":25,"prev":{"id":"ans-variables-facts","title":"Variables and facts"},"next":{"id":"ans-handlers","title":"Handlers and notify"}}},{"id":"ans-handlers","title":"Handlers and notify","level":2,"icon":"lucide-bell","summary":"Restart a service only when its configuration actually changed.","qna":[{"q":"In which situation do we use this?","a":"A service must restart only when its config file actually changed."},{"q":"When does a handler run?","a":"Once, at the end of the play, and only if a task that notifies it reported changed."},{"q":"What comes next?","a":"Use meta: flush_handlers if a restart is needed mid-play."}],"steps":[{"title":"The problem handlers solve","icon":"lucide-bell","text":"If you restart Apache after every run, you cause needless downtime. You only want to restart when the configuration file really changed. Handlers do exactly that.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"A task that notifies","icon":"lucide-pencil","text":"When a task reports changed it can notify a handler by name. If the task reports ok, nothing is notified.","cmd":"cat > handler-demo.yml <<'EOF'\n- name: Handler demo\n  hosts: web\n  become: true\n  tasks:\n    - name: Deploy the site config\n      ansible.builtin.copy:\n        src: mysite.conf\n        dest: /etc/apache2/conf-available/mysite.conf\n        mode: \"0644\"\n      notify: Reload Apache\n  handlers:\n    - name: Reload Apache\n      ansible.builtin.service:\n        name: apache2\n        state: reloaded\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"First run: the handler fires","icon":"lucide-play","text":"The copy task changes the file, so the handler runs once at the end of the play, even if several tasks notified it.","cmd":"echo \"# demo\" > mysite.conf\nansible-playbook handler-demo.yml","out":"TASK [Deploy the site config] ***\nchanged: [web1]\nRUNNING HANDLER [Reload Apache] ***\nchanged: [web1]","outKind":"example","note":"","risk":false,"viz":""},{"title":"Second run: nothing happens","icon":"lucide-check","text":"The file is identical, so the task is ok, the handler is skipped and the service is not touched.","cmd":"ansible-playbook handler-demo.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run handlers earlier","icon":"lucide-arrow-up","text":"Handlers normally wait until the end of the play. flush_handlers runs the pending ones immediately, which you need when a later task depends on the restart.","cmd":"printf '    - name: Run pending handlers now\n      ansible.builtin.meta: flush_handlers\n' >> handler-demo.yml.snippet","out":"","outKind":"","note":"Place this task between the tasks that need the service in its new state.","risk":false,"viz":""}],"nav":{"pos":11,"of":25,"prev":{"id":"ans-conditionals-loops","title":"Conditionals and loops"},"next":{"id":"ans-templates","title":"Templates with Jinja2"}}},{"id":"ans-templates","title":"Templates with Jinja2","level":2,"icon":"lucide-code","summary":"Generate configuration files from templates and variables, including loops and defaults.","qna":[{"q":"In which situation do we use this?","a":"Config files that differ per host or environment: nginx, sshd, application settings."},{"q":"Why a template and not copy?","a":"A template fills in variables with Jinja2, so one file serves every host."},{"q":"What comes next?","a":"Add validate: to test a file before it replaces the live one."}],"steps":[{"title":"Why templates","icon":"lucide-code","text":"Two servers rarely need identical config files. A template is a file with placeholders. Ansible fills them with each host's variables and writes the result.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a template","icon":"lucide-pencil","text":"Template files end in .j2. {{ }} prints a value, and {% %} runs logic. The default filter supplies a fallback when a variable is missing.","cmd":"mkdir -p templates\ncat > templates/index.html.j2 <<'EOF'\n<h1>Welcome to {{ inventory_hostname }}</h1>\n<p>Port: {{ http_port | default(80) }}</p>\n<p>Managed by Ansible. Do not edit by hand.</p>\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Use the template module","icon":"lucide-upload","text":"The template module renders the file on the control node and copies the result. It is idempotent: it only reports changed when the output differs.","cmd":"cat > template-demo.yml <<'EOF'\n- name: Render a page\n  hosts: web\n  become: true\n  tasks:\n    - name: Write index.html\n      ansible.builtin.template:\n        src: index.html.j2\n        dest: /var/www/html/index.html\n        mode: \"0644\"\nEOF\nansible-playbook template-demo.yml --check --diff","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Loops inside a template","icon":"lucide-refresh-cw","text":"A for loop can build a list from your inventory, for example one line per web server.","cmd":"cat > templates/hosts.j2 <<'EOF'\n{% for host in groups['web'] %}\n{{ hostvars[host]['ansible_host'] | default(host) }} {{ host }}\n{% endfor %}\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Validate risky files","icon":"lucide-shield","text":"The validate option runs a command on the rendered file before it replaces the real one. If it fails, the change is not applied. Use it for files that can lock you out, such as sudoers.","cmd":"cat > validate-demo.yml <<'EOF'\n- name: Safe sudoers change\n  hosts: web\n  become: true\n  tasks:\n    - name: Allow the ops group\n      ansible.builtin.copy:\n        content: \"%ops ALL=(ALL) NOPASSWD:ALL\\n\"\n        dest: /etc/sudoers.d/ops\n        mode: \"0440\"\n        validate: /usr/sbin/visudo -cf %s\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":12,"of":25,"prev":{"id":"ans-handlers","title":"Handlers and notify"},"next":{"id":"ans-roles","title":"Roles: structure and reuse"}}},{"id":"ans-roles","title":"Roles: structure and reuse","level":2,"icon":"lucide-package","summary":"Package tasks, handlers, templates and defaults into a role you can reuse in any playbook.","qna":[{"q":"In which situation do we use this?","a":"Playbooks are getting long, or you want to reuse the same setup (say, nginx) across projects."},{"q":"What does a role contain?","a":"tasks, handlers, templates, defaults, vars and files in a fixed folder layout."},{"q":"What comes next?","a":"Use ansible-galaxy to share or download roles and collections."}],"steps":[{"title":"What a role is","icon":"lucide-package","text":"A role is a folder with a fixed layout. It lets you reuse the same automation, for example \"webserver\", across projects without copy-paste.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Generate the skeleton","icon":"lucide-folder","text":"ansible-galaxy creates the standard directories: tasks, handlers, defaults, vars, files, templates, meta and tests.","cmd":"ansible-galaxy role init --init-path roles webserver\nls roles/webserver","out":"README.md  defaults  files  handlers  meta  tasks  templates  tests  vars","outKind":"example","note":"","risk":false,"viz":""},{"title":"Fill in the tasks","icon":"lucide-pencil","text":"Put tasks in tasks/main.yml. Put defaults (lowest precedence, easy to override) in defaults/main.yml. Keep every variable name prefixed with the role name to avoid clashes.","cmd":"cat > roles/webserver/defaults/main.yml <<'EOF'\nwebserver_package: apache2\nwebserver_service: apache2\nwebserver_port: 80\nEOF\ncat > roles/webserver/tasks/main.yml <<'EOF'\n- name: Install the web server\n  ansible.builtin.package:\n    name: \"{{ webserver_package }}\"\n    state: present\n- name: Start and enable the web server\n  ansible.builtin.service:\n    name: \"{{ webserver_service }}\"\n    state: started\n    enabled: true\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Use the role in a playbook","icon":"lucide-rocket","text":"The play lists the role. Variables passed here override the defaults.","cmd":"cat > site.yml <<'EOF'\n- name: Web servers\n  hosts: web\n  become: true\n  roles:\n    - role: webserver\n      vars:\n        webserver_port: 8080\nEOF\nansible-playbook site.yml --syntax-check","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Share roles","icon":"lucide-users","text":"Publish a role to Git or Ansible Galaxy. Other projects pull it in with a requirements.yml file.","cmd":"cat > requirements.yml <<'EOF'\nroles:\n  - name: geerlingguy.docker\ncollections:\n  - name: ansible.posix\nEOF\nansible-galaxy install -r requirements.yml\nansible-galaxy collection install -r requirements.yml","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":13,"of":25,"prev":{"id":"ans-templates","title":"Templates with Jinja2"},"next":{"id":"ans-vault","title":"Secrets with Ansible Vault"}}},{"id":"ans-vault","title":"Secrets with Ansible Vault","level":2,"icon":"lucide-lock","summary":"Encrypt passwords and keys so they can live in Git, and use them at run time.","qna":[{"q":"In which situation do we use this?","a":"Passwords, tokens and keys that must live in the repository without being readable."},{"q":"What should I never do?","a":"Commit the vault password itself. Keep it in a separate file or secret store that Git ignores."},{"q":"What comes next?","a":"encrypt_string lets you encrypt single values inside a normal vars file."}],"steps":[{"title":"Why vault","icon":"lucide-lock","text":"Variables files often hold passwords and tokens. Vault encrypts a file (or a single value) with a password so the encrypted version is safe to commit to Git.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Keep the vault password out of Git","icon":"lucide-shield","text":"Store the vault password in a file with tight permissions and tell Git to ignore it. Do this before you create any secret.","cmd":"openssl rand -base64 24 > .vault_pass\nchmod 600 .vault_pass\necho \".vault_pass\" >> .gitignore","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Encrypt a variables file","icon":"lucide-lock","text":"Create the plain file, then encrypt it. The encrypted file starts with the header $ANSIBLE_VAULT.","cmd":"mkdir -p group_vars/all\nprintf 'db_password: \"change-me\"\n' > group_vars/all/vault.yml\nansible-vault encrypt group_vars/all/vault.yml --vault-password-file .vault_pass\nhead -n 1 group_vars/all/vault.yml","out":"$ANSIBLE_VAULT;1.1;AES256","outKind":"example","note":"","risk":false,"viz":""},{"title":"View and edit","icon":"lucide-eye","text":"view prints the decrypted content. edit opens it in your editor and re-encrypts on save. rekey changes the password.","cmd":"ansible-vault view group_vars/all/vault.yml --vault-password-file .vault_pass\nansible-vault edit group_vars/all/vault.yml --vault-password-file .vault_pass\nansible-vault rekey group_vars/all/vault.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Encrypt a single value","icon":"lucide-key-round","text":"encrypt_string produces a block you can paste into any YAML file, which keeps the rest of the file readable.","cmd":"ansible-vault encrypt_string 'S3cret!' --name db_password --vault-password-file .vault_pass","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Use it when you run","icon":"lucide-rocket","text":"Point at the password file for each run, or set it once in ansible.cfg. Use --ask-vault-pass to type it instead.","cmd":"ansible-playbook site.yml --vault-password-file .vault_pass\nansible-playbook site.yml --ask-vault-pass","out":"","outKind":"","note":"In CI, provide the password from the secret store of your CI system, not from the repository.","risk":false,"viz":""}],"nav":{"pos":14,"of":25,"prev":{"id":"ans-roles","title":"Roles: structure and reuse"},"next":{"id":"ans-idempotence-check","title":"Idempotence, check mode and diff"}}},{"id":"ans-idempotence-check","title":"Idempotence, check mode and diff","level":2,"icon":"lucide-check","summary":"Prove a playbook is safe to run repeatedly, and fix tasks that always report changed.","qna":[{"q":"In which situation do we use this?","a":"Before changing real servers: preview what would change and prove that a second run changes nothing."},{"q":"What do check and diff do?","a":"--check simulates without changing; --diff shows the exact lines that would change."},{"q":"What comes next?","a":"A playbook that reports changed again on the second run needs fixing."}],"steps":[{"title":"What idempotent means","icon":"lucide-refresh-cw","text":"Applying the playbook once or ten times gives the same result and no repeated side effects. The proof is a recap that shows changed=0 on the second run.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Modules are idempotent","icon":"lucide-check","text":"package, copy, file, user and service compare the desired and actual state first. Only differences are changed.","cmd":"ansible-playbook site.yml\nansible-playbook site.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"command and shell are not","icon":"lucide-triangle-alert","text":"These modules cannot know whether work is needed, so they always report changed. Prefer a real module. If you must use command, tell Ansible when to skip it or what counts as a change.","cmd":"cat > idem-demo.yml <<'EOF'\n- name: Idempotence demo\n  hosts: web\n  become: true\n  tasks:\n    - name: Always changed (bad)\n      ansible.builtin.command: touch /tmp/marker\n    - name: Skip when the file exists (good)\n      ansible.builtin.command: touch /tmp/marker2\n      args:\n        creates: /tmp/marker2\n    - name: Read-only command, never a change\n      ansible.builtin.command: uptime\n      changed_when: false\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check mode and diff","icon":"lucide-eye","text":"--check simulates, --diff shows file changes. Tasks that depend on earlier changes may not predict well. Add check_mode: false to a read-only task that must always run.","cmd":"ansible-playbook site.yml --check --diff","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Detect drift","icon":"lucide-search","text":"Running with --check on a schedule tells you when someone changed a server by hand: any changed line is drift from your code.","cmd":"ansible-playbook site.yml --check | grep -E 'changed=|failed='","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":15,"of":25,"prev":{"id":"ans-vault","title":"Secrets with Ansible Vault"},"next":{"id":"ans-webserver-project","title":"Project: deploy Apache (httpd) on two servers"}}},{"id":"ans-webserver-project","title":"Project: deploy Apache (httpd) on two servers","level":3,"icon":"lucide-rocket","summary":"One playbook that works on Debian-family and RHEL-family hosts: install, configure, start, open the firewall and verify.","qna":[{"q":"In which situation do we use this?","a":"Standing up the same web server on several hosts: package, page, service, firewall."},{"q":"How do I confirm it worked?","a":"Use the uri module or curl to request the page and check the status code."},{"q":"What comes next?","a":"Turn the playbook into a role when you add more services."}],"steps":[{"title":"Goal and layout","icon":"lucide-target","text":"Install Apache on two servers, publish a page that shows each server's name, and verify it from the control node. The package is apache2 on Debian-family and httpd on RHEL-family, so the playbook will choose by OS family.","cmd":"mkdir -p ~/ansible-lab/webproject/templates && cd ~/ansible-lab/webproject","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Inventory and variables","icon":"lucide-table","text":"Two hosts in a web group. The default package and service names go in group_vars and are changed per OS in the play.","cmd":"cat > inventory.ini <<'EOF'\n[web]\nweb1 ansible_host=10.0.1.11\nweb2 ansible_host=10.0.1.12\n\n[web:vars]\nansible_user=ubuntu\nEOF\nansible web -i inventory.ini -m ansible.builtin.ping","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The page template","icon":"lucide-code","text":"A tiny template shows which server answered, which is handy later for load balancing.","cmd":"cat > templates/index.html.j2 <<'EOF'\n<h1>Served by {{ inventory_hostname }}</h1>\n<p>OS: {{ ansible_facts['distribution'] }} {{ ansible_facts['distribution_version'] }}</p>\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The playbook","icon":"lucide-file-text","text":"Variables choose package and service by OS family. The service module starts it, the template module writes the page and uri checks the answer from the control node.","cmd":"cat > site.yml <<'EOF'\n- name: Deploy Apache\n  hosts: web\n  become: true\n  vars:\n    web_pkg: \"{{ 'httpd' if ansible_facts['os_family'] == 'RedHat' else 'apache2' }}\"\n  tasks:\n    - name: Install Apache\n      ansible.builtin.package:\n        name: \"{{ web_pkg }}\"\n        state: present\n    - name: Write the home page\n      ansible.builtin.template:\n        src: index.html.j2\n        dest: /var/www/html/index.html\n        mode: \"0644\"\n    - name: Start and enable Apache\n      ansible.builtin.service:\n        name: \"{{ web_pkg }}\"\n        state: started\n        enabled: true\n    - name: Check the site answers\n      ansible.builtin.uri:\n        url: \"http://{{ ansible_host | default(inventory_hostname) }}/\"\n        status_code: 200\n      delegate_to: localhost\n      become: false\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Dry run, then run","icon":"lucide-rocket","text":"Check the syntax, preview the changes and apply. Open the firewall port too if the hosts have one (see the next step).","cmd":"ansible-playbook -i inventory.ini site.yml --syntax-check\nansible-playbook -i inventory.ini site.yml --check --diff\nansible-playbook -i inventory.ini site.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Open the firewall","icon":"lucide-shield-ban","text":"UFW on Ubuntu or firewalld on RHEL. Both modules are idempotent. Add the task for the family you use. The ansible.posix collection provides the firewalld module.","cmd":"ansible web -i inventory.ini -b -m community.general.ufw -a \"rule=allow port=80 proto=tcp\"\nansible web -i inventory.ini -b -m ansible.posix.firewalld -a \"service=http permanent=true state=enabled immediate=true\"","out":"","outKind":"","note":"community.general and ansible.posix are collections. Install them with ansible-galaxy collection install community.general ansible.posix if your install does not include them.","risk":false,"viz":""},{"title":"Verify and rerun","icon":"lucide-check","text":"Fetch the page from each server and run the playbook again. The second run must show changed=0.","cmd":"curl -s http://10.0.1.11/\ncurl -s http://10.0.1.12/\nansible-playbook -i inventory.ini site.yml | tail -n 4","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":16,"of":25,"prev":{"id":"ans-idempotence-check","title":"Idempotence, check mode and diff"},"next":{"id":"ans-docker-project","title":"Project: install Docker Engine and run a container"}}},{"id":"ans-docker-project","title":"Project: install Docker Engine and run a container","level":3,"icon":"lucide-box","summary":"Follow Docker's documented Ubuntu steps as a playbook: key, repository, packages, service and hello-world.","qna":[{"q":"In which situation do we use this?","a":"Preparing container hosts consistently: repository, engine, group membership and a test container."},{"q":"What is the usual snag?","a":"Group membership needs a new login to take effect, so test with a task that runs after a reset_connection."},{"q":"What comes next?","a":"Manage containers with docker_container once the engine is ready."}],"steps":[{"title":"Plan","icon":"lucide-target","text":"These steps follow the official Docker Engine installation guide for Ubuntu: add Docker's signing key and apt repository, install the packages, start the service and run the hello-world image. Test on a throwaway server first.","cmd":"mkdir -p ~/ansible-lab/docker && cd ~/ansible-lab/docker\nprintf '[docker_hosts]\nserver1 ansible_host=203.0.113.10 ansible_user=ubuntu\n' > inventory.ini","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Prerequisites and the signing key","icon":"lucide-key-round","text":"Create the keyring directory, then download Docker's GPG key into it. This is the Ansible form of the documented install, curl and chmod commands.","cmd":"cat > docker.yml <<'EOF'\n- name: Install Docker Engine\n  hosts: docker_hosts\n  become: true\n  tasks:\n    - name: Install prerequisites\n      ansible.builtin.apt:\n        name:\n          - ca-certificates\n          - curl\n        state: present\n        update_cache: true\n    - name: Create the keyring directory\n      ansible.builtin.file:\n        path: /etc/apt/keyrings\n        state: directory\n        mode: \"0755\"\n    - name: Download Docker's GPG key\n      ansible.builtin.get_url:\n        url: https://download.docker.com/linux/ubuntu/gpg\n        dest: /etc/apt/keyrings/docker.asc\n        mode: \"0644\"\n    - name: Add the Docker apt repository\n      ansible.builtin.deb822_repository:\n        name: docker\n        types: [deb]\n        uris: https://download.docker.com/linux/ubuntu\n        suites: [\"{{ ansible_facts['distribution_release'] }}\"]\n        components: [stable]\n        signed_by: /etc/apt/keyrings/docker.asc\n    - name: Install Docker packages\n      ansible.builtin.apt:\n        name:\n          - docker-ce\n          - docker-ce-cli\n          - containerd.io\n          - docker-buildx-plugin\n          - docker-compose-plugin\n        state: present\n        update_cache: true\n    - name: Enable and start Docker\n      ansible.builtin.service:\n        name: docker\n        state: started\n        enabled: true\n    - name: Run the hello-world image\n      ansible.builtin.command: docker run --rm hello-world\n      changed_when: false\nEOF","out":"","outKind":"","note":"deb822_repository needs ansible-core 2.15 or newer on the control node. Use apt_repository on older versions.","risk":false,"viz":""},{"title":"Check and run","icon":"lucide-rocket","text":"Syntax check, a preview (the repository and package steps cannot fully predict in check mode) and then apply.","cmd":"ansible-playbook -i inventory.ini docker.yml --syntax-check\nansible-playbook -i inventory.ini docker.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify on the server","icon":"lucide-check","text":"Confirm the engine version and that the service is active.","cmd":"ansible docker_hosts -i inventory.ini -b -m ansible.builtin.command -a \"docker --version\"\nansible docker_hosts -i inventory.ini -b -m ansible.builtin.command -a \"systemctl is-active docker\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run a real container","icon":"lucide-play","text":"Start Nginx in a container, publish it on port 8080 and check it. The community.docker collection offers a docker_container module if you prefer YAML over shell.","cmd":"ansible docker_hosts -i inventory.ini -b -m ansible.builtin.command -a \"docker run -d --name web -p 8080:80 nginx:stable\"\ncurl -sI http://203.0.113.10:8080 | head -n 1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Allow a user to run docker","icon":"lucide-users","text":"Members of the docker group can control the engine without sudo. That is effectively root access on the host, so grant it carefully.","cmd":"ansible docker_hosts -i inventory.ini -b -m ansible.builtin.user -a \"name=ubuntu groups=docker append=true\"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Remove the test container and, if this was a throwaway server, the image.","cmd":"ansible docker_hosts -i inventory.ini -b -m ansible.builtin.command -a \"docker rm -f web\"\nansible docker_hosts -i inventory.ini -b -m ansible.builtin.command -a \"docker image prune -af\"","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":17,"of":25,"prev":{"id":"ans-webserver-project","title":"Project: deploy Apache (httpd) on two servers"},"next":{"id":"ans-users-hardening","title":"Project: users, keys and SSH hardening"}}},{"id":"ans-users-hardening","title":"Project: users, keys and SSH hardening","level":3,"icon":"lucide-shield","summary":"Create an admin user with a key, then disable root and password logins safely with validation and a handler.","qna":[{"q":"In which situation do we use this?","a":"New servers need admin users, keys and secure SSH settings applied the same way every time."},{"q":"How do I avoid locking myself out?","a":"Test the new config with validate: sshd -t, keep one existing session open, and run on one host first with serial."},{"q":"What comes next?","a":"Add a firewall play and automatic updates."}],"steps":[{"title":"Plan and the lockout warning","icon":"lucide-triangle-alert","text":"You will create a user, install their public key, give sudo and then tighten sshd. The order matters: confirm key login works before turning off passwords, and keep one session open while you test.","cmd":"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Create the user and key","icon":"lucide-user","text":"The user module creates the account. authorized_key (from the ansible.posix collection) installs the public key. The lookup reads the key file from your control node.","cmd":"ansible-galaxy collection install ansible.posix\ncat > users.yml <<'EOF'\n- name: Admin user\n  hosts: all\n  become: true\n  tasks:\n    - name: Create the user\n      ansible.builtin.user:\n        name: opsadmin\n        shell: /bin/bash\n        groups: sudo\n        append: true\n    - name: Install the public key\n      ansible.posix.authorized_key:\n        user: opsadmin\n        key: \"{{ lookup('ansible.builtin.file', '~/.ssh/id_ed25519.pub') }}\"\nEOF\nansible-playbook users.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Test the new login","icon":"lucide-key-round","text":"Before changing sshd, prove the key works from a second terminal.","cmd":"ssh opsadmin@web1.example.com 'sudo -n true && echo \"key login and sudo OK\"'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Harden sshd with validation","icon":"lucide-lock","text":"lineinfile edits one setting. validate runs sshd -t against the new file first, so a typo cannot break the service. The handler reloads sshd only when something changed.","cmd":"cat > harden.yml <<'EOF'\n- name: Harden sshd\n  hosts: all\n  become: true\n  tasks:\n    - name: Disable root login\n      ansible.builtin.lineinfile:\n        path: /etc/ssh/sshd_config\n        regexp: '^#?PermitRootLogin'\n        line: PermitRootLogin no\n        validate: /usr/sbin/sshd -t -f %s\n      notify: Reload sshd\n    - name: Disable password login\n      ansible.builtin.lineinfile:\n        path: /etc/ssh/sshd_config\n        regexp: '^#?PasswordAuthentication'\n        line: PasswordAuthentication no\n        validate: /usr/sbin/sshd -t -f %s\n      notify: Reload sshd\n  handlers:\n    - name: Reload sshd\n      ansible.builtin.service:\n        name: ssh\n        state: reloaded\nEOF","out":"","outKind":"","note":"The service is called ssh on Debian and Ubuntu and sshd on RHEL-family systems. Settings in files under /etc/ssh/sshd_config.d can override the main file.","risk":true,"viz":""},{"title":"Run and test from a second session","icon":"lucide-rocket","text":"Run on one host first with --limit, then test a fresh login before touching the others.","cmd":"ansible-playbook harden.yml --limit web1.example.com --check --diff\nansible-playbook harden.yml --limit web1.example.com\nssh opsadmin@web1.example.com hostname","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Prove the final state","icon":"lucide-check","text":"Read the effective settings back with sshd -T and rerun to confirm idempotence.","cmd":"ansible web1.example.com -b -m ansible.builtin.command -a \"sshd -T\" | grep -E 'permitrootlogin|passwordauthentication'\nansible-playbook harden.yml --limit web1.example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":18,"of":25,"prev":{"id":"ans-docker-project","title":"Project: install Docker Engine and run a container"},"next":{"id":"ans-rolling-update","title":"Rolling updates, error handling and block/rescue"}}},{"id":"ans-rolling-update","title":"Rolling updates, error handling and block/rescue","level":3,"icon":"lucide-repeat","summary":"Update servers one at a time, stop on trouble and clean up after a failure.","qna":[{"q":"In which situation do we use this?","a":"Updating a live fleet without taking all of it down at once."},{"q":"What do serial and max_fail_percentage do?","a":"serial runs a few hosts at a time; max_fail_percentage stops the whole run if too many fail."},{"q":"What comes next?","a":"Use block/rescue/always for cleanup and a rollback path."}],"steps":[{"title":"Why roll","icon":"lucide-repeat","text":"Updating every server at once risks taking the whole service down. serial updates a few hosts at a time and stops if the batch fails.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Control node → web1: update batch 1\nweb1 → Control node: ok\nControl node → web2: update batch 2\nweb2 → Control node: ok"},{"title":"serial and max_fail_percentage","icon":"lucide-layers","text":"serial: 1 updates one host per batch. max_fail_percentage: 0 aborts the play if any host in a batch fails, protecting the hosts that have not started.","cmd":"cat > rolling.yml <<'EOF'\n- name: Rolling restart\n  hosts: web\n  become: true\n  serial: 1\n  max_fail_percentage: 0\n  tasks:\n    - name: Take the host out of rotation (placeholder)\n      ansible.builtin.debug:\n        msg: \"drain {{ inventory_hostname }} from the load balancer here\"\n    - name: Restart Apache\n      ansible.builtin.service:\n        name: apache2\n        state: restarted\n    - name: Wait for port 80\n      ansible.builtin.wait_for:\n        port: 80\n        timeout: 30\n    - name: Put the host back (placeholder)\n      ansible.builtin.debug:\n        msg: \"return {{ inventory_hostname }} to the load balancer here\"\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run it and watch the batches","icon":"lucide-play","text":"Each host finishes the whole task list before the next host starts.","cmd":"ansible-playbook rolling.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"block, rescue and always","icon":"lucide-shield","text":"block groups tasks. If one fails, rescue runs. always runs in every case. This is Ansible's try, catch and finally.","cmd":"cat > block-demo.yml <<'EOF'\n- name: Safe change\n  hosts: web\n  become: true\n  tasks:\n    - name: Change with rollback\n      block:\n        - name: Apply new config\n          ansible.builtin.copy:\n            src: new.conf\n            dest: /etc/myapp.conf\n            backup: true\n        - name: Restart the app\n          ansible.builtin.service:\n            name: myapp\n            state: restarted\n      rescue:\n        - name: Report the failure\n          ansible.builtin.debug:\n            msg: \"restart failed on {{ inventory_hostname }}\"\n      always:\n        - name: Record the attempt\n          ansible.builtin.debug:\n            msg: \"finished on {{ inventory_hostname }}\"\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Stop everything on the first failure","icon":"lucide-circle-slash","text":"any_errors_fatal: true stops the play for every host as soon as one host fails. Use it for steps that must succeed everywhere or nowhere.","cmd":"printf '  any_errors_fatal: true\n' > any-errors.snippet","out":"","outKind":"","note":"Add the line at play level, next to hosts and become.","risk":false,"viz":""}],"nav":{"pos":19,"of":25,"prev":{"id":"ans-users-hardening","title":"Project: users, keys and SSH hardening"},"next":{"id":"ans-tags-limit-debug","title":"Run less, debug more: tags, limit and verbosity"}}},{"id":"ans-tags-limit-debug","title":"Run less, debug more: tags, limit and verbosity","level":2,"icon":"lucide-search","summary":"List what will run, narrow it with limit and tags, step through, and read verbose output.","qna":[{"q":"In which situation do we use this?","a":"A big playbook where you need to run one part, on one host, or see why a task failed."},{"q":"Which option for which need?","a":"--tags or --skip-tags pick tasks, --limit picks hosts, -v to -vvv increase detail."},{"q":"What comes next?","a":"Use --list-tasks and --list-hosts to preview what will run."}],"steps":[{"title":"List before you run","icon":"lucide-eye","text":"These options run nothing. They show which hosts, tasks and tags a playbook would use.","cmd":"ansible-playbook site.yml --list-hosts\nansible-playbook site.yml --list-tasks\nansible-playbook site.yml --list-tags","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Limit to some hosts","icon":"lucide-filter","text":"--limit narrows the play to a subset of its hosts. It is the safe way to try a change on one server first.","cmd":"ansible-playbook site.yml --limit web1.example.com\nansible-playbook site.yml --limit 'web:!web2.example.com'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run only some tasks with tags","icon":"lucide-bookmark","text":"Tag tasks in the playbook with tags: [name]. Then run or skip them by tag.","cmd":"ansible-playbook site.yml --tags packages\nansible-playbook site.yml --skip-tags config","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Start at a task or go step by step","icon":"lucide-play","text":"--start-at-task resumes at a named task. --step asks before each task, which is useful while learning.","cmd":"ansible-playbook site.yml --start-at-task \"Start and enable Apache\"\nansible-playbook site.yml --step","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verbosity levels","icon":"lucide-bug","text":"-v shows task results, -vv shows task input, -vvv shows connection details and -vvvv adds more SSH debugging. Increase one level at a time.","cmd":"ansible-playbook site.yml -v\nansible-playbook site.yml -vvv","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The debug module","icon":"lucide-search","text":"Print variables or messages inside the play. Use var to print a variable and msg to print text.","cmd":"ansible web -m ansible.builtin.debug -a \"var=ansible_host\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Lint your work","icon":"lucide-check","text":"ansible-lint checks playbooks against best practice, for example fully qualified module names and idempotence problems.","cmd":"ansible-lint site.yml\nyamllint .","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":20,"of":25,"prev":{"id":"ans-rolling-update","title":"Rolling updates, error handling and block/rescue"},"next":{"id":"ans-pull-cron","title":"Pull mode: ansible-pull on a schedule"}}},{"id":"ans-pull-cron","title":"Pull mode: ansible-pull on a schedule","level":3,"icon":"lucide-download","summary":"Let each server fetch its own playbook from Git and apply it, instead of a control node pushing to every host.","qna":[{"q":"In which situation do we use this?","a":"Servers that scale automatically, laptops, or machines behind NAT that the control node cannot reach."},{"q":"What do I give up compared to push?","a":"A single central run. You need logging and monitoring to confirm that every host applied the latest commit."},{"q":"What comes next?","a":"Use --only-if-changed and a random delay so a thousand hosts do not pull at the same second."}],"steps":[{"title":"When pull mode helps","icon":"lucide-globe","text":"Push mode needs the control node to reach every host. In pull mode each server runs ansible-pull itself, so it works for auto-scaled machines, laptops and hosts behind NAT.","cmd":"ansible --version\nansible-pull --help | head -n 4","out":"","outKind":"","note":"The trade-off: there is no central run, so you need logs and monitoring to know that every host actually applied the change.","risk":false,"viz":""},{"title":"A playbook in a repository","icon":"lucide-folder","text":"Pull mode needs the playbook in Git. A local.yml in the repo root is the default file ansible-pull looks for, and it targets localhost.","cmd":"mkdir -p ~/pull-demo && cd ~/pull-demo\nprintf -- '- hosts: localhost\n  connection: local\n  tasks:\n    - name: Write a marker file\n      ansible.builtin.copy:\n        content: \"managed by ansible-pull\\n\"\n        dest: /tmp/pull-marker.txt\n' > local.yml\ngit init -q && git add local.yml && git commit -qm \"Add local.yml\"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run it once","icon":"lucide-play","text":"-U gives the repository URL, -d the checkout folder, and -C the branch. A local path works for a test. Re-running when nothing changed reports ok, not changed.","cmd":"ansible-pull -U ~/pull-demo -d /tmp/pull-checkout local.yml\ncat /tmp/pull-marker.txt","out":"$ ansible-pull -U ~/pull-demo -d /tmp/pull-checkout local.yml\nPLAY RECAP *****\nlocalhost : ok=2 changed=1 unreachable=0 failed=0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Run it on a schedule","icon":"wf-cron","text":"Use a cron entry or a systemd timer. --only-if-changed skips the run when the repository has no new commits, and a random sleep spreads the load.","cmd":"echo '*/15 * * * * root ansible-pull -U https://git.example.com/ops/config.git -d /var/lib/ansible/pull --only-if-changed local.yml >> /var/log/ansible-pull.log 2>&1' | sudo tee /etc/cron.d/ansible-pull\nsudo systemctl status cron --no-pager | head -n 3","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check the result","icon":"lucide-eye","text":"Read the log for failures and add an alert when the last run is older than expected. Keep the repository read-only for the servers, using a deploy key.","cmd":"tail -n 5 /var/log/ansible-pull.log\nstat -c '%y' /tmp/pull-marker.txt","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":21,"of":25,"prev":{"id":"ans-tags-limit-debug","title":"Run less, debug more: tags, limit and verbosity"},"next":{"id":"ans-dynamic-inventory","title":"Dynamic inventory for AWS EC2"}}},{"id":"ans-dynamic-inventory","title":"Dynamic inventory for AWS EC2","level":3,"icon":"lucide-cloud","summary":"Let Ansible discover instances from AWS by tag instead of keeping a host list by hand.","qna":[{"q":"In which situation do we use this?","a":"Cloud servers that come and go. A static host list is out of date the moment an autoscaling group changes."},{"q":"How do I group hosts?","a":"Use keyed_groups on tags, such as Role=web becoming role_web, so playbooks target by role, not by address."},{"q":"What comes next?","a":"Enable caching and give the plugin a read-only IAM role."}],"steps":[{"title":"Why dynamic inventory","icon":"lucide-cloud","text":"In the cloud, servers appear and disappear. A static file goes stale. An inventory plugin asks the provider for the current list each time you run.","cmd":"ansible-galaxy collection install amazon.aws\npython3 -m pip install --user boto3 botocore","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Describe the plugin","icon":"lucide-file-text","text":"The file name must end in aws_ec2.yml. It names the regions, which tag filters to apply, and how to group the instances.","cmd":"printf 'plugin: amazon.aws.aws_ec2\nregions:\n  - ap-south-1\nfilters:\n  tag:Env: prod\n  instance-state-name: running\nkeyed_groups:\n  - key: tags.Role\n    prefix: role\nhostnames:\n  - private-ip-address\n' > aws_ec2.yml\ncat aws_ec2.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"List and inspect the result","icon":"wf-fact","text":"ansible-inventory shows the groups the plugin built. A tag Role=web becomes the group role_web. Credentials come from the usual AWS profile or environment variables.","cmd":"ansible-inventory -i aws_ec2.yml --graph\nansible-inventory -i aws_ec2.yml --host 10.0.10.15","out":"$ ansible-inventory -i aws_ec2.yml --graph\n@all:\n  |--@role_web:\n  |  |--10.0.10.15\n  |  |--10.0.11.22\n  |--@role_db:\n  |  |--10.0.20.8","outKind":"example","note":"","risk":false,"viz":""},{"title":"Target a group","icon":"wf-inventory","text":"Use the generated group exactly like a static one. Limit to a single host while you test.","cmd":"ansible role_web -i aws_ec2.yml -m ping\nansible-playbook -i aws_ec2.yml site.yml --limit role_web --check","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Make it fast and safe","icon":"lucide-timer","text":"Turn on caching so repeated runs do not call the API every time, and give the plugin a least-privilege IAM role that can only describe instances.","cmd":"printf 'cache: true\ncache_plugin: jsonfile\ncache_connection: /tmp/aws_inv_cache\ncache_timeout: 300\n' >> aws_ec2.yml","out":"","outKind":"","note":"Never put access keys in the inventory file. Use an instance profile, SSO or environment variables.","risk":false,"viz":""}],"nav":{"pos":22,"of":25,"prev":{"id":"ans-pull-cron","title":"Pull mode: ansible-pull on a schedule"},"next":{"id":"ans-async-retry","title":"Long tasks: async, poll, until and retries"}}},{"id":"ans-async-retry","title":"Long tasks: async, poll, until and retries","level":3,"icon":"lucide-refresh-cw","summary":"Wait for a service to come up, retry flaky steps, and run a slow job in the background.","qna":[{"q":"In which situation do we use this?","a":"A service needs time to start, a download is flaky, or a job takes longer than the SSH timeout."},{"q":"until or wait_for?","a":"wait_for suits ports and files. until with retries suits any module result, such as an HTTP status."},{"q":"What comes next?","a":"Prefer failed_when with a precise rule instead of ignore_errors."}],"steps":[{"title":"A task that must wait","icon":"lucide-clock","text":"After a restart a service needs a moment. A fixed pause is wasteful. until repeats a task until a condition is true, up to retries times with a delay between.","cmd":"printf -- '- hosts: web\n  tasks:\n    - name: Wait until the site answers\n      ansible.builtin.uri:\n        url: http://localhost/\n        status_code: 200\n      register: r\n      until: r.status == 200\n      retries: 10\n      delay: 3\n' > wait.yml\nansible-playbook wait.yml --check","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Wait for a port","icon":"lucide-plug","text":"wait_for is made for this. It polls a port and fails with a clear timeout message, which is better than a generic connection error later.","cmd":"printf -- '- hosts: web\n  tasks:\n    - ansible.builtin.wait_for:\n        port: 80\n        timeout: 60\n' > port.yml\nansible-playbook port.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run a slow job in the background","icon":"lucide-play","text":"async says the task may run up to that many seconds. poll: 0 means \"do not wait\", so Ansible fires and moves on. Save the job id and check it later with async_status.","cmd":"printf -- '- hosts: web\n  tasks:\n    - ansible.builtin.command: /usr/local/bin/long-backup.sh\n      async: 3600\n      poll: 0\n      register: job\n    - ansible.builtin.async_status:\n        jid: \"{{ job.ansible_job_id }}\"\n      register: res\n      until: res.finished\n      retries: 60\n      delay: 30\n' > async.yml\nansible-playbook async.yml --syntax-check","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Choose what counts as failure","icon":"lucide-triangle-alert","text":"failed_when and changed_when decide the result yourself. A command that prints a warning but works can be told not to fail, and a read-only command should never report changed.","cmd":"printf -- '- hosts: web\n  tasks:\n    - ansible.builtin.command: grep -c error /var/log/app.log\n      register: c\n      changed_when: false\n      failed_when: c.rc > 1\n' > rc.yml\nansible-playbook rc.yml --syntax-check","out":"","outKind":"","note":"Use ignore_errors sparingly. It hides real problems; prefer failed_when with a precise rule.","risk":false,"viz":""}],"nav":{"pos":23,"of":25,"prev":{"id":"ans-dynamic-inventory","title":"Dynamic inventory for AWS EC2"},"next":{"id":"ans-molecule-test","title":"Test a role with Molecule"}}},{"id":"ans-molecule-test","title":"Test a role with Molecule","level":4,"icon":"lucide-flask-conical","summary":"Create a role, run it in a throwaway container, check it with a verify step, and run the loop in CI.","qna":[{"q":"In which situation do we use this?","a":"A role is shared or critical and you want proof it works on a clean machine, and that a second run changes nothing."},{"q":"What does molecule test do?","a":"It creates an instance, converges, repeats to check idempotence, verifies, and destroys the instance."},{"q":"What comes next?","a":"Run it in CI on every pull request."}],"steps":[{"title":"Install the tools","icon":"lucide-download","text":"Molecule creates a test instance, applies your role, checks it is idempotent and runs verification. Containers make that fast. You need Docker or Podman on the machine.","cmd":"python3 -m pip install --user molecule molecule-plugins[docker] ansible-lint\nmolecule --version","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Scaffold a role with a scenario","icon":"lucide-folder","text":"ansible-galaxy init makes the role folders. molecule init scenario adds molecule/default with a platform file, a converge playbook and a verify playbook.","cmd":"ansible-galaxy role init webtest\ncd webtest\nmolecule init scenario default --driver-name docker\nls molecule/default","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the role and the check","icon":"lucide-pencil","text":"The role installs and starts nginx. verify.yml asserts what must be true afterwards. Tests state the expected result, not the steps.","cmd":"printf -- '- name: Install nginx\n  ansible.builtin.package:\n    name: nginx\n    state: present\n' > tasks/main.yml\nprintf -- '- hosts: all\n  tasks:\n    - ansible.builtin.package_facts:\n    - ansible.builtin.assert:\n        that: \"\\x27nginx\\x27 in ansible_facts.packages\"\n' > molecule/default/verify.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run the whole loop","icon":"wf-loop","text":"molecule test creates the container, converges, runs a second time to prove idempotence, verifies, then destroys everything. During development use converge and verify to stay fast.","cmd":"molecule test\nmolecule converge && molecule verify","out":"$ molecule test\nINFO     Running default > idempotence\nINFO     Idempotence completed successfully.\nINFO     Running default > verify\nINFO     Verifier completed successfully.","outKind":"example","note":"","risk":false,"viz":""},{"title":"Lint and run it in CI","icon":"lucide-door-open","text":"Run ansible-lint and molecule test on every pull request so a role cannot be merged broken.","cmd":"ansible-lint .\nprintf 'name: role-test\non: [pull_request]\njobs:\n  molecule:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pip install molecule molecule-plugins[docker] ansible-lint\n      - run: molecule test\n' > ../molecule-ci.yml","out":"","outKind":"","note":"A pipeline that runs molecule test is the best evidence that a role is idempotent.","risk":false,"viz":""}],"nav":{"pos":24,"of":25,"prev":{"id":"ans-async-retry","title":"Long tasks: async, poll, until and retries"},"next":{"id":"ans-kubernetes-k8s","title":"Manage Kubernetes objects with kubernetes.core.k8s"}}},{"id":"ans-kubernetes-k8s","title":"Manage Kubernetes objects with kubernetes.core.k8s","level":4,"icon":"lucide-container","summary":"Apply a namespace, a deployment and a service from a playbook, wait for readiness and clean up.","qna":[{"q":"In which situation do we use this?","a":"You already use Ansible and want cluster objects managed in the same repository and pipeline as the servers."},{"q":"Ansible or kubectl and Helm?","a":"Ansible is handy when Kubernetes is one part of a bigger run. For pure application delivery, Helm or GitOps tools are usually a better fit."},{"q":"What comes next?","a":"Check kubectl config current-context before every run, so you do not change the wrong cluster."}],"steps":[{"title":"Prepare the collection and access","icon":"lucide-download","text":"The collection talks to the cluster API with the Python kubernetes client, using your kubeconfig. Check access first with kubectl.","cmd":"ansible-galaxy collection install kubernetes.core\npython3 -m pip install --user kubernetes\nkubectl config current-context\nkubectl get nodes","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a namespace","icon":"lucide-plus","text":"The k8s module is declarative: state present creates or updates, absent deletes. Run it twice and the second run reports ok.","cmd":"printf -- '- hosts: localhost\n  gather_facts: false\n  tasks:\n    - name: Namespace\n      kubernetes.core.k8s:\n        state: present\n        definition:\n          apiVersion: v1\n          kind: Namespace\n          metadata:\n            name: demo\n' > k8s.yml\nansible-playbook k8s.yml","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Deploy an application","icon":"lucide-rocket","text":"Put the manifest in a template and fill in image and replica count from variables. wait makes the task finish only when the Deployment is available, so later tasks can rely on it.","cmd":"printf -- '    - name: Deployment\n      kubernetes.core.k8s:\n        state: present\n        wait: true\n        wait_timeout: 120\n        definition:\n          apiVersion: apps/v1\n          kind: Deployment\n          metadata: {name: web, namespace: demo}\n          spec:\n            replicas: 2\n            selector: {matchLabels: {app: web}}\n            template:\n              metadata: {labels: {app: web}}\n              spec:\n                containers:\n                  - {name: web, image: nginx:1.27}\n' >> k8s.yml\nansible-playbook k8s.yml --check --diff","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Read state back","icon":"lucide-eye","text":"k8s_info returns the live object so you can assert on it or print a field.","cmd":"kubectl -n demo get deploy web\nkubectl -n demo get pods -l app=web","out":"$ kubectl -n demo get deploy web\nNAME   READY   UP-TO-DATE   AVAILABLE   AGE\nweb    2/2     2            2           41s","outKind":"example","note":"","risk":false,"viz":""},{"title":"Update and clean up","icon":"lucide-eraser","text":"Change the image tag in the variable and run again; Kubernetes rolls the pods. Delete with state absent, namespace last.","cmd":"kubectl -n demo rollout status deploy/web\nkubectl delete namespace demo","out":"","outKind":"","note":"Test against a development cluster. Check the context before every run.","risk":true,"viz":""}],"nav":{"pos":25,"of":25,"prev":{"id":"ans-molecule-test","title":"Test a role with Molecule"},"next":null}}]},{"id":"network","name":"Networking","color":"#4F46E5","tagline":"Ping, ping-pong, IP addressing, DNS, HTTP, TCP, routing, NAT, firewalls, TLS, VPC design and a troubleshooting method.","icon":"net-router","workflows":[{"id":"net-ping","title":"Ping: echo request and reply","level":1,"icon":"lucide-zap","summary":"What ping really sends, how to read its output, how to ping in layers and what to do when it fails.","qna":[{"q":"In which situation do we use this?","a":"First check that a host is reachable, and to measure round-trip delay and packet loss."},{"q":"What does a failed ping prove?","a":"Not much alone: many networks block ICMP on purpose. Test the real port with curl or nc as well."},{"q":"What comes next?","a":"net-traceroute to see where packets stop."}],"steps":[{"title":"What ping does","icon":"lucide-zap","text":"ping sends a small ICMP echo request to another machine. If that machine is up and allows it, it sends back an echo reply. The time between the two is the round-trip time (RTT). It tests two things at once: can I reach it, and how long does the round trip take.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"You → Server: ICMP echo request\nServer → You: ICMP echo reply"},{"title":"Send four pings","icon":"lucide-play","text":"-c 4 sends four requests and then stops. Without -c, Linux and macOS ping forever until you press Ctrl+C.","cmd":"ping -c 4 8.8.8.8","out":"PING 8.8.8.8 (8.8.8.8) 56(84) bytes of data.\n64 bytes from 8.8.8.8: icmp_seq=1 ttl=117 time=12.4 ms\n64 bytes from 8.8.8.8: icmp_seq=2 ttl=117 time=11.9 ms\n64 bytes from 8.8.8.8: icmp_seq=3 ttl=117 time=12.1 ms\n64 bytes from 8.8.8.8: icmp_seq=4 ttl=117 time=12.0 ms\n\n--- 8.8.8.8 ping statistics ---\n4 packets transmitted, 4 received, 0% packet loss, time 3004ms\nrtt min/avg/max/mdev = 11.9/12.1/12.4/0.2 ms","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the numbers","icon":"lucide-eye","text":"icmp_seq counts the requests. ttl is the remaining hop limit: each router subtracts one, which hints at distance. time is the round trip in milliseconds. The summary shows packet loss, which should be 0%, and the min, average and maximum RTT. Large differences between min and max (jitter) mean an unstable path.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Ping in layers","icon":"lucide-layers","text":"Work outward. Yourself first (is the network stack working), then your gateway (is the local link working), then an internet address (is routing working), then a name (is DNS working).","cmd":"ping -c 2 127.0.0.1\nping -c 2 $(ip route | awk '/default/ {print $3; exit}')\nping -c 2 1.1.1.1\nping -c 2 example.com","out":"","outKind":"","note":"The ip route line is Linux. On macOS use: route -n get default | awk '/gateway/ {print $2}'.","risk":false,"viz":""},{"title":"Useful options","icon":"lucide-sliders-horizontal","text":"-i sets the interval, -W sets how long to wait for a reply, and -s sets the payload size. On Linux, -M do forbids fragmentation, which finds the largest size that fits through the path (a quick MTU test).","cmd":"ping -c 3 -i 0.5 example.com\nping -c 3 -W 2 192.0.2.1\nping -c 3 -M do -s 1472 example.com","out":"","outKind":"","note":"1472 bytes of payload plus 28 bytes of headers makes a 1500-byte packet, the usual Ethernet MTU.","risk":false,"viz":""},{"title":"When ping fails","icon":"lucide-triangle-alert","text":"No reply does not always mean the host is down. A firewall may drop ICMP, as many cloud security groups do by default. \"Destination Host Unreachable\" comes from a router on the way. \"Request timeout\" means silence. Test the real service instead of ICMP.","cmd":"nc -vz example.com 443\ncurl -sS -o /dev/null -w \"%{http_code}\\n\" https://example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":1,"of":26,"prev":null,"next":{"id":"net-ping-pong","title":"Ping-pong: request and response"}}},{"id":"net-ping-pong","title":"Ping-pong: request and response","level":1,"icon":"lucide-repeat","summary":"The simplest networking idea: one side sends, the other answers. See it with ICMP, then write your own ping and pong programs.","qna":[{"q":"In which situation do we use this?","a":"To learn how any client and server talk: a request goes out, a response comes back."},{"q":"Why teach it with code?","a":"A tiny socket server and client show that a protocol is just agreed messages over a connection."},{"q":"What comes next?","a":"net-tcp-ports and net-http build on the same pattern."}],"steps":[{"title":"Ping-pong is a conversation","icon":"lucide-repeat","text":"In table tennis you hit the ball and your opponent hits it back. Networks work the same way: a client sends a request (ping) and a server sends a response (pong). The time between your hit and the return is the round-trip time. HTTP, DNS and SSH all follow this request and response pattern.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Client → Server: ping (request)\nServer → Client: pong (response)\nClient → Server: ping (request)\nServer → Client: pong (response)"},{"title":"The same idea in ICMP","icon":"lucide-zap","text":"The ping command is exactly this: an echo request out, an echo reply back. Run it and watch the time value, which is one full round trip.","cmd":"ping -c 3 127.0.0.1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the pong server","icon":"lucide-pencil","text":"This small Python program listens on your own machine (127.0.0.1) on port 5000, waits for a connection and answers every message it receives with \"pong\". It handles three rounds, then stops.","cmd":"cat > pong_server.py <<'EOF'\nimport socket\ns = socket.socket()\ns.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\ns.bind((\"127.0.0.1\", 5000))\ns.listen(1)\nprint(\"server: waiting for a ping on 127.0.0.1:5000\")\nconn, addr = s.accept()\nwith conn:\n    for _ in range(3):\n        data = conn.recv(16)\n        print(\"server: got\", data.decode().strip())\n        conn.sendall(b\"pong\\n\")\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the ping client","icon":"lucide-pencil","text":"The client connects, sends \"ping\", waits for the answer and prints it. It does this three times.","cmd":"cat > ping_client.py <<'EOF'\nimport socket\nc = socket.create_connection((\"127.0.0.1\", 5000))\nfor _ in range(3):\n    c.sendall(b\"ping\\n\")\n    print(\"client: sent ping, got\", c.recv(16).decode().strip())\nc.close()\nEOF","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Run both: two terminals","icon":"lucide-play","text":"Start the server in terminal A first, then run the client in terminal B. Each ping from the client triggers one pong from the server.","cmd":"python3 pong_server.py\npython3 ping_client.py","out":"[terminal A]\nserver: waiting for a ping on 127.0.0.1:5000\nserver: got ping\nserver: got ping\nserver: got ping\n\n[terminal B]\nclient: sent ping, got pong\nclient: sent ping, got pong\nclient: sent ping, got pong","outKind":"example","note":"If the port is in use, change 5000 to another number in both files.","risk":false,"viz":""},{"title":"Measure the round trip","icon":"lucide-timer","text":"Time each round trip with a high-resolution clock. On loopback it is tiny (well under a millisecond). Over the internet it is the time you saw with ping.","cmd":"cat > ping_timed.py <<'EOF'\nimport socket, time\nc = socket.create_connection((\"127.0.0.1\", 5000))\nfor i in range(3):\n    t0 = time.perf_counter()\n    c.sendall(b\"ping\\n\")\n    c.recv(16)\n    print(f\"round {i + 1}: {(time.perf_counter() - t0) * 1000:.3f} ms\")\nc.close()\nEOF\npython3 pong_server.py\npython3 ping_timed.py","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"From ping-pong to real protocols","icon":"lucide-globe","text":"HTTP is ping-pong with longer messages: a request line and headers out, a status line, headers and a body back. Start a tiny web server and watch one exchange with curl -v.","cmd":"python3 -m http.server 8000 --bind 127.0.0.1\ncurl -sv http://127.0.0.1:8000/ -o /dev/null","out":"> GET / HTTP/1.1\n> Host: 127.0.0.1:8000\n> User-Agent: curl/8.x\n>\n< HTTP/1.0 200 OK\n< Content-type: text/html; charset=utf-8","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":2,"of":26,"prev":{"id":"net-ping","title":"Ping: echo request and reply"},"next":{"id":"net-osi-tcpip","title":"Network layers: OSI and TCP/IP"}}},{"id":"net-osi-tcpip","title":"Network layers: OSI and TCP/IP","level":1,"icon":"lucide-layers","summary":"The layer model that explains where each tool, device and protocol works.","qna":[{"q":"In which situation do we use this?","a":"To decide where a problem lives: cable and Wi-Fi, IP routing, TCP port, or the application."},{"q":"How do I use the layers?","a":"Test bottom up: link, IP, TCP port, then the application protocol. The first failing layer is your suspect."},{"q":"What comes next?","a":"net-troubleshoot-method turns this into a checklist."}],"steps":[{"title":"Why layers","icon":"lucide-layers","text":"Networking is split into layers so each does one job and can change without breaking the others. Your browser does not care whether the cable is copper or Wi-Fi.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The seven OSI layers","icon":"lucide-table","text":"7 Application (HTTP, DNS, SSH). 6 Presentation (encoding, TLS). 5 Session (conversations). 4 Transport (TCP, UDP, ports). 3 Network (IP, routing). 2 Data link (Ethernet, MAC addresses). 1 Physical (cables, radio, signals). A common memory aid, from layer 7 down: All People Seem To Need Data Processing.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The four-layer TCP/IP model","icon":"lucide-layers","text":"The internet uses a simpler model: Application (OSI 5 to 7), Transport (4), Internet (3) and Link (1 and 2). You will see both names in documentation, so learn how they map.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Encapsulation: wrapping data on the way down","icon":"lucide-package","text":"Your data gets a header at each layer. The application data becomes a TCP segment (with ports), then an IP packet (with addresses), then an Ethernet frame (with MAC addresses). The receiver unwraps in reverse order.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"App data → TCP segment: add ports\nTCP segment → IP packet: add IP addresses\nIP packet → Ethernet frame: add MAC addresses\nEthernet frame → Wire: send bits"},{"title":"One tool per layer","icon":"lucide-search","text":"Link: ip link and ip neigh. Network: ip addr, ip route, ping. Transport: ss, nc. Application: curl and dig. When something fails, test one layer at a time from the bottom.","cmd":"ip -br link\nip -br addr\nss -tn | head -n 5\ncurl -sI https://example.com | head -n 1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Which device works at which layer","icon":"lucide-network","text":"A switch forwards frames by MAC address (layer 2). A router forwards packets by IP address (layer 3). A firewall filters by IP and port (layers 3 and 4, or up to 7 for a next-generation firewall). A load balancer works at layer 4 (TCP) or layer 7 (HTTP).","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":3,"of":26,"prev":{"id":"net-ping-pong","title":"Ping-pong: request and response"},"next":{"id":"net-ip-cidr","title":"IP addresses and CIDR"}}},{"id":"net-ip-cidr","title":"IP addresses and CIDR","level":1,"icon":"lucide-calculator","summary":"Read an address and a prefix, calculate masks and sizes, split a network and check membership. The numbers shown were produced with Python's ipaddress module.","qna":[{"q":"In which situation do we use this?","a":"Planning networks, reading security rules, or deciding whether two addresses can talk directly."},{"q":"How do I read /24?","a":"The first 24 bits are the network and the last 8 bits are hosts: 256 addresses, 254 usable in classic subnets."},{"q":"What comes next?","a":"net-subnet-plan applies it to a VPC."}],"steps":[{"title":"An IPv4 address","icon":"lucide-calculator","text":"An IPv4 address is 32 bits, written as four numbers from 0 to 255, like 192.168.1.10. Part of it identifies the network and the rest identifies the host on that network.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The prefix length (CIDR)","icon":"lucide-table","text":"192.168.1.0/24 means the first 24 bits are the network and the last 8 bits are for hosts. A bigger number after the slash means a smaller network. The subnet mask is the same idea written as an address: /24 is 255.255.255.0.","cmd":"python3 -c \"import ipaddress as i; n = i.ip_network('192.168.1.0/24'); print(n.netmask, n.num_addresses)\"","out":"255.255.255.0 256","outKind":"example","note":"","risk":false,"viz":""},{"title":"Usable hosts","icon":"lucide-calendar","text":"The first address is the network address and the last is the broadcast address, so a /24 has 256 - 2 = 254 usable hosts. In a /26 there are 64 addresses and 62 usable.","cmd":"python3 -c \"import ipaddress as i; n = i.ip_network('192.168.1.0/24'); print(n.num_addresses - 2)\"","out":"254","outKind":"example","note":"AWS reserves five addresses in every subnet, not two, so a /24 gives 251 usable addresses there.","risk":false,"viz":""},{"title":"Split a network","icon":"lucide-git-branch","text":"Carve a /24 into four /26 networks. Each has 62 usable hosts.","cmd":"python3 -c \"import ipaddress as i; [print(s, s.netmask, s.num_addresses - 2) for s in i.ip_network('192.168.1.0/24').subnets(new_prefix=26)]\"","out":"192.168.1.0/26 255.255.255.192 62\n192.168.1.64/26 255.255.255.192 62\n192.168.1.128/26 255.255.255.192 62\n192.168.1.192/26 255.255.255.192 62","outKind":"example","note":"","risk":false,"viz":""},{"title":"Private ranges","icon":"lucide-lock","text":"Three blocks are reserved for private use and are not routed on the internet: 10.0.0.0/8 (16,777,216 addresses), 172.16.0.0/12 (1,048,576) and 192.168.0.0/16 (65,536). Home and cloud networks use them, with NAT for internet access.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Is an address inside a network?","icon":"lucide-search","text":"Checking membership by hand is error-prone. Let the library do it.","cmd":"python3 -c \"import ipaddress as i; print(i.ip_address('192.168.1.130') in i.ip_network('192.168.1.128/26'))\"\npython3 -c \"import ipaddress as i; print(i.ip_network('10.0.0.0/16').overlaps(i.ip_network('10.0.5.0/24')))\"","out":"True","outKind":"example","note":"","risk":false,"viz":""}],"nav":{"pos":4,"of":26,"prev":{"id":"net-osi-tcpip","title":"Network layers: OSI and TCP/IP"},"next":{"id":"net-subnet-plan","title":"Project: plan VPC subnets"}}},{"id":"net-subnet-plan","title":"Project: plan VPC subnets","level":3,"icon":"lucide-table","summary":"Design a /16 network into public, application and database subnets across two availability zones, and prove there are no overlaps.","qna":[{"q":"In which situation do we use this?","a":"Before creating a VPC: choose a CIDR that fits public, app and database tiers in several zones without overlap."},{"q":"What goes wrong?","a":"Overlapping ranges block peering and VPN later. Plan for growth and for other networks you will connect."},{"q":"What comes next?","a":"net-aws-vpc builds the plan."}],"steps":[{"title":"Requirements","icon":"lucide-target","text":"A web application across two availability zones (AZ a and b) with three tiers: public (load balancer), application and database. The database must have no route to the internet. Leave room to grow.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Choose the VPC range","icon":"lucide-cloud","text":"A /16 gives 65,536 addresses, plenty for several tiers. Pick a range that does not overlap with your office network or other VPCs you may connect later, since overlapping ranges cannot be routed together.","cmd":"python3 -c \"import ipaddress as i; print(i.ip_network('10.0.0.0/16').num_addresses)\"","out":"65536","outKind":"example","note":"","risk":false,"viz":""},{"title":"Carve the subnets","icon":"lucide-git-branch","text":"Use /24 subnets (256 addresses each) and leave gaps between tiers so each tier can add more later. Public 10.0.0.0/24 and 10.0.1.0/24. Application 10.0.10.0/24 and 10.0.11.0/24. Database 10.0.20.0/24 and 10.0.21.0/24.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Prove the plan with a script","icon":"lucide-check","text":"Check that every subnet is inside the VPC and none overlap. A paper plan always hides one mistake.","cmd":"python3 - <<'EOF'\nimport ipaddress as ip\nvpc = ip.ip_network('10.0.0.0/16')\nplan = {'public-a': '10.0.0.0/24', 'public-b': '10.0.1.0/24', 'app-a': '10.0.10.0/24', 'app-b': '10.0.11.0/24', 'db-a': '10.0.20.0/24', 'db-b': '10.0.21.0/24'}\nnets = {k: ip.ip_network(v) for k, v in plan.items()}\nprint('all inside the VPC:', all(n.subnet_of(vpc) for n in nets.values()))\nnames = list(nets)\nclash = [(a, b) for i, a in enumerate(names) for b in names[i + 1:] if nets[a].overlaps(nets[b])]\nprint('overlaps:', clash or 'none')\nfor k, n in nets.items():\n    print(k, n, n.num_addresses - 5, 'usable on AWS')\nEOF","out":"all inside the VPC: True\noverlaps: none\npublic-a 10.0.0.0/24 251 usable on AWS\npublic-b 10.0.1.0/24 251 usable on AWS\napp-a 10.0.10.0/24 251 usable on AWS\napp-b 10.0.11.0/24 251 usable on AWS\ndb-a 10.0.20.0/24 251 usable on AWS\ndb-b 10.0.21.0/24 251 usable on AWS","outKind":"example","note":"","risk":false,"viz":""},{"title":"Decide the routing for each tier","icon":"lucide-signpost","text":"Public subnets route 0.0.0.0/0 to an internet gateway. Application subnets route 0.0.0.0/0 to a NAT gateway in a public subnet (outbound only). Database subnets have no default route at all.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Write the plan down","icon":"lucide-file-text","text":"Keep the table in Git next to your infrastructure code so everyone uses the same ranges, and update it before creating a subnet.","cmd":"printf 'name,cidr,az,tier\npublic-a,10.0.0.0/24,a,public\npublic-b,10.0.1.0/24,b,public\napp-a,10.0.10.0/24,a,app\napp-b,10.0.11.0/24,b,app\ndb-a,10.0.20.0/24,a,db\ndb-b,10.0.21.0/24,b,db\n' > subnets.csv\ncolumn -s, -t subnets.csv","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":5,"of":26,"prev":{"id":"net-ip-cidr","title":"IP addresses and CIDR"},"next":{"id":"net-dns","title":"DNS: from name to address"}}},{"id":"net-dns","title":"DNS: from name to address","level":2,"icon":"lucide-book-open","summary":"Resolve names with dig, read record types and TTLs, follow the lookup chain and check which resolver you use.","qna":[{"q":"In which situation do we use this?","a":"A name does not resolve, resolves to the wrong address, or a change has not taken effect yet."},{"q":"Which tool?","a":"dig shows the record and its TTL; dig +trace follows the chain from the root; resolvectl shows what the host uses."},{"q":"What comes next?","a":"Remember that TTL controls how long old answers are cached."}],"steps":[{"title":"What DNS does","icon":"lucide-book-open","text":"DNS is the internet's phone book. It turns a name like example.com into an IP address. Your machine asks a resolver, which asks other servers if it does not know the answer, and caches the result for the record's TTL.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Your PC → Resolver: what is example.com?\nResolver → Root and TLD servers: ask down the chain\nResolver → Your PC: 203.0.113.10"},{"title":"Look up a name","icon":"lucide-search","text":"dig prints the question, the answer and the query time. +short prints only the answer.","cmd":"dig example.com A\ndig +short example.com A","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Record types","icon":"lucide-table","text":"A holds an IPv4 address, AAAA an IPv6 address, CNAME an alias to another name, MX a mail server, TXT free text (SPF, verification) and NS the name servers for the zone.","cmd":"dig +short example.com AAAA\ndig +short example.com MX\ndig +short example.com TXT\ndig +short example.com NS","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"TTL and caching","icon":"lucide-clock","text":"Each answer carries a TTL, in seconds, that says how long it may be cached. Ask twice and the second answer shows a smaller TTL. This is why DNS changes can take a while to spread.","cmd":"dig example.com A +noall +answer","out":"example.com.  3600  IN  A  203.0.113.10","outKind":"example","note":"","risk":false,"viz":""},{"title":"Ask a specific server","icon":"lucide-pin","text":"@server sends the query to that server instead of your default. Comparing answers from two servers is the quickest way to find a stale cache.","cmd":"dig @8.8.8.8 example.com A +short\ndig @1.1.1.1 example.com A +short","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Follow the whole chain","icon":"lucide-arrow-right","text":"+trace starts at the root servers and follows each delegation down to the answer.","cmd":"dig +trace example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Which resolver am I using?","icon":"lucide-settings","text":"On a systemd-resolved system, resolvectl shows the servers and domains per interface. Otherwise read /etc/resolv.conf.","cmd":"resolvectl status | head -n 15\ncat /etc/resolv.conf\nresolvectl query example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":6,"of":26,"prev":{"id":"net-subnet-plan","title":"Project: plan VPC subnets"},"next":{"id":"net-http","title":"HTTP with curl"}}},{"id":"net-http","title":"HTTP with curl","level":2,"icon":"lucide-globe","summary":"Read a request and a response, headers, status codes and methods, and measure where the time goes.","qna":[{"q":"In which situation do we use this?","a":"Testing a web service or API from the terminal, without a browser."},{"q":"Which curl options help?","a":"-I for headers only, -v for the full exchange, -L to follow redirects, -w for timing."},{"q":"What comes next?","a":"net-tls when the failure is about certificates."}],"steps":[{"title":"A request and a response","icon":"lucide-repeat","text":"A client sends a request line (method and path), headers and sometimes a body. The server answers with a status line, headers and a body.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Client → Server: GET /index.html\nServer → Client: 200 OK + HTML"},{"title":"See the whole exchange","icon":"lucide-eye","text":"-v prints the request lines starting with > and the response lines starting with <. -s hides the progress bar and -o /dev/null hides the body.","cmd":"curl -sv https://example.com -o /dev/null","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Headers only","icon":"lucide-file-text","text":"-I sends a HEAD request, which asks for headers without the body. It is the quickest health check.","cmd":"curl -sI https://example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Status codes","icon":"lucide-table","text":"2xx success (200 OK, 201 Created). 3xx redirect (301 moved, 302 found). 4xx client error (400 bad request, 401 unauthenticated, 403 forbidden, 404 not found, 429 too many requests). 5xx server error (500, 502 bad gateway, 503 unavailable, 504 gateway timeout).","cmd":"curl -s -o /dev/null -w \"%{http_code}\\n\" https://example.com\ncurl -s -o /dev/null -w \"%{http_code}\\n\" https://example.com/does-not-exist","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Methods and a body","icon":"lucide-upload","text":"GET reads, POST creates, PUT replaces, PATCH changes part, DELETE removes. -X sets the method, -H adds a header and -d sends a body.","cmd":"curl -s -X POST https://httpbin.org/post -H \"Content-Type: application/json\" -d '{\"name\":\"alice\"}'","out":"","outKind":"","note":"httpbin.org is a public test service. Do not send real data to it.","risk":false,"viz":""},{"title":"Where did the time go?","icon":"lucide-timer","text":"curl can print timings. The gaps show DNS time, connection time, TLS time, time to first byte and the total.","cmd":"curl -s -o /dev/null -w \"dns:%{time_namelookup} connect:%{time_connect} tls:%{time_appconnect} ttfb:%{time_starttransfer} total:%{time_total}\\n\" https://example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Follow redirects and set a timeout","icon":"lucide-refresh-cw","text":"-L follows redirects. --max-time stops a hanging request, which every script needs.","cmd":"curl -sL --max-time 10 -o /dev/null -w \"%{url_effective} %{http_code}\\n\" http://example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":7,"of":26,"prev":{"id":"net-dns","title":"DNS: from name to address"},"next":{"id":"net-tcp-ports","title":"TCP, ports and listening sockets"}}},{"id":"net-tcp-ports","title":"TCP, ports and listening sockets","level":2,"icon":"lucide-plug","summary":"The three-way handshake, what a port is, and how to see and test what is listening.","qna":[{"q":"In which situation do we use this?","a":"A service is running but cannot be reached: check whether it is actually listening, and on which address."},{"q":"What does 127.0.0.1 versus 0.0.0.0 mean?","a":"127.0.0.1 accepts only local connections; 0.0.0.0 accepts from every interface."},{"q":"What comes next?","a":"ss -tulpn lists listeners and the owning process."}],"steps":[{"title":"What a port is","icon":"lucide-plug","text":"An IP address finds the machine and a port finds the program on it. Well-known ports include 22 SSH, 53 DNS, 80 HTTP, 443 HTTPS, 3306 MySQL and 5432 PostgreSQL.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The three-way handshake","icon":"lucide-repeat","text":"TCP opens a connection with three messages. SYN: the client asks to connect. SYN-ACK: the server agrees. ACK: the client confirms. Only then does data flow.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Client → Server: SYN\nServer → Client: SYN-ACK\nClient → Server: ACK\nClient → Server: data"},{"title":"What is listening?","icon":"lucide-search","text":"-t TCP, -u UDP, -l listening, -p the process, -n numbers instead of names. The local address column matters: 127.0.0.1 is reachable only from this machine, 0.0.0.0 from anywhere.","cmd":"sudo ss -tulpn","out":"Netid State  Local Address:Port  Process\ntcp   LISTEN 0.0.0.0:22          users:((\"sshd\",pid=812,fd=3))\ntcp   LISTEN 127.0.0.1:5432      users:((\"postgres\",pid=990,fd=6))","outKind":"example","note":"","risk":false,"viz":""},{"title":"Test a port from another machine","icon":"lucide-check","text":"nc -vz tries a connection and reports success or failure without sending data. This is better than ping when ICMP is blocked.","cmd":"nc -vz web1.example.com 443\nnc -vz -w 3 web1.example.com 8443","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Connection states","icon":"lucide-clipboard-list","text":"ESTABLISHED is a live connection. TIME_WAIT is a recently closed one that lingers briefly. A very large number of CLOSE_WAIT sockets points to an application that does not close its connections. ss -s summarises them.","cmd":"ss -s\nss -tan state established | head -n 5","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Connection refused or timed out?","icon":"lucide-triangle-alert","text":"Refused means the machine answered and nothing listens on that port, or a firewall rejected it. Timed out means silence, usually a firewall dropping packets or no route. They point to different fixes.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":8,"of":26,"prev":{"id":"net-http","title":"HTTP with curl"},"next":{"id":"net-traceroute","title":"Traceroute and mtr: follow the path"}}},{"id":"net-traceroute","title":"Traceroute and mtr: follow the path","level":2,"icon":"lucide-arrow-right","summary":"See each router on the way to a destination, read the output and find where latency or loss starts.","qna":[{"q":"In which situation do we use this?","a":"A connection is slow or fails somewhere in the middle and you want to see which hop is responsible."},{"q":"How do I read stars?","a":"A hop showing * may just not reply to probes. Judge by whether later hops respond."},{"q":"What comes next?","a":"mtr combines ping and traceroute for a live view."}],"steps":[{"title":"How traceroute works","icon":"lucide-arrow-right","text":"Every packet has a TTL that each router lowers by one. A router that lowers it to zero drops the packet and reports back. traceroute sends packets with TTL 1, 2, 3 and so on, so each router in turn reveals itself.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"You → Router 1: TTL=1\nRouter 1 → You: time exceeded\nYou → Router 2: TTL=2\nRouter 2 → You: time exceeded"},{"title":"Run it","icon":"lucide-play","text":"-n skips name lookups, which makes it faster and the output cleaner.","cmd":"traceroute -n example.com","out":"1  192.168.1.1  1.2 ms\n2  10.20.0.1  8.4 ms\n3  * * *\n4  203.0.113.1  15.9 ms","outKind":"example","note":"","risk":false,"viz":""},{"title":"Read the output","icon":"lucide-eye","text":"Each line is one hop with three timing samples. Stars mean that router did not answer, which is common and usually harmless if later hops answer. Look for where latency jumps and stays high.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"mtr: traceroute plus ping","icon":"lucide-chart-line","text":"mtr repeats the trace and keeps statistics, so loss and jitter per hop become visible. -r makes a report, -w uses wide names and -c sets the cycles.","cmd":"mtr -rwc 10 example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Other protocols","icon":"lucide-search","text":"Some networks drop the default UDP probes. Try ICMP (-I) or TCP to a real port (-T), which often passes firewalls.","cmd":"sudo traceroute -I -n example.com\nsudo traceroute -T -p 443 -n example.com","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":9,"of":26,"prev":{"id":"net-tcp-ports","title":"TCP, ports and listening sockets"},"next":{"id":"net-nat","title":"NAT and private addresses"}}},{"id":"net-nat","title":"NAT and private addresses","level":2,"icon":"lucide-repeat","summary":"How many private machines share one public address, and how port forwarding lets the outside reach in.","qna":[{"q":"In which situation do we use this?","a":"Private instances need to reach the internet, or many devices share one public address."},{"q":"What does NAT hide?","a":"Private source addresses. The router rewrites them and tracks connections so replies find the right host."},{"q":"What comes next?","a":"In AWS, a NAT gateway in a public subnet serves private subnets."}],"steps":[{"title":"The problem NAT solves","icon":"lucide-lock","text":"There are not enough public IPv4 addresses for every device. Home and cloud networks use private addresses (10.x, 172.16-31.x, 192.168.x), which cannot be routed on the internet. NAT rewrites addresses at the border so private machines can still reach the internet.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Source NAT: going out","icon":"lucide-upload","text":"A private machine sends a packet. The router replaces its source address with the router's public address and remembers the mapping. The reply comes back to the router, which translates it back.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"10.0.1.5 → NAT router: to 93.184.216.34\nNAT router → Internet: from 203.0.113.7 (rewritten)\nInternet → NAT router: reply to 203.0.113.7\nNAT router → 10.0.1.5: reply (translated back)"},{"title":"See your public address","icon":"lucide-globe","text":"The address the internet sees is the router's, not your machine's.","cmd":"ip -4 addr show scope global\ncurl -s https://checkip.amazonaws.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Destination NAT: coming in","icon":"lucide-download","text":"Port forwarding sends traffic arriving at the public address and a chosen port to one private machine. Without a rule, outside traffic cannot start a connection to your private hosts, which is a useful side effect.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Look at NAT rules on a Linux router","icon":"lucide-search","text":"Masquerade is source NAT for addresses that change. IP forwarding must be on for the host to act as a router.","cmd":"sysctl net.ipv4.ip_forward\nsudo iptables -t nat -L -n -v\nsudo nft list table ip nat","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"NAT in the cloud","icon":"lucide-cloud","text":"An AWS NAT gateway lets private subnets reach the internet outbound only. An internet gateway gives public subnets two-way access for instances that have public addresses.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":10,"of":26,"prev":{"id":"net-traceroute","title":"Traceroute and mtr: follow the path"},"next":{"id":"net-dhcp-arp","title":"DHCP and ARP: how a host joins a LAN"}}},{"id":"net-dhcp-arp","title":"DHCP and ARP: how a host joins a LAN","level":2,"icon":"lucide-plug","summary":"How a new machine gets an address and finds neighbours on its local network.","qna":[{"q":"In which situation do we use this?","a":"A machine joins a LAN with no address, or two devices fight over one IP."},{"q":"What do DHCP and ARP each do?","a":"DHCP hands out address, gateway and DNS. ARP maps an IP on the local network to a MAC address."},{"q":"What comes next?","a":"ip neigh shows the ARP cache."}],"steps":[{"title":"DHCP in four messages","icon":"lucide-settings","text":"A new machine broadcasts a Discover. A DHCP server answers with an Offer, the machine sends a Request for that offer and the server confirms with an Acknowledgement. Remember it as DORA: Discover, Offer, Request, Acknowledge.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"New PC → DHCP server: Discover (broadcast)\nDHCP server → New PC: Offer 192.168.1.50\nNew PC → DHCP server: Request\nDHCP server → New PC: Acknowledge"},{"title":"What DHCP gave you","icon":"lucide-table","text":"A lease contains an address, a netmask, a default gateway, DNS servers and a lease time.","cmd":"ip -4 addr show\nip route show default\nresolvectl dns","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"ARP: who has this address?","icon":"lucide-search","text":"To send a frame to 192.168.1.1 your machine needs its MAC address. It broadcasts an ARP request, \"who has 192.168.1.1?\", and the owner replies with its MAC address. Replies are cached.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Your PC → Everyone on the LAN: who has 192.168.1.1?\nRouter → Your PC: 192.168.1.1 is at aa:bb:cc:dd:ee:ff"},{"title":"Look at the neighbour table","icon":"lucide-table","text":"ip neigh shows the cache. REACHABLE means recently confirmed, STALE means old, FAILED means nobody answered.","cmd":"ip neigh\narp -a","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Renew a lease","icon":"lucide-refresh-cw","text":"Releasing and renewing gets a fresh address. Warning: on a remote machine this can drop your SSH session.","cmd":"sudo dhclient -r && sudo dhclient\nsudo networkctl renew eth0","out":"","outKind":"","note":"Which tool applies depends on whether the system uses dhclient, systemd-networkd or NetworkManager.","risk":true,"viz":""}],"nav":{"pos":11,"of":26,"prev":{"id":"net-nat","title":"NAT and private addresses"},"next":{"id":"net-routing","title":"Routing tables and the default gateway"}}},{"id":"net-routing","title":"Routing tables and the default gateway","level":2,"icon":"lucide-signpost","summary":"Read the routing table, find which route a packet takes and add a temporary route.","qna":[{"q":"In which situation do we use this?","a":"Traffic goes the wrong way, or only some networks are reachable."},{"q":"What is the default gateway?","a":"The route used when nothing more specific matches, usually your router."},{"q":"What comes next?","a":"ip route get a.b.c.d tells you which route a given destination will use."}],"steps":[{"title":"What a route is","icon":"lucide-signpost","text":"A route says \"to reach network X, send packets via gateway Y on interface Z\". The host picks the most specific matching route (the longest prefix). The default route, 0.0.0.0/0, matches everything else.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Show the table","icon":"lucide-table","text":"Typical output has a default route through the gateway and a connected route for your own subnet.","cmd":"ip route","out":"default via 192.168.1.1 dev eth0 proto dhcp\n192.168.1.0/24 dev eth0 proto kernel scope link src 192.168.1.10","outKind":"example","note":"","risk":false,"viz":""},{"title":"Which route would be used?","icon":"lucide-search","text":"ip route get asks the kernel to show the exact route and source address for a destination.","cmd":"ip route get 8.8.8.8\nip route get 192.168.1.20","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add a temporary route","icon":"lucide-plus","text":"This sends traffic for 10.20.0.0/16 through another router. It disappears at reboot, which makes it safe for testing. A wrong route can cut off your own connection.","cmd":"sudo ip route add 10.20.0.0/16 via 192.168.1.254\nip route get 10.20.1.5","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Remove it","icon":"lucide-eraser","text":"Delete it again, or reboot.","cmd":"sudo ip route del 10.20.0.0/16","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Make routes permanent","icon":"lucide-save","text":"Add them to your network configuration, not to a startup script. On Ubuntu that is Netplan, on RHEL-family systems NetworkManager.","cmd":"sudo nmcli connection modify \"Wired connection 1\" +ipv4.routes \"10.20.0.0/16 192.168.1.254\"\nsudo nmcli connection up \"Wired connection 1\"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":12,"of":26,"prev":{"id":"net-dhcp-arp","title":"DHCP and ARP: how a host joins a LAN"},"next":{"id":"net-firewall-rules","title":"Firewall concepts and rules"}}},{"id":"net-firewall-rules","title":"Firewall concepts and rules","level":3,"icon":"lucide-shield-ban","summary":"Default deny, stateful tracking, allow rules, and how UFW, iptables and cloud security groups express the same ideas.","qna":[{"q":"In which situation do we use this?","a":"Opening only the ports a service needs and blocking everything else."},{"q":"What is the safe approach?","a":"Default deny, allow what is required, and allow your own management port before enabling the firewall."},{"q":"What comes next?","a":"In AWS the same idea appears as security groups and network ACLs."}],"steps":[{"title":"What a firewall decides","icon":"lucide-shield-ban","text":"A firewall inspects each packet or connection and allows or blocks it by source, destination, port and protocol. The safest design is default deny: block everything, then allow only what you need.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Stateful and stateless","icon":"lucide-repeat","text":"A stateful firewall remembers connections, so replies to allowed outbound traffic are let in automatically. A stateless one (an AWS network ACL) checks every packet alone, so you must allow both directions. A security group is stateful.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Rules are checked in order","icon":"lucide-list-checks","text":"With iptables and network ACLs the first matching rule wins, so order matters. Put specific rules before general ones and keep a clear default at the end.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"UFW: the simple way","icon":"lucide-settings","text":"UFW (Uncomplicated Firewall) is a friendly layer over the kernel firewall. Allow SSH before enabling it or you may lock yourself out of a remote host.","cmd":"sudo ufw default deny incoming\nsudo ufw default allow outgoing\nsudo ufw allow OpenSSH\nsudo ufw allow 443/tcp\nsudo ufw enable\nsudo ufw status numbered","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Look at the real rules","icon":"lucide-search","text":"See what is loaded in the kernel. iptables lists chains and counters, nft shows the nftables ruleset.","cmd":"sudo iptables -L -n -v --line-numbers\nsudo nft list ruleset","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Test from outside","icon":"lucide-check","text":"Verify from another machine that allowed ports answer and others do not.","cmd":"nc -vz -w 3 server 443\nnc -vz -w 3 server 3306","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Cloud equivalents","icon":"lucide-cloud","text":"An AWS security group is a stateful allow-list attached to an instance. A network ACL is a stateless rule list on a subnet. A Kubernetes NetworkPolicy limits which Pods may talk to each other.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":13,"of":26,"prev":{"id":"net-routing","title":"Routing tables and the default gateway"},"next":{"id":"net-tls","title":"TLS and certificates"}}},{"id":"net-tls","title":"TLS and certificates","level":3,"icon":"lucide-lock","summary":"Inspect a server certificate, check its expiry and issuer and create a self-signed certificate for testing.","qna":[{"q":"In which situation do we use this?","a":"HTTPS errors, expired certificates, or checking what a server presents."},{"q":"Which command shows the certificate?","a":"openssl s_client -connect host:443 and then x509 to see subject, issuer and dates."},{"q":"What comes next?","a":"Automate renewal, and check the chain and the hostname match."}],"steps":[{"title":"What TLS provides","icon":"lucide-lock","text":"TLS gives three things: privacy (traffic is encrypted), integrity (it cannot be altered unnoticed) and authentication (the certificate proves who the server is). HTTPS is HTTP over TLS.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"The handshake in short","icon":"lucide-repeat","text":"The client says hello and lists what it supports. The server answers with its certificate. The client checks the certificate chain and the name. Both sides agree on keys, then traffic is encrypted.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Client → Server: ClientHello\nServer → Client: ServerHello + certificate\nClient → Server: verify and key exchange\nServer → Client: finished, encrypted from here"},{"title":"Look at a certificate","icon":"lucide-search","text":"s_client connects and prints the chain. Piping into x509 prints just the useful fields: subject, issuer and validity dates.","cmd":"openssl s_client -connect example.com:443 -servername example.com </dev/null 2>/dev/null | openssl x509 -noout -subject -issuer -dates","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Check how long is left","icon":"lucide-clock","text":"-checkend asks whether the certificate expires within the next N seconds and sets the exit code, which is ideal for monitoring.","cmd":"echo | openssl s_client -connect example.com:443 -servername example.com 2>/dev/null | openssl x509 -noout -checkend 2592000","out":"Certificate will not expire","outKind":"example","note":"","risk":false,"viz":""},{"title":"Watch it in curl","icon":"lucide-eye","text":"curl -v shows the protocol version, the cipher and the certificate details during the handshake.","cmd":"curl -sv https://example.com -o /dev/null 2>&1 | grep -E 'TLS|subject|issuer|expire'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a self-signed certificate for testing","icon":"lucide-pencil","text":"Self-signed certificates are for local tests only because no one trusts them by default. This creates a key and certificate valid for 30 days.","cmd":"openssl req -x509 -newkey rsa:2048 -nodes -keyout key.pem -out cert.pem -days 30 -subj \"/CN=localhost\"\nopenssl x509 -in cert.pem -noout -subject -enddate","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Common failures","icon":"lucide-triangle-alert","text":"\"certificate has expired\": renew it. \"hostname mismatch\": the name you used is not in the certificate. \"unable to get local issuer certificate\": the server did not send the intermediate certificate, or your trust store is out of date.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":14,"of":26,"prev":{"id":"net-firewall-rules","title":"Firewall concepts and rules"},"next":{"id":"net-load-balancing","title":"Load balancing with Nginx"}}},{"id":"net-load-balancing","title":"Load balancing with Nginx","level":3,"icon":"lucide-network","summary":"Spread requests over two backends, see round robin in action and understand health checks.","qna":[{"q":"In which situation do we use this?","a":"One server is not enough or must stay available while another is updated."},{"q":"What does the balancer need?","a":"A list of backends and a health check so failed ones are skipped."},{"q":"What comes next?","a":"Choose the algorithm to match the workload: round robin, least connections or hash."}],"steps":[{"title":"Why a load balancer","icon":"lucide-network","text":"One server is a single point of failure and has a limit. A load balancer sits in front of several servers, spreads the requests and stops sending traffic to a server that fails.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":"Client → Load balancer: request\nLoad balancer → Server A: request 1\nLoad balancer → Server B: request 2"},{"title":"Common algorithms","icon":"lucide-equal","text":"Round robin takes turns. Least connections picks the server with the fewest active requests. IP hash keeps a client on the same server (sticky). Weighted gives stronger servers more traffic.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Two backends","icon":"lucide-server","text":"Start two tiny web servers that identify themselves, on ports 8001 and 8002.","cmd":"mkdir -p /tmp/a /tmp/b && echo \"backend A\" > /tmp/a/index.html && echo \"backend B\" > /tmp/b/index.html\n(cd /tmp/a && python3 -m http.server 8001 --bind 127.0.0.1 &)\n(cd /tmp/b && python3 -m http.server 8002 --bind 127.0.0.1 &)","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Configure Nginx","icon":"lucide-pencil","text":"An upstream block lists the servers. proxy_pass sends requests to it. Nginx uses round robin by default.","cmd":"sudo tee /etc/nginx/conf.d/lb.conf > /dev/null <<'EOF'\nupstream app {\n    server 127.0.0.1:8001;\n    server 127.0.0.1:8002;\n}\nserver {\n    listen 8080;\n    location / {\n        proxy_pass http://app;\n    }\n}\nEOF\nsudo nginx -t && sudo systemctl reload nginx","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Watch the requests alternate","icon":"lucide-play","text":"Send several requests and see them answered by A and B in turn.","cmd":"for i in 1 2 3 4; do curl -s http://127.0.0.1:8080/; done","out":"backend A\nbackend B\nbackend A\nbackend B","outKind":"example","note":"","risk":false,"viz":""},{"title":"Remove a backend","icon":"lucide-triangle-alert","text":"Stop backend B and keep sending requests. Open source Nginx marks a server failed after real errors (max_fails) and then sends traffic only to the healthy one.","cmd":"pkill -f \"http.server 8002\"\nfor i in 1 2 3 4; do curl -s http://127.0.0.1:8080/; done","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Stop the test servers and remove the configuration.","cmd":"pkill -f \"http.server 800\"\nsudo rm /etc/nginx/conf.d/lb.conf && sudo nginx -t && sudo systemctl reload nginx","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":15,"of":26,"prev":{"id":"net-tls","title":"TLS and certificates"},"next":{"id":"net-ssh-tunnels","title":"SSH tunnels and jump hosts"}}},{"id":"net-ssh-tunnels","title":"SSH tunnels and jump hosts","level":3,"icon":"lucide-cable","summary":"Reach a private service through a bastion with local, remote and dynamic forwarding and ProxyJump.","qna":[{"q":"In which situation do we use this?","a":"Reaching a database or admin page that is not public, through a bastion host you are allowed to use."},{"q":"Which flag does what?","a":"-L forwards a local port to a remote service, -R does the reverse, -J jumps through a host."},{"q":"What comes next?","a":"Keep tunnels short-lived and only to systems you are authorised to access."}],"steps":[{"title":"Why tunnel","icon":"lucide-cable","text":"A database or admin page that is private (no public address) can still be reached safely through SSH to a host that can see it, usually a bastion. The tunnel carries your traffic inside the encrypted SSH connection.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Local forward (-L)","icon":"lucide-download","text":"Listen on your machine and forward to a target as seen from the SSH server. Here local port 5433 reaches the private database on db.internal:5432 through the bastion.","cmd":"ssh -N -L 5433:db.internal:5432 user@bastion.example.com\npsql -h 127.0.0.1 -p 5433 -U app appdb","out":"","outKind":"","note":"","risk":false,"viz":"Your PC → Bastion: SSH tunnel (encrypted)\nBastion → Private DB: 5432"},{"title":"Remote forward (-R)","icon":"lucide-upload","text":"The reverse: listen on the server and forward back to your machine. Useful to show a local development server to a remote host. Be careful about who can reach the listening port.","cmd":"ssh -N -R 9000:localhost:3000 user@server.example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Dynamic forward (-D): a SOCKS proxy","icon":"lucide-globe","text":"-D opens a local SOCKS5 proxy that sends any connection through the SSH server. Point a browser or curl at it.","cmd":"ssh -N -D 1080 user@bastion.example.com\ncurl --socks5-hostname 127.0.0.1:1080 https://checkip.amazonaws.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Jump through a bastion with ProxyJump","icon":"lucide-server","text":"-J connects to the final host through a jump host in one command. The same works for scp and rsync.","cmd":"ssh -J user@bastion.example.com user@10.0.1.20\nscp -o ProxyJump=user@bastion.example.com file.txt user@10.0.1.20:/tmp/","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Save it in ~/.ssh/config","icon":"lucide-save","text":"A config entry turns the long command into ssh app1. Keys never leave your machine with ProxyJump, unlike agent forwarding.","cmd":"cat >> ~/.ssh/config <<'EOF'\nHost bastion\n    HostName bastion.example.com\n    User user\n\nHost app1\n    HostName 10.0.1.20\n    User user\n    ProxyJump bastion\nEOF\nssh app1 hostname","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Security notes","icon":"lucide-shield","text":"Only forward to hosts you are allowed to reach. Keep forwarded ports bound to 127.0.0.1 (the default). Close tunnels when finished and review who can log in to the bastion.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":16,"of":26,"prev":{"id":"net-load-balancing","title":"Load balancing with Nginx"},"next":{"id":"net-packet-capture","title":"Packet capture with tcpdump"}}},{"id":"net-packet-capture","title":"Packet capture with tcpdump","level":3,"icon":"lucide-eye","summary":"Capture a DNS lookup and an HTTP request on your own machine, filter, save to a file and read it back.","qna":[{"q":"In which situation do we use this?","a":"Logs say nothing, but you need to see what really crosses the wire: handshakes, resets, DNS queries."},{"q":"How do I keep it manageable?","a":"Filter by host and port and capture to a file with -w, then read it with -r."},{"q":"What comes next?","a":"Capture only on systems you own or administer, and avoid storing sensitive payloads."}],"steps":[{"title":"When and why","icon":"lucide-eye","text":"A capture shows the real packets, which settles arguments about what the network does. Only capture on systems you own or administer, because packets can contain passwords and personal data.","cmd":"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Capture a few packets","icon":"lucide-play","text":"-i picks the interface (any for all), -nn skips name and port lookups and -c stops after a count. Needs root.","cmd":"sudo tcpdump -i any -nn -c 10","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Filter with a primitive","icon":"lucide-filter","text":"Filters keep the output readable. port 53 shows DNS, host limits to one address and tcp or udp limits the protocol.","cmd":"sudo tcpdump -i any -nn port 53 -c 6\nsudo tcpdump -i any -nn host 1.1.1.1 and icmp -c 4","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Generate traffic and watch","icon":"lucide-search","text":"In a second terminal trigger a lookup and watch the query and the response appear.","cmd":"dig example.com","out":"IP 192.168.1.10.51234 > 192.168.1.1.53: A? example.com.\nIP 192.168.1.1.53 > 192.168.1.10.51234: A 203.0.113.10","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save and read a capture","icon":"lucide-save","text":"-w writes a pcap file you can open in Wireshark. -r reads it back. Add -s 0 on old versions to keep full packets.","cmd":"sudo tcpdump -i any -nn port 443 -c 100 -w web.pcap\ntcpdump -nn -r web.pcap | head","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Look at the TCP flags","icon":"lucide-table","text":"[S] is SYN, [S.] SYN-ACK, [.] ACK, [P.] push data, [F.] FIN and [R] reset. A reset right after a SYN means the port is closed.","cmd":"sudo tcpdump -i any -nn 'tcp[tcpflags] & tcp-syn != 0' -c 6","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":17,"of":26,"prev":{"id":"net-ssh-tunnels","title":"SSH tunnels and jump hosts"},"next":{"id":"net-aws-vpc","title":"Project: build a VPC with the AWS CLI"}}},{"id":"net-aws-vpc","title":"Project: build a VPC with the AWS CLI","level":4,"icon":"lucide-cloud","summary":"Create a VPC with public and private subnets, an internet gateway, a NAT gateway and route tables, then verify.","qna":[{"q":"In which situation do we use this?","a":"Building a clean network for an environment: public, private and database subnets with routes and gateways."},{"q":"Why use the CLI?","a":"The steps are explicit and repeatable, and they map directly to Terraform or CloudFormation later."},{"q":"What comes next?","a":"Delete test resources to avoid cost, in reverse order of creation."}],"steps":[{"title":"Plan","icon":"lucide-target","text":"One VPC (10.0.0.0/16), one public subnet (10.0.0.0/24) with a route to an internet gateway, and one private subnet (10.0.10.0/24) that reaches the internet through a NAT gateway. The same pattern repeats per availability zone for high availability. A NAT gateway costs money while it exists, so delete everything at the end.","cmd":"","out":"","outKind":"","note":"","risk":true,"viz":""},{"title":"Create the VPC","icon":"lucide-cloud","text":"Capture each ID in a shell variable so the next commands can use it. Replace the region with yours.","cmd":"export AWS_REGION=ap-south-1\nVPC=$(aws ec2 create-vpc --cidr-block 10.0.0.0/16 --tag-specifications 'ResourceType=vpc,Tags=[{Key=Name,Value=demo-vpc}]' --query Vpc.VpcId --output text)\naws ec2 modify-vpc-attribute --vpc-id $VPC --enable-dns-hostnames\necho $VPC","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create the subnets","icon":"lucide-table","text":"One public and one private subnet in the same availability zone.","cmd":"PUB=$(aws ec2 create-subnet --vpc-id $VPC --cidr-block 10.0.0.0/24 --availability-zone ${AWS_REGION}a --query Subnet.SubnetId --output text)\nPRIV=$(aws ec2 create-subnet --vpc-id $VPC --cidr-block 10.0.10.0/24 --availability-zone ${AWS_REGION}a --query Subnet.SubnetId --output text)","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Internet gateway and public route","icon":"lucide-door-open","text":"Create the gateway, attach it, then give the public subnet a route to the internet through it.","cmd":"IGW=$(aws ec2 create-internet-gateway --query InternetGateway.InternetGatewayId --output text)\naws ec2 attach-internet-gateway --internet-gateway-id $IGW --vpc-id $VPC\nRTB_PUB=$(aws ec2 create-route-table --vpc-id $VPC --query RouteTable.RouteTableId --output text)\naws ec2 create-route --route-table-id $RTB_PUB --destination-cidr-block 0.0.0.0/0 --gateway-id $IGW\naws ec2 associate-route-table --route-table-id $RTB_PUB --subnet-id $PUB","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"NAT gateway and private route","icon":"lucide-arrow-left-right","text":"The NAT gateway lives in the public subnet and uses an Elastic IP. The private route table sends internet traffic to it.","cmd":"EIP=$(aws ec2 allocate-address --domain vpc --query AllocationId --output text)\nNAT=$(aws ec2 create-nat-gateway --subnet-id $PUB --allocation-id $EIP --query NatGateway.NatGatewayId --output text)\naws ec2 wait nat-gateway-available --nat-gateway-ids $NAT\nRTB_PRIV=$(aws ec2 create-route-table --vpc-id $VPC --query RouteTable.RouteTableId --output text)\naws ec2 create-route --route-table-id $RTB_PRIV --destination-cidr-block 0.0.0.0/0 --nat-gateway-id $NAT\naws ec2 associate-route-table --route-table-id $RTB_PRIV --subnet-id $PRIV","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Verify","icon":"lucide-check","text":"Print the route tables. The public one must have a route to igw-..., and the private one to nat-.... A subnet with no default route has no internet access at all.","cmd":"aws ec2 describe-route-tables --filters Name=vpc-id,Values=$VPC --query 'RouteTables[].{Id:RouteTableId,Routes:Routes[].[DestinationCidrBlock,GatewayId,NatGatewayId]}' --output json","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Delete everything","icon":"lucide-eraser","text":"Remove in reverse order. Skipping the NAT gateway and Elastic IP keeps charging you.","cmd":"aws ec2 delete-nat-gateway --nat-gateway-id $NAT\naws ec2 wait nat-gateway-deleted --nat-gateway-ids $NAT 2>/dev/null; aws ec2 release-address --allocation-id $EIP\naws ec2 detach-internet-gateway --internet-gateway-id $IGW --vpc-id $VPC && aws ec2 delete-internet-gateway --internet-gateway-id $IGW\naws ec2 delete-subnet --subnet-id $PUB; aws ec2 delete-subnet --subnet-id $PRIV\naws ec2 delete-route-table --route-table-id $RTB_PUB; aws ec2 delete-route-table --route-table-id $RTB_PRIV\naws ec2 delete-vpc --vpc-id $VPC","out":"","outKind":"","note":"Delete the route tables only after their subnet associations are gone. The delete-subnet commands remove the associations.","risk":true,"viz":""}],"nav":{"pos":18,"of":26,"prev":{"id":"net-packet-capture","title":"Packet capture with tcpdump"},"next":{"id":"net-k8s-network","title":"Kubernetes networking: Pod, Service, DNS, Ingress"}}},{"id":"net-k8s-network","title":"Kubernetes networking: Pod, Service, DNS, Ingress","level":3,"icon":"lucide-container","summary":"Pod IPs, ClusterIP Services, DNS names, Ingress and a default-deny NetworkPolicy.","qna":[{"q":"In which situation do we use this?","a":"Pods cannot reach each other, a Service has no endpoints, or an Ingress returns 404."},{"q":"How is traffic organised?","a":"Pods get their own IPs, a Service gives them a stable name and address, and Ingress routes outside traffic to Services."},{"q":"What comes next?","a":"kubectl get endpoints shows whether the Service found any Pods."}],"steps":[{"title":"The model","icon":"lucide-container","text":"Every Pod gets its own IP address and can reach every other Pod without NAT. Pod IPs change when Pods are replaced, so a Service gives a stable address and name in front of a set of Pods.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Pods and their IPs","icon":"lucide-box","text":"Create a small deployment and look at the Pod IPs.","cmd":"kubectl create deployment web --image=nginx:stable --replicas=2\nkubectl get pods -l app=web -o wide","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Expose with a Service","icon":"lucide-link","text":"A ClusterIP Service gets a virtual IP and spreads connections across matching Pods. The selector connects them.","cmd":"kubectl expose deployment web --port=80\nkubectl get svc web\nkubectl get endpoints web","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"DNS inside the cluster","icon":"lucide-book-open","text":"CoreDNS gives every Service a name: web.default.svc.cluster.local, or just web inside the same namespace. Test it from a temporary Pod.","cmd":"kubectl run tmp --rm -it --image=busybox:1.36 --restart=Never -- nslookup web\nkubectl run tmp --rm -it --image=busybox:1.36 --restart=Never -- wget -qO- http://web","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Reach it from outside","icon":"lucide-globe","text":"A NodePort opens a port on every node, a LoadBalancer asks the cloud for a load balancer and an Ingress routes HTTP by host and path through one entry point (it needs an ingress controller installed).","cmd":"kubectl get svc,ingress -A","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Limit traffic with a NetworkPolicy","icon":"lucide-shield-ban","text":"By default every Pod can talk to every other. A policy that selects all Pods and allows nothing is default deny. Policies only work if your network plugin (CNI) supports them.","cmd":"kubectl apply -f - <<'EOF'\napiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nmetadata:\n  name: default-deny-ingress\nspec:\n  podSelector: {}\n  policyTypes:\n    - Ingress\nEOF\nkubectl run tmp --rm -it --image=busybox:1.36 --restart=Never -- wget -qO- -T 3 http://web","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Clean up","icon":"lucide-eraser","text":"Remove the test objects.","cmd":"kubectl delete networkpolicy default-deny-ingress\nkubectl delete svc web && kubectl delete deployment web","out":"","outKind":"","note":"","risk":true,"viz":""}],"nav":{"pos":19,"of":26,"prev":{"id":"net-aws-vpc","title":"Project: build a VPC with the AWS CLI"},"next":{"id":"net-troubleshoot-method","title":"A method for network troubleshooting"}}},{"id":"net-troubleshoot-method","title":"A method for network troubleshooting","level":2,"icon":"lucide-search","summary":"Work through the layers in order and find the failing one in minutes instead of guessing.","qna":[{"q":"In which situation do we use this?","a":"Any \"it does not connect\" report, to avoid guessing."},{"q":"What is the method?","a":"Define the failure, test from the bottom layer up, change one thing at a time and write down each result."},{"q":"What comes next?","a":"Reproduce from both sides when you can: the client and the server."}],"steps":[{"title":"Define the problem","icon":"lucide-target","text":"Write down what fails, from where, to what, since when and what changed. \"The site is slow from my laptop but fine from the server\" already narrows it a lot.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Layer 1 and 2: the link","icon":"lucide-plug","text":"Is the interface up and does it see its neighbours?","cmd":"ip -br link\nip neigh","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Layer 3: address and gateway","icon":"lucide-signpost","text":"Does the machine have the right address, and can it reach its gateway?","cmd":"ip -br addr\nip route show default\nping -c 2 $(ip route | awk '/default/ {print $3; exit}')","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Beyond the gateway: routing","icon":"lucide-globe","text":"Reach an internet address by number. If this works but names fail, jump to DNS.","cmd":"ping -c 2 1.1.1.1\ntraceroute -n 1.1.1.1","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"DNS","icon":"lucide-book-open","text":"Resolve the name, then ask a different resolver and compare.","cmd":"dig +short example.com\ndig @1.1.1.1 +short example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Layer 4: the port","icon":"lucide-plug","text":"Can you open a TCP connection to the service?","cmd":"nc -vz -w 3 example.com 443","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Layer 7: the application","icon":"lucide-code","text":"Make a real request and read the status and timing.","cmd":"curl -sS -o /dev/null -w \"%{http_code} %{time_total}s\\n\" https://example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Decide and record","icon":"lucide-clipboard-list","text":"The first layer that fails is where to look. Then check firewalls, security groups and recent changes at that layer. Write down what you found so the next person does not start from zero.","cmd":"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":20,"of":26,"prev":{"id":"net-k8s-network","title":"Kubernetes networking: Pod, Service, DNS, Ingress"},"next":{"id":"net-ssh-forwarding","title":"SSH port forwarding: -L, -R and -D"}}},{"id":"net-ssh-forwarding","title":"SSH port forwarding: -L, -R and -D","level":3,"icon":"lucide-cable","summary":"Reach a private service through an SSH host you are authorised to use, in all three directions.","qna":[{"q":"In which situation do we use this?","a":"A database or admin page is private and you have SSH access to a host inside the network."},{"q":"Which flag, in one line?","a":"-L brings a remote service to your machine, -R sends your service to the server, -D makes a SOCKS proxy."},{"q":"What comes next?","a":"Close tunnels when finished, and use only systems you are authorised to reach."}],"steps":[{"title":"What forwarding does","icon":"wf-tunnel","text":"An SSH connection can carry other traffic inside it. -L opens a local port that leads to a remote service. -R opens a port on the server that leads back to you. -D makes a local SOCKS proxy.","cmd":"ssh -V","out":"","outKind":"","note":"Use forwarding only to systems you own or are explicitly allowed to access, and follow your organisation's policy.","risk":false,"viz":""},{"title":"Local forward: reach a private database","icon":"lucide-database","text":"-L 5433:db.internal:5432 listens on your port 5433. Traffic goes through the bastion and on to db.internal port 5432. -N means \"no command\", -f sends it to the background.","cmd":"ssh -N -f -L 5433:db.internal:5432 ops@bastion.example.com\nss -ltn | grep 5433\npsql -h 127.0.0.1 -p 5433 -U app appdb","out":"$ ss -ltn | grep 5433\nLISTEN 0 128 127.0.0.1:5433 0.0.0.0:*","outKind":"example","note":"","risk":false,"viz":""},{"title":"Remote forward: expose a local app","icon":"lucide-upload","text":"-R 8080:localhost:3000 opens port 8080 on the server and sends it to port 3000 on your laptop. Handy for showing a demo; the server must allow it with GatewayPorts for outside access.","cmd":"ssh -N -R 8080:localhost:3000 ops@demo.example.com\nssh ops@demo.example.com 'curl -s localhost:8080 | head -n 3'","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Dynamic forward: a SOCKS proxy","icon":"lucide-globe","text":"-D 1080 turns the connection into a SOCKS5 proxy. Point a browser or curl at it and their traffic leaves from the SSH host.","cmd":"ssh -N -f -D 1080 ops@bastion.example.com\ncurl --socks5-hostname 127.0.0.1:1080 -I https://intranet.example.com","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Save it and stop it","icon":"lucide-save","text":"Put tunnels in ~/.ssh/config as LocalForward lines so the command is short. Find and stop background tunnels by their command line.","cmd":"printf 'Host db-tunnel\n  HostName bastion.example.com\n  User ops\n  LocalForward 5433 db.internal:5432\n  ExitOnForwardFailure yes\n  ServerAliveInterval 30\n' >> ~/.ssh/config\nssh -N -f db-tunnel\npkill -f \"ssh -N -f db-tunnel\"","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":21,"of":26,"prev":{"id":"net-troubleshoot-method","title":"A method for network troubleshooting"},"next":{"id":"net-nmap-basics","title":"Discover hosts and ports with nmap"}}},{"id":"net-nmap-basics","title":"Discover hosts and ports with nmap","level":2,"icon":"lucide-search","summary":"Scan your own lab network politely: find hosts, open ports and service versions, and save the results.","qna":[{"q":"In which situation do we use this?","a":"Checking which ports your own servers really expose, or confirming that a firewall change worked."},{"q":"What do open, closed and filtered mean?","a":"Open means a program answers, closed means nothing listens, filtered means a firewall hides the answer."},{"q":"What comes next?","a":"Save scans and diff them after each change. Scan only with permission."}],"steps":[{"title":"Only scan what you own","icon":"lucide-shield","text":"Scanning networks without permission can be illegal and triggers alarms. Use your own machines, a lab VM, or scanme.nmap.org, which the nmap project provides for testing.","cmd":"nmap --version","out":"","outKind":"","note":"Write down the scope and permission before scanning a company network.","risk":false,"viz":""},{"title":"Is the host up?","icon":"lucide-eye","text":"-sn is a ping scan: it checks which addresses answer and does not touch ports. Use it to list a small lab subnet.","cmd":"nmap -sn 192.168.56.0/24","out":"$ nmap -sn 192.168.56.0/24\nNmap scan report for 192.168.56.10\nHost is up (0.00031s latency).\nNmap scan report for 192.168.56.11\nNmap done: 256 IP addresses (2 hosts up) scanned in 2.4 seconds","outKind":"example","note":"","risk":false,"viz":""},{"title":"Which ports are open?","icon":"lucide-plug","text":"By default nmap checks the 1000 most common TCP ports. -p picks ports, -p- checks all 65535. Open means a program accepts connections, closed means nothing listens, filtered means a firewall hides it.","cmd":"nmap 192.168.56.10\nnmap -p 22,80,443 192.168.56.10","out":"$ nmap 192.168.56.10\nPORT    STATE SERVICE\n22/tcp  open  ssh\n80/tcp  open  http","outKind":"example","note":"","risk":false,"viz":""},{"title":"What runs there?","icon":"lucide-settings","text":"-sV asks the service for its version, so you can compare it with vulnerability advisories. -sC runs a small set of safe default scripts.","cmd":"nmap -sV -p 22,80 192.168.56.10","out":"$ nmap -sV -p 22,80 192.168.56.10\n22/tcp open ssh   OpenSSH 9.6 (protocol 2.0)\n80/tcp open http  nginx 1.24.0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Save the report and compare later","icon":"lucide-save","text":"-oN writes a readable file. Run the same scan after a change and diff the two files to see exactly which ports opened or closed.","cmd":"nmap -oN before.txt -p 1-1024 192.168.56.10\nnmap -oN after.txt -p 1-1024 192.168.56.10\ndiff before.txt after.txt","out":"","outKind":"","note":"Slow it down with -T2 on fragile networks. Aggressive scans can disturb old devices.","risk":false,"viz":""}],"nav":{"pos":22,"of":26,"prev":{"id":"net-ssh-forwarding","title":"SSH port forwarding: -L, -R and -D"},"next":{"id":"net-wireguard","title":"A WireGuard VPN between two machines"}}},{"id":"net-wireguard","title":"A WireGuard VPN between two machines","level":3,"icon":"lucide-lock","summary":"Generate keys, write both configs, bring the tunnel up and check the handshake.","qna":[{"q":"In which situation do we use this?","a":"A small, fast VPN between two sites or from a laptop to a server, with little configuration."},{"q":"What identifies a peer?","a":"Its public key. AllowedIPs says which addresses may be sent through that peer."},{"q":"What comes next?","a":"Rotate keys on a schedule and never share a private key."}],"steps":[{"title":"What WireGuard is","icon":"lucide-lock","text":"WireGuard makes an encrypted tunnel between peers using public keys. Each side has a private key it never shares and the other side's public key. The tunnel appears as a normal network interface.","cmd":"wg --version\nsudo apt install -y wireguard","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Create a key pair on each machine","icon":"lucide-key-round","text":"wg genkey makes a private key and wg pubkey derives the public key. Restrict file permissions so only root can read the private key.","cmd":"umask 077\nwg genkey | tee privatekey | wg pubkey > publickey\ncat publickey","out":"$ cat publickey\nAbCdEf0123456789exampleExamplePublicKey+/=","outKind":"example","note":"Never paste a private key into chat, tickets or Git.","risk":true,"viz":""},{"title":"Write the two configurations","icon":"lucide-pencil","text":"Server A listens on UDP 51820 and uses 10.8.0.1 inside the tunnel. Server B uses 10.8.0.2 and names A as its peer. AllowedIPs lists which addresses may use that peer.","cmd":"printf '[Interface]\nAddress = 10.8.0.1/24\nListenPort = 51820\nPrivateKey = <A-private-key>\n\n[Peer]\nPublicKey = <B-public-key>\nAllowedIPs = 10.8.0.2/32\n' | sudo tee /etc/wireguard/wg0.conf\nprintf '[Interface]\nAddress = 10.8.0.2/24\nPrivateKey = <B-private-key>\n\n[Peer]\nPublicKey = <A-public-key>\nEndpoint = a.example.com:51820\nAllowedIPs = 10.8.0.1/32\nPersistentKeepalive = 25\n' | sudo tee /etc/wireguard/wg0.conf","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Bring it up and test","icon":"lucide-play","text":"wg-quick up reads the file, creates the interface and adds routes. A recent handshake shows that both sides found each other.","cmd":"sudo wg-quick up wg0\nsudo wg show\nping -c 2 10.8.0.1","out":"$ sudo wg show\ninterface: wg0\npeer: AbCd...=\n  endpoint: 203.0.113.7:51820\n  latest handshake: 12 seconds ago\n  transfer: 1.20 KiB received, 1.05 KiB sent","outKind":"example","note":"","risk":false,"viz":""},{"title":"Start at boot and open the port","icon":"lucide-power","text":"Enable the systemd unit and allow UDP 51820 in the firewall of the listening side. To route all traffic through the tunnel set AllowedIPs = 0.0.0.0/0 on the client.","cmd":"sudo systemctl enable --now wg-quick@wg0\nsudo ufw allow 51820/udp\nsudo ip route get 10.8.0.1","out":"","outKind":"","note":"","risk":false,"viz":""}],"nav":{"pos":23,"of":26,"prev":{"id":"net-nmap-basics","title":"Discover hosts and ports with nmap"},"next":{"id":"net-iptables-nat","title":"NAT and forwarding with iptables"}}},{"id":"net-iptables-nat","title":"NAT and forwarding with iptables","level":4,"icon":"lucide-shield-ban","summary":"Turn a Linux machine into a small router: enable forwarding, masquerade and port-forward.","qna":[{"q":"In which situation do we use this?","a":"A Linux box must act as a router or gateway for a private network, or forward a public port to an internal server."},{"q":"SNAT or DNAT?","a":"MASQUERADE rewrites the source for outgoing traffic. DNAT rewrites the destination for port forwarding."},{"q":"What comes next?","a":"On new systems look at nftables, which replaces iptables."}],"steps":[{"title":"Enable IP forwarding","icon":"lucide-repeat","text":"By default Linux drops packets that are not for itself. Setting net.ipv4.ip_forward=1 lets it route between networks.","cmd":"sysctl net.ipv4.ip_forward\nsudo sysctl -w net.ipv4.ip_forward=1\necho 'net.ipv4.ip_forward = 1' | sudo tee /etc/sysctl.d/99-router.conf","out":"$ sysctl net.ipv4.ip_forward\nnet.ipv4.ip_forward = 0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Masquerade private clients","icon":"wf-nat-swap","text":"Clients on eth1 (192.168.50.0/24) use private addresses. MASQUERADE rewrites their source to the address of eth0 so replies find the way back. It belongs in the nat table, POSTROUTING chain.","cmd":"sudo iptables -t nat -A POSTROUTING -s 192.168.50.0/24 -o eth0 -j MASQUERADE\nsudo iptables -t nat -L POSTROUTING -n -v","out":"$ sudo iptables -t nat -L POSTROUTING -n -v\nChain POSTROUTING (policy ACCEPT)\n pkts bytes target     prot opt in out  source          destination\n    0     0 MASQUERADE all  --  *  eth0 192.168.50.0/24 0.0.0.0/0","outKind":"example","note":"","risk":false,"viz":""},{"title":"Allow forwarding through the filter table","icon":"wf-firewall-wall","text":"Forwarded traffic is judged by the FORWARD chain. Allow new connections from the inside, and replies to established ones from outside.","cmd":"sudo iptables -A FORWARD -i eth1 -o eth0 -j ACCEPT\nsudo iptables -A FORWARD -i eth0 -o eth1 -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT\nsudo iptables -L FORWARD -n -v","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Port forward to an internal server","icon":"lucide-pin","text":"DNAT rewrites the destination. Traffic arriving on port 8080 of the router goes to 192.168.50.20:80. conntrack remembers the mapping, so replies are rewritten back.","cmd":"sudo iptables -t nat -A PREROUTING -i eth0 -p tcp --dport 8080 -j DNAT --to-destination 192.168.50.20:80\nsudo conntrack -L 2>/dev/null | head -n 3","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Save the rules","icon":"lucide-save","text":"Rules live in memory and vanish at reboot. Save them with your distribution's tool and review before relying on them.","cmd":"sudo iptables-save | sudo tee /etc/iptables/rules.v4\nsudo iptables -S | head -n 8","out":"","outKind":"","note":"Edit firewalls from a console or with a safety plan. A wrong rule on a remote machine can lock you out.","risk":true,"viz":""}],"nav":{"pos":24,"of":26,"prev":{"id":"net-wireguard","title":"A WireGuard VPN between two machines"},"next":{"id":"net-aws-peering-endpoints","title":"AWS VPC peering and endpoints"}}},{"id":"net-aws-peering-endpoints","title":"AWS VPC peering and endpoints","level":4,"icon":"lucide-cloud","summary":"Connect two VPCs privately and reach S3 without the internet, using the CLI.","qna":[{"q":"In which situation do we use this?","a":"Two VPCs, for example prod and shared services, need private connectivity, or private subnets need S3 without a NAT gateway."},{"q":"Why does my peering not work?","a":"Usual causes: only one route table was updated, a security group blocks it, or the CIDR ranges overlap."},{"q":"What comes next?","a":"For many VPCs, compare Transit Gateway."}],"steps":[{"title":"Two VPCs that must talk","icon":"lucide-cloud","text":"Peering joins two VPCs so instances reach each other by private IP. Their CIDR ranges must not overlap, and peering is not transitive: A to B and B to C does not give A to C.","cmd":"aws ec2 describe-vpcs --query 'Vpcs[].[VpcId,CidrBlock]' --output text","out":"$ aws ec2 describe-vpcs --query 'Vpcs[].[VpcId,CidrBlock]' --output text\nvpc-0aa111  10.0.0.0/16\nvpc-0bb222  10.1.0.0/16","outKind":"example","note":"","risk":false,"viz":""},{"title":"Request and accept the peering","icon":"wf-peering","text":"One VPC requests; the owner of the other accepts. In the same account you can do both from the CLI.","cmd":"PCX=$(aws ec2 create-vpc-peering-connection --vpc-id vpc-0aa111 --peer-vpc-id vpc-0bb222 --query VpcPeeringConnection.VpcPeeringConnectionId --output text)\naws ec2 accept-vpc-peering-connection --vpc-peering-connection-id $PCX\necho $PCX","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Add routes on both sides","icon":"lucide-signpost","text":"A peering connection carries no traffic until each route table has a route to the other CIDR via the pcx id. Forgetting one side is the commonest mistake.","cmd":"aws ec2 create-route --route-table-id rtb-0aa --destination-cidr-block 10.1.0.0/16 --vpc-peering-connection-id $PCX\naws ec2 create-route --route-table-id rtb-0bb --destination-cidr-block 10.0.0.0/16 --vpc-peering-connection-id $PCX","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Allow it in the security groups","icon":"lucide-shield","text":"Routes alone do not open traffic. The security group on the target must allow the source CIDR or the peer's security group on the right port.","cmd":"aws ec2 authorize-security-group-ingress --group-id sg-0bb --protocol tcp --port 5432 --cidr 10.0.0.0/16","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"A gateway endpoint for S3","icon":"wf-endpoint","text":"A gateway endpoint adds a route so S3 traffic stays on the AWS network, with no NAT gateway cost. Interface endpoints (for other services) use private IPs inside your subnets instead.","cmd":"aws ec2 create-vpc-endpoint --vpc-id vpc-0aa111 --service-name com.amazonaws.ap-south-1.s3 --route-table-ids rtb-0aa\naws ec2 describe-vpc-endpoints --query 'VpcEndpoints[].[VpcEndpointId,ServiceName,State]' --output text","out":"","outKind":"","note":"Delete test peering connections and endpoints afterwards. For many VPCs consider Transit Gateway.","risk":false,"viz":""}],"nav":{"pos":25,"of":26,"prev":{"id":"net-iptables-nat","title":"NAT and forwarding with iptables"},"next":{"id":"net-k8s-networkpolicy","title":"Kubernetes NetworkPolicy: default deny"}}},{"id":"net-k8s-networkpolicy","title":"Kubernetes NetworkPolicy: default deny","level":4,"icon":"lucide-shield-ban","summary":"Lock down a namespace, then allow only the traffic each application needs.","qna":[{"q":"In which situation do we use this?","a":"Locking down a namespace so only the right pods can talk to each other, for example only the frontend reaching the database."},{"q":"Where do people go wrong?","a":"The network plugin must enforce policies, and after denying egress you must still allow DNS on port 53."},{"q":"What comes next?","a":"Test both the allowed and the denied path."}],"steps":[{"title":"Everything is open by default","icon":"lucide-globe","text":"In Kubernetes any pod can reach any other pod. NetworkPolicy changes that, but only if the cluster's network plugin enforces it (Calico, Cilium and others do).","cmd":"kubectl create namespace shop\nkubectl -n shop run web --image=nginx:1.27 --labels=app=web\nkubectl -n shop run db --image=nginx:1.27 --labels=app=db\nkubectl -n shop get pods -o wide","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Prove the open state","icon":"lucide-eye","text":"From a temporary pod, call the web pod by its IP. It answers, because nothing restricts it yet.","cmd":"WEB=$(kubectl -n shop get pod web -o jsonpath='{.status.podIP}')\nkubectl -n shop run probe --rm -it --restart=Never --image=busybox:1.36 -- wget -qO- -T 3 http://$WEB","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Deny all ingress","icon":"wf-firewall-wall","text":"An empty podSelector matches every pod in the namespace. With policyTypes Ingress and no rules, nothing is allowed in.","cmd":"printf 'apiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nmetadata:\n  name: default-deny\n  namespace: shop\nspec:\n  podSelector: {}\n  policyTypes: [Ingress]\n' | kubectl apply -f -\nkubectl -n shop run probe --rm -it --restart=Never --image=busybox:1.36 -- wget -qO- -T 3 http://$WEB","out":"$ wget -qO- -T 3 http://10.244.1.7\nwget: download timed out","outKind":"example","note":"","risk":false,"viz":""},{"title":"Allow only what is needed","icon":"lucide-check","text":"Add a second policy. Pods labelled app=web accept traffic from pods labelled role=frontend on port 80. Policies are additive: each one only adds permitted paths.","cmd":"printf 'apiVersion: networking.k8s.io/v1\nkind: NetworkPolicy\nmetadata:\n  name: allow-frontend\n  namespace: shop\nspec:\n  podSelector:\n    matchLabels: {app: web}\n  ingress:\n    - from:\n        - podSelector:\n            matchLabels: {role: frontend}\n      ports:\n        - {protocol: TCP, port: 80}\n' | kubectl apply -f -\nkubectl -n shop get networkpolicy","out":"","outKind":"","note":"","risk":false,"viz":""},{"title":"Test both outcomes","icon":"lucide-list-checks","text":"A pod with the right label can connect, one without it cannot. Always test the denied case too, not only the allowed one.","cmd":"kubectl -n shop run ok --rm -it --restart=Never --labels=role=frontend --image=busybox:1.36 -- wget -qO- -T 3 http://$WEB\nkubectl -n shop run no --rm -it --restart=Never --image=busybox:1.36 -- wget -qO- -T 3 http://$WEB\nkubectl delete namespace shop","out":"","outKind":"","note":"Remember DNS. If you also deny egress, allow UDP and TCP 53 to kube-dns or names stop resolving.","risk":false,"viz":""}],"nav":{"pos":26,"of":26,"prev":{"id":"net-aws-peering-endpoints","title":"AWS VPC peering and endpoints"},"next":null}}]}];
